/// [Product Entity] - This implements the product definition, catalog management, and onboarding requirement as analyzed from the Product Management, System Overview, and Business Concepts requirement documents.
///
/// Defines the core sellable item in the platform, referenced by SKUs, categories, and media. Maintains strict 3NF: all descriptive and variant fields are separated into related tables (options, tags, media, inventory). This structure enables scalable product onboarding, flexible catalog relationships, and AI-driven enrichment.
///
/// For example, a seller can create a product with multilingual title/description, assign to multiple categories, upload rich media, and manage compliance status.
///
/// Key relationships: owned by a seller, has many SKUs, belongs to many categories (M:N), references options, media, tags.
/// Special behaviors: Approval and compliance workflow states are enforced; no denormalization (aggregates in MVs only).
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_products {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique platform identifier for the product. Implements global uniqueness with UUID as required by architecture and compliance requirements. Enables strict 3NF and referencing from all related entities (SKUs, categories, media, etc.).
  id String @id @db.Uuid

  /// [Seller Relationship] - Links product to the seller owner. Required for RBAC and enforcement of seller-specific permissions, as per Seller/Admin Management requirements. Ensures strict foreign-key normalization. Every product must have a seller owner with referential integrity to ai_ecommerce_sellers.
  seller_id String @db.Uuid

  /// [Product Title] - Product display name (multilingual via related media if needed). Implements requirements for rich, flexible product names. Strictly atomic field. Example: 'AI-Enabled Smart Vacuum'.
  title String

  /// [Product Description] - Detailed description (long text, normalized but atomic; multilingual handled in media/options). Enables AI-enriched copy, templates. Example: 'Next-gen AI-powered vacuum with voice assistant integration.'
  description String

  /// [Product Lifecycle Status] - Implements catalog workflow state (e.g., draft, pending, published, archived). Enforces catalog management lifecycle (3NF: workflow states and timestamps atomic). Example: 'published'.
  status String

  /// [Product Approval State] - Captures compliance/approval state per requirements. Linked to audit but atomic here. Example: 'approved'.
  approval_state String

  /// [Created Timestamp] - Automatic record creation, atomic timestamp for auditing. Fulfills audit trail requirements. Example: '2025-01-01T12:00:00Z'.
  created_at DateTime @db.Timestamptz

  /// [Updated Timestamp] - Last modified timestamp; supports audit logs and automation (atomic). Fulfills audit trail and version tracking requirements.
  updated_at DateTime @db.Timestamptz

  /// [Soft Delete] - Implements data retention and deletion compliance (nullable). Null if not deleted, otherwise soft-deleted for GDPR/KISA retention.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_products_seller_id ai_ecommerce_sellers @relation(fields: [seller_id], references: [id], onDelete: Cascade)

  ai_ecommerce_skus ai_ecommerce_skus[]
  ai_ecommerce_media ai_ecommerce_media[]
  ai_ecommerce_product_options ai_ecommerce_product_options[]

  @@index([seller_id])

  @@unique([title, seller_id])
  @@index([status, approval_state])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [SKU Entity] - This implements normalized stock-keeping unit granularity for each product variation (size, color, etc.), reflecting the Product Management and Inventory requirements. 
///
/// Each SKU represents a unique sellable product configuration, managed atomically. Linked to products, inventory, and optionally to product options (e.g., color, size).
///
/// For example, SKUs allow separate price, barcode, and inventory per variant; a T-shirt product could have several SKUs for each combination of size/color.
///
/// Key relationships: Links to product, inventory, and option tables. 3NF: All computed inventory/price is materialized only in MV tables.
/// Special behaviors: Uniqueness enforced per product and variant details.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_skus {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique identifier for the SKU. Required for unambiguous SKU-level operations and auditing, per inventory/fulfillment requirements.
  id String @id @db.Uuid

  /// [Product Foreign Key] - Denotes which product this SKU belongs to. Enforces referential integrity to ai_ecommerce_products, normalized 1:N product/SKU relationship.
  product_id String @db.Uuid

  /// [SKU Code] - System/barcode, unique within product. For business operations and integrations, 3NF atomic field. Example: 'SKU-121212-BLK-S'.
  code String

  /// [SKU Price] - Normalized unit price. Maintains price atomicity, no computed totals. Example: 129.99.
  price Float @db.DoublePrecision

  /// [Currency Code] - ISO 4217 code. Required for multicurrency; atomic (3NF). Example: 'KRW' or 'USD'.
  currency String

  /// [Active Flag] - True if this SKU is available for purchase, false otherwise. Implements lifecycle rules.
  is_active Boolean

  /// [SKU Created At] - Audit/timestamp. Required for 3NF, enables full traceability.
  created_at DateTime @db.Timestamptz

  /// [SKU Updated At] - Last modified timestamp; atomic for temporal consistency.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_skus_product_id ai_ecommerce_products @relation(fields: [product_id], references: [id], onDelete: Cascade)

  ai_ecommerce_inventories ai_ecommerce_inventories[]
  ai_ecommerce_product_options ai_ecommerce_product_options[]

  @@index([product_id])

  @@unique([code, product_id])
  @@index([is_active, price])
  @@index([code(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Category Entity] - Implements product category taxonomy and assignment per Product Management requirements.
///
/// Categories organize products into hierarchies (1:N, optional parent), enabling dynamic navigation, filtering, and AI-powered merchandising.
///
/// Example: Electronics, sub-category: AI Gadgets.
///
/// Normalization: Each category is atomic; M:N with products is managed by join table (not shown here for focus). Parent/child handled via parent_id FK (self-referencing).
///
/// Key relationships: Products (M:N via join or denormalized in MVs), self-reference for hierarchy, referenced by options/media.
/// Special behaviors: Category path/ordering determined by app logic, not by pre-calculated fields.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_categories {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique ID for every category. Required for taxonomy operations/support.
  id String @id @db.Uuid

  /// [Parent Category FK] - Enables recursive category structure (optional, nullable). 3NF: avoids denormalization.
  parent_id String? @db.Uuid

  /// [Category Name] - Atomic display name. Example: 'AI Home Robots'.
  name String

  /// [Description] - Category details; used for navigation/help, atomic, not aggregated.
  description String

  /// [Created Timestamp] - Category creation, for auditing and navigation.
  created_at DateTime @db.Timestamptz

  /// [Updated Timestamp] - Last modified timestamp, for change audits.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_categories_parent_id ai_ecommerce_categories? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive ai_ecommerce_categories[] @relation("recursive")

  @@index([parent_id])

  @@unique([name, parent_id])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Inventory Entity] - Implements per-SKU, per-location inventory tracking, as required in Product Management and Cart/Order System requirements.
///
/// Every inventory record is atomic: unique per SKU+location; no pre-calculated totals. Enables real-time inventory audit, tracked movements (snapshots/audit not shown here).
///
/// Example: SKU at warehouse 'Seoul #1' has 100 available units.
///
/// Key relationships: 1:N from SKU, location reference (string for normalization; multi-location in app logic).
/// Special behaviors: Audit traceability ensured by atomic fields and no aggregations.
///
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_inventories {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique per inventory record. Reference for all inventory operations.
  id String @id @db.Uuid

  /// [SKU FK] - Inventory is tracked for a specific SKU. Enforces strict referential integrity (app-level multi-location enabled).
  sku_id String @db.Uuid

  /// [Location Name] - Normalized, atomic warehouse or fulfillment location. Example: 'KR-Seoul-001'.
  location String

  /// [Current Available Quantity] - Non-aggregated count, always atomic per record. No pre-calculated totals allow full normalization. Example: 50.
  quantity_available Int @db.Integer

  /// [Reserved Quantity] - Quantity reserved (e.g., in open orders), atomic only for current status.
  quantity_reserved Int @db.Integer

  /// [Inventory Created Timestamp] - For audit trace. Enables temporal queries.
  created_at DateTime @db.Timestamptz

  /// [Inventory Updated Timestamp] - Per-transaction stock change tracking.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_inventories_sku_id ai_ecommerce_skus @relation(fields: [sku_id], references: [id], onDelete: Cascade)

  @@unique([sku_id, location])
  @@index([location])
}

/// [Media Entity] - Manages product/SKU/category-attached files and media (images, video, etc.), implementing requirements for rich multimedia and multilingual support from Product Management and System Overview.
///
/// Each attachment is atomic: URL, type, and owner entity type; strictly normalized.
///
/// Example: A product with 4 image URLs for different languages/views.
///
/// Key relationships: Linked to product, SKU, or category, 1:N to any owner via discriminated owner_type + owner_id.
/// Special behaviors: No denormalization; full localization handled by content fields where needed.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_media {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Each media asset has a globally unique ID, for robust referencing.
  id String @id @db.Uuid

  /// [Owner FK] - Points to ai_ecommerce_products.id, ai_ecommerce_skus.id, or ai_ecommerce_categories.id depending on owner_type.
  owner_id String @db.Uuid

  /// [Owner Type] - Discriminator for product, sku, or category. Only one allowed per row.
  owner_type String

  /// [Media URI] - Where the file is stored (CDN, S3, etc.). Business compliance: strictly atomic, never concatenated/aggregate field.
  uri String @db.VarChar(80000)

  /// [Media Type] - File type (image, video, etc.), atomic field for safe rendering. Example: 'image/png'.
  media_type String

  /// [Language Code] - Optional, ISO format for localization (e.g., 'en','ko').
  language String?

  /// [Created Timestamp] - Audit/item lifecycle field.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_media_owner_id ai_ecommerce_products @relation(fields: [owner_id], references: [id], onDelete: Cascade)

  @@unique([owner_id, uri])
  @@index([owner_type])
}

/// [Product Option Entity] - Implements normalized, atomic representation of selectable product options (e.g., color, size), according to Product Management and personalization requirements.
///
/// Allows dynamic, AI-powered option structures. Each record is atomic (no array fields, one row per product/option name/value pair).
///
/// Example: One record for 'Color/Red', another for 'Size/Large' for the same product.
///
/// Key relationships: Linked to product and (optionally) SKU, enforcing 3NF. Integrates with AI model/materialized views for ML-powered variant suggestion.
/// Special behaviors: Designed for maximum flexibility in personalization workflows.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_product_options {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique identifier for the option row.
  id String @id @db.Uuid

  /// [Product FK] - Each option points to the owning product. Strict referential integrity, no nullable references.
  product_id String @db.Uuid

  /// [SKU FK] - Option may be further scoped to a specific SKU (nullable if generic option).
  sku_id String? @db.Uuid

  /// [Option Name] - e.g., 'color', 'size', atomic field. Used for AI-driven variant personalization.
  option_name String

  /// [Option Value] - Selected value for this option (e.g., 'red', 'XL'), strictly atomic.
  option_value String

  /// [Created Timestamp] - Option audit record (atomic, for option version tracking).
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_options_product_id ai_ecommerce_products @relation(fields: [product_id], references: [id], onDelete: Cascade)
  fk_options_sku_id ai_ecommerce_skus? @relation(fields: [sku_id], references: [id], onDelete: Cascade)

  @@index([sku_id])

  @@unique([product_id, option_name, option_value, sku_id])
  @@index([option_name])
  @@index([option_value(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Product Compliance Rule Entity] - Implements explicit, normalized catalog for compliance rules that products must meet, per architecture and compliance requirements.
///
/// Each record defines an atomic compliance criterion (e.g., safety approval, age limit, localization), referenced by products for state enforcement.
///
/// Key relationships: Many-to-Many (implemented via join elsewhere). Each rule is atomic, managed independently for compliance upgrades/future law changes.
///
/// Example: Rule 'KFDA Safety' applies to multiple products, and a product may require passing several rules.
///
/// 3NF: Purely atomic rule definition, no pre-applied aggregates/state per product here.
/// Special behaviors: Approval state for each product/rule is handled in join (elsewhere).
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_product_compliance_rules {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique atomic rule identifier.
  id String @id @db.Uuid

  /// [Rule Name] - Canonical, atomic rule label. Example: 'No Sale Under 18'.
  rule_name String

  /// [Rule Description] - Explanation/details for this rule. Strictly normalized atomic text (no aggregation).
  description String

  /// [Created Timestamp] - For audit/compliance recordkeeping.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([rule_name])
}

/// [Product Tag Entity] - Implements atomic tag definition, strictly normalized per AI/product management guidelines. Enables flexible, user-defined and AI-generated tagging systems, referenced by products and MVs for search/recommendation.
///
/// For example, 'AI', 'Smart Home', or 'Eco-friendly' tag records, linked in M:N elsewhere. Pure 3NF: Tag state per product (assigned_by, date) is joined in mapping table, not here.
///
/// Key relationships: Many-to-many to products; referenced in analytics and personalization modules (cross-file integrity).
/// Special behaviors: Tag lifecycle managed separately from assignment/analytics.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_product_tags {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique tag ID, used platform-wide in tagging.
  id String @id @db.Uuid

  /// [Tag Name] - Atomic tag text, unique by business rule (per requirements). Example: 'AI', 'Smart Home'.
  name String

  /// [Created Timestamp] - Tag lifecycle atomic timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([name])
  @@index([created_at])
}

/// [Product Entity] - Implements the unified product definition and catalog management requirement from Product Management, System Overview, and Business Concepts documents. 
///
/// Defines the core sellable concept in the ecommerce platform. Strictly 3NF: all descriptive fields, variations, options, tags, and attachments are atomic or fully normalized in related tables. Enables scalable onboarding, flexible categorization (joins elsewhere), and compliance automation.
///
/// Example: A seller creates a product with title/description, assigns categories, uploads media, and is subject to approval flow. 
///
/// Key relationships: Owned by {\@link ai_ecommerce_seller}, 1:N to SKUs, options, media, tags, and compliance join models. 
/// Special behaviors: Lifecycle/approval states are enforced, full auditability through created/updated/deleted timestamps. All aggregates appear in MVs only.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_product {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique global product ID for systemwide referencing, auditing, and relational integrity. Required for strict 3NF and cross-reference by SKUs, inventory, categories, etc.
  id String @id @db.Uuid

  /// [Seller FK] - References owning seller ({\@link ai_ecommerce_seller}), enforcing seller-level product boundary and RBAC per Admin/Seller Management requirements. Non-null, normalized FK.
  seller_id String @db.Uuid

  /// [Product Title] - Human-friendly product display name. Multi-language via media. Strictly atomic per normalization. Example: 'AI Smart Watch'.
  title String

  /// [Product Description] - Rich, atomic product details. Multilingual/content fields go to attachments. Example: 'Next-gen AI watch with health tracking.'
  description String

  /// [Catalog Status] - Supports admin-seller workflow. Enum: draft, pending, published, archived. 3NF, atomic state transition only.
  status String

  /// [Approval State] - Tracks product verification/compliance state per auditing. Enum: pending, approved, rejected. 3NF, atomic state only.
  approval_state String

  /// [Created Timestamp] - Auditing, entity creation. Required for full traceability.
  created_at DateTime @db.Timestamptz

  /// [Updated Timestamp] - Auditing, updated entity. Normalized per 3NF.
  updated_at DateTime @db.Timestamptz

  /// [Soft Delete At] - Nullable for soft deletion/retention. Null if active, timestamp if deleted (for GDPR, compliance).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_product_seller_id ai_ecommerce_seller @relation(fields: [seller_id], references: [id], onDelete: Cascade)

  ai_ecommerce_sku ai_ecommerce_sku[]
  ai_ecommerce_product_option ai_ecommerce_product_option[]
  ai_ecommerce_inquiry ai_ecommerce_inquiry[]
  ai_ecommerce_review ai_ecommerce_review[]
  ai_ecommerce_forum_thread ai_ecommerce_forum_thread[]
  ai_ecommerce_favorite ai_ecommerce_favorite[]
  ai_ecommerce_recommendation ai_ecommerce_recommendation[]
  ai_ecommerce_personalization_analytics ai_ecommerce_personalization_analytics[]
  ai_ecommerce_mv_trending_products ai_ecommerce_mv_trending_products[]

  @@index([seller_id])

  @@unique([title, seller_id])
  @@index([status, approval_state])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [SKU Entity] - Defines atomic stock-keeping units for each product configuration (per Product Management, Inventory, and Fulfillment requirements).
///
/// Each SKU represents a unique combination of options for purchase, price, and fulfillment tracking. Enforces full normalization: price, code, and state are separate from aggregate logic (such as stock or sales count, which are in MVs).
///
/// Example: For a T-shirt, SKUs for sizes S/M/L and colors Red/Blue.
///
/// Key relationships: Each SKU belongs to one product (FK), referenced by options and inventory. 
/// Special behaviors: Strict business uniqueness per (code,product), activation ensures SKU sale state.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_sku {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique SKU record ID, required for transaction integrity and audit logging by Stock/Order systems.
  id String @id @db.Uuid

  /// [Product FK] - SKU parent reference. Enforces unambiguous link to {\@link ai_ecommerce_product}. Required and normalized.
  product_id String @db.Uuid

  /// [SKU Code] - Barcode or logical SKU identifier. Unique per (product_id), 3NF, atomic. Example: 'T12345-RD-M'.
  sku_code String

  /// [Unit Price] - Normalized single price for SKU. No calculated/discounted/total fields (handled elsewhere). Example: 199.0.
  price Float @db.DoublePrecision

  /// [Currency] - ISO 4217 code enforced for transactional accuracy. Example: 'USD'.
  currency String

  /// [Active] - Whether the SKU is for sale. Used in admin, seller, and order APIs for filtering. True = orderable.
  is_active Boolean

  /// [SKU Created At] - Auditing and temporal queries for inventory and sales.
  created_at DateTime @db.Timestamptz

  /// [SKU Updated At] - Record update/audit trail.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_sku_product_id ai_ecommerce_product @relation(fields: [product_id], references: [id], onDelete: Cascade)

  ai_ecommerce_inventory ai_ecommerce_inventory[]
  ai_ecommerce_product_option ai_ecommerce_product_option[]
  ai_ecommerce_cart_item ai_ecommerce_cart_item[]
  ai_ecommerce_order_item ai_ecommerce_order_item[]

  @@index([product_id])

  @@unique([sku_code, product_id])
  @@index([is_active])
  @@index([sku_code(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Category Entity] - Implements multi-level product categorization as required by Product Management.
///
/// Each category is atomic; parent-child tree structure enforced via self-referencing parent_id. 3NF: all hierarchy and display information separated, no aggregates. M:N product mapping handled in separate join table (not here).
///
/// Example: Electronics > Wearables > Watches.
///
/// Key relationships: Self-referential parent_id, atomic name/description.
/// Special behaviors: Sibling uniqueness per parent enforced; app-level navigation/hierarchy handled in API.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_category {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Globally unique category ID for all taxonomy and navigation lookups.
  id String @id @db.Uuid

  /// [Parent Category FK] - Nullable; allows for nested taxonomies. Null for root, otherwise recurses to id. 3NF: atomic relation only.
  parent_id String? @db.Uuid

  /// [Category Name] - Display-friendly display name, unique under parent. Example: 'Electronics'.
  name String

  /// [Category Description] - Human-friendly category context. No pre-aggregated content. Example: 'Smart devices and accessories.'
  description String

  /// [Created Timestamp] - When category entered system. Required for queries/audit.
  created_at DateTime @db.Timestamptz

  /// [Updated Timestamp] - Track changes for audit/API navigation.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_category_parent_id ai_ecommerce_category? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive ai_ecommerce_category[] @relation("recursive")
  ai_ecommerce_forum_thread ai_ecommerce_forum_thread[]

  @@index([parent_id])

  @@unique([name, parent_id])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Inventory Entity] - Implements per-SKU, per-location, atomic inventory levels for real-time tracking and fulfillment, as required by Cart/Order/Product Management requirements. 3NF: No aggregate or calculated fields in this table.
///
/// Each record represents stock counts for a given SKU at a specific location (e.g., warehouse, store). All movements and derived counts are handled in audit tables/views.
///
/// Example: SKU T12345-RD-M has 21 units at Seoul warehouse.
///
/// Key relationships: Each entry references a valid SKU (not product), and location as atomic string. 
/// Special behaviors: Unique record per (SKU, location). No pre-calculation; transactional accuracy only.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_inventory {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique inventory ID for traceability/auditing of stock movements.
  id String @id @db.Uuid

  /// [SKU FK] - Strictly references SKU for per-variant/option/warehouse tracking. Required by 3NF and stock audit.
  sku_id String @db.Uuid

  /// [Location] - Human-friendly location code. Unique per SKU. Example: 'KR-Seoul-01'.
  location String

  /// [Available Quantity] - Atomic current inventory. No pre-computed, only system state. Example: 20.
  quantity_available Int @db.Integer

  /// [Reserved Quantity] - Amount locked by orders but not shipped (atomic only, not aggregate).
  quantity_reserved Int @db.Integer

  /// [Created Timestamp] - For full auditability & compliance.
  created_at DateTime @db.Timestamptz

  /// [Updated Timestamp] - Enables real-time/temporal inventory queries.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_inventory_sku_id ai_ecommerce_sku @relation(fields: [sku_id], references: [id], onDelete: Cascade)

  @@unique([sku_id, location])
  @@index([location])
}

/// [Product Option Entity] - Provides atomic, fully normalized attribute options (size, color, etc) for each product as required in Product Management and personalization requirements. 
///
/// Enables dynamic, AI-powered option mapping and variant construction. Each record is atomic: one row per option name/value. 3NF:   no arrays/aggregates; all relationships explicit per product and (optional) SKU.
///
/// Example: Option: color=blue for product X, or size=large scoped to a specific SKU.
///
/// Key relationships: Always references product; optionally, a specific SKU for granular configuration. Used by product onboarding, configuration UIs, and AI suggesters.
/// Special behaviors: Unique per (product, option_name, option_value, sku_id).
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_product_option {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - For traceability, option editing, AI learning/analytics.
  id String @id @db.Uuid

  /// [Product FK] - Option always has a parent product. Strict foreign key to enforce catalog integrity.
  product_id String @db.Uuid

  /// [SKU FK] - Nullable; if present, this option applies to a specific SKU (for highly-specific variants only).
  sku_id String? @db.Uuid

  /// [Option Name] - E.g., 'size', 'color', 'material'. Always atomic per 3NF.
  option_name String

  /// [Option Value] - E.g., 'Large', 'Red', 'Plastic'. Normalized and atomic.
  option_value String

  /// [Created Timestamp] - Audit purposes for option evolution/analysis.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_option_product_id ai_ecommerce_product @relation(fields: [product_id], references: [id], onDelete: Cascade)
  fk_option_sku_id ai_ecommerce_sku? @relation(fields: [sku_id], references: [id], onDelete: Cascade)

  @@index([sku_id])

  @@unique([product_id, option_name, option_value, sku_id])
  @@index([option_name])
  @@index([option_value(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Product Compliance Rule Entity] - Catalogs atomic, normalized compliance business rules (safety, localization, etc) for products. Fulfills Compliance and Product Management requirements. 
///
/// Each record is an atomic rule; mapping of products to rules appears in join elsewhere. Used by admin audit and compliance, never by product itself directly.
///
/// Example: Rule 'KFDA Certified', 'Age > 18 Only', etc.
///
/// Key relationships: Standalone, many-to-many join with product or MV tables. 
/// Special behaviors: All approval/violation status handled atomically in join or audit tables.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_product_compliance_rule {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique compliance rule ID for systemwide normalization.
  id String @id @db.Uuid

  /// [Rule Name] - Canonical, atomic rule label. Example: 'EU Toys Safety'.
  rule_name String

  /// [Rule Description] - Plain, atomic text for audit/compliance explanation. No aggregates. Example: 'Must comply with EN71 for toys.'
  description String

  /// [Created Timestamp] - For audit, audit rule lifecycle/evolution.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([rule_name])
}

/// [Product Tag Entity] - Provides atomic tag definitions for flexible, AI-powered and user-organizable product tagging per Product Management and Personalization requirements. Each tag is a single, normalized label used as a reference in join tables (M:N relationship with products, handled elsewhere).
///
/// Example: Tags 'AI', 'Green', 'Gift Ideas' for recommendation and navigation.
///
/// Key relationships: Referenced in M:N joins, audit, analytics, personalization modules.
/// Special behaviors: Tag assignment/analytics is external—this entity is canonical registry only.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_product_tag {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Systemwide unique tag ID for joins, analytics, and display.
  id String @id @db.Uuid

  /// [Tag Name] - Business-canonical tag, enforced unique. Examples: 'Eco-Friendly'.
  name String

  /// [Tag Created At] - Tag lifecycle timestamp (audit, analytics UX).
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([name])
  @@index([created_at])
}

schemas.schema-04_community.prisma:
/// [Product and Order Inquiries] - Implements requirements from '06_ai_ecommerce_inquiry_review_forum.md'. Enables customers to ask product/order questions and receive seller/admin responses. Maintains strict normalization by separating main inquiry from comments/replies and enforcing linking to other domain entities by ID. Supports audit and compliance workflows.
///
/// @namespace Community
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_inquiry {
  //----
  // COLUMNS
  //----
  /// [Inquiry Identifier] - Unique, stable, atomic primary key for each inquiry entry. Enables precise referencing and audit preservation.
  id String @id @db.Uuid

  /// [Inquiry Author] - FK to ai_ecommerce_customer. Each inquiry must refer to its creator.
  customer_id String @db.Uuid

  /// [Product Reference] - FK to ai_ecommerce_product (the item inquired on).
  product_id String @db.Uuid

  /// [Linked Order] - FK to ai_ecommerce_order if relevant; null if product-only inquiry.
  order_id String? @db.Uuid

  /// [Inquiry Title] - Required, atomic.
  title String

  /// [Inquiry Message] - Required, atomic.
  body String

  /// [Inquiry Status] - Workflow indicator. Enum enforced in app code.
  status String

  /// [Visibility] - Marks public/private visibility.
  is_private Boolean

  /// [Created Time] - Atomic timestamp.
  created_at DateTime @db.Timestamptz

  /// [Updated Time] - Last change timestamp.
  updated_at DateTime @db.Timestamptz

  /// [Soft Delete] - Null if active; timestamp if deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer ai_ecommerce_customer @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  product ai_ecommerce_product @relation(fields: [product_id], references: [id], onDelete: Cascade)
  order ai_ecommerce_order? @relation(fields: [order_id], references: [id], onDelete: Cascade)

  ai_ecommerce_comment ai_ecommerce_comment[]
  ai_ecommerce_reply ai_ecommerce_reply[]
  ai_ecommerce_inquiry_snapshot ai_ecommerce_inquiry_snapshot[]
  mv_community_last_activity mv_community_last_activity[]

  @@index([order_id])

  @@index([customer_id, created_at])
  @@index([product_id, status])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Product Review] - Enables verified product review and feedback, enforcing strict normalization per '06_ai_ecommerce_inquiry_review_forum.md'. Each review is tied to a specific order and customer. All text fields atomic. One review per customer/product/order tuple allowed (enforced via unique index).
///
/// @namespace Community
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_review {
  //----
  // COLUMNS
  //----
  /// [Review Identifier] - Stable, atomic PK for each review.
  id String @id @db.Uuid

  /// [Review Author] - FK to ai_ecommerce_customer.
  customer_id String @db.Uuid

  /// [Product reviewed] - FK to ai_ecommerce_product.
  product_id String @db.Uuid

  /// [Order verification] - FK to ai_ecommerce_order (ensures verified purchase for reviews).
  order_id String @db.Uuid

  /// [Star Rating] - Atomic review rating.
  rating Int @db.Integer

  /// [Review Title] - Optional.
  title String?

  /// [Review Content] - Main review text.
  body String

  /// [Verified Status] - True if linked to an order.
  is_verified Boolean

  /// [Review Privacy] - Optional privacy toggle.
  is_private Boolean

  /// [Created Time] - Timestamp.
  created_at DateTime @db.Timestamptz

  /// [Updated Time] - Timestamp.
  updated_at DateTime @db.Timestamptz

  /// [Deleted Time] - Indicates soft delete.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer ai_ecommerce_customer @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  product ai_ecommerce_product @relation(fields: [product_id], references: [id], onDelete: Cascade)
  order ai_ecommerce_order @relation(fields: [order_id], references: [id], onDelete: Cascade)

  ai_ecommerce_comment ai_ecommerce_comment[]
  ai_ecommerce_reply ai_ecommerce_reply[]
  ai_ecommerce_report ai_ecommerce_report[]
  ai_ecommerce_moderation_action ai_ecommerce_moderation_action[]
  ai_ecommerce_review_snapshot ai_ecommerce_review_snapshot[]
  mv_community_last_activity mv_community_last_activity[]

  @@index([order_id])

  @@unique([customer_id, product_id, order_id])
  @@index([product_id, created_at])
  @@index([customer_id])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Forum Thread] - Top-level community thread or Q&A. Strictly normalized, each thread links back to category/product if applicable. Text and status stored atomically. One thread may be contextually tied to product/category, else global/community.
///
/// @namespace Community
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_forum_thread {
  //----
  // COLUMNS
  //----
  /// [Forum Thread Identifier] - PK for forum/Q&A topics.
  id String @id @db.Uuid

  /// [Thread Author] - FK to ai_ecommerce_customer.
  customer_id String @db.Uuid

  /// [Product Context] - FK to product; null if not product specific.
  product_id String? @db.Uuid

  /// [Category Context] - FK to category; null if not category-specific.
  category_id String? @db.Uuid

  /// [Thread Title] - Required atomic.
  title String

  /// [Thread Body] - Required atomic.
  body String

  /// [Thread Status] - E.g., 'open', 'closed', etc.
  status String

  /// [Pinned] - Moderation sticky display.
  is_pinned Boolean

  /// [Thread Privacy] - For private/members-only boards.
  is_private Boolean

  /// [Created Time] - Atomic timestamp.
  created_at DateTime @db.Timestamptz

  /// [Updated Time] - Atomic timestamp.
  updated_at DateTime @db.Timestamptz

  /// [Soft Delete] - If deleted, timestamp.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer ai_ecommerce_customer @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  product ai_ecommerce_product? @relation(fields: [product_id], references: [id], onDelete: Cascade)
  category ai_ecommerce_category? @relation(fields: [category_id], references: [id], onDelete: Cascade)

  ai_ecommerce_comment ai_ecommerce_comment[]
  ai_ecommerce_reply ai_ecommerce_reply[]
  ai_ecommerce_report ai_ecommerce_report[]
  ai_ecommerce_moderation_action ai_ecommerce_moderation_action[]
  mv_community_last_activity mv_community_last_activity[]

  @@index([customer_id])

  @@index([product_id, created_at])
  @@index([category_id, created_at])
  @@index([status])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Universal Comment] - Atomic comment on one of: thread, inquiry, review. Parent-id enables threading up to 3 levels. All relationships explicit by FK; schema ensures strict normalization and rejects denormalization chains.
///
/// @namespace Community
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_comment {
  //----
  // COLUMNS
  //----
  /// [Comment Identifier] - PK for comment row.
  id String @id @db.Uuid

  /// [Comment Author] - FK to ai_ecommerce_customer.
  customer_id String @db.Uuid

  /// [Parent] - Parent comment FK, null if top-level.
  parent_id String? @db.Uuid

  /// [Thread] - FK to forum_thread, if this is thread comment.
  forum_thread_id String? @db.Uuid

  /// [Inquiry] - FK to inquiry if this is inquiry comment.
  inquiry_id String? @db.Uuid

  /// [Review] - FK to review if this is review comment.
  review_id String? @db.Uuid

  /// [Comment Body] - Main atomic text.
  body String

  /// [Depth] - Integer: top=0, reply=1, etc.
  depth Int @db.Integer

  /// [Created Timestamp] - Row creation time.
  created_at DateTime @db.Timestamptz

  /// [Updated Timestamp] - Row last updated.
  updated_at DateTime @db.Timestamptz

  /// [Soft Delete] - Timestamp if soft deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer ai_ecommerce_customer @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  parent ai_ecommerce_comment? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)
  forum_thread ai_ecommerce_forum_thread? @relation(fields: [forum_thread_id], references: [id], onDelete: Cascade)
  inquiry ai_ecommerce_inquiry? @relation(fields: [inquiry_id], references: [id], onDelete: Cascade)
  review ai_ecommerce_review? @relation(fields: [review_id], references: [id], onDelete: Cascade)

  recursive ai_ecommerce_comment[] @relation("recursive")
  ai_ecommerce_reply ai_ecommerce_reply[]
  ai_ecommerce_report ai_ecommerce_report[]
  ai_ecommerce_moderation_action ai_ecommerce_moderation_action[]
  mv_community_last_activity mv_community_last_activity[]

  @@index([customer_id])
  @@index([parent_id])

  @@index([forum_thread_id, created_at])
  @@index([inquiry_id, created_at])
  @@index([review_id, created_at])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Seller/Admin Reply] - Formal response to inquiry, comment, thread, or review. At most one of inquiry_id, review_id, forum_thread_id, comment_id set for target linkage. Author is seller or admin, not customer. Maintains strict normalization: no role denormalization; references by FK only.
///
/// @namespace Community
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_reply {
  //----
  // COLUMNS
  //----
  /// [Reply Identifier] - PK for reply row.
  id String @id @db.Uuid

  /// [Seller Author] - FK to ai_ecommerce_seller.
  seller_id String? @db.Uuid

  /// [Admin Author] - FK to ai_ecommerce_administrator.
  administrator_id String? @db.Uuid

  /// [Inquiry Target] - FK if replying to inquiry.
  inquiry_id String? @db.Uuid

  /// [Review Target] - FK if replying to review.
  review_id String? @db.Uuid

  /// [Forum Thread Target] - FK if replying to thread.
  forum_thread_id String? @db.Uuid

  /// [Comment Target] - FK if replying to comment.
  comment_id String? @db.Uuid

  /// [Reply Body] - Formal text, atomic.
  body String

  /// [Created At] - Timestamp when reply made.
  created_at DateTime @db.Timestamptz

  /// [Updated At] - Last row update.
  updated_at DateTime @db.Timestamptz

  /// [Soft Delete] - Timestamp if deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  seller ai_ecommerce_seller? @relation(fields: [seller_id], references: [id], onDelete: Cascade)
  administrator ai_ecommerce_administrator? @relation(fields: [administrator_id], references: [id], onDelete: Cascade)
  inquiry ai_ecommerce_inquiry? @relation(fields: [inquiry_id], references: [id], onDelete: Cascade)
  review ai_ecommerce_review? @relation(fields: [review_id], references: [id], onDelete: Cascade)
  forum_thread ai_ecommerce_forum_thread? @relation(fields: [forum_thread_id], references: [id], onDelete: Cascade)
  comment ai_ecommerce_comment? @relation(fields: [comment_id], references: [id], onDelete: Cascade)

  @@index([seller_id])
  @@index([administrator_id])
  @@index([forum_thread_id])
  @@index([comment_id])

  @@index([inquiry_id, created_at])
  @@index([review_id, created_at])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Abuse Report] - Customer-initiated reporting for abuse, spam, violation, linked by FKs to affected comment, review, or thread only. Maintains full normalization. Only one target FK per report row (others must be null).
///
/// @namespace Community
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_report {
  //----
  // COLUMNS
  //----
  /// [Report PK] - Unique row key.
  id String @id @db.Uuid

  /// [Reporter] - FK, who reported.
  reporter_id String @db.Uuid

  /// [Reported Comment] - FK if comment targeted.
  target_comment_id String? @db.Uuid

  /// [Reported Review] - FK if review targeted.
  target_review_id String? @db.Uuid

  /// [Reported Thread] - FK if forum thread targeted.
  target_forum_thread_id String? @db.Uuid

  /// [Resolver] - Admin FK for resolution.
  resolved_by_id String? @db.Uuid

  /// [Report Reason] - Short, atomic.
  reason String

  /// [Report Status] - Workflow step; enum in app code.
  status String

  /// [Detailed Comment] - Reporter free-form.
  detailed_comment String?

  /// [Creation Timestamp] - Atomic.
  created_at DateTime @db.Timestamptz

  /// [Resolution Timestamp] - Null if unresolved.
  resolved_at DateTime? @db.Timestamptz

  /// [Soft Delete] - If deleted, timestamp.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  reporter ai_ecommerce_customer @relation(fields: [reporter_id], references: [id], onDelete: Cascade)
  target_comment ai_ecommerce_comment? @relation(fields: [target_comment_id], references: [id], onDelete: Cascade)
  target_review ai_ecommerce_review? @relation(fields: [target_review_id], references: [id], onDelete: Cascade)
  target_forum_thread ai_ecommerce_forum_thread? @relation(fields: [target_forum_thread_id], references: [id], onDelete: Cascade)
  resolved_by ai_ecommerce_administrator? @relation(fields: [resolved_by_id], references: [id], onDelete: Cascade)

  @@index([target_comment_id])
  @@index([target_review_id])
  @@index([target_forum_thread_id])
  @@index([resolved_by_id])

  @@index([status, created_at])
  @@index([reporter_id, created_at])
  @@index([reason(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([detailed_comment(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Moderation Action/Audit Log] - All admin/seller moderation of reports/violations, strictly normalized. Each action targets only one content type FK at a time; rationale always provided.
///
/// @namespace Community
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_moderation_action {
  //----
  // COLUMNS
  //----
  /// [Moderation Action PK] - Row unique ID.
  id String @id @db.Uuid

  /// [Action Performer] - Admin actor FK.
  administrator_id String @db.Uuid

  /// [Target Comment] - FK to comment.
  comment_id String? @db.Uuid

  /// [Target Review] - FK to review.
  review_id String? @db.Uuid

  /// [Target Thread] - FK to forum thread.
  thread_id String? @db.Uuid

  /// [Action Type] - Action performed; enum in app code.
  action_type String

  /// [Rationale] - Justification for moderate action.
  rationale String

  /// [Reversed] - If action reversed, true.
  reversed Boolean

  /// [Action Time] - When action taken.
  created_at DateTime @db.Timestamptz

  /// [Reversal Time] - Null unless reversed.
  reversed_at DateTime? @db.Timestamptz

  /// [Soft Delete] - Audit-complete row deletion.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  administrator ai_ecommerce_administrator @relation(fields: [administrator_id], references: [id], onDelete: Cascade)
  comment ai_ecommerce_comment? @relation(fields: [comment_id], references: [id], onDelete: Cascade)
  review ai_ecommerce_review? @relation(fields: [review_id], references: [id], onDelete: Cascade)
  thread ai_ecommerce_forum_thread? @relation(fields: [thread_id], references: [id], onDelete: Cascade)

  @@index([review_id])
  @@index([thread_id])

  @@index([administrator_id, created_at])
  @@index([comment_id, created_at])
  @@index([rationale(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Inquiry Snapshot] - Full snapshot pattern for audit/history/rollback on ai_ecommerce_inquiry. Strictly append-only, uneditable, captures old state at each edit/change. Linked to inquiry and user who triggered the change. All snapshot fields atomic, denormalized for performance/history only.
///
/// @namespace Community
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_inquiry_snapshot {
  //----
  // COLUMNS
  //----
  /// Unique PK for every snapshot row.
  id String @id @db.Uuid

  /// [Snapshot of Inquiry] - FK to inquired entity.
  inquiry_id String @db.Uuid

  /// [Snapshot Actor] - User who triggered history capture.
  captured_by_id String @db.Uuid

  /// [Old Title] - Title state in history.
  title String

  /// [Old Body] - Content in snapshot.
  body String

  /// [Historical Status] - Point-in-time.
  status String

  /// [Reason] - Reason for snapshot; e.g., 'edit', 'status change', etc.
  snapshot_reason String

  /// [Snapshot Timestamp] - Atomic, append-only.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  inquiry ai_ecommerce_inquiry @relation(fields: [inquiry_id], references: [id], onDelete: Cascade)
  captured_by ai_ecommerce_customer @relation(fields: [captured_by_id], references: [id], onDelete: Cascade)

  @@index([captured_by_id])

  @@index([inquiry_id, created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Review Snapshot] - Captures history of old review states. Audit/rollback/append-only; all foreign keys explicit. No denormalization beyond history/data lineage. Each snapshot points to unique review row and actor user.
///
/// @namespace Community
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_review_snapshot {
  //----
  // COLUMNS
  //----
  /// PK for review snapshot.
  id String @id @db.Uuid

  /// [Target Review] - Which review snapshot tracks.
  review_id String @db.Uuid

  /// [Snapshot Actor] - Who triggered the snapshot.
  captured_by_id String @db.Uuid

  /// [Old Title] - Null if original review had no title.
  title String?

  /// [Old Body] - Snapshot review text.
  body String

  /// [Historical Rating] - Point-in-time rating.
  rating Int @db.Integer

  /// [Old Status] - Status at snapshot time.
  status String

  /// [Why] - Why this snapshot exists.
  snapshot_reason String

  /// [Snapshot Timestamp] - Atomic timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  review ai_ecommerce_review @relation(fields: [review_id], references: [id], onDelete: Cascade)
  captured_by ai_ecommerce_customer @relation(fields: [captured_by_id], references: [id], onDelete: Cascade)

  @@index([captured_by_id])

  @@index([review_id, created_at])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Materialized View: Last Community Activity] - Read-only, denormalized reporting of last content creation per user/entity. Used by dashboards, AI/ranking systems, and community operator analytics. All references by FK; calculated fields atomic and for read/performance only. Never updated by business domain logic directly.
///
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model mv_community_last_activity {
  //----
  // COLUMNS
  //----
  /// Materialized row PK.
  id String @id @db.Uuid

  /// [User for activity scope].
  customer_id String? @db.Uuid

  /// [Latest Thread Scope].
  thread_id String? @db.Uuid

  /// [Latest comment by this user/topic].
  comment_id String? @db.Uuid

  /// [Latest inquiry, if any].
  inquiry_id String? @db.Uuid

  /// [Latest review, if any].
  review_id String? @db.Uuid

  /// [Activity Type] - Enum: comment, review, thread, inquiry, etc.
  last_activity_type String

  /// [Last Activity] - Timestamp for reporting/analytics.
  last_activity_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer ai_ecommerce_customer? @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  thread ai_ecommerce_forum_thread? @relation(fields: [thread_id], references: [id], onDelete: Cascade)
  comment ai_ecommerce_comment? @relation(fields: [comment_id], references: [id], onDelete: Cascade)
  inquiry ai_ecommerce_inquiry? @relation(fields: [inquiry_id], references: [id], onDelete: Cascade)
  review ai_ecommerce_review? @relation(fields: [review_id], references: [id], onDelete: Cascade)

  @@index([thread_id])
  @@index([comment_id])
  @@index([inquiry_id])
  @@index([review_id])

  @@index([customer_id, last_activity_at])
}

schemas.schema-05_cart_order.prisma:
/// [Cart Purpose] - This implements the persistent shopping cart requirement from the AI E-Commerce Cart & Order System document.
///
/// A cart represents a customer's temporary, device/platform-synchronized collection of products intended for purchase, maintained before checkout. Maintains 3NF compliance by isolating temporary cart state from finalized order records, and by referencing only user and item entities via foreign keys. For example, customers can add, update, or remove products in their carts on mobile or web, retrieve cart items on login, and merge guest carts.
///
/// Key relationships: References customer (ai_ecommerce_customer), contains many ai_ecommerce_cart_items. Does not duplicate order data. Special behaviors: Ensures each customer has multiple carts (for different sessions), with soft-delete support and device context.
///
/// @namespace CartOrder
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_cart {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Implements unique cart identity per instance.
  ///
  /// Business meaning: Uniquely identifies a cart in the system, regardless of customer, device, or session. Ensures normalization by preventing duplication or ambiguity. For example, required in all cart CRUD queries and foreign key references. Cannot be null, auto-generated.
  id String @id @db.Uuid

  /// [Customer Foreign Key] - Implements association to cart owner.
  ///
  /// Business meaning: Links this cart to the owning customer profile. Ensures normalization by storing only the reference, avoiding duplication of customer info. For example, used to fetch all carts or recovered sessions for a given user. Cannot be null.
  customer_id String @db.Uuid

  /// [Device Context] - Implements device/session-specific state requirement.
  ///
  /// Stores info like device type, browser fingerprint, or guest/registered status. Ensures normalization by not repeating device details in related records. For example, tracks whether cart originated from mobile app or guest session.
  device_context String?

  /// [Cart Status] - Implements cart state transitions (e.g., active, merged, expired) required for recovery and audit.
  ///
