  /// [FK to Customer] - Links order to buyer. Prevents duplication by referencing atomic customer record.
  customer_id String @db.Uuid

  /// [FK to Cart] - Links to originating cart for audit/tracing purposes. Example: Used for reconstructing user intent.
  cart_id String @db.Uuid

  /// [Shipping FK] - Links to delivery address for recordkeeping and logistics.
  shipping_address_id String @db.Uuid

  /// [Order Status] - Implements order lifecycle status tracking (pending, paid, shipped, etc.), enabling clear state transitions and queries.
  order_status String

