/// [Order Item Purpose] - Tracks each SKU/quantity in an order at checkout, following strict 3NF.
///
/// Each row records a product/variation purchased, with atomic references and purchase quantity. No duplication of pricing or product metadata; all derived/calculated fields are forbidden. Used for fulfillment, analytics, return matching.
///
/// Key relationships: Required link to ai_ecommerce_order and ai_ecommerce_sku. Special behaviors: Does not support calculated total or cached values.
///
/// @namespace CartOrder
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_order_item {
  //----
  // COLUMNS
  //----
  /// [Order Item PK] - Uniquely identifies this line item for partial fulfillment, returns, and audit logic.
  id String @id @db.Uuid

  /// [Order FK] - Links item to parent order for grouping and status tracking.
  order_id String @db.Uuid

  /// [SKU FK] - Identifies the sold product/variation SKU atomically.
  sku_id String @db.Uuid

  /// [Purchased Quantity] - Number of this item purchased in the order, to support fulfillment, returns, analytics. Must be atomic.
  quantity Int @db.Integer

