model ai_ecommerce_payment {
  //----
  // COLUMNS
  //----
  /// [Payment PK] - Uniquely identifies a payment for audit, refund, or reconciliation.
  id String @id @db.Uuid

  /// [Transaction Amount] - Atomic payment amount for audit. No total, no calculations here.
  amount Float @db.DoublePrecision

  /// [Payment Provider] - Payment integration reference string (e.g., 'stripe', 'toss', 'paypal'). No calcs or external duplication.
  provider String

  /// [Method] - The actual payment channel used (e.g., credit_card, bank_transfer). For analytics only.
  method String

  /// [Provider Reference] - External processor ID if available. Null if not provided.
  payment_reference String?

  /// [Status] - Payment state at this event (pending, completed, failed, cancelled, etc.). Enables reattempts, dispute management.
  status String

  /// [Created Timestamp] - For traceability and compliance.
  created_at DateTime @db.Timestamptz

  /// [Updated Timestamp] - For refunds, disputes, and reconciliation flows.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_ecommerce_wallet_transaction ai_ecommerce_wallet_transaction[]

  @@unique([payment_reference])
}

/// [Order Status Log Purpose] - Implements an immutable, additive audit trail of all order status changes, supporting regulatory/compliance requirements for e-commerce platforms.
///
/// Each record represents a single status transition for an order (e.g., 'pending' → 'paid'), with actor, actor type, and timestamp. All audit logic is separated from live order data, enforcing strict normalization and minimizing update anomalies.
///
/// Key relationships: ai_ecommerce_order FK (target order); actor_id with actor_type supports references to customer, seller, or administrator (for multi-actor flows). Special behaviors: Appends only; never updated after creation.
///
/// @namespace CartOrder
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_order_status_log {
  //----
  // COLUMNS
  //----
  /// [Status Log PK] - Uniquely identifies this log for each state change entry.
  id String @id @db.Uuid

  /// [Order FK] - Order being changed.
  order_id String @db.Uuid

  /// [Old Status] - Previous order status for change tracking, e.g., 'pending'.
  old_status String

  /// [New Status] - New status after transition.
  new_status String

  /// [Actor ID] - Who made the change (references customer, seller, admin based on context; polymorphic pattern).
  actor_id String @db.Uuid

  /// [Actor Type] - Role of the actor: 'customer', 'seller', 'administrator'. Analytical/trace purpose only.
  actor_type String

  /// [Changed At] - Transition timestamp, for legal/audit trail.
  changed_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_ecommerce_order_status_log_order ai_ecommerce_order @relation(fields: [order_id], references: [id], onDelete: Cascade)

  @@index([order_id, changed_at])
}

/// [Shipment Purpose] - Tracks outbound shipment details for each order, as required for fulfillment and delivery audit.
///
/// A shipment record is created per order, containing external tracking, carrier, and shipping status, not duplicating item, customer, or pricing data. Maintains 3NF compliance.
///
/// Key relationships: Order FK, optional carrier/provider string. Special behaviors: Supports multi-stage tracking and addresses, without denormalization of totals.
///
/// @namespace CartOrder
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_shipment {
  //----
  // COLUMNS
  //----
  /// [Shipment PK] - Unique shipment tracking for audit, return, status sync.
  id String @id @db.Uuid

  /// [FK to Order] - Links shipment to its order. 1:1 mapping at regular e-commerce order level.
  order_id String @db.Uuid

  /// [Carrier] - The delivery company/provider name. Optional; can be null if ship-from-store or digital.
  carrier String?

  /// [Tracking Number] - Carrier-provided shipment code for customer tracking.
  tracking_number String?

  /// [Shipping Status] - Current status of shipment independent of order status (e.g., pending, shipped, delivered, returned, etc.).
  shipping_status String

  /// [Shipped Timestamp] - When the package was handed to carrier.
  shipped_at DateTime? @db.Timestamptz

  /// [Delivered Timestamp] - When shipment confirmed delivered.
  delivered_at DateTime? @db.Timestamptz

  /// [Created] - When shipment record entered system.
  created_at DateTime @db.Timestamptz

  /// [Last Update] - When shipping info last modified by system, admin, or carrier sync.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_ecommerce_shipment_order ai_ecommerce_order @relation(fields: [order_id], references: [id], onDelete: Cascade)

  @@unique([order_id])
  @@index([order_id, carrier])
}

/// [Return Request Purpose] - Implements the customer-initiated return/cancellation workflow per compliance regulation and e-commerce expectation.
///
/// Each record represents a distinct request for either return or cancellation, with reference to order and customer, including reason, status, and timestamps. 3NF is enforced by isolating request data from main order rows, preventing transitive duplications.
///
/// Key relationships: ai_ecommerce_order, customer; target item(s) by order_item_id if required in extensions. Special behaviors: Tracked separately from order; each return/cancel tracked atomically.
///
/// @namespace CartOrder
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_return_request {
  //----
  // COLUMNS
  //----
  /// [Return Request PK] - Unique per request, supports auditing of customer claims.
  id String @id @db.Uuid

  /// [Order FK] - Identifies the target order for return/cancellation logic.
  order_id String @db.Uuid

  /// [Customer FK] - Initiator of the request.
  customer_id String @db.Uuid

  /// [Request Status] - Tracks return approval, pending, denied, or completed state in atomic field.
  status String

  /// [Request Type] - Identifies 'return', 'cancellation', or other request variant.
  request_type String

  /// [Reason] - Optional customer-provided explanation, can be null for 'no reason' selected.
  reason String?

  /// [Created] - When customer made the request.
  created_at DateTime @db.Timestamptz

  /// [Last Updated] - Audit trail timestamp for each request update.
  updated_at DateTime @db.Timestamptz

