  //----
  // RELATIONS
  //----
  customer_wallet ai_ecommerce_customer @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  ai_ecommerce_wallet_transaction ai_ecommerce_wallet_transaction[]

  @@unique([customer_id, currency_code])
