  //----
  // COLUMNS
  //----
  /// [Primary key] - Unique rule definition.
  id String @id @db.Uuid

  /// [Type] - E.g., 'fixed_amount', 'percentage', 'stacking', etc.
  rule_type String

  /// [Description] - Human-readable summary of the rule.
  description String

