import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_sellers } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_sellers";
import type { IPageai_ecommerce_sellers } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageai_ecommerce_sellers";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test the retrieval of a paginated and filterable list of sellers for the admin interface.
 *
 * Validates:
 * 1. Default paginated seller list retrieval and basic metadata check
 * 2. Filtering by status (e.g., 'active', 'deleted') matches data
 * 3. Free-text search filter for no-match edge case
 * 4. Pagination boundaries (page request beyond total page count returns empty data)
 * 5. Sorting and sort metadata (descending by created_at)
 * 6. Invalid filter value (bad status) triggers an error
 *
 * Steps:
 * 1. Retrieve seller list with default (empty) filters; check key fields and pagination shape
 * 2. Filter by status ('active' and 'deleted'); check deleted_at field logic reflects filter
 * 3. Search term guaranteed to match nothing → data.length=0
 * 4. Pagination page request out-of-bounds yields empty data
 * 5. Sorting by created_at desc and check sorting order in returned data
 * 6. Supply a malformed value for status filter and verify error handling
 */
export async function test_api_ai_ecommerce_sellers_test_list_sellers_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Default: paginated, no filter
  const defaultResp = await api.functional.ai_ecommerce.sellers.patch(connection, {
    body: {} as ai_ecommerce_sellers.IRequest
  });
  typia.assert(defaultResp);
  TestValidator.predicate("all seller fields present and allowed")(defaultResp.data.every(
    (seller) => seller.hasOwnProperty("id") && seller.hasOwnProperty("profile_id")
      && seller.hasOwnProperty("created_at") && seller.hasOwnProperty("updated_at")
  ));

  // 2. Filter by status ('active' and 'deleted')
  for (const status of ["active", "deleted"]) {
    const resp = await api.functional.ai_ecommerce.sellers.patch(connection, {
      body: { status } as ai_ecommerce_sellers.IRequest
    });
    typia.assert(resp);
    if (resp.data.length > 0) {
      TestValidator.predicate("status matches filter")(
        resp.data.every((s) => (status === "active" ? s.deleted_at === null : s.deleted_at !== null))
      );
    } else {
      TestValidator.equals("empty data for non-match status")(resp.data.length)(0);
    }
  }

  // 3. Free-text search: string unlikely to match
  const noMatchResp = await api.functional.ai_ecommerce.sellers.patch(connection, {
    body: { search: "zzzzzzzzzz_not_a_real_seller_name" } as ai_ecommerce_sellers.IRequest
  });
  typia.assert(noMatchResp);
  TestValidator.equals("empty data for impossible search")(noMatchResp.data.length)(0);

  // 4. Out-of-bounds pagination test
  const paged = await api.functional.ai_ecommerce.sellers.patch(connection, {
    body: { page: 1, limit: 2 } as ai_ecommerce_sellers.IRequest
  });
  typia.assert(paged);
  if (paged.pagination.pages > 0) {
    const overPaged = await api.functional.ai_ecommerce.sellers.patch(connection, {
      body: { page: paged.pagination.pages + 1, limit: 2 } as ai_ecommerce_sellers.IRequest
    });
    typia.assert(overPaged);
    TestValidator.equals("empty data for out-of-bounds page")(overPaged.data.length)(0);
  }

  // 5. Sorting: created_at DESC, check order
  const sorted = await api.functional.ai_ecommerce.sellers.patch(connection, {
    body: { sort_key: "created_at", sort_order: "desc", limit: 3 } as ai_ecommerce_sellers.IRequest
  });
  typia.assert(sorted);
  const sellers = sorted.data;
  if (sellers.length > 1) {
    for (let i = 1; i < sellers.length; ++i) {
      TestValidator.predicate("created_at desc order")(
        new Date(sellers[i - 1].created_at) >= new Date(sellers[i].created_at)
      );
    }
  }

  // 6. Error on bad status value
  await TestValidator.error("invalid status value triggers error")(() =>
    api.functional.ai_ecommerce.sellers.patch(connection, {
      body: { status: "BAD_STATUS_VALUE!!" } as ai_ecommerce_sellers.IRequest
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_sellers } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_sellers";
import type { IPageai_ecommerce_sellers } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageai_ecommerce_sellers";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Verify access controls for listing sellers by non-administrator users.
 *
 * This test ensures that only users with administrator (privileged) access
 * can retrieve the paginated/filterable list of sellers using PATCH /ai_ecommerce/sellers.
 * When a request is made by a user lacking admin privileges (such as an unauthenticated user or a customer),
 * the API should strictly deny access and return a clear authorization error, with no seller data returned.
 * This enforces compliance requirements and prevents sensitive seller/merchant data from being exposed.
 *
 * Steps:
 * 1. Make a PATCH request to /ai_ecommerce/sellers as an unauthenticated user with valid filtering input
 *    - Expect an authorization/access error (HTTP 401 or 403), not a seller list
 * 2. (If customer role authentication is possible via other API, login as a customer and re-attempt)
 *    - Expect the same authorization/access error (HTTP 403)
 * 3. Confirm that no seller data is returned on error
 * 4. Confirm that error is clear, structured, and does not disclose sensitive details
 */
export async function test_api_ai_ecommerce_sellers_test_list_sellers_access_denied_for_non_admin_users(
  connection: api.IConnection,
) {
  // 1. Attempt seller list PATCH as unauthenticated user
  await TestValidator.error("unauthenticated access denied")(async () => {
    await api.functional.ai_ecommerce.sellers.patch(connection, {
      body: {
        page: 1,
        limit: 10,
      } satisfies ai_ecommerce_sellers.IRequest,
    });
  });

  // 2. Note: If customer login API exists, authenticate as customer and repeat request below.
  // [Not implemented as no customer login API provided.]

  // 3. If error structures can be validated, could expand assertions on error structure here.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_sellers } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_sellers";

/**
 * 셀러 상세 정보 조회 E2E 시나리오 테스트
 *
 * - 목적: 관리자/시스템 권한으로 셀러 상세정보(id 기반) 조회 시, 허용된 모든 필드(고유 uuid, profile_id, 삭제/활성 상태 등)를 정확히 반환하는지 검증한다.
 * - 부정 path: 잘못된 uuid 포맷, 존재하지 않는 uuid에 대한 요청 시 명확한 오류(Validation/NotFound)를 반환하는지 확인한다.
 * - Edge: soft-delete 된 셀러에 대해 deleted_at 값이 표기되어 논리삭제 상태가 API 응답에 반영되는지 검증한다.
 *
 * 테스트 상세 단계:
 * 1. 정상 셀러 생성(선행: profile_id 임의 할당)
 * 2. 생성된 uuid로 상세정보 요청 → 필드값 단건 검증, deleted_at null임을 보장
 * 3. 잘못된 uuid 포맷으로 요청시 Validation error 반환
 * 4. 존재하지 않는 uuid로 요청시 Not Found(404 등) 반환
 * 5. soft-delete edge: 삭제된 셀러 타입(Mock) 값으로 deleted_at 필드 검증
 */
export async function test_api_ai_ecommerce_sellers_test_get_seller_detail_with_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. 정상 셀러 생성 (profile_id 임의 값)
  const profileId: string = typia.random<string & tags.Format<"uuid">>();
  const seller = await api.functional.ai_ecommerce.sellers.post(connection, {
    body: {
      profile_id: profileId,
    },
  });
  typia.assert(seller);
  TestValidator.equals("profile_id 일치")(seller.profile_id)(profileId);
  TestValidator.equals("deleted_at null")(seller.deleted_at)(null);

  // 2. 정상 uuid로 상세조회
  const detail = await api.functional.ai_ecommerce.sellers.getById(connection, {
    id: seller.id,
  });
  typia.assert(detail);
  TestValidator.equals("상세조회 id 일치")(detail.id)(seller.id);
  TestValidator.equals("상세조회 profile_id 일치")(detail.profile_id)(profileId);
  TestValidator.equals("상세조회 deleted_at null")(detail.deleted_at)(null);

  // 3. 잘못된 UUID 포맷 요청 (Validation 오류)
  await TestValidator.error("잘못된 UUID 포맷")(
    async () => {
      await api.functional.ai_ecommerce.sellers.getById(connection, {
        id: "not-a-valid-uuid" as string & tags.Format<"uuid">,
      });
    },
  );

  // 4. 존재하지 않는 uuid 요청 (NotFound 오류)
  await TestValidator.error("존재하지 않는 uuid")(
    async () => {
      await api.functional.ai_ecommerce.sellers.getById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 5. soft-delete edge: deleted_at 값 있을 때 논리삭제로 간주됨을 타입 검증(Mock)
  const softDeletedSeller: ai_ecommerce_sellers = {
    ...seller,
    deleted_at: new Date().toISOString(),
  };
  typia.assert(softDeletedSeller);
  TestValidator.predicate("soft-delete 시 deleted_at 존재해야 함")(!!softDeletedSeller.deleted_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_sellers } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_sellers";
import type { IAiEcommerceUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserProfile";

/**
 * E2E test for creating a new ai_ecommerce_sellers entity (seller onboarding).
 *
 * This test covers both positive and negative cases:
 *
 * 1. Success path: Create a new user profile, onboard a seller using its unique profile_id.
 *    - Ensure the seller is returned correctly and profile_id is linked.
 * 2. Uniqueness violation: Attempt to create another seller with the same profile_id.
 *    - Must fail due to 1:1 seller/profile linkage rule.
 * 3. Missing/invalid field: Attempt to create seller with missing or malformed profile_id (invalid format).
 *    - Must fail with proper constraint errors (runtime-only; TS compile-time impossible is omitted).
 *
 * Steps:
 * 1. Create a user profile (dependency).
 * 2. Create a seller with the profile_id (expect success).
 * 3. Attempt to create a seller with the same profile_id (expect error).
 * 4. Attempt to create a seller with malformed profile_id (expect error).
 */
export async function test_api_ai_ecommerce_sellers_test_create_seller_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create a unique user profile (dependency for seller linkage)
  const profilePayload: IAiEcommerceUserProfile.ICreate = {
    nickname: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    communication_consent: true,
    avatar_uri: null,
    phone_number: null,
  };
  const profile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: profilePayload,
  });
  typia.assert(profile);

  // 2. Create seller using valid profile_id
  const sellerRegister: ai_ecommerce_sellers.IRegister = {
    profile_id: profile.id,
  };
  const seller = await api.functional.ai_ecommerce.sellers.post(connection, {
    body: sellerRegister,
  });
  typia.assert(seller);
  TestValidator.equals("profile_id matches")(seller.profile_id)(profile.id);

  // 3. Attempt to create another seller with same profile_id (should trigger uniqueness error)
  await TestValidator.error("duplicate profile_id should fail")(async () => {
    await api.functional.ai_ecommerce.sellers.post(connection, {
      body: sellerRegister,
    });
  });

  // 4. Attempt to create seller with malformed profile_id (invalid format)
  await TestValidator.error("malformed profile_id should fail")(async () => {
    await api.functional.ai_ecommerce.sellers.post(connection, {
      body: {
        profile_id: "not-a-uuid" as string & tags.Format<"uuid">,
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_sellers } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_sellers";

/**
 * E2E test for updating ai_ecommerce_sellers via PUT /ai_ecommerce/sellers/{id}.
 *
 * This test validates the ability of an administrator to update editable fields on an existing seller entity, ensures audit fields are updated, checks enforcement of business rules regarding immutable fields, and tests update denial on a soft-deleted entity.
 *
 * Steps:
 * 1. Create a seller with controlled initial input.
 * 2. Update allowed fields (status, deleted_at) and verify changes apply, including updated_at refresh.
 * 3. Attempt to update forbidden fields (id/profile_id); confirm this is blocked by the schema/type system and API behavior.
 * 4. Soft-delete the seller, then attempt further updates (should fail).
 * 5. Note: Negative test for privilege enforcement (non-admin) is not available given current API exposure.
 */
export async function test_api_ai_ecommerce_sellers_test_update_seller_with_allowed_and_forbidden_changes(
  connection: api.IConnection,
) {
  // 1. Create a seller to use for update tests
  const profileId = typia.random<string & tags.Format<"uuid">>();
  const seller = await api.functional.ai_ecommerce.sellers.post(connection, {
    body: { profile_id: profileId } satisfies ai_ecommerce_sellers.IRegister,
  });
  typia.assert(seller);

  // 2. Update allowed fields (status; stored only in audit trail, not returned directly)
  const newStatus = "active";
  const updated = await api.functional.ai_ecommerce.sellers.putById(connection, {
    id: seller.id,
    body: { status: newStatus } satisfies ai_ecommerce_sellers.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("id unchanged after update")(updated.id)(seller.id);
  TestValidator.equals("profile unchanged")(updated.profile_id)(seller.profile_id);
  // updated_at must advance
  TestValidator.predicate("updated_at is newer")(updated.updated_at > seller.updated_at);

  // 3. (Negative case) Attempt forbidden/immutable field update
  // Can't be done by type system: id/profile_id forbidden by schema. Demonstrated by absence in IUpdate type.

  // 4. Soft-delete: set deleted_at, confirm field updates
  const delTime = new Date().toISOString();
  const deleted = await api.functional.ai_ecommerce.sellers.putById(connection, {
    id: seller.id,
    body: { deleted_at: delTime } satisfies ai_ecommerce_sellers.IUpdate,
  });
  typia.assert(deleted);
  // deleted_at will now be set (or changed)
  TestValidator.equals("deleted_at set")(deleted.deleted_at ?? null)(delTime);

  // 5. Try further update after soft-delete, expect failure
  await TestValidator.error("update prohibited after deletion")(
    async () => {
      await api.functional.ai_ecommerce.sellers.putById(connection, {
        id: seller.id,
        body: { status: "should_fail_after_deleted" } satisfies ai_ecommerce_sellers.IUpdate,
      });
    },
  );
  // 6. (Optional) Privilege/permission negative case not implemented due to insufficient API simulation capability
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_sellers } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_sellers";

/**
 * Test soft-delete of a seller (admin) including error and access control.
 *
 * Validates:
 * 1. Soft-delete works—deleted_at set after admin DELETE call
 * 2. Attempting to delete non-existent seller returns error
 * 3. Attempting to delete already-deleted seller is rejected (error)
 * 4. Access control works: non-admin permission cannot delete seller
 *
 * This test covers both positive/negative business flows and ensures that
 * administrative restrictions, not found/duplicate operations, and audit
 * soft-delete field logic are handled.
 *
 * Steps:
 * 1. Create a seller (dependency) to acquire a valid id
 * 2. Soft-delete via DELETE /ai_ecommerce/sellers/{id} as admin; verify
 *    deleted_at field
 * 3. Attempt to soft-delete a random (nonexistent) id; expect error
 * 4. Attempt to soft-delete same seller id again; expect error
 * 5. Simulate insufficient privilege/non-admin and attempt delete; expect access error
 */
export async function test_api_ai_ecommerce_sellers_test_soft_delete_seller_and_error_cases(
  connection: api.IConnection,
) {
  // 1. Create a seller as dependency (setup)
  const seller = await api.functional.ai_ecommerce.sellers.post(connection, {
    body: {
      profile_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies ai_ecommerce_sellers.IRegister,
  });
  typia.assert(seller);

  // 2. Soft-delete the seller as admin
  const deletedSeller = await api.functional.ai_ecommerce.sellers.eraseById(connection, {
    id: seller.id,
  });
  typia.assert(deletedSeller);
  TestValidator.predicate("deleted_at field should be set")(!!deletedSeller.deleted_at);

  // 3. Try to delete a non-existent seller (expect error)
  const fakeId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("delete non-existent seller")(() =>
    api.functional.ai_ecommerce.sellers.eraseById(connection, {
      id: fakeId,
    })
  );

  // 4. Try to delete an already-deleted seller (expect error)
  await TestValidator.error("delete already-deleted seller")(() =>
    api.functional.ai_ecommerce.sellers.eraseById(connection, {
      id: seller.id,
    })
  );

  // 5. Simulate insufficient privileges (non-admin connection)
  // Remove headers to lose admin privileges (simulate normal user)
  const nonAdminConnection = { ...connection, headers: {} };
  await TestValidator.error("delete as non-admin should be denied")(() =>
    api.functional.ai_ecommerce.sellers.eraseById(nonAdminConnection, {
      id: seller.id,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserProfile";
import type { ai_ecommerce_user_audit_logs } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_user_audit_logs";
import type { IPageai_ecommerce_user_audit_logs } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageai_ecommerce_user_audit_logs";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test: List/search user audit logs, validating filtering, pagination, permissions, and error handling as regular user & admin.
 *
 * Business goals:
 * - Ensure user sees only their own audit logs, admin can see any logs
 * - Test filterable fields: profile_id, event_type, created_from/to (date range)
 * - Test pagination (page/limit), including excessive limit triggers error
 * - Test search returns actual matches and zero results when filters are too restrictive
 * - Check permission enforcement: regular user cannot see others' logs
 * - Validate response structure conforms to expected pagination DTO
 * - Validate error on malformed filters (e.g., non-uuid profile_id, string for page)
 *
 * Workflow:
 * 1. Create one regular user profile, one admin profile
 * 2. Create 3 logs for user, 2 logs for admin
 * 3. As the user:
 *   a. List all logs (should only see their own)
 *   b. Search logs for their profile by event_type
 *   c. Search using date range filter within their own logs
 *   d. Attempt to search logs for admin's profile (should see zero or forbidden)
 * 4. As admin:
 *   a. List all logs (should see all logs)
 *   b. Search by user's profile_id and by their own
 *   c. Search by event_type and by date range across all logs
 *   d. Apply excessive page size (should error)
 * 5. Submit invalid filters: malformed profile_id, string for page, negative limit
 * 6. Validate all outputs with strict assertions: only expected data, total records right, error conditions raised
 */
export async function test_api_ai_ecommerce_userAuditLogs_test_list_user_audit_logs_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create one regular user profile and one admin profile
  const userProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      avatar_uri: null,
      email: `${RandomGenerator.name()}_user@e2e.com`,
      phone_number: null,
      communication_consent: true,
    },
  });
  typia.assert(userProfile);

  const adminProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      avatar_uri: null,
      email: `${RandomGenerator.name()}_admin@e2e.com`,
      phone_number: null,
      communication_consent: true,
    },
  });
  typia.assert(adminProfile);

  // 2. Create 3 logs for the user and 2 logs for admin
  const eventTypes = ["registration", "login", "profile_update"];
  const userAuditLogs: ai_ecommerce_user_audit_logs[] = [];
  for (let i = 0; i < 3; ++i) {
    const log = await api.functional.ai_ecommerce.userAuditLogs.post(connection, {
      body: {
        profile_id: userProfile.id,
        event_type: eventTypes[i],
        event_payload: `payload - ${eventTypes[i]}`,
      },
    });
    typia.assert(log);
    userAuditLogs.push(log);
  }

  const adminAuditLogs: ai_ecommerce_user_audit_logs[] = [];
  for (let i = 0; i < 2; ++i) {
    const log = await api.functional.ai_ecommerce.userAuditLogs.post(connection, {
      body: {
        profile_id: adminProfile.id,
        event_type: eventTypes[i],
        event_payload: `payload - ${eventTypes[i]}`,
      },
    });
    typia.assert(log);
    adminAuditLogs.push(log);
  }

  // 3. As the user: filter using their own profile only
  // 3.a. List all logs (expecting only their own logs)
  let res = await api.functional.ai_ecommerce.userAuditLogs.patch(connection, {
    body: {
      profile_id: userProfile.id,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(res);
  // Expect only user's logs
  for (const log of res.data) {
    TestValidator.equals("profile_id matches user")(log.profile_id)(userProfile.id);
  }
  TestValidator.equals("user audit log count")(res.data.length)(userAuditLogs.length);

  // 3.b. Search logs for their profile by event_type
  const targetEventType = eventTypes[1];
  res = await api.functional.ai_ecommerce.userAuditLogs.patch(connection, {
    body: {
      profile_id: userProfile.id,
      event_type: targetEventType,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(res);
  for (const log of res.data) {
    TestValidator.equals("only own event type")(log.event_type)(targetEventType);
    TestValidator.equals("profile_id matches user")(log.profile_id)(userProfile.id);
  }

  // 3.c. Search using date range filter (within their logs)
  const from = userAuditLogs[0].created_at;
  const to = userAuditLogs[2].created_at;
  res = await api.functional.ai_ecommerce.userAuditLogs.patch(connection, {
    body: {
      profile_id: userProfile.id,
      created_from: from,
      created_to: to,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(res);
  for (const log of res.data) {
    TestValidator.equals("profile_id matches user")(log.profile_id)(userProfile.id);
    TestValidator.predicate("created_at between range")(
      log.created_at >= from && log.created_at <= to,
    );
  }

  // 3.d. Attempt to search logs for admin's profile as user (should get zero or forbidden per access logic)
  res = await api.functional.ai_ecommerce.userAuditLogs.patch(connection, {
    body: {
      profile_id: adminProfile.id,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(res);
  TestValidator.equals("cannot see other's logs")(res.data.length)(0);

  // 4. As admin: no profile_id filter => should see all logs
  // (no actual role switching possible in given SDK, so simulate global search by leaving profile_id undefined)
  res = await api.functional.ai_ecommerce.userAuditLogs.patch(connection, {
    body: {
      page: 1,
      limit: 100,
    },
  });
  typia.assert(res);
  const allLogIds = [
    ...userAuditLogs.map((l) => l.id),
    ...adminAuditLogs.map((l) => l.id),
  ];
  for (const log of res.data) {
    TestValidator.predicate("log is from known testset - all logs visible as admin")(
      allLogIds.includes(log.id),
    );
  }

  // 4.b. Search by user profile_id and by admin's profile_id
  res = await api.functional.ai_ecommerce.userAuditLogs.patch(connection, {
    body: {
      profile_id: userProfile.id,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(res);
  TestValidator.equals("user logs visible as admin")(res.data.length)(userAuditLogs.length);
  for (const log of res.data) {
    TestValidator.equals("profile_id matches user")(log.profile_id)(userProfile.id);
  }
  res = await api.functional.ai_ecommerce.userAuditLogs.patch(connection, {
    body: {
      profile_id: adminProfile.id,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(res);
  TestValidator.equals("admin logs visible as admin")(res.data.length)(adminAuditLogs.length);
  for (const log of res.data) {
    TestValidator.equals("profile_id matches admin")(log.profile_id)(adminProfile.id);
  }

  // 4.c. Search by event_type as admin
  const adminTargetEventType = eventTypes[0];
  res = await api.functional.ai_ecommerce.userAuditLogs.patch(connection, {
    body: {
      event_type: adminTargetEventType,
      page: 1,
      limit: 100,
    },
  });
  typia.assert(res);
  for (const log of res.data) {
    TestValidator.equals("event_type")(log.event_type)(adminTargetEventType);
  }

  // 4.d. Search by date range across all logs
  const allCreatedTimes = allLogIds.map((id) => {
    const log = [...userAuditLogs, ...adminAuditLogs].find((l) => l.id === id)!;
    return log.created_at;
  });
  const globalFrom = allCreatedTimes.reduce((min, dt) => dt < min ? dt : min, allCreatedTimes[0]);
  const globalTo = allCreatedTimes.reduce((max, dt) => dt > max ? dt : max, allCreatedTimes[0]);
  res = await api.functional.ai_ecommerce.userAuditLogs.patch(connection, {
    body: {
      created_from: globalFrom,
      created_to: globalTo,
      page: 1,
      limit: 100,
    },
  });
  typia.assert(res);
  for (const log of res.data) {
    TestValidator.predicate("created_at in global date range")(
      log.created_at >= globalFrom && log.created_at <= globalTo,
    );
  }

  // 4.e. Query with excessive page size (should error or restrict by business logic)
  await TestValidator.error("excessive limit should error or restrict")(
    async () => {
      await api.functional.ai_ecommerce.userAuditLogs.patch(connection, {
        body: {
          page: 1,
          limit: 1000000,
        },
      });
    },
  );

  // 5. Invalid filter: malformed profile_id (not a uuid)
  await TestValidator.error("malformed profile_id should error")(
    async () => {
      await api.functional.ai_ecommerce.userAuditLogs.patch(connection, {
        body: {
          profile_id: "not-a-uuid",
          page: 1,
          limit: 10,
        },
      });
    },
  );

  // 5. Invalid filter: string for page (TypeScript won't allow, but test for negative/invalid numerics)
  await TestValidator.error("negative page should error")(
    async () => {
      await api.functional.ai_ecommerce.userAuditLogs.patch(connection, {
        body: {
          page: -1 as number & tags.Type<"int32">,
          limit: 10,
        },
      });
    },
  );

  // 5. Invalid filter: negative limit
  await TestValidator.error("negative limit should error")(
    async () => {
      await api.functional.ai_ecommerce.userAuditLogs.patch(connection, {
        body: {
          page: 1,
          limit: -100 as number & tags.Type<"int32">,
        },
      });
    },
  );

  // 6. Overly restrictive filters: date range in which there are no logs
  res = await api.functional.ai_ecommerce.userAuditLogs.patch(connection, {
    body: {
      created_from: "2099-12-31T23:59:59.000Z",
      created_to: "2100-01-01T01:00:00.000Z",
      page: 1,
      limit: 10,
    },
  });
  typia.assert(res);
  TestValidator.equals("no logs for futuristic date range")(res.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
