import type { ai_ecommerce_user_audit_logs } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_user_audit_logs";

/**
 * Test getting user audit log detail by ID as owner and administrator, and validate correct access/error behaviors for different scenarios.
 *
 * This test simulates retrieving a user audit log record as various roles:
 *   1. The user who owns the audit log (matching profile)
 *   2. Another user (authorization/forbidden scenario documented, but not enforced at SDK level)
 *   3. Administrator (SDK does not distinguish admin profiles at this level, so treated as simple profile)
 *   4. Deleted log (should not be retrievable)
 *   5. Non-existent log ID (should error)
 *   6. Invalid UUID format (should error)
 *
 * Steps:
 * 1. Create 3 user profiles (owner, other user, admin, though RBAC is not enforced/implementable here)
 * 2. Insert an audit log record for the owner profile
 * 3. Retrieve the audit log as owner (should succeed)
 * 4. Retrieve the audit log as admin (simulated/should succeed)
 * 5. (Simulated) Retrieve as other user (if RBAC was enforced, would expect forbidden error)
 * 6. Delete the log
 * 7. Retrieve the deleted log (should error)
 * 8. Try retrieving with a valid non-existent ID (should error)
 * 9. Try retrieving with an invalid UUID (should error)
 */
export async function test_api_ai_ecommerce_userAuditLogs_test_get_user_audit_log_detail_with_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. Create test profiles
  const ownerEmail = typia.random<string & tags.Format<"email">>();
  const owner = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: ownerEmail,
      communication_consent: true,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(owner);

  const otherEmail = typia.random<string & tags.Format<"email">>();
  const otherUser = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: otherEmail,
      communication_consent: true,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(otherUser);

  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: adminEmail,
      communication_consent: true,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(admin);

  // 2. Create audit log entry for owner
  const log = await api.functional.ai_ecommerce.userAuditLogs.post(connection, {
    body: {
      profile_id: owner.id,
      event_type: "login",
      event_payload: JSON.stringify({ ip: "127.0.0.1" }),
    } satisfies ai_ecommerce_user_audit_logs.ICreate,
  });
  typia.assert(log);

  // 3. Retrieve as owner (should succeed)
  const logAsOwner = await api.functional.ai_ecommerce.userAuditLogs.getById(connection, { id: log.id });
  typia.assert(logAsOwner);
  TestValidator.equals("log id as owner")(logAsOwner.id)(log.id);

  // 4. Retrieve as admin (treated same, since no auth separation in SDK)
  const logAsAdmin = await api.functional.ai_ecommerce.userAuditLogs.getById(connection, { id: log.id });
  typia.assert(logAsAdmin);
  TestValidator.equals("log id as admin")(logAsAdmin.id)(log.id);

  // 5. (Simulated) Retrieve as other user; SDK lacks RBAC, so it will succeed for demo,
  // but if RBAC existed, would expect a forbidden error here.
  // To check real RBAC, TestValidator.error(...), but not implementable here.

  // 6. Delete the log
  await api.functional.ai_ecommerce.userAuditLogs.eraseById(connection, { id: log.id });

  // 7. Attempt to retrieve deleted log (should error)
  TestValidator.error("deleted log retrieval should fail")(async () => {
    await api.functional.ai_ecommerce.userAuditLogs.getById(connection, { id: log.id });
  });

  // 8. Try valid but non-existent ID (random uuid)
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("non-existent log id should fail")(async () => {
    await api.functional.ai_ecommerce.userAuditLogs.getById(connection, { id: nonExistentId });
  });

  // 9. Try invalid UUID
  const invalidId = "not-a-uuid" as string & tags.Format<"uuid">;
  TestValidator.error("invalid uuid should fail")(async () => {
    await api.functional.ai_ecommerce.userAuditLogs.getById(connection, { id: invalidId });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserProfile";
import type { ai_ecommerce_user_audit_logs } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_user_audit_logs";

/**
 * E2E test for the creation of user audit log records with both valid and invalid input.
 *
 * Validates:
 * 1. Normal user can create an audit log for their own profile only.
 * 2. Admin user can create a log for any profile.
 * 3. Error is raised if a normal user tries to create a log for another person's profile.
 * 4. Error is raised if required fields are missing.
 * 5. Error is raised if the profile ID does not exist.
 * 6. Audit log entries are immutable (no update/delete allowed).
 * 7. All business rules for event creation and input validation are enforced.
 *
 * Test Steps:
 * 1. Create two user profiles (user, admin).
 * 2. Normal user creates an event on their own profile (should succeed).
 * 3. Admin creates an event for user's profile (should succeed).
 * 4. Normal user attempts to create a log for admin's profile (should fail).
 * 5. Attempt to log with missing required fields (should fail).
 * 6. Attempt to log with a non-existent profile ID (should fail).
 * 7. Check that audit log entries are immutable (no way to update/delete).
 */
export async function test_api_ai_ecommerce_user_audit_logs_test_create_user_audit_log_with_valid_and_invalid_input(
  connection: api.IConnection,
) {
  // 1. Create two user profiles: user and admin (simulate different users)
  const userProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true,
      avatar_uri: null,
      phone_number: null,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(userProfile);

  const adminProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true,
      avatar_uri: null,
      phone_number: null,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(adminProfile);

  // 2. Normal user creates an audit log for themselves - success
  const userLog = await api.functional.ai_ecommerce.userAuditLogs.post(connection, {
    body: {
      profile_id: userProfile.id,
      event_type: "login",
      event_payload: JSON.stringify({ device: "iPhone 14" }),
    } satisfies ai_ecommerce_user_audit_logs.ICreate,
  });
  typia.assert(userLog);
  TestValidator.equals("user's log profile matches")(userLog.profile_id)(userProfile.id);
  TestValidator.equals("event type is login")(userLog.event_type)("login");

  // 3. Admin creates an audit log for the user's profile - success
  const adminLog = await api.functional.ai_ecommerce.userAuditLogs.post(connection, {
    body: {
      profile_id: userProfile.id,
      event_type: "profile_update",
      event_payload: JSON.stringify({ admin: true, change: "nickname" }),
    } satisfies ai_ecommerce_user_audit_logs.ICreate,
  });
  typia.assert(adminLog);
  TestValidator.equals("admin log profile matches")(adminLog.profile_id)(userProfile.id);
  TestValidator.equals("event type is profile_update")(adminLog.event_type)("profile_update");

  // 4. Normal user tries to create log for admin's profile (should fail)
  await TestValidator.error("user cannot log for another profile")(() =>
    api.functional.ai_ecommerce.userAuditLogs.post(connection, {
      body: {
        profile_id: adminProfile.id,
        event_type: "login",
        event_payload: null,
      } as ai_ecommerce_user_audit_logs.ICreate,
    })
  );

  // 5. Missing required fields (event_type missing) - should fail
  await TestValidator.error("missing required fields")(() =>
    api.functional.ai_ecommerce.userAuditLogs.post(connection, {
      body: {
        profile_id: userProfile.id as string & tags.Format<"uuid">,
        // event_type missing
      } as any,
    })
  );

  // 6. Non-existent profile_id - should fail
  await TestValidator.error("non-existent profile id")(() =>
    api.functional.ai_ecommerce.userAuditLogs.post(connection, {
      body: {
        profile_id: typia.random<string & tags.Format<"uuid">>(),
        event_type: "login",
        event_payload: null,
      } satisfies ai_ecommerce_user_audit_logs.ICreate,
    })
  );

  // 7. Audit log entries immutable: attempting to update/delete not possible (only new entries allowed)
  const logEntry = await api.functional.ai_ecommerce.userAuditLogs.post(connection, {
    body: {
      profile_id: userProfile.id,
      event_type: "registration",
      event_payload: JSON.stringify({ ip: "127.0.0.1" }),
    } satisfies ai_ecommerce_user_audit_logs.ICreate,
  });
  typia.assert(logEntry);
  // There is no update/delete; just ensure a new entry works and no overwrite is possible.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserProfile";
import type { ai_ecommerce_user_audit_logs } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_user_audit_logs";

/**
 * Test updating user audit logs with owner and admin, verifying field-level permission (allowed/disallowed),
 * and proper error handling on immutable/nonexistent/deleted logs.
 *
 * - Creates 'owner' and 'admin' user profiles.
 * - Inserts audit logs for each.
 * - Attempts permitted update (event_payload) as owner — expects success.
 * - Attempts forbidden update (event_type) as owner — expects error.
 * - As admin, updates event_type and event_payload — expects success.
 * - Attempts update on non-existent ID (expects error).
 * - Inserts and deletes a log, then tries to update it (expects error).
 */
export async function test_api_ai_ecommerce_userAuditLogs_test_update_user_audit_log_by_admin_and_owner_with_allowed_and_disallowed_fields(
  connection: api.IConnection,
) {
  // Step 1: Create two user profiles — 'owner' and 'admin'
  const ownerProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      avatar_uri: null,
      email: typia.random<string & tags.Format<"email">>(),
      phone_number: null,
      communication_consent: true,
    },
  });
  typia.assert(ownerProfile);

  const adminProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      avatar_uri: null,
      email: typia.random<string & tags.Format<"email">>(),
      phone_number: null,
      communication_consent: true,
    },
  });
  typia.assert(adminProfile);

  // Step 2: Insert user audit log for owner
  const ownerLog = await api.functional.ai_ecommerce.userAuditLogs.post(connection, {
    body: {
      profile_id: ownerProfile.id,
      event_type: "registration",
      event_payload: "{" + `device":"web"` + "}",
    },
  });
  typia.assert(ownerLog);

  // Step 3: As owner, update permitted field (event_payload only)
  const updatedPayload = "{" + `device":"mobile"` + "}";
  const ownerUpdateAllowed = await api.functional.ai_ecommerce.userAuditLogs.putById(connection, {
    id: ownerLog.id,
    body: { event_payload: updatedPayload },
  });
  typia.assert(ownerUpdateAllowed);
  TestValidator.equals("event_payload updated as owner")(ownerUpdateAllowed.event_payload)(updatedPayload);
  TestValidator.equals("event_type unchanged")(ownerUpdateAllowed.event_type)(ownerLog.event_type);

  // Step 4: As owner, forbidden update (event_type)
  await TestValidator.error("owner cannot change event_type")(() =>
    api.functional.ai_ecommerce.userAuditLogs.putById(connection, {
      id: ownerLog.id,
      body: { event_type: "profile_update" },
    })
  );

  // Step 5: As admin, both allowed field changes — event_type and event_payload
  const adminLog = await api.functional.ai_ecommerce.userAuditLogs.post(connection, {
    body: {
      profile_id: adminProfile.id,
      event_type: "login",
      event_payload: "{" + `device":"desktop"` + "}",
    },
  });
  typia.assert(adminLog);

  // As admin — allowed update: event_type
  const adminEventTypeUpdate = await api.functional.ai_ecommerce.userAuditLogs.putById(connection, {
    id: adminLog.id,
    body: { event_type: "profile_update" },
  });
  typia.assert(adminEventTypeUpdate);
  TestValidator.equals("admin changed event_type")(adminEventTypeUpdate.event_type)("profile_update");

  // As admin — allowed update: event_payload
  const newAdminPayload = "{" + `location":"EU"` + "}";
  const adminPayloadUpdate = await api.functional.ai_ecommerce.userAuditLogs.putById(connection, {
    id: adminLog.id,
    body: { event_payload: newAdminPayload },
  });
  typia.assert(adminPayloadUpdate);
  TestValidator.equals("admin changed event_payload")(adminPayloadUpdate.event_payload)(newAdminPayload);

  // Step 6: Update on non-existent audit log record
  await TestValidator.error("non-existent audit log")(async () =>
    api.functional.ai_ecommerce.userAuditLogs.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { event_payload: "{" + `x":"y"` + "}" },
    })
  );

  // Step 7: Update after soft delete
  const logToDelete = await api.functional.ai_ecommerce.userAuditLogs.post(connection, {
    body: {
      profile_id: ownerProfile.id,
      event_type: "login",
      event_payload: null,
    },
  });
  typia.assert(logToDelete);
  await api.functional.ai_ecommerce.userAuditLogs.eraseById(connection, {
    id: logToDelete.id,
  });

  await TestValidator.error("cannot update soft-deleted log")(async () =>
    api.functional.ai_ecommerce.userAuditLogs.putById(connection, {
      id: logToDelete.id,
      body: { event_payload: "soft deleted test" },
    })
  );
}

