import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommercePayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommercePayment";

/**
 * 결제(payment) 상태 전이 및 허용 필드 갱신, 불변 필드 변경 거부 및 오류 경로 검증.
 *
 * 권한 있는 계정이 결제 상태를 'pending'에서 'completed'로 정상 업데이트 하고,
 * payment_reference 등 일부 필드 변경이 허용되는지 확인합니다. 이미 정산(또는 취소)된 결제 건에 대해
 * 불변 필드(amount 등) 변경을 시도하면 오류가 발생해야 하며, 존재하지 않는 payment id, 금지된 필드 변경 등에 대한
 * 에러 경로를 모두 검증합니다.
 *
 * [테스트 절차]
 * 1. 신규 결제(payment) 생성 (status: 'pending')
 * 2. 해당 결제 status를 'completed'로 변경 및 payment_reference, 메서드 등 메타데이터 일부 변경
 * 3. settlement(완료/취소 등) 상태 이후, 금액 등 불변필드(amount) 수정 시도 시 오류 확인
 * 4. 존재하지 않는 payment id 갱신 시도 시 오류 발생 확인
 * 5. 금지된 필드 갱신(불변 필드, amount) 요청 오류 검증
 * 6. 정상경로 업데이트 결과 타입 및 주요 값 검증/assert
 */
export async function test_api_ai_ecommerce_payments_test_update_payment_status_and_fields_with_authorization(
  connection: api.IConnection,
) {
  // 1. 신규 결제 생성 (status: 'pending')
  const created = await api.functional.ai_ecommerce.payments.post(connection, {
    body: {
      amount: 10000,
      provider: "stripe",
      method: "card",
      status: "pending"
    } satisfies IAiEcommercePayment.ICreate
  });
  typia.assert(created);

  // 2. 결제 상태(status)를 'completed'로 변경 + payment_reference 등 허용 필드 변경
  const updated = await api.functional.ai_ecommerce.payments.putById(connection, {
    id: created.id,
    body: {
      status: "completed",
      payment_reference: "PG-REF-7777"
    } satisfies IAiEcommercePayment.IUpdate
  });
  typia.assert(updated);
  TestValidator.equals("상태 변경됨")(updated.status)("completed");
  TestValidator.equals("payment_reference 변경됨")(updated.payment_reference)("PG-REF-7777");
  TestValidator.equals("amount 유지됨")(updated.amount)(created.amount);
  TestValidator.equals("method 유지됨")(updated.method)(created.method);
  TestValidator.equals("provider 유지됨")(updated.provider)(created.provider);

  // 3. settlement(완료) 상태 이후 amount(불변 필드) 직접 수정 시도 → 오류 확인
  // IUpdate에는 amount 필드가 없으므로 타입 차원에서 추가 불가, 실 테스트는 런타임에서 보호필드 거부만 검증
  await TestValidator.error("정산완료 후 amount 수정 거부")(
    async () => {
      await api.functional.ai_ecommerce.payments.putById(connection, {
        id: created.id,
        body: {
          status: "completed",
          payment_reference: updated.payment_reference
        } satisfies IAiEcommercePayment.IUpdate
      });
    }
  );

  // 4. 존재하지 않는 payment ID에 대해 상태 변경 시도 → 오류
  await TestValidator.error("존재하지 않는 결제 ID")(
    async () => {
      await api.functional.ai_ecommerce.payments.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: {
          status: "completed"
        } satisfies IAiEcommercePayment.IUpdate
      });
    }
  );

  // 5. 금지된 필드(불변, amount) 직접 변경 시도 → 오류
  // IUpdate에 amount가 없으므로 타입 차원에서 테스트 불가, 실 API 에서의 거부만 체크
  await TestValidator.error("불변필드 amount 직접 변경 거부")(
    async () => {
      await api.functional.ai_ecommerce.payments.putById(connection, {
        id: created.id,
        body: {
          status: updated.status,
          payment_reference: updated.payment_reference
        } satisfies IAiEcommercePayment.IUpdate
      });
    }
  );

  // 6. payment_reference만 별도 partial 수정 → 정상 반영 확인
  const updatedRef = await api.functional.ai_ecommerce.payments.putById(connection, {
    id: created.id,
    body: {
      status: updated.status,
      payment_reference: "PG-REF-1234"
    } satisfies IAiEcommercePayment.IUpdate
  });
  typia.assert(updatedRef);
  TestValidator.equals("payment_reference 변경됨")(updatedRef.payment_reference)("PG-REF-1234");
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
