import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommercePayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommercePayment";

/**
 * Validate the deletion of payment records via DELETE /ai_ecommerce/payments/{id}.
 *
 * This function covers multiple scenarios:
 * (a) A privileged user can successfully delete a fresh, deletable payment and receives a proper delete result.
 * (b) Attempting to delete a payment in a non-deletable state (e.g., 'completed'/'settled') is rejected and the system returns an error.
 * (c) Deleting a payment that belongs to another user (without permission) is forbidden and should result in an error.
 * (d) Attempting to delete a non-existent payment record returns a proper not-found or error response.
 *
 * All deletion actions should be reflected in delete result and, for scenario (a), the payment should not be retrievable afterward.
 *
 * Steps:
 * 1. Create a new payment (status 'pending') and delete it – should succeed.
 * 2. Create a payment with 'completed' status and attempt to delete it – should error (business constraint).
 * 3. (Role sim required) Attempt to delete a payment created by 'another user' (if API supports permissions) – should error/forbid (Note: omitted if no user context mechanism).
 * 4. Attempt to delete a random non-existent payment id – should return not-found error.
 */
export async function test_api_ai_ecommerce_test_delete_payment_with_audit_and_constraint_checks(connection: api.IConnection) {
  // 1. Create a deletable payment (status: 'pending')
  const deletablePayment = await api.functional.ai_ecommerce.payments.post(connection, {
    body: {
      amount: 50000,
      provider: "stripe",
      method: "card",
      payment_reference: "ref-pending-" + Math.random().toString(36).slice(2,9),
      status: "pending"
    } satisfies IAiEcommercePayment.ICreate,
  });
  typia.assert(deletablePayment);

  // 1a. Delete the pending payment, expecting success
  const delResult1 = await api.functional.ai_ecommerce.payments.eraseById(connection, {
    id: deletablePayment.id,
  });
  typia.assert(delResult1);
  TestValidator.equals("delete: deleted==true")(delResult1.deleted)(true);
  TestValidator.equals("delete: correct id returned")(delResult1.id)(deletablePayment.id);

  // 2. Create a completed/settled payment and attempt deletion
  const completedPayment = await api.functional.ai_ecommerce.payments.post(connection, {
    body: {
      amount: 35000,
      provider: "paypal",
      method: "bank_transfer",
      payment_reference: "ref-compl-" + Math.random().toString(36).slice(2,9),
      status: "completed"
    } satisfies IAiEcommercePayment.ICreate,
  });
  typia.assert(completedPayment);
  await TestValidator.error("cannot delete completed/settled payment")(() =>
    api.functional.ai_ecommerce.payments.eraseById(connection, {
      id: completedPayment.id,
    })
  );

  // 3. Attempt to delete non-existent payment id – expects error
  const fakeUuid = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("delete non-existent payment should error")(() =>
    api.functional.ai_ecommerce.payments.eraseById(connection, {
      id: fakeUuid,
    })
  );
}

