  // 4. Create business profile for Seller B
  const businessProfileBdata: IAiEcommerceSellerBusinessProfile.ICreate = {
    seller_id: sellerB.id,
    business_name: `B 회사 ${RandomGenerator.alphabets(4)}`,
    business_registration_number: RandomGenerator.alphaNumeric(10),
    tax_id: RandomGenerator.alphaNumeric(8),
    contact_name: RandomGenerator.name(),
    contact_phone: RandomGenerator.mobile(),
    contact_email: `${RandomGenerator.alphabets(8)}@companyB.com`,
    address_line1: RandomGenerator.alphaNumeric(10),
    address_line2: null,
    city: "Busan",
    state: "Busan",
    postal_code: "48789",
    country: "KR",
  };
  const businessProfileB = await api.functional.ai_ecommerce.sellerBusinessProfiles.post(connection, {
    body: businessProfileBdata,
  });
  typia.assert(businessProfileB);

