    contact_phone: RandomGenerator.mobile(),
    contact_email: `${RandomGenerator.alphabets(10)}@update.com`,
    address_line1: RandomGenerator.alphaNumeric(10),
    city: "Incheon",
    state: "Gyeonggi",
    postal_code: "12345",
    country: "KR",
