  // 7. List replies by administrator_id
  const result_by_admin = await api.functional.ai_ecommerce.replies.patch(connection, {
    body: {
      administrator_id,
    },
  });
  typia.assert(result_by_admin);
  TestValidator.equals("admin's reply present")(result_by_admin.data.length)(1);
  TestValidator.equals("right admin")(result_by_admin.data[0].administrator_id)(administrator_id);

  // 8. List replies by seller_id
  const result_by_seller = await api.functional.ai_ecommerce.replies.patch(connection, {
    body: {
      seller_id,
    },
  });
  typia.assert(result_by_seller);
  TestValidator.equals("seller's reply present")(result_by_seller.data.length)(1);
  TestValidator.equals("right seller")(result_by_seller.data[0].seller_id)(seller_id);

  // 9. List replies with keyword filter (body)
  const search_phrase = reply_by_admin.body.split(" ")[2];
  const search_result = await api.functional.ai_ecommerce.replies.patch(connection, {
    body: {
