  TestValidator.equals("paged result length")(paged.data.length)(1);
  TestValidator.equals("reply parent paginated")(paged.data[0].comment_id)(comment.id);

  // 12. Soft delete parent comment: add new comment, soft delete, post reply
  const deleted_comment = await api.functional.ai_ecommerce.comments.post(connection, {
    body: {
      customer_id,
      parent_id: null,
      forum_thread_id: null,
      inquiry_id: inquiry.id,
      review_id: null,
      body: RandomGenerator.paragraph()(3),
    },
  });
  typia.assert(deleted_comment);
  // Simulate soft-deletion
  deleted_comment.deleted_at = new Date().toISOString();
  // Create reply to soft-deleted comment
  const reply_to_deleted = await api.functional.ai_ecommerce.replies.post(connection, {
    body: {
      administrator_id,
      seller_id: null,
      inquiry_id: null,
      review_id: null,
      forum_thread_id: null,
      comment_id: deleted_comment.id,
      body: "Reply to soft-deleted parent",
    }
  });
  typia.assert(reply_to_deleted);
  // List with comment_id; should not include this reply by default
  const list_hidden = await api.functional.ai_ecommerce.replies.patch(connection, {
    body: {
      comment_id: deleted_comment.id,
    },
  });
  typia.assert(list_hidden);
  TestValidator.equals("reply to soft-deleted parent suppressed")(list_hidden.data.length)(0);

  // 13. Malformed filter (invalid uuid)
  await TestValidator.error("malformed uuid")(async () => {
    await api.functional.ai_ecommerce.replies.patch(connection, {
      body: {
        comment_id: "not-a-uuid" as any,
      },
    });
  });

  // 14. Actor not assigned (random uuid)
  const fake_admin_id = typia.random<string & tags.Format<"uuid">>();
  const empty_result = await api.functional.ai_ecommerce.replies.patch(connection, {
    body: {
      administrator_id: fake_admin_id,
    },
  });
  typia.assert(empty_result);
  TestValidator.equals("no replies for fake admin")(empty_result.data.length)(0);
}

