  await TestValidator.error("Not found for unknown reply ID")(async () => {
    await api.functional.ai_ecommerce.replies.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });

  // Authorization and soft-delete edge cases are skipped; not testable with current API/DTOs.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerceComment } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerceComment";
import type { ai_ecommerceReply } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerceReply";

/**
 * Test reply creation as admin and seller, check required fields and validation.
 *
 * 1. Create a base comment by customer (for reply target, type: forum, inquiry, or review)
 * 2. Post a reply to comment as administrator (administrator_id is set, seller_id null)
 *    - Validate returned reply links correct parent, correct administrator_id
 * 3. Post a reply to another valid comment as seller (seller_id is set, administrator_id null)
 *    - Validate links and author fields
 * 4. Error test: Post reply with missing both seller_id and administrator_id (actor); expect creation failure
 * 5. Error test: Post reply without a valid target id (all association fields null); expect failure
 * 6. Error test: Post reply with non-existent/deleted parent; expect failure
 * 7. Check audit trail (created_at/updated_at) is populated
 */
export async function test_api_ai_ecommerce_test_create_reply_to_comment_by_admin_and_seller(
  connection: api.IConnection,
) {
  // 1. Create a comment as the base
  const customer_id = typia.random<string & tags.Format<"uuid">>();
  const base_comment = await api.functional.ai_ecommerce.comments.post(connection, {
    body: {
      customer_id,
      body: "Base test comment.",
      forum_thread_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies ai_ecommerceComment.ICreate,
  });
  typia.assert(base_comment);

  // 2. Post a reply as administrator
  const administrator_id = typia.random<string & tags.Format<"uuid">>();
  const admin_reply = await api.functional.ai_ecommerce.replies.post(connection, {
    body: {
      administrator_id,
      seller_id: null,
      comment_id: base_comment.id,
      body: "Reply from admin.",
    } satisfies ai_ecommerceReply.ICreate,
  });
  typia.assert(admin_reply);
  TestValidator.equals("reply is for parent comment")(admin_reply.comment_id)(base_comment.id);
  TestValidator.equals("reply admin field")(admin_reply.administrator_id)(administrator_id);
  TestValidator.equals("seller_id null")(admin_reply.seller_id)(null);
  TestValidator.predicate("audit created_at present")(typeof admin_reply.created_at === "string" && admin_reply.created_at.length > 0);

  // 3. Post reply as seller
  const seller_id = typia.random<string & tags.Format<"uuid">>();
  // Create another comment to reply on (linked to a review)
  const review_comment = await api.functional.ai_ecommerce.comments.post(connection, {
    body: {
      customer_id,
      body: "Review-related comment.",
      review_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies ai_ecommerceComment.ICreate,
  });
  typia.assert(review_comment);

  const seller_reply = await api.functional.ai_ecommerce.replies.post(connection, {
    body: {
      seller_id,
      administrator_id: null,
      comment_id: review_comment.id,
      body: "Reply from seller.",
    } satisfies ai_ecommerceReply.ICreate,
  });
  typia.assert(seller_reply);
  TestValidator.equals("seller_id matches")(seller_reply.seller_id)(seller_id);
  TestValidator.equals("admin null")(seller_reply.administrator_id)(null);
  TestValidator.equals("comment link")(seller_reply.comment_id)(review_comment.id);
  TestValidator.predicate("audit created_at present")(typeof seller_reply.created_at === "string" && seller_reply.created_at.length > 0);

  // 4. Error: missing both seller_id and administrator_id
  await TestValidator.error("fail if no actor supplied")(() =>
    api.functional.ai_ecommerce.replies.post(connection, {
      body: {
        seller_id: null,
        administrator_id: null,
        comment_id: base_comment.id,
        body: "Should fail; no actor.",
      } as ai_ecommerceReply.ICreate,
    })
  );

  // 5. Error: all association fields null (no target)
  await TestValidator.error("fail if no target supplied")(() =>
    api.functional.ai_ecommerce.replies.post(connection, {
      body: {
        seller_id,
        administrator_id: null,
        comment_id: null,
        forum_thread_id: null,
        inquiry_id: null,
        review_id: null,
        body: "Should fail, no valid target.",
      } as ai_ecommerceReply.ICreate,
    })
  );

  // 6. Error: reply to non-existent parent
  await TestValidator.error("fail for non-existent parent")(() =>
    api.functional.ai_ecommerce.replies.post(connection, {
      body: {
        seller_id,
        administrator_id: null,
        comment_id: typia.random<string & tags.Format<"uuid">>(), // random, non-existing
        body: "Should fail for non-existent parent.",
      } as ai_ecommerceReply.ICreate,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
