import type { ai_ecommerceReply } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerceReply";

/**
 * Validate that creating a reply with multiple target associations
 * (e.g., non-null comment_id AND review_id) is rejected as invalid.
 *
 * Business context: Per business rules and DTO structure, a reply must reference
 * exactly one target entity (comment, review, inquiry, or forum thread),
 * not multiple at once. The test ensures that the API robustly enforces atomic
 * association. Attempting to associate a reply with more than one target must
 * be rejected by the server as invalid, raising a runtime error (validation or business logic).
 *
 * 1. Set up a valid parent comment using the comments API
 * 2. Attempt to create a reply, with both comment_id and review_id fields
 *    set to non-null values; choose plausible UUIDs (one referencing the parent comment,
 *    the other a random UUID for review association).
 * 3. Assert that the API responds with an error (TestValidator.error), confirming
 *    violation is detected and rejected, and reply is not created.
 *
 * Note: This test does not inspect the error message or structure—only that
 * an error is thrown. It does NOT test TypeScript compile-time enforcement,
 * but runtime rejection and business rule adherence.
 */
export async function test_api_ai_ecommerce_replies_test_create_reply_with_duplicate_target_associations_rejected(
  connection: api.IConnection,
) {
  // 1. Set up a valid parent comment as a reply target
  const customer_id: string = typia.random<string & tags.Format<"uuid">>();
  const parent_comment = await api.functional.ai_ecommerce.comments.post(connection, {
    body: {
      customer_id,
      body: "Parent comment for atomicity business rule test",
      forum_thread_id: null,
      inquiry_id: null,
      review_id: null,
      parent_id: null
    } satisfies ai_ecommerceComment.ICreate
  });
  typia.assert(parent_comment);

  // 2. Attempt to create a reply with both comment_id and review_id set
  const seller_id = typia.random<string & tags.Format<"uuid">>();

  await TestValidator.error("Multiple target refs are rejected")(
    async () => {
      await api.functional.ai_ecommerce.replies.post(connection, {
        body: {
          seller_id,
          comment_id: parent_comment.id,
          review_id: typia.random<string & tags.Format<"uuid">>(),
          forum_thread_id: null,
          inquiry_id: null,
          administrator_id: null,
          body: "Try associating reply to both comment and review (should fail)"
        } satisfies ai_ecommerceReply.ICreate
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
