import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerceComment } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerceComment";
import type { ai_ecommerceReply } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerceReply";

/**
 * Test the update of a reply's body text by the original author (admin or seller),
 * and verify permission, proper update propagation, and soft-deletion protection.
 *
 * Steps:
 * 1. Create a base comment as context.
 * 2. Post a reply to this comment by a seller (as the original author).
 * 3. Update this reply with new body text as the author, and verify the response reflects the new content and updated_at changes.
 * 4. Attempt to update the same reply as a different seller/admin and expect a permission error.
 * 5. (Skipped: Soft-deletion case) – Not supported by the update API/DTO, so not executed.
 */
export async function test_api_ai_ecommerce_test_update_reply_body_by_authorized_user(
  connection: api.IConnection,
) {
  // Step 1: Create a comment as the parent for the reply
  const commentCreate: ai_ecommerceComment.ICreate = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    body: "Initial parent comment for reply update test.",
    parent_id: null,
    forum_thread_id: null,
    inquiry_id: null,
    review_id: null,
  };
  const comment = await api.functional.ai_ecommerce.comments.post(connection, { body: commentCreate });
  typia.assert(comment);

  // Step 2: Seller posts a reply to the above comment
  const sellerId = typia.random<string & tags.Format<"uuid">>();
  const replyCreate: ai_ecommerceReply.ICreate = {
    seller_id: sellerId,
    administrator_id: null,
    comment_id: comment.id,
    forum_thread_id: null,
    inquiry_id: null,
    review_id: null,
    body: "Reply from seller to parent comment.",
  };
  const reply = await api.functional.ai_ecommerce.replies.post(connection, { body: replyCreate });
  typia.assert(reply);
  TestValidator.equals("author matches")(reply.seller_id)(sellerId);
  TestValidator.equals("body matches")(reply.body)(replyCreate.body);

  // Step 3: Seller updates their reply body
  const updatedBody = "Updated reply body content by original seller.";
  const updatedReply = await api.functional.ai_ecommerce.replies.putById(connection, {
    id: reply.id,
    body: { body: updatedBody } satisfies ai_ecommerceReply.IUpdate,
  });
  typia.assert(updatedReply);
  TestValidator.equals("id unchanged")(updatedReply.id)(reply.id);
  TestValidator.equals("body is updated")(updatedReply.body)(updatedBody);
  TestValidator.predicate("updated_at has changed")(updatedReply.updated_at !== reply.updated_at);

  // Step 4: Attempt update as different seller—should fail
  await TestValidator.error("permission denied for non-author seller")(async () => {
    await api.functional.ai_ecommerce.replies.putById(connection, {
      id: reply.id,
      body: { body: "Attempted update by other seller." } satisfies ai_ecommerceReply.IUpdate,
    });
  });

  // Step 5: (Skipped soft-deletion, not supported by IUpdate/PUT API as per DTO)
}

