import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerceComment } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerceComment";
import type { ai_ecommerceReply } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerceReply";

/**
 * Test soft deletion of a reply for both owner (seller/admin) and privileged admin.
 *
 * - Covers the contract that DELETE /ai_ecommerce/replies/:id is a soft delete (sets deleted_at, doesn't remove row).
 * - The test simulates replies authored by seller and administrator for a comment, and that both owner and admin (as privileged) can delete replies.
 * - Simulates an unauthorized user attempting deletion, expecting an error.
 * - Also checks idempotency or reasonable handling of multiple deletes (repeat call on deleted reply).
 *
 * Note: As the API does not provide GET for replies or user authentication context, the test uses fabricated UUIDs to represent ownership.
 *
 * Steps:
 * 1. Create a comment as a customer.
 * 2. Post two replies: one by seller, one by admin, both to the comment.
 * 3. Seller deletes their own reply (should succeed).
 * 4. Admin deletes their own reply (should succeed).
 * 5. Admin (privileged) deletes seller's reply (should be idempotent/allowed).
 * 6. Simulate unauthorized user deleting another's reply (should result in error).
 * 7. Try deleting an already-soft-deleted reply for idempotency.
 */
export async function test_api_ai_ecommerce_test_soft_delete_reply_by_owner_and_admin(
  connection: api.IConnection,
) {
  // 1. Create a comment as customer (fabricated customer_id)
  const customer_id = typia.random<string & tags.Format<"uuid">>();
  const comment = await api.functional.ai_ecommerce.comments.post(connection, {
    body: {
      customer_id,
      body: RandomGenerator.paragraph()(),
    } satisfies ai_ecommerceComment.ICreate,
  });
  typia.assert(comment);

  // 2. Create two replies: seller and admin
  const seller_id = typia.random<string & tags.Format<"uuid">>();
  const admin_id = typia.random<string & tags.Format<"uuid">>();

  const sellerReply = await api.functional.ai_ecommerce.replies.post(connection, {
    body: {
      seller_id,
      comment_id: comment.id,
      body: "Reply from seller",
    } satisfies ai_ecommerceReply.ICreate,
  });
  typia.assert(sellerReply);

  const adminReply = await api.functional.ai_ecommerce.replies.post(connection, {
    body: {
      administrator_id: admin_id,
      comment_id: comment.id,
      body: "Reply from admin",
    } satisfies ai_ecommerceReply.ICreate,
  });
  typia.assert(adminReply);

  // 3. Seller deletes their own reply
  await api.functional.ai_ecommerce.replies.eraseById(connection, {
    id: sellerReply.id,
  });

  // 4. Admin deletes their own reply
  await api.functional.ai_ecommerce.replies.eraseById(connection, {
    id: adminReply.id,
  });

  // 5. Admin deletes seller's reply (should be idempotent/allowed)
  await api.functional.ai_ecommerce.replies.eraseById(connection, {
    id: sellerReply.id,
  });

  // 6. Simulate unauthorized actor attempting to delete admin's reply (should fail)
  const unauth_seller_id = typia.random<string & tags.Format<"uuid">>();
