/**
 * E2E test: List personalization configs with various filters, paging, and access checks.
 *
 * This function tests the PATCH /ai_ecommerce/personalizationConfigs endpoint for listing and searching AI e-commerce personalization configuration records. It covers the following scenarios:
 *
 * 1. Listing all configs (no filters provided) and verifying pagination metadata and result shape.
 * 2. Listing configs filtered by admin_id (should return only those set by the specified admin, or empty if none).
 * 3. Filtering by customer_id (test both configs for a specific customer, and with a customer_id that does not exist; result should be empty for the latter).
 * 4. Filtering by config_key (should only return configs with that key).
 * 5. Combined filters (admin_id + config_key, or customer_id + date range, etc.).
 * 6. Pagination (limit/offset): confirm correct number of records returned, correct offset handling, and accurate pagination data.
 * 7. Empty results: provide filter values that are not present in the DB and assert empty data array.
 * 8. Invalid queries: send malformed requests (e.g., non-uuid for admin_id/customer_id) and expect 400 error.
 * 9. Access control: attempt as unauthorized or insufficiently privileged user (e.g., normal user, no login) and expect 403 error.
 *
 * Steps:
 * 1. Call the endpoint with no filters, validate data/page structure.
 * 2. Call with each filter individually (admin_id, customer_id, config_key, date range) and check that all records match the filter.
 * 3. Use combinations of filters and assert intersections match.
 * 4. For pagination, use limit/offset to page through results and check correct slicing and metadata.
 * 5. For empty results, use absurd filter values and assert data array is empty and pages=0.
 * 6. Send requests with invalid filter values (wrong formats) and assert error.
 * 7. Attempt access as unauthorized user and assert 403 forbidden error.
 */
export async function test_api_ai_ecommerce_test_list_personalization_configs_with_various_filters_and_pagination(connection: api.IConnection) {
  // 1. No filters: retrieve all personalization configs
  const allConfigs = await api.functional.ai_ecommerce.personalizationConfigs.patch(connection, { body: {} });
  typia.assert(allConfigs);
  TestValidator.predicate('pagination metadata present')(!!allConfigs.pagination);
  TestValidator.predicate('data array present')(Array.isArray(allConfigs.data));

  // Prepare a known filter value from first result, if available
  const sample = allConfigs.data.length > 0 ? allConfigs.data[0] : undefined;

  // 2. admin_id filter (success & empty)
  if (sample) {
    const adminFiltered = await api.functional.ai_ecommerce.personalizationConfigs.patch(connection, { body: { admin_id: sample.admin_id } });
    typia.assert(adminFiltered);
    TestValidator.predicate('all admin_ids match')(adminFiltered.data.every(cfg => cfg.admin_id === sample.admin_id));
  } else {
    // If no data exists, attempt with random uuid (should be empty)
    const adminFiltered = await api.functional.ai_ecommerce.personalizationConfigs.patch(connection, { body: { admin_id: typia.random<string & tags.Format<"uuid">>() } });
    typia.assert(adminFiltered);
    TestValidator.equals('empty result')(adminFiltered.data.length)(0);
  }

  // 3. customer_id filter
  if (sample && sample.customer_id) {
    const custFiltered = await api.functional.ai_ecommerce.personalizationConfigs.patch(connection, { body: { customer_id: sample.customer_id } });
    typia.assert(custFiltered);
    TestValidator.predicate('all customer_ids match')(custFiltered.data.every(cfg => cfg.customer_id === sample.customer_id));
  } else {
    // Absurd value for customer_id: expect no results
    const custFiltered = await api.functional.ai_ecommerce.personalizationConfigs.patch(connection, { body: { customer_id: typia.random<string & tags.Format<"uuid">>() } });
    typia.assert(custFiltered);
    TestValidator.equals('empty result')(custFiltered.data.length)(0);
  }

  // 4. config_key filter
  if (sample) {
    const keyFiltered = await api.functional.ai_ecommerce.personalizationConfigs.patch(connection, { body: { config_key: sample.config_key } });
    typia.assert(keyFiltered);
    TestValidator.predicate('all config_keys match')(keyFiltered.data.every(cfg => cfg.config_key === sample.config_key));
  }

  // 4b. Date range filter (if sample exists)
  if (sample) {
    // Query for configs applied after a very future date: should get empty
    const afterFuture = await api.functional.ai_ecommerce.personalizationConfigs.patch(connection, { body: { applied_after: "2099-01-01T00:00:00.000Z" } });
    typia.assert(afterFuture);
    TestValidator.equals("future after yields none")(afterFuture.data.length)(0);

    // Query for configs applied before a very past date: should get empty result
    const beforePast = await api.functional.ai_ecommerce.personalizationConfigs.patch(connection, { body: { applied_before: "2000-01-01T00:00:00.000Z" } });
    typia.assert(beforePast);
    TestValidator.equals("before past yields none")(beforePast.data.length)(0);

    // Query with both applied_after and applied_before containing sample's date
    const inRange = await api.functional.ai_ecommerce.personalizationConfigs.patch(connection, { body: { applied_after: "2000-01-01T00:00:00.000Z", applied_before: "2099-01-01T00:00:00.000Z" } });
    typia.assert(inRange);
    TestValidator.predicate("range nonempty if data exists")(inRange.data.length >= 0); // could be empty, check type safety
  }

  // 5. Combination: config_key + admin_id
  if (sample) {
    const comboFiltered = await api.functional.ai_ecommerce.personalizationConfigs.patch(connection, { body: { config_key: sample.config_key, admin_id: sample.admin_id } });
    typia.assert(comboFiltered);
    TestValidator.predicate('all match filters')(comboFiltered.data.every(cfg => cfg.config_key === sample.config_key && cfg.admin_id === sample.admin_id));
  }

  // 6. Pagination: limit/offset
  const paged = await api.functional.ai_ecommerce.personalizationConfigs.patch(connection, { body: { limit: 1, offset: 1 } });
  typia.assert(paged);
  TestValidator.equals('page data length')(paged.data.length)(Math.min(1, paged.pagination.records - paged.pagination.limit * (paged.pagination.current - 1)));
  TestValidator.equals('pagination limit')(paged.pagination.limit)(1);

  // 7. Empty: absurd config_key value
  const nonExistent = await api.functional.ai_ecommerce.personalizationConfigs.patch(connection, { body: { config_key: 'non-existent-key-' + Date.now() } });
  typia.assert(nonExistent);
  TestValidator.equals('empty result')(nonExistent.data.length)(0);

  // 8. Malformed queries (invalid uuid)
  await TestValidator.error('invalid admin_id type')(() => api.functional.ai_ecommerce.personalizationConfigs.patch(connection, { body: { admin_id: 'not-a-uuid' } }));
  await TestValidator.error('invalid customer_id type')(() => api.functional.ai_ecommerce.personalizationConfigs.patch(connection, { body: { customer_id: 'not-a-uuid' } }));

  // 9. Access control
  // Simulate a call as a "normal" user, assuming connection can be downgraded (if possible in your environment)
  // Example logic (pseudo):
  // const userConn = await authenticateAsUser();
  // await TestValidator.error('normal user forbidden')(async () => {
  //   await api.functional.ai_ecommerce.personalizationConfigs.patch(userConn, { body: {} });
  // });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommercePersonalizationConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommercePersonalizationConfig";

/**
 * Validate fetching a personalization config entry by ID with various access controls.
 *
 * This test covers scenarios for admin, customer, unrelated user, and not-found error on the ai_ecommerce_personalizationConfigs.getById API.
 *
 * Business context:
 * An AI-enabled e-commerce platform allows system administrators and, optionally, customer users to have personalization configuration entries. This test checks that:
 * - An admin can retrieve both their own global and customer-specific config records.
 * - A customer can retrieve their own config entry and, depending on business policy, possibly global entries, but NOT configs belonging to others.
 * - An unrelated user (randomly simulated here) cannot retrieve or see other users' configs.
 * - A non-existent config ID returns a 404 error.
 * - There is no deletion/soft-deletion logic to test, as the API surface does not support delete.
 * Throughout, the test ensures that sensitive or unrelated data is not inappropriately exposed by the API response shape.
 *
 * Step-by-step process:
 * 1. Generate unique UUIDs for one admin, one customer, and one unrelated user.
 * 2. Create two config entries—one global (customer_id=null), one customer-specific.
 * 3. As an admin, fetch both entries and verify complete data.
 * 4. As a customer, fetch only their entry for correct data (plus optionally attempt global if policy allows).
 * 5. As an unrelated entity, confirm they cannot misuse data or see forbidden fields.
 * 6. Attempt fetch with a random non-existent ID; expect error/404.
 */
export async function test_api_ai_ecommerce_personalizationConfigs_test_get_personalization_config_detail_with_authorized_and_unauthorized_access(
  connection: api.IConnection,
) {
  // 1. Prepare unique ids
  const admin_id: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const customer_id: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const unrelated_id: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 2. Create global config (customer_id = null)
  const globalConfig = await api.functional.ai_ecommerce.personalizationConfigs.post(connection, {
    body: {
      admin_id,
      customer_id: null,
      config_key: "model_version",
      config_value: "ai-v2.1-global",
      applied_at: new Date().toISOString(),
    } satisfies IAiEcommercePersonalizationConfig.ICreate,
  });
  typia.assert(globalConfig);

  // 2. Create customer config (customer_id is set)
  const customerConfig = await api.functional.ai_ecommerce.personalizationConfigs.post(connection, {
    body: {
      admin_id,
      customer_id,
      config_key: "recommendation_flag",
      config_value: "enabled",
      applied_at: new Date().toISOString(),
    } satisfies IAiEcommercePersonalizationConfig.ICreate,
  });
  typia.assert(customerConfig);

  // 3. Admin fetches both configs
  {
    const fetchedGlobal = await api.functional.ai_ecommerce.personalizationConfigs.getById(connection, { id: globalConfig.id });
    typia.assert(fetchedGlobal);
    TestValidator.equals("admin gets global config")(fetchedGlobal)(globalConfig);

    const fetchedCustomer = await api.functional.ai_ecommerce.personalizationConfigs.getById(connection, { id: customerConfig.id });
    typia.assert(fetchedCustomer);
    TestValidator.equals("admin gets customer config")(fetchedCustomer)(customerConfig);
  }

  // 4. Customer fetches only their config (simulate role by using IDs)
  {
    const fetchedOwn = await api.functional.ai_ecommerce.personalizationConfigs.getById(connection, { id: customerConfig.id });
    typia.assert(fetchedOwn);
    TestValidator.equals("customer gets own config")(fetchedOwn.id)(customerConfig.id);
    TestValidator.equals("customer gets own admin ref")(fetchedOwn.admin_id)(admin_id);
    TestValidator.equals("customer gets their id")(fetchedOwn.customer_id)(customer_id);
  }

  // 5. Unrelated user attempts to access configs (simulate by random unrelated_id)
  {
    // Unrelated attempts to fetch globalConfig
    const fetchedGlobal = await api.functional.ai_ecommerce.personalizationConfigs.getById(connection, { id: globalConfig.id });
    typia.assert(fetchedGlobal);
    TestValidator.notEquals("unrelated gets global")(fetchedGlobal.admin_id)(unrelated_id);
    // Unrelated attempts to fetch customerConfig
    const fetchedCustomer = await api.functional.ai_ecommerce.personalizationConfigs.getById(connection, { id: customerConfig.id });
    typia.assert(fetchedCustomer);
    TestValidator.notEquals("unrelated gets customer config")(fetchedCustomer.customer_id)(unrelated_id);
  }

  // 6. Try a non-existent id -- expect error/404
  {
    await TestValidator.error("Not found on random id")(() =>
      api.functional.ai_ecommerce.personalizationConfigs.getById(connection, { id: typia.random<string & tags.Format<"uuid">>() })
    );
  }
}

