import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommercePersonalizationConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommercePersonalizationConfig";

/**
 * Comprehensive E2E test for updating an AI ecommerce personalization config.
 *
 * ## Business Workflow Validated:
 * 1. Create a personalization config via POST endpoint.
 * 2. Update mutable fields (config_value, applied_at, admin/customer assignment) using PUT by ID.
 * 3. Attempt to update immutable fields (such as id or created_at) and confirm the API ignores/rejects those (skipped per DTO restriction).
 * 4. Simulate permission checks by updating with unrelated admin/customer IDs (no auth API, so this is as close as feasible).
 * 5. Try updating a config with a random non-existent id (expect not found error).
 * 6. Confirm all successful changes are reflected and proper errors are returned on failure.
 *
 * > Note: API does not expose authentication/role-switching endpoints, so permission checks are simulated via admin_id/customer_id parameter changes.
 * > Attempting to update immutable fields is not possible by DTO shape and so is omitted from the test implementation per E2E requirements.
 *
 * @author
 */
export async function test_api_ai_ecommerce_test_update_personalization_config_with_full_and_partial_changes(
  connection: api.IConnection,
) {
  // 1. Create a new personalization config to setup test context
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const initialConfigKey = `model_version_${RandomGenerator.alphaNumeric(4)}`;
  const initialPayload: IAiEcommercePersonalizationConfig.ICreate = {
    admin_id: adminId,
    customer_id: customerId,
    config_key: initialConfigKey,
    config_value: "v1.0.0",
    applied_at: new Date().toISOString(),
  };
  const createdConfig = await api.functional.ai_ecommerce.personalizationConfigs.post(connection, { body: initialPayload });
  typia.assert(createdConfig);

  // 2. Update mutable fields (config_value, applied_at, admin_id, customer_id, config_key)
  const updatedValue = "v2.0.1";
  const newAppliedAt = new Date(Date.now() + 86400000).toISOString();
  const newAdminId = typia.random<string & tags.Format<"uuid">>();
  const newCustomerId = typia.random<string & tags.Format<"uuid">>();
  const updatePayloadFull: IAiEcommercePersonalizationConfig.IUpdate = {
    config_value: updatedValue,
    applied_at: newAppliedAt,
    admin_id: newAdminId,
    customer_id: newCustomerId,
    config_key: initialConfigKey + "_updated",
  };
  const updatedConfig = await api.functional.ai_ecommerce.personalizationConfigs.putById(connection, {
    id: createdConfig.id,
    body: updatePayloadFull,
  });
  typia.assert(updatedConfig);
  TestValidator.equals("updated config_value")(updatedConfig.config_value)(updatedValue);
  TestValidator.equals("updated applied_at")(updatedConfig.applied_at)(newAppliedAt);
  TestValidator.equals("updated admin_id")(updatedConfig.admin_id)(newAdminId);
  TestValidator.equals("updated customer_id")(updatedConfig.customer_id)(newCustomerId);
  TestValidator.equals("updated config_key")(updatedConfig.config_key)(updatePayloadFull.config_key);

  // 3. Attempt to update immutable fields (e.g., id):
  //    DTO schema forbids this, so we skip this step per E2E rules (TypeScript prevents compiling such payload).

  // 4. Simulate role-based permission check: attempt update as unrelated admin/customer (no login API)
  const nonPrivAdminId = typia.random<string & tags.Format<"uuid">>();
  const nonPrivCustomerId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("forbidden update for non-privileged user")(
    async () => {
      await api.functional.ai_ecommerce.personalizationConfigs.putById(connection, {
        id: createdConfig.id,
        body: {
          admin_id: nonPrivAdminId,
          customer_id: nonPrivCustomerId,
          config_value: "hacker-attack"
        } satisfies IAiEcommercePersonalizationConfig.IUpdate,
      });
    },
  );

  // 5. Try updating with a random non-existent config id (should yield not found error)
  await TestValidator.error("not found update")(
    async () => {
      await api.functional.ai_ecommerce.personalizationConfigs.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: {
          config_value: "missing-config-test"
        } satisfies IAiEcommercePersonalizationConfig.IUpdate,
      });
    },
  );

  // 6. If the API exposed a method to check audit history, we would now verify audit logging or change tracing. No such method is present, so this is skipped.
}

