import type { IPageIai_ecommerceCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIai_ecommerceCartItem";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAiEcommerceCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceCartItem";

/**
 * Test listing cart items (ai_ecommerce_cart_item) with various filters and pagination options.
 *
 * This e2e function covers the following:
 *   1. Creating a cart for a customer, then adding two separate SKUs as cart items.
 *   2. Running list/search (PATCH /ai_ecommerce/cartItems) as the customer, while:
 *      - Filtering by cart_id (should return both items)
 *      - Filtering by sku_id for one SKU (should return a single item)
 *      - Filtering by non-existent/unauthorized cart_id (should return none)
 *   3. Verifies that filtering works, only authorized queries succeed, and error handling works for input edge cases.
 *
 * Steps:
 * 1. Create a cart for a random customer
 * 2. Add two cart items with different SKU IDs
 * 3. List cart items with no filters (should return both for the customer's cart)
 * 4. List cart items filtered by sku_id for the first SKU (should return one)
 * 5. List cart items filtered by cart_id (should return both)
 * 6. List using invalid cart_id (should return 0)
 */
export async function test_api_ai_ecommerce_test_list_cart_items_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a random customer UUID for test association
  const customer_id: string = typia.random<string & tags.Format<"uuid">>();
  // 2. Create a cart for the customer
  const cart = await api.functional.ai_ecommerce.cart.post(connection, {
    body: {
      customer_id,
      cart_status: "active",
      device_context: "e2e-test-context"
    } satisfies Iai_ecommerceCart.ICreate,
  });
  typia.assert(cart);

  // 3. Add two cart items with different SKUs
  const sku_id_1: string = typia.random<string & tags.Format<"uuid">>();
  const sku_id_2: string = typia.random<string & tags.Format<"uuid">>();

  const item1 = await api.functional.ai_ecommerce.cartItems.post(connection, {
    body: {
      cart_id: cart.id,
      sku_id: sku_id_1,
      quantity: 2
    } satisfies IAiEcommerceCartItem.ICreate,
  });
  typia.assert(item1);

  const item2 = await api.functional.ai_ecommerce.cartItems.post(connection, {
    body: {
      cart_id: cart.id,
      sku_id: sku_id_2,
      quantity: 3
    } satisfies IAiEcommerceCartItem.ICreate,
  });
  typia.assert(item2);

  // 4. List without filters: should get both items
  let result = await api.functional.ai_ecommerce.cartItems.patch(connection, {
    body: {} satisfies Iai_ecommerceCartItem.IRequest,
  });
  typia.assert(result);
  // Should contain both items in data (may contain more if not isolated test DB)
  const matchCart = result.data.filter(r => r.cart_id === cart.id);
  TestValidator.equals("both items present")(matchCart.length)(2);
  TestValidator.predicate("item 1 in results")(matchCart.some(r => r.id === item1.id));
  TestValidator.predicate("item 2 in results")(matchCart.some(r => r.id === item2.id));

  // 5. List with cart_id filter
  result = await api.functional.ai_ecommerce.cartItems.patch(connection, {
    body: { cart_id: cart.id } satisfies Iai_ecommerceCartItem.IRequest,
  });
  typia.assert(result);
  TestValidator.equals("filter by cart_id")(result.data.length)(2);
  TestValidator.predicate("cart_id matched for all")(result.data.every(r => r.cart_id === cart.id));

  // 6. List with sku_id filter for item1
  result = await api.functional.ai_ecommerce.cartItems.patch(connection, {
    body: { sku_id: sku_id_1 } satisfies Iai_ecommerceCartItem.IRequest,
  });
  typia.assert(result);
  const sku1inCart = result.data.find(r => r.sku_id === sku_id_1 && r.cart_id === cart.id);
  TestValidator.predicate("sku_id_1 found")(!!sku1inCart);
  TestValidator.equals("sku_id matches")(sku1inCart?.sku_id)(sku_id_1);

  // 7. List with invalid cart_id
  result = await api.functional.ai_ecommerce.cartItems.patch(connection, {
    body: { cart_id: typia.random<string & tags.Format<"uuid">>() } satisfies Iai_ecommerceCartItem.IRequest,
  });
  typia.assert(result);
  // The result may be empty array; expect no items matching our known cart
  TestValidator.equals("empty results for invalid cart_id")(result.data.some(r => r.cart_id === cart.id))(false);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { Iai_ecommerceCart } from "@ORGANIZATION/PROJECT-api/lib/structures/Iai_ecommerceCart";
import type { IAiEcommerceCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceCartItem";

/**
 * Test retrieving a cart item by its ID under various scenarios: normal, not found, and (where feasible) forbidden access.
 *
 * Business context:
 * - Ensures that a customer can retrieve their own cart item by its ID and that full details match expectations.
 * - Verifies that API correctly responds with an error when an unknown ID is used.
 * - Where possible, simulates that cart items are not accessible across customers, though true multi-user isolation is not testable with the available interface.
 *
 * Test process:
 * 1. Create a cart (for a synthetic customer) using the proper API, and then create a cart item in this cart. This yields a valid, owned cart item ID.
 * 2. Retrieve the cart item by ID. Assert all details, including cart, SKU, and quantity, match those provided at creation, and that typia asserts the type structure.
 * 3. Attempt to retrieve a cart item by a random non-existent UUID, and confirm error is thrown (simulates not found response).
 * 4. (Simulated) Attempt to access cart item as if using another user's credentials. Due to missing user switching capability in the current SDK, this is documented rather than functionally enforced.
 *
 * Any scenario steps which cannot be directly implemented with the API or SDK are annotated and gracefully omitted.
 */
export async function test_api_ai_ecommerce_test_get_cart_item_by_id_when_exists_and_when_not_found(
  connection: api.IConnection,
) {
  // 1. Create a cart for a synthetic (random) customer
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const cart = await api.functional.ai_ecommerce.cart.post(connection, {
    body: {
      customer_id: customerId,
      device_context: RandomGenerator.alphaNumeric(8),
      cart_status: "active",
    } satisfies Iai_ecommerceCart.ICreate,
  });
  typia.assert(cart);

  // 2. Create a cart item in the cart
  const skuId = typia.random<string & tags.Format<"uuid">>();
  const quantity = 1;
  const cartItem = await api.functional.ai_ecommerce.cartItems.post(connection, {
    body: {
      cart_id: cart.id,
      sku_id: skuId,
      quantity,
    } satisfies IAiEcommerceCartItem.ICreate,
  });
  typia.assert(cartItem);
  TestValidator.equals("cart id matches")(cartItem.cart_id)(cart.id);
  TestValidator.equals("sku id matches")(cartItem.sku_id)(skuId);
  TestValidator.equals("quantity matches")(cartItem.quantity)(quantity);

  // 3. Retrieve the cart item by its own id
  const fetched = await api.functional.ai_ecommerce.cartItems.getById(connection, {
    id: cartItem.id,
  });
  typia.assert(fetched);
  TestValidator.equals("fetched matches created")(fetched.id)(cartItem.id);
  TestValidator.equals("cart id matches")(fetched.cart_id)(cart.id);
  TestValidator.equals("sku id matches")(fetched.sku_id)(skuId);
  TestValidator.equals("quantity matches")(fetched.quantity)(quantity);

  // 4. NotFound: Attempt to fetch a cart item with a random, likely non-existent ID
  await TestValidator.error("not found for random cart item id")(() =>
    api.functional.ai_ecommerce.cartItems.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );

  // 5. Simulated forbidden: If there were multi-user support with isolation, we would attempt retrieval with another customer context.
  // As the SDK/API does not support user switching or session tokens for different customers, this is not implemented.
  // Documentation: In production, test would attempt to access previous cart item using a different authorized user, and check for forbidden/permission error.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_product } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_product";
import type { ai_ecommerce_skus } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_skus";
import type { Iai_ecommerceCart } from "@ORGANIZATION/PROJECT-api/lib/structures/Iai_ecommerceCart";
import type { IAiEcommerceCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceCartItem";

/**
 * 테스트 목적: 장바구니에 SKU(제품 옵션)를 추가하는 행위를 검증한다.
 *
 * - 장바구니와 SKU는 사전 생성되어 있어야 한다.
 * - 성공: 올바른 카트/sku, 유효한 quantity(1 이상)로 카트 아이템을 추가한다.
 * - 비즈니스 규칙 위반: 같은 SKU를 동일 카트에 중복 추가하면 새로운 행(row)이 생성되는 게 아니라 수량이 증가해야 한다(단, 실제 스키마와 구현 비즈니스 로직에 따라 예외/실패/증가 등 기대 동작을 검증한다).
 * - 실패: 존재하지 않는 카트ID/skuID, 잘못된 수량(0, 음수)으로 추가 시 실패해야 한다.
 * - 권한: 자신의 카트가 아니라면 추가에 실패(권한 오류)를 검증한다.
 *
 * 테스트 단계:
 * 1. 상품(product)을 생성한다 (SKU를 만들기 위해 필요)
 * 2. 해당 상품에 SKU를 만든다
 * 3. cart를 만든다
 * 4. cartItem을 유효한 조합으로 성공적으로 넣는다
 * 5. 동일 SKU 중복 추가 시 수량이 증감됨을 확인(또는 정책상 에러가 발생함을 확인)
 * 6. 존재하지 않는 SKU/cart id로 시도 시 실패 검증
 * 7. 수량 0/음수로 시도 시 실패 검증
 *  (권한/다른 사용자의 cart 추가실패 케이스는 별도의 인증API 필요 시 생략)
 */
export async function test_api_ai_ecommerce_test_add_cart_item_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. 상품 생성(선행)
  const product = await api.functional.ai_ecommerce.products.post(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      description: RandomGenerator.content()()(),
      status: "published",
      approval_state: "approved",
    },
  });
  typia.assert(product);

  // 2. SKU 생성(상품 필수)
  const sku = await api.functional.ai_ecommerce.skus.post(connection, {
    body: {
      product_id: product.id,
      code: RandomGenerator.alphaNumeric(8),
      price: 9900,
      currency: "KRW",
      is_active: true,
    },
  });
  typia.assert(sku);

  // 3. 장바구니 생성
  const cart = await api.functional.ai_ecommerce.cart.post(connection, {
    body: {
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      device_context: RandomGenerator.alphaNumeric(10),
      cart_status: "active",
    },
  });
  typia.assert(cart);

  // 4. 정상: 유효한 SKU/Cart/수량(1 이상) 으로 추가 (성공)
  const item1 = await api.functional.ai_ecommerce.cartItems.post(connection, {
    body: {
      cart_id: cart.id,
      sku_id: sku.id,
      quantity: 2,
    },
  });
  typia.assert(item1);
  TestValidator.equals("item1 카트ID 체크")(item1.cart_id)(cart.id);
  TestValidator.equals("item1 SKU 체크")(item1.sku_id)(sku.id);
  TestValidator.equals("item1 수량 체크")(item1.quantity)(2);

  // 5. 동일 SKU 중복 추가 시 수량 증가 정책(O 또는 정책상 예외):
  const item2 = await api.functional.ai_ecommerce.cartItems.post(connection, {
    body: {
      cart_id: cart.id,
      sku_id: sku.id,
      quantity: 3,
    },
  });
  typia.assert(item2);
  TestValidator.equals("item2 카트ID 체크")(item2.cart_id)(cart.id);
  TestValidator.equals("item2 SKU 체크")(item2.sku_id)(sku.id);
  // 정책상 OK(합산), 기존수량+3=5 일 수도, 아니면 정책상 에러일 수도. 실제 output에 맞게 체크
  TestValidator.predicate("수량은 3 이상이어야 함")(item2.quantity >= 3);

  // 6. 실패: 존재하지 않는 cart ID
  await TestValidator.error("존재하지 않는 cart id는 실패해야 함")(async () => {
    await api.functional.ai_ecommerce.cartItems.post(connection, {
      body: {
        cart_id: typia.random<string & tags.Format<"uuid">>(),
        sku_id: sku.id,
        quantity: 1,
      },
    });
  });

  // 7. 실패: 존재하지 않는 SKU id
  await TestValidator.error("존재하지 않는 sku id는 실패")(async () => {
    await api.functional.ai_ecommerce.cartItems.post(connection, {
      body: {
        cart_id: cart.id,
        sku_id: typia.random<string & tags.Format<"uuid">>(),
        quantity: 1,
      },
    });
  });

  // 8. 실패: 수량 0
  await TestValidator.error("수량 0은 실패")(async () => {
    await api.functional.ai_ecommerce.cartItems.post(connection, {
      body: {
        cart_id: cart.id,
        sku_id: sku.id,
        quantity: 0 as 0,
      },
    });
  });

  // 9. 실패: 수량 음수
  await TestValidator.error("수량이 음수는 실패")(async () => {
    await api.functional.ai_ecommerce.cartItems.post(connection, {
      body: {
        cart_id: cart.id,
        sku_id: sku.id,
        quantity: -4 as -4,
      },
    });
  });
  // 권한/다른 사용자의 cart 접근은 별도의 인증API (custom login/join)이 있는 경우만 추가 검증
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_product } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_product";
import type { ai_ecommerce_skus } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_skus";
import type { Iai_ecommerceCart } from "@ORGANIZATION/PROJECT-api/lib/structures/Iai_ecommerceCart";
import type { IAiEcommerceCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceCartItem";

/**
 * Validate updating the quantity of an AI E-commerce cart item by ID including business logic, boundaries, and permissions.
 *
 * This test simulates a realistic customer shopping scenario with the following validation steps:
 *
 * 1. Prepare dependencies by creating a cart (customer-owned), adding a product and SKU, and inserting a cart item.
 * 2. Successfully update the cart item quantity to a new valid value, verifying the changed value.
 * 3. Boundary validation: try to set quantity to zero (should fail, as minimum is 1), and to a negative number (should fail validation).
 * 4. Permission error: simulate another user's cart and item, then attempt to update as the original user and expect a permission error.
 * 5. Not-found error: attempt to update a random/nonexistent or deleted cart item and verify error is thrown.
 */
export async function test_api_ai_ecommerce_cartItems_test_update_cart_item_quantity_and_permissions(
  connection: api.IConnection,
) {
  // 1. Prepare cart for customer
  const customer_id: string = typia.random<string & tags.Format<"uuid">>();
  const cart = await api.functional.ai_ecommerce.cart.post(connection, {
    body: {
      customer_id,
      device_context: null,
      cart_status: "active",
    } satisfies Iai_ecommerceCart.ICreate,
  });
  typia.assert(cart);

  // 2. Create product and SKU associated with cart item
  const seller_id: string = typia.random<string & tags.Format<"uuid">>();
  const product = await api.functional.ai_ecommerce.products.post(connection, {
    body: {
      seller_id,
      title: RandomGenerator.paragraph()(),
      description: RandomGenerator.content()()(),
      status: "published",
      approval_state: "approved",
    } satisfies ai_ecommerce_product.ICreate,
  });
  typia.assert(product);
  const sku = await api.functional.ai_ecommerce.skus.post(connection, {
    body: {
      product_id: product.id,
      code: RandomGenerator.alphaNumeric(8),
      price: 29900,
      currency: "KRW",
      is_active: true,
    } satisfies ai_ecommerce_skus.ICreate,
  });
  typia.assert(sku);

  // 3. Add cart item (quantity=1)
  const cartItem = await api.functional.ai_ecommerce.cartItems.post(connection, {
    body: {
      cart_id: cart.id,
      sku_id: sku.id,
      quantity: 1,
    } satisfies IAiEcommerceCartItem.ICreate,
  });
  typia.assert(cartItem);

  // 4. Update quantity to a valid value (e.g. 3)
  const updatedItem = await api.functional.ai_ecommerce.cartItems.putById(connection, {
    id: cartItem.id,
    body: {
      quantity: 3,
    } satisfies IAiEcommerceCartItem.IUpdate,
  });
  typia.assert(updatedItem);
  TestValidator.equals("quantity updated")(updatedItem.quantity)(3);

  // 5. Set quantity to zero (should fail validation - min 1)
  await TestValidator.error("quantity=0 must fail")(() =>
    api.functional.ai_ecommerce.cartItems.putById(connection, {
      id: cartItem.id,
      body: { quantity: 0 } satisfies IAiEcommerceCartItem.IUpdate,
    }),
  );

  // 6. Set quantity to a negative value (should fail validation)
  await TestValidator.error("quantity negative must fail")(() =>
    api.functional.ai_ecommerce.cartItems.putById(connection, {
      id: cartItem.id,
      body: { quantity: -2 } satisfies IAiEcommerceCartItem.IUpdate,
    }),
  );

  // 7. Simulate a foreign user: create their cart and cart item, attempt update
  const other_customer_id = typia.random<string & tags.Format<"uuid">>();
  const other_cart = await api.functional.ai_ecommerce.cart.post(connection, {
    body: {
      customer_id: other_customer_id,
      device_context: null,
      cart_status: "active",
    } satisfies Iai_ecommerceCart.ICreate,
  });
  typia.assert(other_cart);
  const other_item = await api.functional.ai_ecommerce.cartItems.post(connection, {
    body: {
      cart_id: other_cart.id,
      sku_id: sku.id,
      quantity: 1,
    } satisfies IAiEcommerceCartItem.ICreate,
  });
  typia.assert(other_item);
  // Attempt update as original user (connection context): expect permission error
  await TestValidator.error("updating other user's cart item must fail")(() =>
    api.functional.ai_ecommerce.cartItems.putById(connection, {
      id: other_item.id,
      body: { quantity: 2 } satisfies IAiEcommerceCartItem.IUpdate,
    }),
  );

  // 8. Attempt update to random/deleted cart item (simulate not-found)
  await TestValidator.error("updating deleted/nonexistent cart item")(() =>
    api.functional.ai_ecommerce.cartItems.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { quantity: 2 } satisfies IAiEcommerceCartItem.IUpdate,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_product } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_product";
import type { ai_ecommerce_skus } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_skus";
import type { Iai_ecommerceCart } from "@ORGANIZATION/PROJECT-api/lib/structures/Iai_ecommerceCart";
import type { IAiEcommerceCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceCartItem";
import type { IDeleteResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IDeleteResult";

/**
 * Test deletion of cart items, covering success and error conditions.
 *
 * This test will:
 * 1. Create a full product→sku→cart→cartItem hierarchy
 * 2. Delete an existing cart item as the cart owner, expecting successful deletion confirmation
 * 3. Attempt to delete a non-existent cart item UUID (should get not found error)
 * 4. Attempt to delete a cart item that is not owned by the current user (requires creating a cart for a different user and adding an item)
 * 5. Try deleting the same cart item twice to confirm idempotency or expected error on the second try
 */
export async function test_api_ai_ecommerce_cartItems_test_delete_cart_item_success_and_error_conditions(
  connection: api.IConnection,
) {
  // 1. Create a product with a unique seller
  const seller_id = typia.random<string & tags.Format<"uuid">>();
  const product = await api.functional.ai_ecommerce.products.post(connection, {
    body: {
      seller_id,
      title: RandomGenerator.alphabets(10),
      description: RandomGenerator.alphabets(20),
      status: "published",
      approval_state: "approved",
    } satisfies ai_ecommerce_product.ICreate,
  });
  typia.assert(product);

  // 2. Create SKU for the product
  const sku = await api.functional.ai_ecommerce.skus.post(connection, {
    body: {
      product_id: product.id,
      code: RandomGenerator.alphabets(8),
      price: 5000,
      currency: "KRW",
      is_active: true,
    } satisfies ai_ecommerce_skus.ICreate,
  });
  typia.assert(sku);

  // 3. Create a cart for a user
  const customer_id = typia.random<string & tags.Format<"uuid">>();
  const cart = await api.functional.ai_ecommerce.cart.post(connection, {
    body: {
      customer_id,
      device_context: RandomGenerator.alphabets(8),
      cart_status: "active",
    } satisfies Iai_ecommerceCart.ICreate,
  });
  typia.assert(cart);

  // 4. Create a cart item for that cart and SKU
  const cartItem = await api.functional.ai_ecommerce.cartItems.post(connection, {
    body: {
      cart_id: cart.id,
      sku_id: sku.id,
      quantity: 2,
    } satisfies IAiEcommerceCartItem.ICreate,
  });
  typia.assert(cartItem);

  // 5. Successful deletion: Remove the existing cart item by its ID
  const firstDelete = await api.functional.ai_ecommerce.cartItems.eraseById(connection, {
    id: cartItem.id,
  });
  typia.assert(firstDelete);
  TestValidator.equals("deleted cartItem.id")(firstDelete.id)(cartItem.id);
  TestValidator.predicate("deleted flag true")(firstDelete.deleted === true);

  // 6. Attempt to delete the same cart item again (expect either idempotent success or error)
  await TestValidator.error("Repeated deletion should fail or be idempotent")(
    async () => {
      await api.functional.ai_ecommerce.cartItems.eraseById(connection, {
        id: cartItem.id,
      });
    },
  );

  // 7. Delete a non-existent cart item (random uuid)
  await TestValidator.error("Delete non-existent cart item should fail")(
    async () => {
      await api.functional.ai_ecommerce.cartItems.eraseById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 8. Create a secondary customer, cart, and cart item
  const outsider_customer_id = typia.random<string & tags.Format<"uuid">>();
  const outsider_cart = await api.functional.ai_ecommerce.cart.post(connection, {
    body: {
      customer_id: outsider_customer_id,
      device_context: RandomGenerator.alphabets(8),
      cart_status: "active",
    } satisfies Iai_ecommerceCart.ICreate,
  });
  typia.assert(outsider_cart);
  const outsider_cart_item = await api.functional.ai_ecommerce.cartItems.post(connection, {
    body: {
      cart_id: outsider_cart.id,
      sku_id: sku.id,
      quantity: 1,
    } satisfies IAiEcommerceCartItem.ICreate,
  });
  typia.assert(outsider_cart_item);

  // 9. Try deleting outsider's cart item as the original user (assuming connection is not admin)
  await TestValidator.error("Cannot delete cart item not owned by current user")(
    async () => {
      await api.functional.ai_ecommerce.cartItems.eraseById(connection, {
        id: outsider_cart_item.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrder";
import type { IPageIAiEcommerceOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiEcommerceOrder";
import type { IAiEcommerceOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrderItem";

/**
 * 주문 페이징/상태/고객 필터링 기능 검증.
 *
 * - 고객1, 고객2 각각의 주문 생성 후 페이징/상태별 주문 조회 동작 검증
 * - Customer1로 로그인하여 자신의 주문만 나오는지, 페이징/상태 필터가 정상 작동하는지 확인
 * - 무효한 상태로 필터시 에러 반환 확인
 * - Customer2도 같은 방식으로 확인 (Role 전환 불가이므로, 각자 독립적으로 로그인/생성/조회)
 * - 어드민/셀러 등 고급 권한 테스트는 지원 API 부재로 생략 (권한, role 변환은 불가)
 */
export async function test_api_ai_ecommerce_test_list_orders_with_pagination_and_filtering_by_status_customer(
  connection: api.IConnection,
) {
  // 1. 테스트를 위해 고객 2명(각기 다른 UUID), 장바구니/주소 생성 (간략화, UUID 무작위)
  const customer1_id = typia.random<string & tags.Format<"uuid">>();
  const customer2_id = typia.random<string & tags.Format<"uuid">>();
  const cart1_id = typia.random<string & tags.Format<"uuid">>();
  const cart2_id = typia.random<string & tags.Format<"uuid">>();
  const address1_id = typia.random<string & tags.Format<"uuid">>();
  const address2_id = typia.random<string & tags.Format<"uuid">>();

  // 2. 고객1/2 각각 주문 여러 개 생성 (상태 다양화)
  const statuses = ["pending", "paid", "shipped", "cancelled"];
  const orders_customer1: string[] = [];
  const orders_customer2: string[] = [];

  // 고객1 주문 5개 생성
  for (let i = 0; i < 5; ++i) {
    const status = statuses[i % statuses.length];
    const order = await api.functional.ai_ecommerce.orders.post(connection, {
      body: {
        customer_id: customer1_id,
        cart_id: cart1_id,
        shipping_address_id: address1_id,
        order_status: status,
        order_channel: "web",
        items: [
          {
            sku_id: typia.random<string & tags.Format<"uuid">>(),
            quantity: 1,
          },
        ],
      } satisfies IAiEcommerceOrder.ICreate,
    });
    typia.assert(order);
    orders_customer1.push(order.id);
  }
  // 고객2 주문 3개 생성
  for (let i = 0; i < 3; ++i) {
    const status = statuses[(i + 1) % statuses.length];
    const order = await api.functional.ai_ecommerce.orders.post(connection, {
      body: {
        customer_id: customer2_id,
        cart_id: cart2_id,
        shipping_address_id: address2_id,
        order_status: status,
        order_channel: "app",
        items: [
          {
            sku_id: typia.random<string & tags.Format<"uuid">>(),
            quantity: 1,
          },
        ],
      } satisfies IAiEcommerceOrder.ICreate,
    });
    typia.assert(order);
    orders_customer2.push(order.id);
  }

  // 3. 고객1 기준: 페이징/고객 필터 조회 (limit=2, offset=0)
  const result1 = await api.functional.ai_ecommerce.orders.patch(connection, {
    body: {
      customer_id: customer1_id,
      limit: 2,
      offset: 0,
    } satisfies IAiEcommerceOrder.IRequest,
  });
  typia.assert(result1);
  // 레코드가 customer1 것만 있는지 체크
  for (const rec of result1.records) {
    TestValidator.equals("customer1 only")(rec.customer_id)(customer1_id);
  }
  // 페이징 메타 검증
  TestValidator.equals("limit matches record")(result1.pagination.limit)(2);
  TestValidator.predicate("pagination total_count >= 생성개수")(
    result1.total_count >= orders_customer1.length,
  );

  // 4. 상태 필터: 예를 들어 "paid"만
  const result_status = await api.functional.ai_ecommerce.orders.patch(connection, {
    body: {
      customer_id: customer1_id,
      order_status: "paid",
      limit: 10,
      offset: 0,
    } satisfies IAiEcommerceOrder.IRequest,
  });
  typia.assert(result_status);
  for (const rec of result_status.records) {
    TestValidator.equals("filter paid")(rec.order_status)("paid");
    TestValidator.equals("belongs to customer1")(rec.customer_id)(customer1_id);
  }

  // 5. 잘못된 status 값으로 시도 - 반드시 에러 발생해야 함
  await TestValidator.error("invalid status fails")(() =>
    api.functional.ai_ecommerce.orders.patch(connection, {
      body: {
        customer_id: customer1_id,
        order_status: "does-not-exist",
        limit: 5,
        offset: 0,
      } satisfies IAiEcommerceOrder.IRequest,
    }),
  );

  // 6. 고객2도 똑같이 (limit 2)
  const result2 = await api.functional.ai_ecommerce.orders.patch(connection, {
    body: {
      customer_id: customer2_id,
      limit: 2,
      offset: 0,
    } satisfies IAiEcommerceOrder.IRequest,
  });
  typia.assert(result2);
  for (const rec of result2.records) {
    TestValidator.equals("customer2 only")(rec.customer_id)(customer2_id);
  }
  TestValidator.equals("limit customer2")(result2.pagination.limit)(2);
  TestValidator.predicate("pagination count2 >= 생성개수")(
    result2.total_count >= orders_customer2.length,
  );
  // 고급 권한 테스트는 생략 (role 기반 권한은 인증 API 등 더 필요)
}

