import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserProfile";
import type { IAiEcommerceUserAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserAddress";
import type { Iai_ecommerceCart } from "@ORGANIZATION/PROJECT-api/lib/structures/Iai_ecommerceCart";
import type { IAiEcommerceCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceCartItem";
import type { IAiEcommerceOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrder";
import type { IAiEcommerceOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrderItem";

/**
 * 주문 생성 API의 정상 동작 확인 테스트
 *
 * 고객(유저) 프로필 → 장바구니(cart) 생성 → cart에 상품 추가 → 사용자 배송지 입력 → 
 * 최종적으로 cart, address, customer id로 주문을 등록하는 엔드투엔드 흐름 전체를 검증한다.
 *
 * 비즈니스 규칙:
 * - cart, address, customer 모두 유효해야 하며 cart는 최소 1개 이상의 아이템이 존재해야 함
 * - 성공 시 반환 주문 객체의 주요 식별자/정보가 입력과 일치해야 한다
 * - (실제 SKU 재고 등은 테스트의 한계로 무작위 uuid/quantity 허용)
 *
 * 1. 고객 프로필 생성
 * 2. 장바구니 생성
 * 3. 카트 아이템(임의 SKU 1개 이상) 추가
 * 4. 배송지 주소 생성
 * 5. 주문 생성
 * 6. 주문 생성 결과 상세 검증
 */
export async function test_api_ai_ecommerce_test_create_order_with_valid_cart_and_address(
  connection: api.IConnection,
) {
  // 1. 고객 프로필 생성
  const userProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      avatar_uri: null,
      email: typia.random<string & tags.Format<'email'>>(),
      phone_number: RandomGenerator.mobile(),
      communication_consent: true,
    },
  });
  typia.assert(userProfile);

  // 2. 장바구니(cart) 생성
  const cart = await api.functional.ai_ecommerce.cart.post(connection, {
    body: {
      customer_id: userProfile.id,
      device_context: null,
      cart_status: 'active',
    },
  });
  typia.assert(cart);

  // 3. 카트 아이템 1개 추가 (SKU는 무작위 uuid)
  const sampleSkuId = typia.random<string & tags.Format<'uuid'>>();
  const itemQuantity = 1;
  const cartItem = await api.functional.ai_ecommerce.cartItems.post(connection, {
    body: {
      cart_id: cart.id,
      sku_id: sampleSkuId,
      quantity: itemQuantity,
    },
  });
  typia.assert(cartItem);

  // 4. 배송지 주소 생성
  const userAddress = await api.functional.ai_ecommerce.userAddresses.post(connection, {
    body: {
      profile_id: userProfile.id,
      address_type: 'delivery',
      name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      postal_code: '12345',
      address_line1: RandomGenerator.paragraph()(),
      address_line2: null,
      custom_label: '테스트배송지',
      region_code: 'KR',
      is_default: true,
    },
  });
  typia.assert(userAddress);

  // 5. 주문 생성
  const orderInput = {
    customer_id: userProfile.id,
    cart_id: cart.id,
    shipping_address_id: userAddress.id,
    order_status: 'pending',
    order_channel: 'web',
    items: [
      {
        sku_id: sampleSkuId,
        quantity: itemQuantity,
      },
    ],
  };
  const order = await api.functional.ai_ecommerce.orders.post(connection, {
    body: orderInput,
  });
  typia.assert(order);

  // 6. 반환된 주문 정보가 입력값과 일치하는지 확인
  TestValidator.equals('customer_id')(order.customer_id)(orderInput.customer_id);
  TestValidator.equals('cart_id')(order.cart_id)(orderInput.cart_id);
  TestValidator.equals('shipping_address_id')(order.shipping_address_id)(orderInput.shipping_address_id);
  TestValidator.equals('order_status')(order.order_status)(orderInput.order_status);
  TestValidator.equals('주문 아이템 개수')(order.items.length)(orderInput.items.length);
  TestValidator.equals('주문 sku 일치')(order.items[0].sku_id)(orderInput.items[0].sku_id);
  TestValidator.equals('주문 수량 일치')(order.items[0].quantity)(orderInput.items[0].quantity);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserProfile";
import type { Iai_ecommerceCart } from "@ORGANIZATION/PROJECT-api/lib/structures/Iai_ecommerceCart";
import type { IAiEcommerceOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrder";
import type { IAiEcommerceOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrderItem";

/**
 * Validate order creation fails when cart is invalid, empty, or belongs to a different customer.
 *
 * This test ensures the /ai_ecommerce/orders POST endpoint rejects attempts to create an order using:
 * 1. A deleted/expired cart (where cart_status or deleted_at is set)
 * 2. An empty cart (i.e., items=[] in request — the API only receives items from the order body,
 *    but empty cart generally means attempting order with no items provided)
 * 3. A cart owned by a different user than the request's customer_id
 *
 * These checks ensure security, prevent broken checkouts, and enforce business rules.
 *
 * Steps:
 * 1. Create two user profiles (user1 and user2) for ownership scenarios
 * 2. Create a cart for user1
 * 3. Attempt an order with:
 *    a. A deleted/expired cart_id (simulate by setting wrong or random UUID)
 *    b. An empty cart—simulate by providing empty items array (or with an otherwise valid cart
 *       and order body but no items)
 *    c. Cart belonging to user2 but supply user1's customer_id in the order body
 * 4. For each, verify error is thrown and no sensitive data is exposed in error.
 *
 * All order creation attempts should fail with an error for each scenario. Use TestValidator.error
 * to confirm error is thrown. Do not create real order on failure.
 */
export async function test_api_ai_ecommerce_test_create_order_with_invalid_cart_fails(
  connection: api.IConnection,
) {
  // 1. Create user1 profile
  const user1Profile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(user1Profile);

  // 2. Create user2 profile
  const user2Profile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(user2Profile);

  // 3. Create cart for user1
  const cart1 = await api.functional.ai_ecommerce.cart.post(connection, {
    body: {
      customer_id: user1Profile.id,
      cart_status: "active",
    } satisfies Iai_ecommerceCart.ICreate,
  });
  typia.assert(cart1);

  // Prepare minimal valid shipping address uuid and order item
  const shippingAddressId = typia.random<string & tags.Format<"uuid">>();
  const orderItem = {
    sku_id: typia.random<string & tags.Format<"uuid">>(),
    quantity: 1,
  } satisfies IAiEcommerceOrderItem.ICreate;

  // 4.a Attempt order with non-existent/deleted cart_id
  TestValidator.error("should fail for deleted/invalid cart")(() =>
    api.functional.ai_ecommerce.orders.post(connection, {
      body: {
        customer_id: user1Profile.id,
        cart_id: typia.random<string & tags.Format<"uuid">>(),
        shipping_address_id: shippingAddressId,
        order_status: "pending",
        items: [orderItem],
      } satisfies IAiEcommerceOrder.ICreate,
    })
  );

  // 4.b Attempt order with empty items (simulate empty cart)
  TestValidator.error("should fail for empty cart/items")(() =>
    api.functional.ai_ecommerce.orders.post(connection, {
      body: {
        customer_id: user1Profile.id,
        cart_id: cart1.id,
        shipping_address_id: shippingAddressId,
        order_status: "pending",
        items: [],
      } satisfies IAiEcommerceOrder.ICreate,
    })
  );

  // 4.c Attempt order with cart belonging to different user (user2)
  const cart2 = await api.functional.ai_ecommerce.cart.post(connection, {
    body: {
      customer_id: user2Profile.id,
      cart_status: "active",
    } satisfies Iai_ecommerceCart.ICreate,
  });
  typia.assert(cart2);
  TestValidator.error("should fail for cart owned by different user")(() =>
    api.functional.ai_ecommerce.orders.post(connection, {
      body: {
        customer_id: user1Profile.id,
        cart_id: cart2.id,
        shipping_address_id: shippingAddressId,
        order_status: "pending",
        items: [orderItem],
      } satisfies IAiEcommerceOrder.ICreate,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceUserAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserAddress";
import type { IAiEcommerceOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrder";
import type { IAiEcommerceOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrderItem";

/**
 * Test the update logic for an order's status and shipping address as performed by either the legitimate order owner or an admin user.
 *
 * This test validates the following business expectations:
 *
 * 1. Only the owner of an order (or an admin user, if simulated) can update modifiable fields (order_status, shipping_address_id, order_channel).
 * 2. The test must first create a valid order with a known owner/profile.
 * 3. The test must also create an alternate shipping address for the owner, so a shipping_address_id can be changed.
 * 4. Attempt to change modifiable fields (order_status and shipping_address_id) and verify that the update succeeds for the owner.
 * 5. Attempt to update immutable fields or by unauthorized profiles and confirm rejection (e.g., customer_id, cart_id).
 * 6. Attempt to perform a state transition not permitted by business rules (e.g., updating after delivered status) and confirm rejection.
 * 7. Verify that changes to allowed fields are properly reflected in the returned object and that updated timestamps are set.
 * 8. If the system includes audit logging, ensure a modification is reflected accordingly (log check may be omitted if not accessible via API).
 *
