/**
 * Negative E2E tests for updating an AI e-commerce order (PUT /ai_ecommerce/orders/{id})
 *
 * This function validates error cases for modifying orders:
 * 1. Non-existent order update (should return 404)
 * 2. Attempting forbidden field modifications (immutables)
 * 3. Illegal status transitions (e.g., moving directly from shipped to pending)
 * 4. Attempting to update after order is locked (after shipped/cancelled)
 *
 * Prerequisite: A valid order is created via POST for testing forbidden updates (with varying status changes as needed).
 *
 * Major Steps:
 * 1. Try to update a random (non-existent) order ID. Expect 404 error.
 * 2. Change immutable fields (simulate by attempting an impossible status transition or editing after cancellation/shipment).
 * 3. Verify that on error, the order data remains unchanged.
 * 4. (Authorization-related case cannot be tested unless a user context API is available; omitted if such is not in the provided SDK.)
 */
export async function test_api_ai_ecommerce_test_update_order_invalid_id_and_forbidden_changes(
  connection: api.IConnection,
) {
  // 1. Create a valid order to use for negative update scenarios
  const orderCreateInput: IAiEcommerceOrder.ICreate = typia.random<IAiEcommerceOrder.ICreate>();
  const order = await api.functional.ai_ecommerce.orders.post(connection, {
    body: orderCreateInput,
  });
  typia.assert(order);

  // 2. Try updating a non-existent order
  await TestValidator.error("404 on non-existent order")(() =>
    api.functional.ai_ecommerce.orders.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // use a likely-absent uuid
      body: {
        order_status: "shipped",
      } satisfies IAiEcommerceOrder.IUpdate,
    })
  );

  // 3. Try an illegal status transition (e.g., shipped->pending)
  // First, update order status to 'shipped' (assuming allowed)
  const shipped = await api.functional.ai_ecommerce.orders.putById(connection, {
    id: order.id,
    body: { order_status: "shipped" } satisfies IAiEcommerceOrder.IUpdate,
  });
  typia.assert(shipped);
  TestValidator.equals("order is shipped")(shipped.order_status)("shipped");

  // Attempt an invalid transition: shipped -> pending
  await TestValidator.error("invalid status transition")(() =>
    api.functional.ai_ecommerce.orders.putById(connection, {
      id: order.id,
      body: { order_status: "pending" } satisfies IAiEcommerceOrder.IUpdate,
    })
  );
  // Verify the order is still shipped (should remain unchanged)
  const stillShipped = await api.functional.ai_ecommerce.orders.putById(connection, {
    id: order.id,
    body: { order_status: "shipped" } satisfies IAiEcommerceOrder.IUpdate,
  });
  typia.assert(stillShipped);
  TestValidator.equals("order status unchanged after failed transition")(stillShipped.order_status)("shipped");

  // 4. Mark order as cancelled, then try to re-edit (should be forbidden)
  const cancelled = await api.functional.ai_ecommerce.orders.putById(connection, {
    id: order.id,
    body: { order_status: "cancelled" } satisfies IAiEcommerceOrder.IUpdate,
  });
  typia.assert(cancelled);
  TestValidator.equals("order cancelled")(cancelled.order_status)("cancelled");
  await TestValidator.error("update after cancellation forbidden")(() =>
    api.functional.ai_ecommerce.orders.putById(connection, {
      id: order.id,
      body: { order_status: "pending" } satisfies IAiEcommerceOrder.IUpdate,
    })
  );
}

