import type { IDeleteResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IDeleteResult";

/**
 * E2E test for soft deletion (cancellation) of orders by owner,
 * validating permission logic and business rules.
 *
 * - Verifies successful soft-delete by order owner (deleted, deleted_at fields)
 * - Ensures deleted orders cannot be deleted again (proper business error)
 * - Ensures non-owners cannot delete others' orders (permission error)
 * - Cannot test admin-case or order state transitions due to API/DTO limitations
 * - Only reachable business logic paths are tested per available SDK and DTO
 *
 * Steps:
 * 1. Create a new order in a deletable state ("pending")
 * 2. Attempt soft-delete as the owner
 *    - Validate { deleted: true, deleted_at: <not null> }
 * 3. Attempt to delete again (should fail)
 * 4. Create another order belonging to someone else (different customer_id)
 *    - Attempt to delete as original owner (should fail)
 */
export async function test_api_ai_ecommerce_orders_test_delete_order_by_owner_or_admin_with_soft_delete(
  connection: api.IConnection,
) {
  // 1. Create a deletable order as a new customer ("pending" status)
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const cartId = typia.random<string & tags.Format<"uuid">>();
  const shippingAddressId = typia.random<string & tags.Format<"uuid">>();
  const skuId = typia.random<string & tags.Format<"uuid">>();
  const orderCreate: IAiEcommerceOrder.ICreate = {
    customer_id: customerId,
    cart_id: cartId,
    shipping_address_id: shippingAddressId,
    order_status: "pending",
    items: [
      {
        sku_id: skuId,
        quantity: 1,
      },
    ],
  };
  const order = await api.functional.ai_ecommerce.orders.post(connection, {
    body: orderCreate,
  });
  typia.assert(order);

  // 2. Attempt to delete the order as the owner
  const delResult = await api.functional.ai_ecommerce.orders.eraseById(connection, {
    id: order.id,
  });
  typia.assert(delResult);
  TestValidator.equals("should be deleted")(delResult.deleted)(true);
  TestValidator.predicate("deleted_at is populated")(!!delResult.deleted_at);

  // 3. Attempt to delete again (should fail)
  await TestValidator.error("cannot delete already deleted order")(() =>
    api.functional.ai_ecommerce.orders.eraseById(connection, {
      id: order.id,
    })
  );

  // 4. Create an order belonging to another customer
  const anotherCustomerId = typia.random<string & tags.Format<"uuid">>();
  const anotherOrderCreate: IAiEcommerceOrder.ICreate = {
    ...orderCreate,
    customer_id: anotherCustomerId,
    cart_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const anotherOrder = await api.functional.ai_ecommerce.orders.post(connection, {
    body: anotherOrderCreate,
  });
  typia.assert(anotherOrder);

  // Attempt to delete as non-owner (should fail)
  await TestValidator.error("cannot delete order belonging to another customer")(() =>
    api.functional.ai_ecommerce.orders.eraseById(connection, {
      id: anotherOrder.id,
    })
  );
}

