    TestValidator.equals("payment id matches")(fetched.payment_id)(txPayload.payment_id ?? null);
  }

  // 5. Attempt to fetch using a random, non-existent UUID: expect an error
  await TestValidator.error("should fail for non-existent transaction id")(async () => {
    await api.functional.ai_ecommerce.walletTransactions.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>()
    });
