    } satisfies ai_ecommerce_wallet_transaction.ICreate,
  });
  typia.assert(valid_transaction);
  TestValidator.equals("wallet linkage")(valid_transaction.wallet_id)(wallet.id);
  TestValidator.equals("currency")(valid_transaction.currency_code)(currency_code);
  TestValidator.equals("change amount")(valid_transaction.change_amount)(5000);
  TestValidator.equals("type")(valid_transaction.transaction_type)(deposit_type);

  // 4. Invalid wallet_id (should throw error)
  await TestValidator.error("transaction: invalid wallet ID should fail")(async () => {
    await api.functional.ai_ecommerce.walletTransactions.post(connection, {
      body: {
        wallet_id: typia.random<string & tags.Format<"uuid">>(), // definitely not existing
        change_amount: 2000,
        currency_code,
        transaction_type: deposit_type,
        created_at: now,
      } satisfies ai_ecommerce_wallet_transaction.ICreate,
    });
  });

  // 5. Negative change_amount (should pass if business logic allows for refunds/payments, otherwise should fail)
  const negative_transaction_type = "payment";
  const negative_amount = -1000;
  const negative_tx_body = {
    wallet_id: wallet.id,
    change_amount: negative_amount,
    currency_code,
    transaction_type: negative_transaction_type,
    created_at: now,
  } satisfies ai_ecommerce_wallet_transaction.ICreate;
  // Try to create a transaction with negative amount (assuming business rules may allow for 'payment' transaction)
  let negative_tx: ai_ecommerce_wallet_transaction | undefined = undefined;
  try {
    negative_tx = await api.functional.ai_ecommerce.walletTransactions.post(connection, { body: negative_tx_body });
    typia.assert(negative_tx);
    TestValidator.equals("change_amount negative")(negative_tx.change_amount)(negative_amount);
    TestValidator.equals("type")(negative_tx.transaction_type)(negative_transaction_type);
  } catch (err) {
    // If business rules do not allow it, this should throw and reach here
    TestValidator.predicate("error thrown for negative amount")(!!err);
  }

  // 6. Invalid transaction_type (should fail)
  await TestValidator.error("transaction: invalid type should fail")(async () => {
    await api.functional.ai_ecommerce.walletTransactions.post(connection, {
      body: {
        wallet_id: wallet.id,
        change_amount: 1000,
        currency_code,
        transaction_type: "invalid-type",
        created_at: now,
      } satisfies ai_ecommerce_wallet_transaction.ICreate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserProfile";
