import type { ai_ecommerce_wallet_transaction } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_wallet_transaction";

/**
 * Test updating the details of an existing wallet transaction, including all business rules and edge cases.
 *
 * This function covers the following scenario:
 * 1. Create a user profile (the wallet owner).
 * 2. Create a wallet for that user.
 * 3. Create a wallet transaction linked to that wallet.
 * 4. Update mutable fields in the transaction (order_id, payment_id, change_amount, currency_code, transaction_type, created_at) and verify that those changes persist.
 * 5. Try forbidden update attempts (e.g., changing immutable fields or updating settled or locked transactions)—though APIs for locking/settling aren't present, so this is skipped.
 * 6. Edge case: Attempt to update a non-existent transaction ID and expect an error.
 * 
 * Business context: Only mutable fields are updatable; immutable or locked business logic is enforced at the API/service layer. RBAC/privilege scenarios are not implementable due to lack of explicit authentication/business-user role endpoints.
 * 
 * Steps:
 *   1. Create user profile.
 *   2. Create wallet for user.
 *   3. Create wallet transaction.
 *   4. Update the transaction and check the changed values were applied.
 *   5. Attempt update with random/fake transaction ID (expect error).
 *   6. (RBAC/locked/settled) Not tested—due to API limitations.
 */
export async function test_api_ai_ecommerce_walletTransactions_test_update_wallet_transaction_with_valid_and_invalid_cases(
  connection: api.IConnection,
) {
  // 1. Create a user profile.
  const userProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      avatar_uri: null,
      email: typia.random<string & tags.Format<'email'>>(),
      phone_number: null,
      communication_consent: true,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(userProfile);

  // 2. Create a wallet for that user.
  const currency = 'KRW';
  const wallet = await api.functional.ai_ecommerce.wallets.post(connection, {
    body: {
      customer_id: userProfile.id,
      currency_code: currency,
      is_active: true,
    } satisfies ai_ecommerce_wallet.ICreate,
  });
  typia.assert(wallet);
  TestValidator.equals('wallet owner')(wallet.customer_id)(userProfile.id);

  // 3. Create a wallet transaction linked to that wallet.
  const initialTransaction = await api.functional.ai_ecommerce.walletTransactions.post(connection, {
    body: {
      wallet_id: wallet.id,
      order_id: null,
      payment_id: null,
      change_amount: 50000,
      currency_code: currency,
      transaction_type: 'deposit',
      created_at: new Date().toISOString(),
    } satisfies ai_ecommerce_wallet_transaction.ICreate,
  });
  typia.assert(initialTransaction);
  TestValidator.equals('wallet id on transaction')(initialTransaction.wallet_id)(wallet.id);
  TestValidator.equals('transaction type')(initialTransaction.transaction_type)('deposit');

  // 4. Update mutable fields in the transaction.
  const updatedOrderId = typia.random<string & tags.Format<'uuid'>>();
  const updatedPaymentId = typia.random<string & tags.Format<'uuid'>>();
  const updatedAmount = 49000;
  const updatedType = 'refund';
  const updatedCurrency = 'USD';
  const updatedTimestamp = new Date(Date.now() + 1000000).toISOString();

  const updatedTransaction = await api.functional.ai_ecommerce.walletTransactions.putById(connection, {
    id: initialTransaction.id,
    body: {
      order_id: updatedOrderId,
      payment_id: updatedPaymentId,
      change_amount: updatedAmount,
      transaction_type: updatedType,
      currency_code: updatedCurrency,
      created_at: updatedTimestamp,
    } satisfies ai_ecommerce_wallet_transaction.IUpdate,
  });
  typia.assert(updatedTransaction);
  TestValidator.equals('order_id')(updatedTransaction.order_id)(updatedOrderId);
  TestValidator.equals('payment_id')(updatedTransaction.payment_id)(updatedPaymentId);
  TestValidator.equals('change_amount')(updatedTransaction.change_amount)(updatedAmount);
  TestValidator.equals('transaction_type')(updatedTransaction.transaction_type)(updatedType);
  TestValidator.equals('currency_code')(updatedTransaction.currency_code)(updatedCurrency);
  TestValidator.equals('created_at')(updatedTransaction.created_at)(updatedTimestamp);

  // 5. Attempt update with a non-existent transaction ID (expect error)
  const fakeTransactionId = typia.random<string & tags.Format<'uuid'>>();
  await TestValidator.error('update with non-existent transaction id throws not found')(
    () => api.functional.ai_ecommerce.walletTransactions.putById(connection, {
      id: fakeTransactionId,
      body: {
        change_amount: 12345,
      } satisfies ai_ecommerce_wallet_transaction.IUpdate,
    })
  );
  // Cannot test RBAC/locked/settled edge cases due to missing endpoints.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserProfile";
import type { ai_ecommerce_wallet } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_wallet";
import type { ai_ecommerce_wallet_transaction } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_wallet_transaction";

/**
 * E2E test for deleting wallet transactions (soft and locked/settled cases).
 *
 * Verifies deletion by wallet owner, proper not-found/error on subsequent access,
 * edge cases for 'locked' transactions, unauthorized attempts, and non-existent records.
 *
 * Steps:
 * 1. Create a user profile (wallet owner).
 * 2. Create a wallet linked to the user profile.
 * 3. Create a wallet transaction linked to the wallet (normal deletable deposit).
 * 4. Delete the transaction as the wallet owner—expect success.
 * 5. Attempt to read/delete the same transaction again—expect not-found error.
 * 6. (Edge) Attempt to delete a different transaction (simulate locked/settled)—expect regular delete as 'locked' status is not exposed in API.
 * 7. (Edge) Create another user, attempt to delete the first user's transaction as unauthorized user—actual role context switching cannot be tested (SDK limitation).
 * 8. (Edge) Attempt to delete a non-existent transaction—expect not-found error.
 */
export async function test_api_ai_ecommerce_walletTransactions_test_delete_wallet_transaction_soft_and_locked_cases(
  connection: api.IConnection,
) {
  // 1. Create user profile (wallet owner)
  const user: IAiEcommerceUserProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      avatar_uri: null,
      email: typia.random<string & tags.Format<"email">>(),
      phone_number: null,
      communication_consent: true,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(user);

  // 2. Create wallet linked to user profile
  const wallet: ai_ecommerce_wallet = await api.functional.ai_ecommerce.wallets.post(connection, {
    body: {
      customer_id: user.id,
      currency_code: "KRW",
      is_active: true,
    } satisfies ai_ecommerce_wallet.ICreate,
  });
  typia.assert(wallet);

  // 3. Create wallet transaction (deletable)
  const transaction: ai_ecommerce_wallet_transaction = await api.functional.ai_ecommerce.walletTransactions.post(connection, {
    body: {
      wallet_id: wallet.id,
      change_amount: 10000,
      currency_code: wallet.currency_code,
      transaction_type: "deposit",
      created_at: new Date().toISOString(),
    } satisfies ai_ecommerce_wallet_transaction.ICreate,
  });
  typia.assert(transaction);

  // 4. Delete the transaction
  await api.functional.ai_ecommerce.walletTransactions.eraseById(connection, { id: transaction.id });

  // 5. Attempt to delete/read the transaction again—should fail (not found)
  await TestValidator.error("should be not found after deletion")(() =>
    api.functional.ai_ecommerce.walletTransactions.eraseById(connection, { id: transaction.id })
  );

  // 6. (Edge) Simulate 'locked/settled' transaction (API/DTO does not expose lock; just create and delete another transaction)
  const locked_txn: ai_ecommerce_wallet_transaction = await api.functional.ai_ecommerce.walletTransactions.post(connection, {
    body: {
      wallet_id: wallet.id,
      change_amount: 5000,
      currency_code: wallet.currency_code,
      transaction_type: "payment",
      created_at: new Date().toISOString(),
    } satisfies ai_ecommerce_wallet_transaction.ICreate,
  });
  typia.assert(locked_txn);
  await api.functional.ai_ecommerce.walletTransactions.eraseById(connection, { id: locked_txn.id });

  // 7. (Edge) Unauthorized delete by another user (new user profile, no context switch possible here)
  const otherUser: IAiEcommerceUserProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      avatar_uri: null,
      email: typia.random<string & tags.Format<"email">>(),
      phone_number: null,
      communication_consent: true,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(otherUser);
  // Cannot simulate privilege change without auth SDK—edge left as comment

  // 8. (Edge) Attempt to delete a non-existent transaction
  await TestValidator.error("should error when deleting non-existent transaction")(() =>
    api.functional.ai_ecommerce.walletTransactions.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>()
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_product } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_product";
import type { ai_ecommerce_sku } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_sku";
import type { IPageai_ecommerce_sku } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageai_ecommerce_sku";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ai_ecommerce_skus } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_skus";

/**
 * 다양한 검색 및 필터 옵션을 활용한 SKU 페이지네이션 리스트 조회 검증.
 *
 * 이 테스트는 실제 스토어 환경에서 SKU(상품 단위)의 리스트를 다양한 조건으로 검색/필터링/정렬하는 요구를 반영한다.
 * 1. 여러 개의 상품(Product)을 생성하고, 각 상품에 속한 SKU를 다양한 속성(활성/비활성, 코드/가격 등)으로 등록한다.
 * 2. /ai_ecommerce/skus PATCH 엔드포인트로 상품별, 활성화 상태별, 코드 패턴별, 가격 범위별 등 다양한 조건을 조합해 목록을 조회한다.
 * 3. 반환되는 결과 셋이 쿼리 조건과 정확히 일치하는지, 반환된 SKUs가 요청한 조건 내에 있는지를 모두 검증한다.
 * 4. 페이지네이션: limit/page 조합으로 적절히 slicing·합계·범위 초과 등 엣지케이스도 테스트한다(음수 page, 과도한 limit 요청 등).
 * 5. 유효하지 않은 페이지/사이즈 요청시 서버가 적절한 에러를 반환하는지도 반드시 체크.
 *
 * 세부 검증 시나리오:
 * - 상품1, 상품2에 각각 3개 이상의 SKU(코드, 가격, 활성/비활성 혼합)를 등록
 * - product_id별 필터, 활성/비활성(is_active), SKU code(프리픽스/패턴), 가격(min_price/max_price) 조합 반복 테스트
 * - 결과 내 모든 SKU가 최종 조건을 만족하는지 확인(불만족시 error)
 * - 페이징(page, limit) 동작 정상 여부 확인(예상건수, slicing 일관성)
 * - 음수 page, limit=9999 등 잘못된 요청 케이스에 대해 error 검증
 */
export async function test_api_ai_ecommerce_test_list_skus_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. 여러 Product 생성
  const sellerId: string = typia.random<string & tags.Format<"uuid">>();

  const products = await Promise.all(
    ArrayUtil.repeat(2)(async () => {
      const product = await api.functional.ai_ecommerce.products.post(connection, {
        body: {
          seller_id: sellerId,
          title: RandomGenerator.alphabets(8),
          description: RandomGenerator.paragraph()(),
          status: RandomGenerator.pick(["draft", "published", "archived"]),
          approval_state: RandomGenerator.pick(["pending", "approved"]),
        } satisfies ai_ecommerce_product.ICreate,
      });
      typia.assert(product);
      return product;
    })
  );

  // 2. 각 Product에 다양한 속성의 SKU 등록 (code, price, is_active)
  const allSkus: ai_ecommerce_skus[] = [];
  for (const [i, product] of products.entries()) {
    const skus = await Promise.all(
      ArrayUtil.repeat(3)(async (j) => {
        const sku = await api.functional.ai_ecommerce.skus.post(connection, {
          body: {
            product_id: product.id,
            code: `TESTSKU-${i}${j}${RandomGenerator.alphaNumeric(4)}`,
            price: 1000 + i * 5000 + j * 1000,
            currency: "KRW",
            is_active: (j % 2 === 0),
          } satisfies ai_ecommerce_skus.ICreate,
        });
        typia.assert(sku);
        return sku;
      })
    );
    allSkus.push(...skus);
  }

  // 3. product_id별 필터링 검증
  for (const product of products) {
    const res = await api.functional.ai_ecommerce.skus.patch(connection, {
      body: { product_id: product.id } satisfies ai_ecommerce_sku.IRequest,
    });
    typia.assert(res);
    TestValidator.predicate("모든 SKU가 해당 product_id와 일치함")(
      res.data.every((sku) => sku.product_id === product.id),
    );
  }

  // 4. is_active 별 필터
  for (const is_active of [true, false]) {
    const res = await api.functional.ai_ecommerce.skus.patch(connection, {
      body: { is_active } satisfies ai_ecommerce_sku.IRequest,
    });
    typia.assert(res);
    TestValidator.predicate(`모든 SKU is_active=${is_active}`)(
      res.data.every((sku) => sku.is_active === is_active),
    );
  }

  // 5. 코드 패턴별(프리픽스) 필터
  const prefix = "TESTSKU-10"; // 상품2에만 부여된 코드 프리픽스
  const resPrefix = await api.functional.ai_ecommerce.skus.patch(connection, {
    body: { code: prefix } satisfies ai_ecommerce_sku.IRequest,
  });
  typia.assert(resPrefix);
  TestValidator.predicate("코드 프리픽스 필터가 정상 동작: 모두 prefix로 시작")(resPrefix.data.every((sku) => sku.code.startsWith(prefix)));

  // 6. 가격 범위(min_price/max_price) 조합: 1000~7000 구간 내
  const resPrice = await api.functional.ai_ecommerce.skus.patch(connection, {
    body: { min_price: 2000, max_price: 6000 } satisfies ai_ecommerce_sku.IRequest,
  });
  typia.assert(resPrice);
  TestValidator.predicate("가격 범위 내의 SKU만 추출")(
    resPrice.data.every((sku) => sku.price >= 2000 && sku.price <= 6000),
  );

  // 7. 페이지네이션(page, limit) 동작 확인
  const paged = await api.functional.ai_ecommerce.skus.patch(connection, {
    body: { page: 1, limit: 2, sort: "price", order: "asc" } satisfies ai_ecommerce_sku.IRequest,
  });
  typia.assert(paged);
  TestValidator.equals("페이지 size = 2")(paged.data.length)(2);
  TestValidator.equals("pagination 정보 일치")(paged.pagination.current)(1);
  TestValidator.equals("pagination limit 일치")(paged.pagination.limit)(2);

  // 8. 음수 page / 과도한 limit 등 잘못된 요청시 error 반환 확인
  await TestValidator.error("음수 page 요청시 에러")(() =>
    api.functional.ai_ecommerce.skus.patch(connection, {
      body: { page: -1, limit: 2 } satisfies ai_ecommerce_sku.IRequest,
    }),
  );

  await TestValidator.error("limit이 비정상적으로 큰 값일 때 에러")(() =>
    api.functional.ai_ecommerce.skus.patch(connection, {
      body: { page: 1, limit: 9999 } satisfies ai_ecommerce_sku.IRequest,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_product } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_product";
import type { ai_ecommerce_sku } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_sku";
import type { ai_ecommerce_skus } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_skus";

/**
 * SKU 상세 조회 by ID: 성공, 잘못된 ID, 미존재 ID, 비활성화 SKU 사례 커버
 *
 * - 정상 SKU 조회 후 필드 정확성 검증 (생성 값과 일치)
 * - 잘못된 UUID 포맷 조회 시 validation 에러 및 런타임 에러 처리
 * - 존재하지 않는 UUID로 조회 시 404(미존재 자원) 에러 처리
 * - is_active: false로 생성된 SKU도 별도 조회/매칭 시도함(Access 제한 없으므로 API가 허용하면 성공)
 *
 * 준비 단계: Product, SKU(활성/비활성) 데이터 생성
 */
export async function test_api_ai_ecommerce_skus_test_get_sku_detail_by_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. 상품 등록 (SKU 등록용 product 필요)
  const sellerId: string = typia.random<string & tags.Format<"uuid">>();
  const productInput: ai_ecommerce_product.ICreate = {
    seller_id: sellerId,
    title: RandomGenerator.paragraph()(2),
    description: RandomGenerator.paragraph()(3),
    status: "published",
    approval_state: "approved",
  };
  const product = await api.functional.ai_ecommerce.products.post(connection, { body: productInput });
  typia.assert(product);

  // 2. SKU 등록 (is_active: true)
  const skuInput: ai_ecommerce_skus.ICreate = {
    product_id: product.id,
    code: RandomGenerator.alphaNumeric(10),
    price: 99.99,
    currency: "USD",
    is_active: true,
  };
  const sku = await api.functional.ai_ecommerce.skus.post(connection, { body: skuInput });
  typia.assert(sku);

  // 3. SKU id로 상세조회: 필드 일치 검증
  const foundSku = await api.functional.ai_ecommerce.skus.getById(connection, { id: sku.id });
  typia.assert(foundSku);
  TestValidator.equals("SKU fields, create==fetch")(foundSku)(sku);

  // 4. 잘못된 UUID (format 오류) 호출시 에러 발생 검증
  await TestValidator.error("invalid UUID format error throws")(
    async () => {
      await api.functional.ai_ecommerce.skus.getById(connection, { id: "X-Y-Z-NOT-UUID" as any });
    },
  );

  // 5. 미존재지만 valid UUID로 조회시 404 반환 검증
  await TestValidator.error("non-existent SKU id returns 404")(
    async () => {
      await api.functional.ai_ecommerce.skus.getById(connection, { id: typia.random<string & tags.Format<"uuid">>() });
    },
  );

  // 6. 비활성화 SKU 생성 후 조회: is_active = false 여도 조회 가능, 필드 일치 여부 확인
  const inactiveSkuInput: ai_ecommerce_skus.ICreate = {
    product_id: product.id,
