import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_product } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_product";
import type { ai_ecommerce_skus } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_skus";

/**
 * E2E test for SKU creation with valid and invalid payloads on /ai_ecommerce/skus (POST).
 *
 * This test simulates the onboarding workflow of SKUs for a newly created product, and ensures robust validation of failures:
 *
 * 1. Prerequisite – create a product that the SKU will reference. Store its product_id.
 * 2. Happy path – create a SKU with required fields (unique code, positive price, valid currency, is_active). Assert fields match inputs.
 * 3. Duplicate code error – try to create a SKU with the same code for the same product; expect error.
 * 4. Validation error – try creating with missing required field (code missing); expect error.
 * 5. Referential error – try creating with a non-existent product_id; expect error.
 * 6. Price edge cases – try creating SKUs with price zero and negative, both should fail.
 *
 * All errors ensure atomic transactionality (no partial creation occurs).
 * Note: No SKU GET/search API is present, so we cannot re-query for count/duplicates.
 */
export async function test_api_ai_ecommerce_skus_test_create_sku_with_valid_and_invalid_inputs(
  connection: api.IConnection,
) {
  // 1. Create a prerequisite product
  const product = await api.functional.ai_ecommerce.products.post(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()(),
      status: "draft",
      approval_state: "pending",
    } satisfies ai_ecommerce_product.ICreate,
  });
  typia.assert(product);

  // 2. Happy path – valid SKU creation
  const skuPayload = {
    product_id: product.id,
    code: RandomGenerator.alphaNumeric(8),
    price: 19900,
    currency: "KRW",
    is_active: true,
  } satisfies ai_ecommerce_skus.ICreate;
  const sku = await api.functional.ai_ecommerce.skus.post(connection, { body: skuPayload });
  typia.assert(sku);
  TestValidator.equals("sku product_id matches")(sku.product_id)(product.id);
  TestValidator.equals("sku code matches")(sku.code)(skuPayload.code);
  TestValidator.equals("sku price matches")(sku.price)(skuPayload.price);
  TestValidator.equals("sku currency matches")(sku.currency)(skuPayload.currency);
  TestValidator.equals("sku is_active matches")(sku.is_active)(true);

  // 3. Duplicate code error – same product, same code
  await TestValidator.error("duplicate SKU code should fail")(() =>
    api.functional.ai_ecommerce.skus.post(connection, { body: skuPayload })
  );

  // 4. Validation error – missing code field (intentional type violation)
  await TestValidator.error("missing SKU code should fail")(() =>
    api.functional.ai_ecommerce.skus.post(connection, {
      body: {
        product_id: product.id,
        // code intentionally omitted
        price: 10000,
        currency: "KRW",
        is_active: true,
      } as any,
    })
  );

  // 5. Referential error – invalid product_id
  await TestValidator.error("invalid product_id should fail")(() =>
    api.functional.ai_ecommerce.skus.post(connection, {
      body: {
        product_id: typia.random<string & tags.Format<"uuid">>(),
        code: RandomGenerator.alphaNumeric(9),
        price: 15000,
        currency: "USD",
        is_active: true,
      } satisfies ai_ecommerce_skus.ICreate,
    })
  );

  // 6. Price edge cases: zero and negative
  for (const invalidPrice of [0, -1000]) {
    await TestValidator.error(`invalid price (${invalidPrice}) should fail`)(() =>
      api.functional.ai_ecommerce.skus.post(connection, {
        body: {
          product_id: product.id,
          code: RandomGenerator.alphaNumeric(7),
          price: invalidPrice,
          currency: "KRW",
          is_active: true,
        } satisfies ai_ecommerce_skus.ICreate,
      })
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_product } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_product";
import type { ai_ecommerce_skus } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_skus";

/**
 * Comprehensive test for updating SKU fields via PUT.
 *
 * This test covers the following business workflow for SKUs:
 * 1. Create a product (for association).
 * 2. Create an initial SKU under that product.
 * 3. Update allowed fields (code, price, currency, is_active) and verify update result.
 * 4. Attempt to update the SKU with a duplicate code within same product (should fail).
 * 5. Negative case: try to update with negative price (should fail).
 * 6. Negative case: try to update with invalid currency code (should fail).
 * 7. After each failed transaction, verify no partial update was applied to the SKU.
 *
 * Not implemented/skipped (by schema constraints):
 * - Direct update of immutable fields (id): not possible by IUpdate schema.
 * - Update referencing a non-existent product_id: not possible by IUpdate schema.
 *
 * Steps:
 * A. Positive: allowed update of all mutable fields and verify result.
 * B. Negative: attempt duplicate code and verify error, no update.
 * C. Negative: invalid (negative) price (error, no update).
 * D. Negative: invalid currency code (error, no update).
 */
export async function test_api_ai_ecommerce_skus_test_update_sku_fields_with_valid_invalid_and_immutable_data(
  connection: api.IConnection,
) {
  // 1. Create a product
  const sellerId = typia.random<string & tags.Format<"uuid">>();
  const productTitle = RandomGenerator.alphabets(10);
  const productDescription = RandomGenerator.paragraph()();
  const productStatus = "published";
  const productApprovalState = "approved";
  const product = await api.functional.ai_ecommerce.products.post(connection, {
    body: {
      seller_id: sellerId,
      title: productTitle,
      description: productDescription,
      status: productStatus,
      approval_state: productApprovalState,
    } satisfies ai_ecommerce_product.ICreate,
  });
  typia.assert(product);

  // 2. Create initial SKU
  const skuCode = RandomGenerator.alphabets(8);
  const skuPrice = 20000.0;
  const skuCurrency = "KRW";
  const skuIsActive = true;
  const sku = await api.functional.ai_ecommerce.skus.post(connection, {
    body: {
      product_id: product.id,
      code: skuCode,
      price: skuPrice,
      currency: skuCurrency,
      is_active: skuIsActive,
    } satisfies ai_ecommerce_skus.ICreate,
  });
  typia.assert(sku);

  // 3. A. Positive: valid update all allowed fields
  const updatedSkuCode = RandomGenerator.alphabets(8);
  const updatedSkuPrice = 18000.0;
  const updatedSkuCurrency = "USD";
  const updatedSkuIsActive = false;
  const updatedSku = await api.functional.ai_ecommerce.skus.putById(connection, {
    id: sku.id,
    body: {
      code: updatedSkuCode,
      price: updatedSkuPrice,
      currency: updatedSkuCurrency,
      is_active: updatedSkuIsActive,
    } satisfies ai_ecommerce_skus.IUpdate,
  });
  typia.assert(updatedSku);
  TestValidator.equals("code updated")(updatedSku.code)(updatedSkuCode);
  TestValidator.equals("price updated")(updatedSku.price)(updatedSkuPrice);
  TestValidator.equals("currency updated")(updatedSku.currency)(updatedSkuCurrency);
  TestValidator.equals("is_active updated")(updatedSku.is_active)(updatedSkuIsActive);

  // 4. B. Negative: duplicate code violation
  // Create a second SKU with a unique code
  const sku2 = await api.functional.ai_ecommerce.skus.post(connection, {
    body: {
      product_id: product.id,
      code: RandomGenerator.alphabets(8),
      price: 15000.0,
      currency: "KRW",
      is_active: true,
    } satisfies ai_ecommerce_skus.ICreate,
  });
  typia.assert(sku2);
  // Try to update sku2.code to the same as updatedSkuCode (already used by sku1 in the same product)
  await TestValidator.error("duplicate code should fail")(() =>
    api.functional.ai_ecommerce.skus.putById(connection, {
      id: sku2.id,
      body: {
        code: updatedSkuCode,
      } satisfies ai_ecommerce_skus.IUpdate,
    }),
  );
  // Confirm no partial update
  const sku2After = await api.functional.ai_ecommerce.skus.putById(connection, {
    id: sku2.id,
    body: {},
  });
  typia.assert(sku2After);
  TestValidator.equals("sku2 unchanged")(sku2After.code)(sku2.code);
  TestValidator.equals("sku2 unchanged (price)")(sku2After.price)(sku2.price);
  TestValidator.equals("sku2 unchanged (currency)")(sku2After.currency)(sku2.currency);
  TestValidator.equals("sku2 unchanged (is_active)")(sku2After.is_active)(sku2.is_active);

  // 5. C. Negative: negative price
  await TestValidator.error("negative price should fail")(() =>
    api.functional.ai_ecommerce.skus.putById(connection, {
      id: sku.id,
      body: {
        price: -1,
      } satisfies ai_ecommerce_skus.IUpdate,
    }),
  );
  // Verify no partial update
  const skuAfterNegPrice = await api.functional.ai_ecommerce.skus.putById(connection, {
    id: sku.id,
    body: {},
  });
  typia.assert(skuAfterNegPrice);
  TestValidator.equals("no negative price change")(skuAfterNegPrice.price)(updatedSkuPrice);
  TestValidator.equals("no negative price change (code)")(skuAfterNegPrice.code)(updatedSkuCode);
  TestValidator.equals("no negative price change (currency)")(skuAfterNegPrice.currency)(updatedSkuCurrency);
  TestValidator.equals("no negative price change (is_active)")(skuAfterNegPrice.is_active)(updatedSkuIsActive);

  // 6. D. Negative: invalid currency code
  await TestValidator.error("invalid currency")(() =>
    api.functional.ai_ecommerce.skus.putById(connection, {
      id: sku.id,
      body: {
        currency: "XYZ",
      } satisfies ai_ecommerce_skus.IUpdate,
    }),
  );
  // Confirm no partial update
  const skuAfterBadCurrency = await api.functional.ai_ecommerce.skus.putById(connection, {
    id: sku.id,
    body: {},
  });
  typia.assert(skuAfterBadCurrency);
  TestValidator.equals("no currency change")(skuAfterBadCurrency.currency)(updatedSkuCurrency);
  TestValidator.equals("no currency change (code)")(skuAfterBadCurrency.code)(updatedSkuCode);
  TestValidator.equals("no currency change (price)")(skuAfterBadCurrency.price)(updatedSkuPrice);
  TestValidator.equals("no currency change (is_active)")(skuAfterBadCurrency.is_active)(updatedSkuIsActive);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
