import type { IAiEcommerceOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrder";
import type { IAiEcommerceOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrderItem";

/**
 * 테스트 시나리오:
 * 1. 새 상품(Product) 생성
 * 2. 해당 상품에 대해 신규 SKU 생성
 * 3. SKU 삭제(Delete) 호출 → 정상 soft-delete: deleted_at 값이 세팅되고 is_active가 false 처리되었는지 검증(조회, DB 상태 검증 대체 불가 시 API 재생성 등 필요)
 * 4. 이미 삭제된(soft-deleted) SKU에 대해 다시 Delete 시도 → 적절한 에러 발생 확인
 * 5. 존재하지 않는 SKU ID로 Delete 시도 → 적절한 에러(404 등) 확인
 * 6. (비즈니스 규칙/필요시) SKU가 주문(Order)에 참조중일 때 삭제 요청 → 삭제 차단/에러 처리 확인
 * 7. 삭제 과정과 결과가 비즈니스 audit/log에 일치하는지(별도 로그 검증 API가 없다면 함수 내 적절 코멘트 및 확장성 고려)
 *
 * 각 단계별 예상 검증 포인트:
 * - 성공 시 deleted_at은 null이 아닌 값(ISO8601 string)이어야 하고 is_active는 false이어야 함
 * - 더블 삭제/없는 SKU 삭제 등 비정상 케이스는 명시적 에러로 처리되어야 함
 * - 주문 연동 SKU 삭제 차단 등은 exists 여부와 연관참조 검증 필요
 */
export async function test_api_ai_ecommerce_skus_test_soft_delete_sku_and_handle_edge_cases(
  connection: api.IConnection,
) {
  // 1. 새 상품 생성
  const product = await api.functional.ai_ecommerce.products.post(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      description: RandomGenerator.content()()(),
      status: "published",
      approval_state: "approved",
    } satisfies ai_ecommerce_product.ICreate,
  });
  typia.assert(product);

  // 2. 신규 SKU 생성
  const sku = await api.functional.ai_ecommerce.skus.post(connection, {
    body: {
      product_id: product.id,
      code: RandomGenerator.alphaNumeric(8),
      price: 9900,
      currency: "KRW",
      is_active: true,
    } satisfies ai_ecommerce_skus.ICreate,
  });
  typia.assert(sku);

  // 3. SKU 삭제 (soft-delete)
  await api.functional.ai_ecommerce.skus.eraseById(connection, {
    id: sku.id,
  });

  // Soft-delete 검증을 위해 재조회가 필요한데 별도 GET API가 없으므로,
  // 같은 코드/ID로 SKU 재생성 시도(중복 생성 => error 등으로 soft-delete 상태 간접 검증)
  TestValidator.error("soft-deleted SKU 재생성 시도는 반드시 unique 에러 또는 충돌이어야 함")(
    async () => {
      await api.functional.ai_ecommerce.skus.post(connection, {
        body: {
          product_id: sku.product_id,
          code: sku.code,
          price: sku.price,
          currency: sku.currency,
          is_active: true,
        } satisfies ai_ecommerce_skus.ICreate,
      });
    },
  );

  // 4. 이미 삭제한 SKU 다시 삭제 시도 → 오류 검증
  TestValidator.error("Deleted SKU에 두 번째 delete 호출 → error throw")(
    async () => {
      await api.functional.ai_ecommerce.skus.eraseById(connection, {
        id: sku.id,
      });
    },
  );

  // 5. 존재하지 않는 SKU id로 delete
  TestValidator.error("존재하지 않는 SKU에 delete → error throw")(
    async () => {
      await api.functional.ai_ecommerce.skus.eraseById(connection, {
        id: typia.random<string & tags.Format<"uuid">>()
      });
    }
  );

  // 6. (비즈니스 규칙) SKU 사용 중(주문 linkage) 삭제 차단 시 검증
  // 신규 SKU + 주문 생성 (SKU가 주문중이면 실제 삭제 차단됨을 검증)
  const product2 = await api.functional.ai_ecommerce.products.post(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      description: RandomGenerator.content()()(),
      status: "published",
      approval_state: "approved",
    } satisfies ai_ecommerce_product.ICreate,
  });
  typia.assert(product2);

  const sku2 = await api.functional.ai_ecommerce.skus.post(connection, {
    body: {
      product_id: product2.id,
      code: RandomGenerator.alphaNumeric(8),
      price: 12000,
      currency: "USD",
      is_active: true,
    } satisfies ai_ecommerce_skus.ICreate,
  });
  typia.assert(sku2);

  // 가상의 고객/카트/주소/random 값 할당 (테스트 목적)
  const order = await api.functional.ai_ecommerce.orders.post(connection, {
    body: {
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      cart_id: typia.random<string & tags.Format<"uuid">>(),
      shipping_address_id: typia.random<string & tags.Format<"uuid">>(),
      order_status: "pending",
      order_channel: "web",
      items: [{
        sku_id: sku2.id,
        quantity: 1,
      }],
    } satisfies IAiEcommerceOrder.ICreate,
  });
  typia.assert(order);

  TestValidator.error("주문 연동 중인 SKU의 삭제 attempt는 에러로 차단되어야 함")(
    async () => {
      await api.functional.ai_ecommerce.skus.eraseById(connection, {
        id: sku2.id,
      });
    },
  );

  // 삭제 로깅/Audit 트레이스는 실제 시스템의 logging DB에 기록되나, 외부 API 제공 없으므로 verify comment 만 기입함
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceMedia";
import type { IPageIAiEcommerceMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiEcommerceMedia";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test filtering and paginated listing of media assets via PATCH /ai_ecommerce/media.
 *
 * This test seeds multiple media assets with unique owners, types, and languages,
 * and validates that listing, filtering, and pagination via the PATCH endpoint work correctly.
 *
 * **Business context:**
 * Managing media assets (such as product images/videos) is central to modern ecommerce.
 * Filtering and paginated queries are required for efficient UI admin/content management.
 * This test ensures that core query parameters—owner_type, media_type, language, and pagination—result
 * in correct and consistent API results for compliant client-side consumption.
 *
 * **Test Steps:**
 * 1. Seed media assets: Create 3 different media via POST /ai_ecommerce/media using distinct values.
 * 2. Filter by owner_type, check correct entries are returned.
 * 3. Filter by media_type, validate output.
 * 4. Filter by language, check filtered result (skip if none set).
 * 5. Combined filters: Filter by owner_type and media_type together.
 * 6. Paginate: Use limit to walk across all pages, ensure all seeded entries are seen in paged results.
 * 7. (Skipped: soft-delete logic, role-negative tests, due to lack of API/DTO support.)
 */
export async function test_api_ai_ecommerce_media_test_list_media_assets_with_filters_and_pagination(connection: api.IConnection) {
  // 1. Seed media assets: three with unique parameter sets
  const owner_id_1 = typia.random<string & tags.Format<"uuid">>();
  const owner_id_2 = typia.random<string & tags.Format<"uuid">>();
  const types = ["product", "sku", "category"];
  const media_types = ["image/jpeg", "video/mp4", "image/png"];
  const languages = ["en", "ko", null];

  const created = await Promise.all(
    [0, 1, 2].map(i =>
      api.functional.ai_ecommerce.media.post(connection, {
        body: {
          owner_id: [owner_id_1, owner_id_2][i % 2],
          owner_type: types[i],
          uri: `https://cdn.example.com/upload/${typia.random<string & tags.Format<"uuid">>()}.${media_types[i].split("/")[1]}`,
          media_type: media_types[i],
          language: languages[i],
        } satisfies IAiEcommerceMedia.ICreate,
      })
    ),
  );
  created.forEach(m => typia.assert(m));

  // 2. Filter by owner_type (e.g., 'sku')
  const resp_owner_type = await api.functional.ai_ecommerce.media.patch(connection, {
    body: { owner_type: "sku" } satisfies IAiEcommerceMedia.IRequest
  });
  typia.assert(resp_owner_type);
  TestValidator.predicate("all have owner_type 'sku'")(
    resp_owner_type.data.every(m => m.owner_type === "sku")
  );

  // 3. Filter by media_type (e.g., 'image/jpeg')
  const resp_media_type = await api.functional.ai_ecommerce.media.patch(connection, {
    body: { media_type: "image/jpeg" } satisfies IAiEcommerceMedia.IRequest
  });
  typia.assert(resp_media_type);
  TestValidator.predicate("all have media_type 'image/jpeg'")(
    resp_media_type.data.every(m => m.media_type === "image/jpeg")
  );

  // 4. Filter by language (e.g., 'ko')
  const resp_language = await api.functional.ai_ecommerce.media.patch(connection, {
    body: { language: "ko" } satisfies IAiEcommerceMedia.IRequest,
  });
  typia.assert(resp_language);
  TestValidator.predicate("all have language 'ko'")(
    resp_language.data.every(m => m.language === "ko")
  );

  // 5. Combined filter: owner_type = 'category', media_type = 'image/png'
  const resp_combined = await api.functional.ai_ecommerce.media.patch(connection, {
    body: { owner_type: "category", media_type: "image/png" } satisfies IAiEcommerceMedia.IRequest,
  });
  typia.assert(resp_combined);
  TestValidator.predicate("all have owner_type 'category' AND media_type 'image/png'")(
    resp_combined.data.every(m => m.owner_type === "category" && m.media_type === "image/png")
  );

  // 6. Pagination: limit 1, step through all pages and confirm all created entries appear
  const firstPage = await api.functional.ai_ecommerce.media.patch(connection, {
    body: { limit: 1 } satisfies IAiEcommerceMedia.IRequest,
  });
  typia.assert(firstPage);
  TestValidator.equals("pagination limit 1")(firstPage.data.length)(1);
  const pages = firstPage.pagination.pages;
  let foundIds = new Set<string>();
  for (let page = 1; page <= pages; ++page) {
    const res = await api.functional.ai_ecommerce.media.patch(connection, {
      body: { limit: 1, page } satisfies IAiEcommerceMedia.IRequest
    });
    typia.assert(res);
    res.data.forEach(x => foundIds.add(x.id));
  }
  // Must have all initially created asset ids present in paginated results
  created.forEach(x => TestValidator.predicate(`id ${x.id} present in paginated results`)(foundIds.has(x.id)));
  // 7,8: Skipped soft-delete and role-based negative cases (DTO/API limitation)
}

