import type { IPageIAiEcommerceMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiEcommerceMedia";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that the media listing endpoint returns an informative error when provided invalid filter parameters.
 *
 * This test ensures that the API responds gracefully and with descriptive feedback if called with malformed or nonsensical filter parameters, such as an invalid owner_type or incorrect pagination settings.
 *
 * Steps:
 * 1. Call the /ai_ecommerce/media PATCH endpoint with a malformed filter (e.g., owner_type set to an unexpected value).
 * 2. Confirm that the API returns an error and not a successful result.
 * 3. Call again with an invalid pagination (negative page, or zero limit).
 * 4. Confirm that in each case, the API responds with a clear and descriptive error message, without internal errors or stack traces leaking.
 * 5. Check that valid requests work as a control to verify baseline success path.
 */
export async function test_api_ai_ecommerce_test_media_list_returns_error_on_invalid_filter(
  connection: api.IConnection,
) {
  // Step 1: Use an invalid owner_type (completely nonsensical string)
  await TestValidator.error("media list error: nonsensical owner_type")(
    async () => {
      await api.functional.ai_ecommerce.media.patch(connection, {
        body: {
          owner_type: "__INVALID_TYPE__",
        } satisfies IAiEcommerceMedia.IRequest,
      });
    },
  );

  // Step 2: Use invalid negative page number
  await TestValidator.error("media list error: negative page")(
    async () => {
      await api.functional.ai_ecommerce.media.patch(connection, {
        body: {
          page: -1 as number & tags.Type<"int32">,
        } satisfies IAiEcommerceMedia.IRequest,
      });
    },
  );

  // Step 3: Use invalid zero limit
  await TestValidator.error("media list error: zero limit")(
    async () => {
      await api.functional.ai_ecommerce.media.patch(connection, {
        body: {
          limit: 0 as number & tags.Type<"int32">,
        } satisfies IAiEcommerceMedia.IRequest,
      });
    },
  );

  // Step 4: Use valid request as control (should NOT throw)
  const output = await api.functional.ai_ecommerce.media.patch(connection, {
    body: {}, // valid empty (no filter, list all)
  });
  typia.assert(output);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceMedia";

/**
 * Validate that an authorized user can retrieve detailed metadata of a media asset by its ID.
 *
 * Business context:
 * - Media assets represent digital files or attachments registered by sellers or admins for products, SKUs, or categories.
 * - Only authorized users (admins, relevant sellers) should be able to retrieve the full asset detail by ID.
 *
 * Test procedure:
 * 1. Register a new media asset with meaningful metadata via POST /ai_ecommerce/media
 * 2. Retrieve the asset details by its ID via GET /ai_ecommerce/media/{id} as an authorized user
 * 3. Validate all returned metadata fields match the original registration
 * 4. Check that timestamps and field formats are valid per business constraints
 */
export async function test_api_ai_ecommerce_media_test_get_media_details_success_for_authorized_actor(
  connection: api.IConnection,
) {
  // 1. Register a new media asset for testing
  const createInput: IAiEcommerceMedia.ICreate = {
    owner_id: typia.random<string & tags.Format<"uuid">>(),
    owner_type: "product", // Using a business-valid owner_type
    uri: "https://cdn.example.com/media/test-image.png",
    media_type: "image/png",
    language: null,
  };
  const created: IAiEcommerceMedia = await api.functional.ai_ecommerce.media.post(connection, {
    body: createInput,
  });
  typia.assert(created);

  // 2. Retrieve the asset's detail as an authorized actor
  const detail: IAiEcommerceMedia = await api.functional.ai_ecommerce.media.getById(connection, {
    id: created.id,
  });
  typia.assert(detail);

  // 3. Validate that metadata fields match registration
  TestValidator.equals("media ID matches")(detail.id)(created.id);
  TestValidator.equals("owner_id matches")(detail.owner_id)(createInput.owner_id);
  TestValidator.equals("owner_type matches")(detail.owner_type)(createInput.owner_type);
  TestValidator.equals("uri matches")(detail.uri)(createInput.uri);
  TestValidator.equals("media_type matches")(detail.media_type)(createInput.media_type);
  TestValidator.equals("language matches")(detail.language)(createInput.language);

  // 4. Confirm created_at is a valid ISO 8601 timestamp string
  TestValidator.predicate("created_at is present and ISO8601")(
    typeof detail.created_at === "string" && !isNaN(Date.parse(detail.created_at))
  );
}

