/**
 * Validate that unauthorized users cannot access a media asset's details.
 *
 * Business context:
 * Ensures strict access control for ai_ecommerce_media records, such that users who are neither the owner nor an admin are denied all detail access (GET by ID).
 * This prevents data leaks and enforces privacy/compliance policies tied to business file/media attachments. This is a crucial test for access security.
 *
 * Steps:
 * 1. Create a new media asset as a regular owner/allowed user (using POST /ai_ecommerce/media)
 * 2. Clone the connection and remove authentication headers (simulate an unauthorized/guest/irrelevant user)
 * 3. Attempt to access the media asset's details via GET /ai_ecommerce/media/{id} with THAT unauthorized connection
 * 4. Assert that an access/permission error is thrown (TestValidator.error)
 */
export async function test_api_ai_ecommerce_media_test_get_media_details_permission_denied(connection: api.IConnection) {
  // 1. Create a new media asset (dependency/setup)
  const created: IAiEcommerceMedia = await api.functional.ai_ecommerce.media.post(connection, {
    body: {
      owner_id: typia.random<string & tags.Format<"uuid">>(),
      owner_type: "product",
      uri: `https://cdn.example.com/media/${typia.random<string & tags.Format<"uuid">>()}.jpg`,
      media_type: "image/jpeg",
      language: "en",
    } satisfies IAiEcommerceMedia.ICreate,
  });
  typia.assert(created);

  // 2. Prepare a connection with no credentials to simulate an unauthorized/irrelevant user
  const unauthorizedConnection: api.IConnection = { ...connection, headers: {} };

  // 3 & 4. Attempt to fetch media asset details and expect strict access denial
