import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceMedia";

/**
 * Validate error handling for media asset fetch by non-existent and soft-deleted ID.
 *
 * This test ensures the GET /ai_ecommerce/media/{id} endpoint does not reveal or ambiguously handle requests for resources that are either missing or have been soft-deleted. It covers:
 *
 * 1. Requesting a media record with a random, non-existent UUID and confirming the error response is clear (not found or forbidden).
 * 2. Simulating a media record, soft-deleting it, and verifying that subsequent GETs no longer expose the resource.
 *
 * In both cases, the endpoint must not return ambiguous or partial success, and deleted records should remain inaccessible.
 */
export async function test_api_ai_ecommerce_media_test_get_media_details_not_found_or_deleted(
  connection: api.IConnection,
) {
  // 1. Attempt to fetch a non-existent media asset (random UUID)
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("should return not found or forbidden when media does not exist")(async () => {
    await api.functional.ai_ecommerce.media.getById(connection, { id: randomId });
