  await api.functional.ai_ecommerce.media.eraseById(connection, { id: fakeMedia.id });
  await TestValidator.error("should not allow retrieval of soft-deleted media asset")(async () => {
    await api.functional.ai_ecommerce.media.getById(connection, { id: fakeMedia.id });
