import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceMedia";

/**
 * Test invalid payloads when attempting to create a media asset in the ai_ecommerce_media endpoint.
 *
 * This test verifies the endpoint rejects and properly handles validation errors for:
 *  1. Missing required fields (owner_id, owner_type, uri, media_type)
 *  2. Invalid formats or empty/disallowed values (e.g., bad UUID, empty uri/type)
 *  3. Explicitly passing null for non-nullable fields
 *
 * Steps:
 *  1. For each case, attempt to POST a payload with missing or invalid fields
 *  2. Ensure a validation error is thrown (not a generic server error)
 *  3. Confirm no media record is created/returned for invalid attempts
 */
export async function test_api_ai_ecommerce_media_test_create_media_with_invalid_payload_fails(connection: api.IConnection) {
  // Matrix of invalid input payloads
  const invalidPayloads: Partial<IAiEcommerceMedia.ICreate>[] = [
    // Missing required fields (one at a time)
    { owner_type: "product", uri: "https://cdn/media.jpg", media_type: "image/jpeg" }, // missing owner_id
    { owner_id: typia.random<string & tags.Format<"uuid">>(), uri: "https://cdn/media.jpg", media_type: "image/jpeg" }, // missing owner_type
    { owner_id: typia.random<string & tags.Format<"uuid">>(), owner_type: "product", media_type: "image/jpeg" }, // missing uri
    { owner_id: typia.random<string & tags.Format<"uuid">>(), owner_type: "product", uri: "https://cdn/media.jpg" }, // missing media_type

    // Invalid values (format or emptiness)
    { owner_id: "not-a-uuid", owner_type: "product", uri: "https://cdn/media.jpg", media_type: "image/jpeg" }, // invalid UUID
    { owner_id: typia.random<string & tags.Format<"uuid">>(), owner_type: "", uri: "https://cdn/media.jpg", media_type: "image/jpeg" }, // empty owner_type
    { owner_id: typia.random<string & tags.Format<"uuid">>(), owner_type: "product", uri: "", media_type: "image/jpeg" }, // empty uri
    { owner_id: typia.random<string & tags.Format<"uuid">>(), owner_type: "product", uri: "https://cdn/media.jpg", media_type: "" }, // empty media_type
    { owner_id: typia.random<string & tags.Format<"uuid">>(), owner_type: "product", uri: "not_a_url", media_type: "image/jpeg" }, // non-url uri
    { owner_id: typia.random<string & tags.Format<"uuid">>(), owner_type: "product", uri: "https://cdn/media.jpg", media_type: "image/jpg/image" }, // syntactically wrong MIME

    // Explicit nulls for required fields
    { owner_id: null as any, owner_type: "product", uri: "https://cdn/media.jpg", media_type: "image/jpeg" },
    { owner_id: typia.random<string & tags.Format<"uuid">>(), owner_type: null as any, uri: "https://cdn/media.jpg", media_type: "image/jpeg" },
    { owner_id: typia.random<string & tags.Format<"uuid">>(), owner_type: "product", uri: null as any, media_type: "image/jpeg" },
    { owner_id: typia.random<string & tags.Format<"uuid">>(), owner_type: "product", uri: "https://cdn/media.jpg", media_type: null as any },
  ];

  for (const body of invalidPayloads) {
    await TestValidator.error("media creation with invalid payload should fail")(async () => {
      // forcibly cast to required type, to trigger server-side validation
      await api.functional.ai_ecommerce.media.post(connection, {
        body: body as IAiEcommerceMedia.ICreate,
      });
    });
  }
}

