/**
 * Test updating metadata fields of a media asset by its authorized owner (administrator/seller).
 *
 * Validates that an authorized owner (admin/seller) can update mutable metadata on a media asset via PUT /ai_ecommerce/media/{id}.
 * 
 * Steps:
 * 1. Create a media asset as the owner with valid required properties (owner_id, owner_type, uri, media_type, language).
 * 2. Update its language and uri fields using the update endpoint.
 * 3. Verify the changes are correctly persisted in the returned object.
 * 4. Audit trail or previous state preservation cannot be directly verified as there is no audit endpoint or output field, so only functional update is checked here.
 */
export async function test_api_ai_ecommerce_media_test_update_media_metadata_success_by_owner(
  connection: api.IConnection,
) {
  // 1. Create a new media asset to update
  const createPayload = {
    owner_id: typia.random<string & tags.Format<"uuid">>(),
    owner_type: "product",
    uri: `https://cdn.example.com/media/${typia.random<string & tags.Format<"uuid">>()}.jpg`,
    media_type: "image/jpeg",
    language: "en",
  } satisfies IAiEcommerceMedia.ICreate;
  const initialMedia = await api.functional.ai_ecommerce.media.post(connection, {
    body: createPayload,
  });
  typia.assert(initialMedia);

  // 2. Prepare update payload (change language and uri only)
  const updatePayload = {
    language: "ko",
    uri: `https://cdn.example.com/media/${typia.random<string & tags.Format<"uuid">>()}_updated.jpg`,
  } satisfies IAiEcommerceMedia.IUpdate;

