    id: initialMedia.id,
    body: updatePayload,
  });
  typia.assert(updatedMedia);

  // 4. Validate changes
  TestValidator.equals("media.id matches")(updatedMedia.id)(initialMedia.id);
  TestValidator.equals("language updated")(updatedMedia.language)(updatePayload.language);
  TestValidator.equals("uri updated")(updatedMedia.uri)(updatePayload.uri);
  // Audit-trail validation not possible here
}

