import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceMedia";

/**
 * Test updating a non-existent or soft-deleted media record.
 *
 * This test validates that attempting to update a media entity by UUID that has either never existed or has been previously soft-deleted (via the DELETE endpoint) results in the correct error response (not found or forbidden) and does not inadvertently allow or execute an update.
 *
 * Business justification: Media assets must be strictly controlled to prevent update or mutation of deleted (soft-deleted) records, or records that do not exist. This preserves audit integrity and ensures compliance with update/delete invariants. Attempts to update non-existent or logically deleted records should fail, signaling to the caller that the object cannot be mutated and has no effect.
 *
 * Test sequence:
 * 1. Generate a random UUID not associated with any existing media entity (ensures non-existent record).
 * 2. Attempt to update the non-existent media record and confirm error (not found or forbidden).
 * 3. (Soft delete test) Generate a random UUID, attempt a deletion, then attempt an update and confirm forbidden/not found error.
 * 4. Validate that no update is performed and that an error is thrown according to the invariants.
 */
export async function test_api_ai_ecommerce_media_test_update_media_not_found_or_deleted(
  connection: api.IConnection,
) {
  // 1. Attempt to update a non-existent media record
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  const updatePayload: IAiEcommerceMedia.IUpdate = {
    uri: "https://dummy.example.com/media/updated.png",
    media_type: "image/png",
    language: "en"
  };
  await TestValidator.error("update non-existent media should fail with not found or forbidden")(
    async () => {
      await api.functional.ai_ecommerce.media.putById(connection, {
        id: nonExistentId,
        body: updatePayload
      });
    }
  );

  // 2. Generate a UUID, soft-delete it, and attempt update again
  const deletedId = typia.random<string & tags.Format<"uuid">>();
  // Simulate deletion (even if record didn't exist, deletion should be idempotent or have no visible effect)
  await api.functional.ai_ecommerce.media.eraseById(connection, {
    id: deletedId,
  });

  await TestValidator.error("update soft-deleted media should also fail")(
    async () => {
      await api.functional.ai_ecommerce.media.putById(connection, {
        id: deletedId,
        body: updatePayload
      });
    }
  );
}

