import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserProfile";
import type { IAiEcommerceUserAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserAddress";
import type { IPageIAiEcommerceUserAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiEcommerceUserAddress";

/**
 * Validate paginated and filtered retrieval of user addresses linked to a profile.
 *
 * This test ensures an authenticated user can retrieve only their addresses filtered by a specific profile_id with correct pagination. The test covers:
 *   - Only non-deleted addresses are listed
 *   - Addresses from other profiles are never included
 *   - Pagination metadata reflects the query
 *   - Edge cases such as empty pages and excessive page size
 *
 * Steps:
 * 1. Create a user profile for testing
 * 2. Create at least 5 addresses for this profile (with variety)
 * 3. Create another profile and at least one address for noise/filter testing
 * 4. Retrieve addresses for the test profile with filter/pagination (limit=2, page=1)
 * 5. Assert that only correct addresses are returned, pagination is accurate, and results match expectations
 * 6. Edge: Query empty page (page number out of range) and excessive page size for error or capping
 */
export async function test_api_ai_ecommerce_test_list_user_addresses_with_valid_profile_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a user profile for retrieval and address association
  const userProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(userProfile);

  // 2. Create several addresses for this profile to ensure pagination, filtering, and presence in results
  const addresses = await ArrayUtil.asyncRepeat(5)(async (i: number) => {
    const address = await api.functional.ai_ecommerce.userAddresses.post(connection, {
      body: {
        profile_id: userProfile.id,
        address_type: RandomGenerator.pick(["delivery", "billing", "default"]),
        name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        postal_code: `0${10000 + i}`,
        address_line1: RandomGenerator.paragraph()(),
        region_code: RandomGenerator.pick(["KR","US","JP"]),
        is_default: i === 0,
      } satisfies IAiEcommerceUserAddress.ICreate,
    });
    typia.assert(address);
    return address;
  });

  // 3. Create a second user profile and an address for noise (should never appear in test results)
  const otherProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(otherProfile);
  const otherAddress = await api.functional.ai_ecommerce.userAddresses.post(connection, {
    body: {
      profile_id: otherProfile.id,
      address_type: "delivery",
      name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      postal_code: "99999",
      address_line1: RandomGenerator.paragraph()(),
      region_code: "US",
      is_default: false,
    } satisfies IAiEcommerceUserAddress.ICreate,
  });
  typia.assert(otherAddress);

  // 4. Retrieve paged addresses for primary profile (limit=2, page=1)
  const pageLimit = 2;
  const addressesPage1 = await api.functional.ai_ecommerce.userAddresses.patch(connection, {
    body: {
      profile_id: userProfile.id,
      limit: pageLimit,
      page: 1,
    } satisfies IAiEcommerceUserAddress.IRequest,
  });
  typia.assert(addressesPage1);
  TestValidator.equals("query page size")(addressesPage1.data.length)(pageLimit);
  TestValidator.predicate("all with correct profile_id")(
    addressesPage1.data.every(entry => entry.profile_id === userProfile.id),
  );
  TestValidator.predicate("none soft-deleted")(
    addressesPage1.data.every(entry => !entry.deleted_at),
  );
  TestValidator.equals("pagination.limit correct")(
    addressesPage1.pagination.limit)(pageLimit);
  TestValidator.predicate("other profile's address never present")(
    addressesPage1.data.every(entry => entry.profile_id !== otherProfile.id),
  );

  // 5. Edge: Querying a page far beyond contents returns empty result set
  const addressesEmpty = await api.functional.ai_ecommerce.userAddresses.patch(connection, {
    body: {
      profile_id: userProfile.id,
      limit: pageLimit,
      page: 999,
    } satisfies IAiEcommerceUserAddress.IRequest,
  });
  typia.assert(addressesEmpty);
  TestValidator.equals("beyond last page empty")(
    addressesEmpty.data.length,
  )(0);

  // 6. Edge: Query with excessive page size to test cap or error
  const largeLimit = 1000;
  const oversizedResult = await api.functional.ai_ecommerce.userAddresses.patch(connection, {
    body: {
      profile_id: userProfile.id,
      page: 1,
      limit: largeLimit,
    } satisfies IAiEcommerceUserAddress.IRequest,
  });
  typia.assert(oversizedResult);
  TestValidator.predicate("limit respected or capped")(
    oversizedResult.pagination.limit <= largeLimit && oversizedResult.pagination.limit > 0,
  );
  TestValidator.predicate("no deleted, all own profile")(
    oversizedResult.data.every(entry => entry.profile_id === userProfile.id && !entry.deleted_at),
  );
}

