/**
 * 유효하지만 존재하지 않거나 소프트 삭제된 UUID로 유저 주소를 조회할 때의 예외 동작 검증
 *
 * 이 테스트는 다음 두 가지 부정 케이스에 대해 적절한 에러 및 데이터 미노출을 검증합니다:
 * 1. DB에 존재하지 않는 무작위 UUID로 조회 시: 404 또는 not found 에러
 * 2. 실제로 발급/연결한 주소를 소프트 삭제 후 동일 ID로 조회 시: 404 또는 deleted 에러(실제 주소 데이터 반환 금지)
 *
 * 실제 활성화된 주소 데이터가 반환되지 않는지(typia.assert로 output 검사 불가) 반드시 확인해야 합니다.
 * 두 경우 모두 비즈니스 규약상 에러가 반드시 발생해야 하며, TestValidator.error를 이용해 검증합니다.
 *
 * [진행 순서]
 * 1. 사용자 프로필 생성 (주소 생성에 필요)
 * 2. 해당 프로필로 주소 데이터 생성
 * 3. 주소를 eraseById로 소프트 삭제 실시
 * 4. 삭제된 주소 ID로 getById 호출 → 에러 발생하는지 확인
 * 5. 무작위/존재하지 않는 UUID로 getById 호출 → 에러 발생하는지 확인
 */
export async function test_api_ai_ecommerce_test_get_user_address_not_found_or_deleted_case(
  connection: api.IConnection,
) {
  // 1. 사용자 프로필 생성 (address.profile_id로 활용)
  const profile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true
    } satisfies IAiEcommerceUserProfile.ICreate
  });
  typia.assert(profile);

  // 2. 프로필로 유저 주소 생성
  const address = await api.functional.ai_ecommerce.userAddresses.post(connection, {
    body: {
      profile_id: profile.id,
      address_type: "delivery",
      name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      postal_code: "12345",
      address_line1: "테스트로 7길 10-1",
      address_line2: null,
      custom_label: null,
      region_code: "KOR",
      is_default: true
    } satisfies IAiEcommerceUserAddress.ICreate
  });
  typia.assert(address);

  // 3. 주소 소프트 삭제 (deleted_at 갱신)
  await api.functional.ai_ecommerce.userAddresses.eraseById(connection, { id: address.id });

  // 4. 삭제된 주소를 다시 조회하면 무조건 에러(존재하지 않음)
  await TestValidator.error("소프트 삭제된 주소 조회 시 에러 발생해야 함")(
    async () => {
      await api.functional.ai_ecommerce.userAddresses.getById(connection, { id: address.id });
    },
  );

  // 5. 존재하지 않는 무작위 UUID로 조회 시에도 마찬가지로 not found 에러가 발생해야 함
  const notExistsId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("존재하지 않는 주소 UUID로 조회 시 에러 발생해야 함")(
    async () => {
      await api.functional.ai_ecommerce.userAddresses.getById(connection, { id: notExistsId });
    },
  );
}

