 *
 * - address_line1, name, phone_number 등 입력값과 응답값 동일 필드 매핑 검증
 * - address_line2, custom_label, deleted_at 등 optional/null 필드는 반환 값에서 null/undefined 인지 체크
 */
export async function test_api_ai_ecommerce_test_create_user_address_with_minimum_required_fields(
  connection: api.IConnection,
) {
  // 1. 사용자 프로필 생성(의존성 처리)
  const profileInput = {
    nickname: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    communication_consent: true,
  } satisfies IAiEcommerceUserProfile.ICreate;
  const userProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, { body: profileInput });
