    region_code: "KR",
    is_default: true,
  } satisfies IAiEcommerceUserAddress.ICreate;
  const userAddress = await api.functional.ai_ecommerce.userAddresses.post(connection, { body: addressInput });
  typia.assert(userAddress);

  // 3. 주소가 시스템에 정상적으로 기록 되었는지 및 모든 필수 필드 검증
  TestValidator.equals("profile_id mapping")(userAddress.profile_id)(userProfile.id);
  TestValidator.equals("address_type")(userAddress.address_type)(addressInput.address_type);
  TestValidator.equals("region_code")(userAddress.region_code)(addressInput.region_code);
  TestValidator.equals("is_default")(userAddress.is_default)(true);

  // 입력값과 반환값 필드가 일치하는지 검증
  TestValidator.equals("address_line1")(userAddress.address_line1)(addressInput.address_line1);
  TestValidator.equals("name")(userAddress.name)(addressInput.name);
  TestValidator.equals("phone_number")(userAddress.phone_number)(addressInput.phone_number);
  TestValidator.equals("postal_code")(userAddress.postal_code)(addressInput.postal_code);

