import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserProfile";
import type { IAiEcommerceUserAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserAddress";

/**
 * Validates updating allowed fields (address_line1, name, is_default) for a user's address record.
 *
 * This test ensures:
 *  - A user can update permitted fields (address_line1, name, is_default) for their own address.
 *  - Validation is enforced and attempts to update only allowed fields are accepted.
 *  - The updated_at timestamp is changed after the update.
 *  - The response includes new values for updated fields and unchanged values for others.
 *
 * Workflow:
 * 1. Create a user profile (POST /ai_ecommerce/userProfiles).
 * 2. Create a user address record (POST /ai_ecommerce/userAddresses) bound to the profile.
 * 3. Update selected allowed fields (PUT /ai_ecommerce/userAddresses/{id}).
 * 4. Assert:
 *    - Only updated fields are changed; other fields remain the same.
 *    - updated_at reflects later time than before.
 *    - API response has intended values.
 */
export async function test_api_ai_ecommerce_userAddresses_test_update_user_address_successful_field_update(
  connection: api.IConnection,
) {
  // 1. Create user profile
  const userProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(userProfile);

  // 2. Create user address record
  const origAddress = await api.functional.ai_ecommerce.userAddresses.post(connection, {
    body: {
      profile_id: userProfile.id,
      address_type: "delivery",
      name: "Original Name",
      phone_number: "01012345678",
      postal_code: "12345",
      address_line1: "Old Address 1st line",
      address_line2: null,
      custom_label: null,
      region_code: "KR",
      is_default: false,
    } satisfies IAiEcommerceUserAddress.ICreate,
  });
  typia.assert(origAddress);

  // 3. Update allowed fields on the address
  const updateInput = {
    address_line1: "New Address 1st line",
    name: "New Recipient Name",
    is_default: true,
  } satisfies IAiEcommerceUserAddress.IUpdate;

  const updated = await api.functional.ai_ecommerce.userAddresses.putById(connection, {
    id: origAddress.id,
    body: updateInput,
  });
  typia.assert(updated);

  // 4. Assertions
  // a. Updated fields are changed
  TestValidator.equals("address_line1 changed")(updated.address_line1)(updateInput.address_line1);
  TestValidator.equals("name changed")(updated.name)(updateInput.name);
  TestValidator.equals("is_default changed")(updated.is_default)(updateInput.is_default);

  // b. Other fields remain unchanged
  TestValidator.equals("profile_id unchanged")(updated.profile_id)(origAddress.profile_id);
  TestValidator.equals("address_type unchanged")(updated.address_type)(origAddress.address_type);
  TestValidator.equals("phone_number unchanged")(updated.phone_number)(origAddress.phone_number);
  TestValidator.equals("postal_code unchanged")(updated.postal_code)(origAddress.postal_code);
  TestValidator.equals("address_line2 unchanged")(updated.address_line2)(origAddress.address_line2);
  TestValidator.equals("custom_label unchanged")(updated.custom_label)(origAddress.custom_label);
  TestValidator.equals("region_code unchanged")(updated.region_code)(origAddress.region_code);

  // c. updated_at is actually changed to a later time
  TestValidator.predicate("updated_at is updated")(new Date(updated.updated_at) > new Date(origAddress.updated_at));
}

