import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserProfile";
import type { IPageIAiEcommerceUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiEcommerceUserProfile";

/**
 * Validate paginated and filtered search of user profiles for admin/customer service scenarios.
 *
 * This test ensures that the API correctly supports search by nickname/email, pagination (page/limit), and returns proper paging metadata. It focuses on ensuring only active/non-deleted profiles are returned, and all paging properties (current/limit/records/pages) align with the data.
 *
 * 1. Use a distinctive search keyword likely to match some real profiles (as profile creation is unavailable, this assumes data exists)
 * 2. Execute PATCH search with page, limit, sortBy, sortDir, and a search string.
 * 3. Assert output data array contains user profiles matching the search criteria (by nickname/email), and only valid profiles with all essential fields are present.
 * 4. Assert pagination metadata aligns with paging request and output data length.
 * 5. Optionally, repeat for page 2 to confirm further paging works as expected.
 */
export async function test_api_ai_ecommerce_test_search_user_profiles_with_full_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Define search/pagination parameters
  const searchValue = "a"; // Likely substring in some nicknames/emails
  const page = 1;
  const limit = 2;
  const sortBy = "created_at";
  const sortDir = "desc";

  // 2. Run filter & paginated search
  const response = await api.functional.ai_ecommerce.userProfiles.patch(connection, {
    body: {
      search: searchValue,
      page,
      limit,
      sortBy,
      sortDir,
    } satisfies IAiEcommerceUserProfile.IRequest,
  });
  typia.assert(response);

  // 3. Validate pagination response matches input and covers result array
  TestValidator.equals("pagination current page")(response.pagination.current)(page);
  TestValidator.equals("pagination limit")(response.pagination.limit)(limit);
  TestValidator.predicate("data array length not above limit")(
    response.data.length <= limit && response.data.length >= 0,
  );
  TestValidator.predicate("total record count >= data so far")(
    response.pagination.records >= (page - 1) * limit + response.data.length,
  );
  TestValidator.predicate("total pages computed correctly")(
    response.pagination.pages ===
      Math.max(1, Math.ceil(response.pagination.records / response.pagination.limit)),
  );

  // 4. Validate all profiles in data match search and have all required fields
  response.data.forEach((profile) => {
    // Profile matches search substring in nickname or email
    TestValidator.predicate("profile matches search")(
