    TestValidator.predicate("has nickname")(!!profile.nickname);
    TestValidator.predicate("has created_at")(!!profile.created_at);
    TestValidator.predicate("has updated_at")(!!profile.updated_at);
  });

  // 5. If multiple pages, fetch page 2 for further validation
  if (response.pagination.pages > 1) {
    const response2 = await api.functional.ai_ecommerce.userProfiles.patch(connection, {
      body: {
