        page: 2,
        limit,
        sortBy,
        sortDir,
      } satisfies IAiEcommerceUserProfile.IRequest,
    });
    typia.assert(response2);
    TestValidator.equals("pagination on page 2")(response2.pagination.current)(2);
    TestValidator.equals("pagination limit page 2")(response2.pagination.limit)(limit);
  }
}

