import type { IPageIAiEcommerceUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiEcommerceUserProfile";

/**
 * 검증: 소프트 삭제된 사용자 프로필이 목록/검색에서 제외되는지 테스트합니다.
 *
 * 프로필 여러 개를 생성한 후, 그 중 하나를 소프트 삭제(eraseById) 합니다.
 * 그런 다음, 전체 목록/검색(모든 조건/혹은 일부 필터링 포함) 요청을 통해, 삭제한 프로필이 결과에 포함되지 않는지 확인합니다.
 *
 * 이 테스트는 논리적 필터링(soft-deleted의 목록 미노출)과 Privacy/유저 데이터 보호 요구사항의 기본 동작을 검증합니다.
 *
 * 1. 랜덤하게 이메일/Nickname으로 3명의 사용자 프로필을 생성합니다.
 * 2. 이 중 1명을 소프트 삭제(eraseById)합니다.
 * 3. 별도 조건없이 목록(patch) API로 모두 조회했을 때, 삭제된 프로필이 나오지 않는지 확인합니다.
 * 4. 삭제된 프로필의 이메일이나 닉네임으로 (search로) 패치 API를 호출해도, 해당 결과가 비어있음을 검증합니다.
 */
export async function test_api_ai_ecommerce_userProfiles_test_search_user_profiles_excluding_soft_deleted_records(
  connection: api.IConnection,
) {
  // 1. 사용자 프로필 3개 생성
  const profiles = await ArrayUtil.asyncRepeat(3)(async () => {
    const profile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
      body: {
        nickname: RandomGenerator.name(),
        avatar_uri: null,
        email: `${RandomGenerator.alphaNumeric(8)}@test.com`,
        phone_number: null,
        communication_consent: true,
      } satisfies IAiEcommerceUserProfile.ICreate,
    });
    typia.assert(profile);
    return profile;
  });

  // 2. 생성된 프로필 중 1명을 무작위로 골라 소프트 삭제
  const deletedProfile = RandomGenerator.pick(profiles);
  const erased = await api.functional.ai_ecommerce.userProfiles.eraseById(connection, {
    id: deletedProfile.id,
  });
  typia.assert(erased);

  // 3. 조건없이 전체 목록 patch: 삭제된 프로필이 결과에 없는지 검증
  const result = await api.functional.ai_ecommerce.userProfiles.patch(connection, {
    body: {},
  });
  typia.assert(result);
  const found = result.data.find((p) => p.id === deletedProfile.id);
  TestValidator.equals("soft-deleted profile filtered from list")(found)(undefined);

  // 4-1. 삭제 프로필의 email로 검색하면 결과가 비어있는지
  const r1 = await api.functional.ai_ecommerce.userProfiles.patch(connection, {
    body: {
      search: deletedProfile.email,
    },
  });
  typia.assert(r1);
  TestValidator.equals("patch by deleted email returns no result")(r1.data.length)(0);

  // 4-2. 삭제 프로필의 nickname으로 검색해도 결과가 비어있는지
  const r2 = await api.functional.ai_ecommerce.userProfiles.patch(connection, {
    body: {
      search: deletedProfile.nickname,
    },
  });
  typia.assert(r2);
  TestValidator.equals("patch by deleted nickname returns no result")(r2.data.length)(0);
}

