 * 1. Create a user profile using the dependency POST API.
 * 2. Update the nickname and communication_consent fields of the created profile with new valid values using the PUT API.
 * 3. Confirm the persisted changes are accurately reflected in the response.
 * 4. Ensure all unmodified fields remain unchanged and that updated_at timestamp is updated.
 */
export async function test_api_ai_ecommerce_userProfiles_test_update_user_profile_valid_fields(connection: api.IConnection) {
  // 1. Create an initial user profile to update
  const initialProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
