/**
 * Attempt to update a user profile that has already been soft-deleted.
 *
 * This test validates that if a user profile has been soft-deleted
 * (via the DELETE endpoint), any subsequent attempt to modify that
 * profile through the update API must result in an error. This ensures
 * strict compliance with audit and deletion protections—no further
 * changes may be made to soft-deleted records in the system.
 *
 * Step-by-step process:
 * 1. Create a valid user profile via the POST endpoint, with all required fields.
 * 2. Soft-delete this profile using the DELETE endpoint.
 * 3. Attempt to update the soft-deleted profile by calling the PUT endpoint with new values.
 * 4. Assert that the update fails by using TestValidator.error, ensuring the system properly blocks modifications to deleted records.
 */
export async function test_api_ai_ecommerce_userProfiles_test_update_user_profile_that_is_soft_deleted_returns_error(
  connection: api.IConnection,
) {
  // 1. Create a valid user profile
  const createInput: IAiEcommerceUserProfile.ICreate = {
    nickname: RandomGenerator.name(),
    avatar_uri: null,
    email: typia.random<string & tags.Format<"email">>(),
    phone_number: null,
    communication_consent: true,
  };
  const profile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: createInput,
  });
  typia.assert(profile);

  // 2. Soft-delete this profile
  const deleted = await api.functional.ai_ecommerce.userProfiles.eraseById(connection, {
    id: profile.id,
  });
  typia.assert(deleted);

  // 3. Attempt to update the soft-deleted profile
  const updateInput: IAiEcommerceUserProfile.IUpdate = {
    nickname: RandomGenerator.name(),
    communication_consent: false,
  };
  await TestValidator.error("Update to soft-deleted user profile must fail")(
    async () => {
      await api.functional.ai_ecommerce.userProfiles.putById(connection, {
        id: profile.id,
        body: updateInput,
      });
    },
  );
}

