/**
 * Validate administrator access to paginated, filtered loyalty tier listing endpoint.
 *
 * This test covers:
 *  - Setup: Several tiers with unique names, min_points, and sort_order for filter scenario coverage
 *  - Positive: Admin retrieves paginated, filtered list by individual fields (name, min_points, sort_order)
 *      - Check: Only correct matching records returned, structure conforms to schema, meta correct
 *      - Filter no-match returns empty set
 *      - Filter with single match returns only that tier
 *      - Pagination works: partial results (limit < records), correct meta, no duplicates, next page correct
 *  - Negative: Invalid filter triggers appropriate error, unauthorized user cannot access endpoint
 *
 * Steps:
 *  1. Insert at least 3 distinct loyalty tiers (different names, points, orders)
 *  2. As admin, retrieve list with different filters:
 *      a. By name (exact, case sensitive)
 *      b. By min_points_required
 *      c. By sort_order
 *      d. By combination (e.g. name/min_points)
 *      e. Non-matching filter (should get empty)
 *      f. Pagination: limit = 2, page = 1/2, verify data/meta
 *  3. Negative: invalid filter (string in numeric field etc) gets error
 *  4. Access control: non-admin or unauthenticated cannot retrieve list (TestValidator.error)
 *  5. All result data passes typia.assert, meta correct, only visible fields, no leakage
 */
export async function test_api_ai_ecommerce_loyaltyTiers_test_list_loyalty_tiers_with_pagination_and_filters_by_administrator(
  connection: api.IConnection,
) {
  // 1. Insert at least 3 distinct loyalty tiers for filter/pagination coverage
  const tiers = [
    {
      name: `Bronze_${RandomGenerator.alphaNumeric(6)}`,
      min_points_required: 100,
      multiplier: 1.0,
      sort_order: 3,
    },
    {
      name: `Silver_${RandomGenerator.alphaNumeric(6)}`,
      min_points_required: 500,
      multiplier: 1.25,
      sort_order: 2,
    },
    {
      name: `Gold_${RandomGenerator.alphaNumeric(6)}`,
      min_points_required: 2000,
      multiplier: 1.5,
      sort_order: 1,
    },
  ];
  const inserted = [] as IAiEcommerceLoyaltyTier[];
  for (const tier of tiers) {
    // Use .post to insert the tier
    const created = await api.functional.ai_ecommerce.loyaltyTiers.post(connection, {
      body: tier satisfies IAiEcommerceLoyaltyTier.ICreate,
    });
    typia.assert(created);
    inserted.push(created);
  }

  // 2a. Filter by name (case sensitive, exact)
  {
    const target = inserted[1];
    const byName = await api.functional.ai_ecommerce.loyaltyTiers.patch(connection, {
      body: {
        name: target.name,
      } satisfies IAiEcommerceLoyaltyTier.IListRequest,
    });
    typia.assert(byName);
    TestValidator.equals("filter by name count")(1)(byName.data.length);
    TestValidator.equals("filter by name content")(byName.data[0].id)(target.id);
  }

  // 2b. Filter by min_points_required
  {
    const target = inserted[2];
    const byPoints = await api.functional.ai_ecommerce.loyaltyTiers.patch(connection, {
      body: {
        min_points_required: target.min_points_required,
      } satisfies IAiEcommerceLoyaltyTier.IListRequest,
    });
    typia.assert(byPoints);
    TestValidator.equals("filter by min_points_required count")(1)(byPoints.data.length);
    TestValidator.equals("filter by min_points_required content")(byPoints.data[0].id)(target.id);
  }

  // 2c. Filter by sort_order
  {
    const target = inserted[0];
    const byOrder = await api.functional.ai_ecommerce.loyaltyTiers.patch(connection, {
      body: {
        sort_order: target.sort_order,
      } satisfies IAiEcommerceLoyaltyTier.IListRequest,
    });
    typia.assert(byOrder);
    TestValidator.equals("filter by sort_order count")(1)(byOrder.data.length);
    TestValidator.equals("filter by sort_order content")(byOrder.data[0].id)(target.id);
  }

  // 2d. Combination filter (name + min_points)
  {
    const target = inserted[1];
    const byCombo = await api.functional.ai_ecommerce.loyaltyTiers.patch(connection, {
      body: {
        name: target.name,
        min_points_required: target.min_points_required,
      } satisfies IAiEcommerceLoyaltyTier.IListRequest,
    });
    typia.assert(byCombo);
    TestValidator.equals("combo filter count")(1)(byCombo.data.length);
    TestValidator.equals("combo filter content")(byCombo.data[0].id)(target.id);
  }

  // 2e. No-match filter returns empty
  {
    const byEmpty = await api.functional.ai_ecommerce.loyaltyTiers.patch(connection, {
      body: {
        name: "NO_EXISTING_TIER_NAME",
      } satisfies IAiEcommerceLoyaltyTier.IListRequest,
    });
    typia.assert(byEmpty);
    TestValidator.equals("empty filter count")(0)(byEmpty.data.length);
  }

  // 2f/Edge: Pagination (limit = 2, page = 1/2)
  {
    // Page 1
    const page1 = await api.functional.ai_ecommerce.loyaltyTiers.patch(connection, {
      body: {
        limit: 2,
        page: 1,
      } satisfies IAiEcommerceLoyaltyTier.IListRequest,
    });
    typia.assert(page1);
    TestValidator.equals("pagination limit")(2)(page1.pagination.limit);
    TestValidator.equals("pagination page")(1)(page1.pagination.current);
    TestValidator.predicate("page 1 data count <= limit")(page1.data.length <= 2);
    // Page 2
    const page2 = await api.functional.ai_ecommerce.loyaltyTiers.patch(connection, {
      body: {
        limit: 2,
        page: 2,
      } satisfies IAiEcommerceLoyaltyTier.IListRequest,
    });
    typia.assert(page2);
    TestValidator.equals("pagination page 2")(2)(page2.pagination.current);
    // Combined, all inserted IDs should be found (no duplicates, full set)
    const ids = new Set([...page1.data, ...page2.data].map(x => x.id));
    for (const i of inserted.map(x => x.id)) {
      TestValidator.predicate(`inserted tier ${i} found in pages`)(ids.has(i));
    }
  }

  // 3. Negative: invalid filter param triggers error (string for numeric)
  {
    await TestValidator.error("invalid min_points_required triggers error")(
      async () => {
        await api.functional.ai_ecommerce.loyaltyTiers.patch(connection, {
          body: {
            min_points_required: "NOT_A_NUMBER" as any,
          } as IAiEcommerceLoyaltyTier.IListRequest,
        });
      },
    );
  }

  // 4. Access control: simulate unauthorized access
  {
    // Remove admin credentials or clear connection.headers.Authorization
    const unauthConn = { ...connection, headers: { ...connection.headers } };
    delete unauthConn.headers.Authorization;
    await TestValidator.error("unauthenticated cannot retrieve tiers")(
      async () => {
        await api.functional.ai_ecommerce.loyaltyTiers.patch(unauthConn, {
          body: {},
        });
      },
    );
  }
}

