import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceLoyaltyTier } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceLoyaltyTier";

/**
 * E2E test for updating an existing loyalty tier with both valid and invalid data.
 *
 * Validates correct update logic, business rules, uniqueness enforcement, and error handling:
 *
 * 1. Admin creates two unique loyalty tiers for baseline and clash testing.
 * 2. Admin updates the first loyalty tier with valid unique values (all mutable fields).
 * 3. Verifies the update response, type assertions, and correct application of new values.
 * 4. Attempts to update a nonexistent tier (expects an error).
 * 5. Attempts to update a tier using a duplicate name or sort order (expects uniqueness violations).
 * 6. Tries to update with invalid numeric values (negative numbers, zero multipliers, etc.).
 * 7. Confirms that only mutable fields are touched and skips immutable/extra fields (none in schema).
 *
 * The test covers both business logic and integration boundaries, providing strong confidence in the PUT endpoint compliance.
 */
export async function test_api_ai_ecommerce_loyaltyTiers_test_update_loyalty_tier_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create two different loyalty tiers for update and uniqueness/validation tests.
  const tierAInput: IAiEcommerceLoyaltyTier.ICreate = {
    name: `Silver_${RandomGenerator.alphaNumeric(8)}`,
    min_points_required: 1000,
    multiplier: 1.1,
    sort_order: 1,
  };
  const tierA = await api.functional.ai_ecommerce.loyaltyTiers.post(connection, { body: tierAInput });
  typia.assert(tierA);

  const tierBInput: IAiEcommerceLoyaltyTier.ICreate = {
    name: `Gold_${RandomGenerator.alphaNumeric(8)}`,
    min_points_required: 5000,
    multiplier: 1.5,
    sort_order: 2,
  };
  const tierB = await api.functional.ai_ecommerce.loyaltyTiers.post(connection, { body: tierBInput });
  typia.assert(tierB);

  // 2. Update tierA with all mutable fields
  const updateInput: IAiEcommerceLoyaltyTier.IUpdate = {
    name: `SilverUpdated_${RandomGenerator.alphaNumeric(8)}`,
    min_points_required: 2000,
    multiplier: 1.2,
    sort_order: 3,
  };
  const updatedTierA = await api.functional.ai_ecommerce.loyaltyTiers.putById(connection, {
    id: tierA.id,
    body: updateInput,
  });
  typia.assert(updatedTierA);
  TestValidator.equals("updated loyalty tier - name")(updatedTierA.name)(updateInput.name);
  TestValidator.equals("updated loyalty tier - min_points_required")(updatedTierA.min_points_required)(updateInput.min_points_required);
  TestValidator.equals("updated loyalty tier - multiplier")(updatedTierA.multiplier)(updateInput.multiplier);
  TestValidator.equals("updated loyalty tier - sort_order")(updatedTierA.sort_order)(updateInput.sort_order);

  // 3. Attempt updating a nonexistent tier (expect error)
  await TestValidator.error("update nonexistent loyalty tier")(() =>
    api.functional.ai_ecommerce.loyaltyTiers.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { name: "ShouldNotExist" },
    })
  );

  // 4a. Try updating tierB to use tierA's (updated) name (expect uniqueness error)
  await TestValidator.error("update with duplicate name")(() =>
    api.functional.ai_ecommerce.loyaltyTiers.putById(connection, {
      id: tierB.id,
      body: { name: updateInput.name },
    })
  );
  // 4b. Try updating tierB to use tierA's sort_order (3, which is now already in use)
  await TestValidator.error("update with duplicate sort_order")(() =>
    api.functional.ai_ecommerce.loyaltyTiers.putById(connection, {
      id: tierB.id,
      body: { sort_order: updateInput.sort_order },
    })
  );

  // 5. Invalid values: negative points
  await TestValidator.error("update with negative min_points_required")(() =>
    api.functional.ai_ecommerce.loyaltyTiers.putById(connection, {
      id: tierA.id,
      body: { min_points_required: -100 },
    })
  );
  // 6. Invalid values: negative multiplier
  await TestValidator.error("update with negative multiplier")(() =>
    api.functional.ai_ecommerce.loyaltyTiers.putById(connection, {
      id: tierA.id,
      body: { multiplier: -1 },
    })
  );
  // 7. Invalid values: zero multiplier is probably invalid for a multiplier
  await TestValidator.error("update with zero multiplier")(() =>
    api.functional.ai_ecommerce.loyaltyTiers.putById(connection, {
      id: tierA.id,
      body: { multiplier: 0 },
    })
  );
}

