import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserProfile";
import type { ai_ecommerce_product } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_product";
import type { IAiEcommerceReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceReview";

/**
 * Validate detail fetch and permission logic for product reviews.
 *
 * This end-to-end test verifies the business rule that review detail endpoints enforce appropriate access control
 * and privacy logic. Both public and private reviews are created, and attempts are made to fetch them as different
 * kinds of users (author, product seller, admin, unrelated user). The test asserts that public reviews are accessible
 * by anyone, but private reviews are only accessible by the author, product seller, or administrator. It also checks
 * that requests for non-existent or deleted reviews result in an error as expected.
 *
 * Full business process covered:
 * 1. Create a customer profile (to use as review author)
 * 2. Create a seller profile (who owns the product being reviewed)
 * 3. Create an admin profile
 * 4. Create an unrelated/stranger user profile
 * 5. Seller creates a product entry
 * 6. Customer authors a public review
 * 7. Fetches public review as all four user types
 * 8. Customer authors a private review on the same product
 * 9. Fetches private review as all four user types, expecting failure for stranger
 * 10. Attempts to fetch a non-existent review as any user, expecting all to fail
 */
export async function test_api_ai_ecommerce_test_get_review_detail_success_and_permission_control(
  connection: api.IConnection,
) {
  // 1. Create customer profile (author)
  const customer = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<'email'>>(),
      communication_consent: true,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(customer);

  // 2. Create seller profile
  const seller = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<'email'>>(),
      communication_consent: true,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(seller);

  // 3. Create admin profile
  const admin = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<'email'>>(),
      communication_consent: true,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(admin);

  // 4. Create unrelated/stranger user
  const stranger = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<'email'>>(),
      communication_consent: true,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(stranger);

  // 5. Seller creates product
  const product = await api.functional.ai_ecommerce.products.post(connection, {
    body: {
      seller_id: seller.id,
      title: RandomGenerator.paragraph()(3),
      description: RandomGenerator.content()(1)(1),
      status: "published",
      approval_state: "approved",
    } satisfies ai_ecommerce_product.ICreate,
  });
  typia.assert(product);

  // 6. Customer creates a public review (is_private: false)
  const review = await api.functional.ai_ecommerce.reviews.post(connection, {
    body: {
      customer_id: customer.id,
      product_id: product.id,
      order_id: typia.random<string & tags.Format<'uuid'>>(),
      rating: 5,
      body: RandomGenerator.content()(2)(2),
      title: RandomGenerator.paragraph()(1),
      is_private: false,
    } satisfies IAiEcommerceReview.ICreate,
  });
  typia.assert(review);

  // 7. Fetch as customer (author)
  const fetchedByCustomer = await api.functional.ai_ecommerce.reviews.getById(connection, { id: review.id });
  typia.assert(fetchedByCustomer);
  TestValidator.equals("fetched by customer")(fetchedByCustomer.id)(review.id);

  // 8. Fetch as seller (product owner)
  const fetchedBySeller = await api.functional.ai_ecommerce.reviews.getById(connection, { id: review.id });
  typia.assert(fetchedBySeller);
  TestValidator.equals("fetched by seller")(fetchedBySeller.id)(review.id);

  // 9. Fetch as admin
  const fetchedByAdmin = await api.functional.ai_ecommerce.reviews.getById(connection, { id: review.id });
  typia.assert(fetchedByAdmin);
  TestValidator.equals("fetched by admin")(fetchedByAdmin.id)(review.id);

  // 10. Fetch as stranger (unrelated user)
  const fetchedByStranger = await api.functional.ai_ecommerce.reviews.getById(connection, { id: review.id });
  typia.assert(fetchedByStranger);
  TestValidator.equals("fetched by stranger")(fetchedByStranger.id)(review.id);

  // 11. Customer creates a private review
  const privateReview = await api.functional.ai_ecommerce.reviews.post(connection, {
    body: {
      customer_id: customer.id,
      product_id: product.id,
      order_id: typia.random<string & tags.Format<'uuid'>>(),
      rating: 4,
      body: RandomGenerator.content()(2)(2),
      title: RandomGenerator.paragraph()(1),
      is_private: true,
    } satisfies IAiEcommerceReview.ICreate,
  });
  typia.assert(privateReview);

  // 12. Fetch private review as customer
  const privateByCustomer = await api.functional.ai_ecommerce.reviews.getById(connection, { id: privateReview.id });
  typia.assert(privateByCustomer);
  TestValidator.equals("private review fetch by customer")(privateByCustomer.id)(privateReview.id);

  // 13. Fetch private review as seller (product owner)
  const privateBySeller = await api.functional.ai_ecommerce.reviews.getById(connection, { id: privateReview.id });
  typia.assert(privateBySeller);
  TestValidator.equals("private review fetch by seller")(privateBySeller.id)(privateReview.id);

  // 14. Fetch private review as admin
  const privateByAdmin = await api.functional.ai_ecommerce.reviews.getById(connection, { id: privateReview.id });
  typia.assert(privateByAdmin);
  TestValidator.equals("private review fetch by admin")(privateByAdmin.id)(privateReview.id);

  // 15. Fetch private review as stranger — must fail (forbidden/404)
  await TestValidator.error("forbidden for stranger to fetch private review")(
    async () => {
      await api.functional.ai_ecommerce.reviews.getById(connection, { id: privateReview.id });
    },
  );

  // 16. Fetch non-existent/deleted review (random uuid) as all roles
  const nonExistentId = typia.random<string & tags.Format<'uuid'>>();
  await TestValidator.error("customer fetch non-existent review")(async () => {
    await api.functional.ai_ecommerce.reviews.getById(connection, { id: nonExistentId });
  });
  await TestValidator.error("seller fetch non-existent review")(async () => {
    await api.functional.ai_ecommerce.reviews.getById(connection, { id: nonExistentId });
  });
  await TestValidator.error("admin fetch non-existent review")(async () => {
    await api.functional.ai_ecommerce.reviews.getById(connection, { id: nonExistentId });
  });
  await TestValidator.error("stranger fetch non-existent review")(async () => {
    await api.functional.ai_ecommerce.reviews.getById(connection, { id: nonExistentId });
  });
}

