 * are required and enforced correctly. Ensures only one review can be
 * submitted for a given order-product-customer combination.
 *
 * Steps:
 * 1. Create a customer profile
 * 2. Create a product (with the customer as seller - as schemas only require seller_id link)
 * 3. Create a completed order for this customer and product
 * 4. Submit a review (with all business-required fields), expect success
 * 5. Attempt to submit a duplicate review for same order-product-customer, expect error
 * 6. Validate that response exactly matches what was submitted and required fields are persisted
 */
export async function test_api_ai_ecommerce_test_create_review_verified_purchase_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a customer profile
  const profile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      avatar_uri: null,
      email: typia.random<string & tags.Format<"email">>(),
      phone_number: null,
      communication_consent: true,
    },
  });
  typia.assert(profile);

  // 2. Create a product with this customer as seller (allowed by schema)
  const product = await api.functional.ai_ecommerce.products.post(connection, {
    body: {
      seller_id: profile.id,
      title: RandomGenerator.paragraph()(),
      description: RandomGenerator.content()()(),
      status: "published",
      approval_state: "approved",
    },
  });
  typia.assert(product);

  // 3. Create an order. Use required order fields to link this customer and product.
