    body: {
      customer_id: profile.id,
      cart_id: typia.random<string & tags.Format<"uuid">>(),
      shipping_address_id: typia.random<string & tags.Format<"uuid">>(),
      order_status: "delivered",
      items: [{
        sku_id: product.id,
        quantity: 1,
      }],
    },
  });
  typia.assert(order);

  // 4. Create a review for the product/order-customer combo (should succeed)
  const reviewCreateInput = {
    customer_id: profile.id,
    product_id: product.id,
    order_id: order.id,
    rating: 5,
    body: "Amazing quality and quick shipping!",
    title: "Great purchase",
    is_private: false,
