  const review = await api.functional.ai_ecommerce.reviews.post(connection, {
    body: reviewCreateInput,
  });
  typia.assert(review);
  TestValidator.equals("review fields - customer_id")(review.customer_id)(reviewCreateInput.customer_id);
  TestValidator.equals("review fields - product_id")(review.product_id)(reviewCreateInput.product_id);
  TestValidator.equals("review fields - order_id")(review.order_id)(reviewCreateInput.order_id);
  TestValidator.equals("review fields - rating")(review.rating)(reviewCreateInput.rating);
  TestValidator.equals("review fields - body")(review.body)(reviewCreateInput.body);
  TestValidator.equals("review fields - title")(review.title)(reviewCreateInput.title);
  TestValidator.equals("review fields - is_private")(review.is_private)(reviewCreateInput.is_private);
  TestValidator.predicate("review is_verified should be true")(review.is_verified === true);

  // 5. Attempt to create a second review for the same order-product-customer (expect error)
  await TestValidator.error("duplicate review for same order-product-customer is rejected")(async () => {
    await api.functional.ai_ecommerce.reviews.post(connection, {
      body: reviewCreateInput,
    });
  });
}

