import type { IAiEcommerceOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrderItem";

/**
 * Validates that a review can be updated by its author for allowed fields only (title, body, rating, privacy),
 * and ensures that unauthorized edits or attempts to change prohibited fields are disallowed per business rules.
 *
 * This test ensures:
 * - A user (customer) can update their own review for editable fields only (title, body, rating, is_private).
 * - Attempts to update a review by a non-author are rejected.
 * - Attempts to update immutable/restricted fields (customer/product/order association) via the type system are prevented.
 *
 * Step-by-step process:
 * 1. Create a customer user profile (author of review)
 * 2. Create a product
 * 3. Create an order for the user
 * 4. Create a review for the product/order by the customer
 * 5. Update review as the author, changing only permitted fields
 * 6. Confirm updated fields reflect changes
 * 7. Attempt update as different user and assert error
 * 8. Confirm type system does not allow attempt to update prohibited fields
 */
export async function test_api_ai_ecommerce_reviews_test_update_review_editable_fields_and_permission(
  connection: api.IConnection,
) {
  // 1. Create a customer user profile
  const userProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(userProfile);

  // 2. Create a product (using the same user as seller for isolation)
  const product = await api.functional.ai_ecommerce.products.post(connection, {
    body: {
      seller_id: userProfile.id,
      title: RandomGenerator.paragraph()(10),
      description: RandomGenerator.content()(3)(24),
      status: "published",
      approval_state: "approved",
    } satisfies ai_ecommerce_product.ICreate,
  });
  typia.assert(product);

  // 3. Create an order (minimal mock - assumes the system will accept the product's id as SKU)
  const order = await api.functional.ai_ecommerce.orders.post(connection, {
    body: {
      customer_id: userProfile.id,
      cart_id: typia.random<string & tags.Format<"uuid">>(),
      shipping_address_id: typia.random<string & tags.Format<"uuid">>(),
      order_status: "pending",
      items: [
        {
          sku_id: typia.random<string & tags.Format<"uuid">>(),
          quantity: 1,
        } satisfies IAiEcommerceOrderItem.ICreate,
      ],
    } satisfies IAiEcommerceOrder.ICreate,
  });
  typia.assert(order);

  // 4. Create a review for this product/order
  const review = await api.functional.ai_ecommerce.reviews.post(connection, {
    body: {
      customer_id: userProfile.id,
      product_id: product.id,
      order_id: order.id,
      rating: 5,
      body: "Initial review body.",
      title: "Initial review title",
      is_private: false,
    } satisfies IAiEcommerceReview.ICreate,
  });
  typia.assert(review);

  // 5. Update as the author: all permitted fields (title, body, rating, is_private)
  const updatePayload: IAiEcommerceReview.IUpdate = {
    title: "Updated title",
    body: "Updated review content.",
    rating: 3,
    is_private: true,
  };
  const updated = await api.functional.ai_ecommerce.reviews.putById(connection, {
    id: review.id,
    body: updatePayload,
  });
  typia.assert(updated);
  TestValidator.equals("Review: updated title")(updated.title)(updatePayload.title);
  TestValidator.equals("Review: updated body")(updated.body)(updatePayload.body);
  TestValidator.equals("Review: updated rating")(updated.rating)(updatePayload.rating);
  TestValidator.equals("Review: updated privacy")(updated.is_private)(updatePayload.is_private);

  // 6. Edge: Attempt update as different user profile (should be rejected)
  const otherUser = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(otherUser);
  // Simulate different user context: in a real system, this would mean a switched auth token,
  // but here we illustrate with a logically separated user and attempt update
  await TestValidator.error("Deny update from non-author")(
    async () => {
      await api.functional.ai_ecommerce.reviews.putById(connection, {
        id: review.id,
        body: {
          title: "Malicious title edit",
          body: "Malicious content edit.",
        } satisfies IAiEcommerceReview.IUpdate,
      });
    }
  );
  // 7. Confirm it is not possible by type or API to attempt updating forbidden fields such as customer_id/product_id/order_id.
  // IAiEcommerceReview.IUpdate does not allow such fields by definition, so this scenario is covered by the type system.
}

