  const adminProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      avatar_uri: null,
      email: typia.random<string & tags.Format<"email">>(),
      phone_number: null,
      communication_consent: true,
    },
  });
  typia.assert(adminProfile);

  // 2. Seller (adminProfile acts as seller) registers a product
  const product = await api.functional.ai_ecommerce.products.post(connection, {
    body: {
      seller_id: adminProfile.id,
      title: RandomGenerator.paragraph()(),
      description: RandomGenerator.content()()(),
      status: "active",
      approval_state: "approved",
    },
  });
  typia.assert(product);

  // 3. Author places an order on the product (needs a cart_id, shipping_address_id, and items)
  const fakeCartId = typia.random<string & tags.Format<"uuid">>();
  const fakeShippingAddressId = typia.random<string & tags.Format<"uuid">>();
  const skuId = typia.random<string & tags.Format<"uuid">>();
