import type { IPageIai_ecommerceCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIai_ecommerceCart";

/**
 * Validates that a customer can only list their own shopping carts and never sees carts of other users' carts.
 * Also ensures the system properly handles cases of filter absence or invalid filter input, especially with regards to permissions.
 *
 * Steps:
 * 1. Create a user profile for the customer (dependency setup)
 * 2. Attempt to query list of carts (with no filters) as the customer
 *     - Ensure the result shows only carts belonging to the customer, and does not leak other users' carts
 * 3. Attempt to query with the customer's own customer_id as a filter
 *     - Ensure only own carts are shown
 * 4. Attempt to query using an invalid filter (e.g., someone else's customer_id)
 *     - Confirm that no data is returned (or an appropriate error/permission denial occurs)
 * 5. Attempt to use a structurally valid but semantically invalid filter (e.g., negative page number or limit), and confirm a runtime error is raised accordingly
 */
export async function test_api_ai_ecommerce_test_list_carts_for_customer_only_own_visible(
  connection: api.IConnection,
) {
  // 1. Create a user profile for the customer
  const customerProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(customerProfile);

  // 2. List carts with no filters (should return carts belonging to this customer only)
  const cartsNoFilter = await api.functional.ai_ecommerce.cart.patch(connection, {
    body: {
      pagination: { current: 1, limit: 20 },
    } satisfies Iai_ecommerceCart.IRequest,
  });
  typia.assert(cartsNoFilter);
  TestValidator.predicate("All carts are owned by the customer")(
    cartsNoFilter.data.every((cart) => cart.customer_id === customerProfile.id),
  );

  // 3. List carts using own customer_id
  const cartsOwn = await api.functional.ai_ecommerce.cart.patch(connection, {
    body: {
      customer_id: customerProfile.id,
      pagination: { current: 1, limit: 20 },
    } satisfies Iai_ecommerceCart.IRequest,
  });
  typia.assert(cartsOwn);
  TestValidator.predicate("All carts are owned by the customer (with filter)")(
    cartsOwn.data.every((cart) => cart.customer_id === customerProfile.id),
  );

  // 4. Attempt to list carts using a different/random customer_id
  const fakeCustId = typia.random<string & tags.Format<"uuid">>();
  const cartsOther = await api.functional.ai_ecommerce.cart.patch(connection, {
    body: {
      customer_id: fakeCustId,
      pagination: { current: 1, limit: 20 },
    } satisfies Iai_ecommerceCart.IRequest,
  });
  typia.assert(cartsOther);
  TestValidator.equals("No leakage of others' carts")(cartsOther.data.length)(0);

  // 5. Try structurally valid but semantically invalid pagination (e.g. negative page number)
  await TestValidator.error("Negative page number should cause error")(
    async () => {
      await api.functional.ai_ecommerce.cart.patch(connection, {
        body: { pagination: { current: -1, limit: 20 } } satisfies Iai_ecommerceCart.IRequest,
      });
    },
  );
}

