/**
 * E2E test cart update API: valid and invalid metadata mutation flows.
 *
 * This test validates that carts can be updated via allowed fields (cart_status, device_context),
 * and asserts correct behavior for business constraints. Negative flows for impossible scenarios
 * are omitted per API type strictness and available SDK.
 *
 * Test Steps:
 * 1. Create a user profile and cart (precondition).
 * 2. Valid update: change cart_status, verify updated_at changed and cart_status updated.
 * 3. Valid update: update device_context, verify updated.
 * 4. Invalid cart_status: attempt to set an obviously illegal/unknown status.
 * 5. Update non-existent cart (random UUID): must error.
 * 6. Auth/user-in-context negative flows omitted (cannot auth-switch).
 * 7. Item mutation via metadata update omitted (schema strictly enforces fields, not testable).
 */
export async function test_api_ai_ecommerce_cart_test_update_cart_metadata_valid_and_invalid_cases(
  connection: api.IConnection,
) {
  // 1. Create user and cart.
  const userProfile = await api.functional.ai_ecommerce.userProfiles.post(
    connection,
    {
      body: {
        nickname: RandomGenerator.name(),
        email: typia.random<string & tags.Format<"email">>(),
        communication_consent: true,
      } satisfies IAiEcommerceUserProfile.ICreate,
    },
  );
  typia.assert(userProfile);

  const cart = await api.functional.ai_ecommerce.cart.post(connection, {
    body: {
      customer_id: userProfile.id,
      cart_status: "active",
    } satisfies Iai_ecommerceCart.ICreate,
  });
  typia.assert(cart);

  const originalUpdatedAt = cart.updated_at;

  // 2. Valid update - change cart_status
  const updatedCart = await api.functional.ai_ecommerce.cart.putById(connection, {
    id: cart.id,
    body: { cart_status: "merged" } satisfies Iai_ecommerceCart.IUpdate,
  });
  typia.assert(updatedCart);
  TestValidator.notEquals("updated_at updates")(updatedCart.updated_at)(originalUpdatedAt);
  TestValidator.equals("cart_status changed")(updatedCart.cart_status)("merged");

  // 3. Valid update - update device_context
  const updatedCart2 = await api.functional.ai_ecommerce.cart.putById(connection, {
    id: cart.id,
    body: { device_context: "iPhone-14-Pro" } satisfies Iai_ecommerceCart.IUpdate,
  });
  typia.assert(updatedCart2);
  TestValidator.equals("device_context set")(updatedCart2.device_context)("iPhone-14-Pro");

  // 4. Invalid cart_status value
  await TestValidator.error("illegal cart_status fails")(() =>
    api.functional.ai_ecommerce.cart.putById(connection, {
      id: cart.id,
      body: { cart_status: "not_a_valid_status" } satisfies Iai_ecommerceCart.IUpdate,
    }),
  );

  // 5. Update non-existent cart (random uuid)
  await TestValidator.error("update on random cart id fails")(() =>
    api.functional.ai_ecommerce.cart.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { cart_status: "active" } satisfies Iai_ecommerceCart.IUpdate,
    }),
  );

  // 6. Negative flows not testable due to API constraints.
}

