import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserProfile";
import type { ai_ecommerce_user_oauth } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_user_oauth";
import type { IPageai_ecommerce_user_oauth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageai_ecommerce_user_oauth";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing OAuth account bindings for an authenticated user with filtering and pagination.
 *
 * This test validates all key behaviors of the PATCH /ai_ecommerce/userOauth endpoint with realistic flows and edge cases:
 *
 * 1. Create a user profile (as the account owner).
 * 2. Link two OAuth accounts ("google" and "apple") to this user.
 * 3. Query OAuth accounts for this authenticated user, applying filter and pagination parameters, and verify:
 *    - Output only includes this user's OAuth account links, never another's.
 *    - Filtering by provider and created_at date range works.
 *    - Pagination correctly slices the results (pages, limits, etc.).
 *    - Sensitive or extra fields are excluded from the response.
 * 4. Edge case: Query with a provider filter that is not linked (expect empty page).
 * 5. Edge case: Query with invalid filter (malformed date string; expect error).
 * 6. Edge case: Attempt to list another user's OAuth bindings using another profile_id (should be denied or return empty).
 */
export async function test_api_ai_ecommerce_userOauth_test_list_oauth_accounts_for_authenticated_user_with_filtering_and_pagination(connection: api.IConnection) {
  // 1. Create a user profile
  const email: string = typia.random<string & tags.Format<"email">>();
  const userProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      avatar_uri: null,
      email,
      phone_number: null,
      communication_consent: true,
    },
  });
  typia.assert(userProfile);
  const profileId = userProfile.id;

  // 2. Link two OAuth accounts (google, apple)
  const googleOauth = await api.functional.ai_ecommerce.userOauth.post(connection, {
    body: {
      profile_id: profileId,
      provider: "google",
      provider_user_id: RandomGenerator.alphaNumeric(10),
    },
  });
  typia.assert(googleOauth);

  // Add short delay for distinguishable created_at if needed
  await new Promise((r) => setTimeout(r, 100));

  const appleOauth = await api.functional.ai_ecommerce.userOauth.post(connection, {
    body: {
      profile_id: profileId,
      provider: "apple",
      provider_user_id: RandomGenerator.alphaNumeric(12),
    },
  });
  typia.assert(appleOauth);

  // 3. List OAuth accounts for authenticated user (no filter, expect both)
  let pageResp = await api.functional.ai_ecommerce.userOauth.patch(connection, {
    body: {
      profile_id: profileId,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(pageResp);
  // Should see at least googleOauth and appleOauth
  const userOauthIds = pageResp.data.map((o) => o.id);
  TestValidator.predicate("contains google and apple accounts")(
    userOauthIds.includes(googleOauth.id) && userOauthIds.includes(appleOauth.id)
  );
  // All entries should match this user
  TestValidator.predicate("all belong to user")(
    pageResp.data.every((o) => o.profile_id === profileId)
  );
  // Response should NOT contain sensitive info (only defined fields returned)
  pageResp.data.forEach((record) => {
    // Check only properties defined by schema
    for (const k of Object.keys(record)) {
      TestValidator.predicate(`property '${k}' valid`)(["id","profile_id","provider","provider_user_id","created_at"].includes(k));
    }
  });

  // 3b. Filter by provider ("google")
  pageResp = await api.functional.ai_ecommerce.userOauth.patch(connection, {
    body: {
      profile_id: profileId,
      provider: "google",
      page: 1,
      limit: 10,
    },
  });
  typia.assert(pageResp);
  TestValidator.predicate("all are google accounts")(
    pageResp.data.every((o) => o.provider === "google")
  );

  // 3c. Filter by date range for 'created_at' (should find one or both)
  {
    const from = googleOauth.created_at;
    const to = appleOauth.created_at;
    pageResp = await api.functional.ai_ecommerce.userOauth.patch(connection, {
      body: {
        profile_id: profileId,
        created_from: from,
        created_to: to,
        page: 1,
        limit: 10,
      },
    });
    typia.assert(pageResp);
    TestValidator.predicate("filter by date range")(
      pageResp.data.every((o) => o.created_at >= from && o.created_at <= to)
    );
  }

  // 3d. Pagination check (use limit=1 to get single entries)
  const paged1 = await api.functional.ai_ecommerce.userOauth.patch(connection, {
    body: {
      profile_id: profileId,
      page: 1,
      limit: 1,
    },
  });
  typia.assert(paged1);
  TestValidator.equals("page size 1")(paged1.data.length)(1);
  // If there are at least 2 entries, next page contains the other
  if (paged1.pagination.pages >= 2) {
    const paged2 = await api.functional.ai_ecommerce.userOauth.patch(connection, {
      body: {
        profile_id: profileId,
        page: 2,
        limit: 1,
      },
    });
    typia.assert(paged2);
    TestValidator.equals("page size 1 on page 2")(paged2.data.length)(1);
    TestValidator.notEquals("entries differ across pages")(paged1.data[0].id)(paged2.data[0].id);
  }

  // 4. Edge: Unlinked provider filter returns empty page
  pageResp = await api.functional.ai_ecommerce.userOauth.patch(connection, {
    body: {
      profile_id: profileId,
      provider: "kakao",
      page: 1,
      limit: 10,
    },
  });
  typia.assert(pageResp);
  TestValidator.equals("no kakao accounts")(pageResp.data.length)(0);

  // 5. Edge: Invalid filter (malformed date string for created_from)
  await TestValidator.error("malformed date throws")(
    async () => {
      await api.functional.ai_ecommerce.userOauth.patch(connection, {
        body: {
          profile_id: profileId,
          created_from: "not-a-date" as any,
          page: 1,
          limit: 10,
        },
      });
    }
  );

  // 6. Attempt to query another user's OAuth accounts (should not succeed)
  // Create a second user
  const secondProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      avatar_uri: null,
      email: typia.random<string & tags.Format<"email">>(),
      phone_number: null,
      communication_consent: true,
    },
  });
  typia.assert(secondProfile);

  // Query OAuth list for the second profile (should be empty or error)
  const secondPage = await api.functional.ai_ecommerce.userOauth.patch(connection, {
    body: {
      profile_id: secondProfile.id,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(secondPage);
  TestValidator.equals("second profile has no OAuth links")(secondPage.data.length)(0);
}

