/**
 * End-to-end test for updating user OAuth account linkages, covering success and error scenarios.
 *
 * This test ensures the following workflows:
 *   1. Creation of a user profile (profile1) and linking an OAuth provider.
 *   2. Update the OAuth linkage with new unique provider/provider_user_id values and validate the update.
 *   3. Attempt to update provider/provider_user_id to values that already exist for another (profile2), expect uniqueness error.
 *   4. Edge: Attempt update on a non-existent OAuth linkage id (expect not found error).
 *   5. Validation: Send a malformed payload (neither provider nor provider_user_id) and expect a validation error.
 *
 * Prerequisite setup: Uses the dependencies to create the user profile and initial OAuth linkage.
 *
 * This tests both positive and negative update cases, including uniqueness guard, not found, and input validation error.
 */
export async function test_api_ai_ecommerce_userOauth_test_update_oauth_account_link_with_and_without_conflicts(
  connection: api.IConnection,
) {
  // 1. Create user profile1
  const profile1 = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true
    } satisfies IAiEcommerceUserProfile.ICreate
  });
  typia.assert(profile1);

  // 2. Link a provider for profile1
  const oauth1 = await api.functional.ai_ecommerce.userOauth.post(connection, {
    body: {
      profile_id: profile1.id,
      provider: "google",
      provider_user_id: RandomGenerator.alphabets(12)
    } satisfies ai_ecommerce_user_oauth.ICreate
  });
  typia.assert(oauth1);

  // 3. Update the existing linkage with NEW unique provider_user_id
  const updated = await api.functional.ai_ecommerce.userOauth.putById(connection, {
    id: oauth1.id,
    body: {
      provider: "google",
      provider_user_id: RandomGenerator.alphabets(12)
    } satisfies ai_ecommerce_user_oauth.IUpdate
  });
  typia.assert(updated);
  TestValidator.equals("profile_id remains same")(updated.profile_id)(profile1.id);
  TestValidator.equals("provider updated")(updated.provider)("google");

  // 4. Setup: Create profile2 + its oauth (to test uniqueness guard)
  const profile2 = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true
    } satisfies IAiEcommerceUserProfile.ICreate
  });
  typia.assert(profile2);

  const oauth2_provider = "kakao";
  const oauth2_user = RandomGenerator.alphabets(12);
  const oauth2 = await api.functional.ai_ecommerce.userOauth.post(connection, {
    body: {
      profile_id: profile2.id,
      provider: oauth2_provider,
      provider_user_id: oauth2_user
    } satisfies ai_ecommerce_user_oauth.ICreate
  });
  typia.assert(oauth2);

  // 5. Attempt to update profile1's oauth to provider/provider_user_id of profile2 (=conflict)
  await TestValidator.error("conflicting uniqueness should fail")(async () => {
    await api.functional.ai_ecommerce.userOauth.putById(connection, {
      id: oauth1.id,
      body: {
        provider: oauth2_provider,
        provider_user_id: oauth2_user
      } satisfies ai_ecommerce_user_oauth.IUpdate
    });
  });

  // 6. Attempt update on a non-existent OAuth linkage id
  await TestValidator.error("nonexistent oauth id fails")(async () => {
    await api.functional.ai_ecommerce.userOauth.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        provider: "google",
        provider_user_id: RandomGenerator.alphabets(12)
      } satisfies ai_ecommerce_user_oauth.IUpdate
    });
  });

  // 7. Validation: Malformed payload (empty)
  await TestValidator.error("must fail when neither field present")(async () => {
    await api.functional.ai_ecommerce.userOauth.putById(connection, {
      id: oauth1.id,
      body: { } as ai_ecommerce_user_oauth.IUpdate
    });
  });
}

