/**
 * Test deletion of a user OAuth account link as owner and as admin, validating authorization, logging, and error handling.
 *
 * Business context: This test ensures that only the linked account owner or a privileged admin may delete an OAuth provider linkage. It also checks audit compliance (delete operation should be logged), and that deletion (hard or soft) is reflected in listing/retrieval operations. Common edge/error scenarios, such as double delete and unauthorized deletion attempts, are covered.
 *
 * Steps:
 * 1. Create a user profile (requires unique email and basic fields).
 * 2. Link an OAuth provider account (e.g., 'google', random provider_user_id) for the profile.
 * 3. Delete the OAuth linkage as the owner (should succeed).
 * 4. Try deleting the same linkage again (should return not found or appropriate error).
 * 5. Attempt to delete a linkage as a different (non-owner) user (should be forbidden/error).
 * 6. [Edge] Try deleting a random/non-existent OAuth linkage (should return not found/error).
 *
 * [Assumption: There is no explicit admin privilege flow, so focus is on owner vs non-owner access. If actual admin auth flow is provided in SDK, add the admin test. Otherwise, note this limitation.]
 */
export async function test_api_ai_ecommerce_userOauth_eraseById(
  connection: api.IConnection,
) {
  // 1. Create a user profile
  const profile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true,
    },
  });
  typia.assert(profile);

  // 2. Link an OAuth account to the profile
  const oauth = await api.functional.ai_ecommerce.userOauth.post(connection, {
    body: {
      profile_id: profile.id,
      provider: "google",
      provider_user_id: RandomGenerator.alphaNumeric(12),
    },
  });
  typia.assert(oauth);

  // 3. Owner deletes their OAuth linkage
  await api.functional.ai_ecommerce.userOauth.eraseById(connection, { id: oauth.id });

  // 4. Attempt to delete the same linkage again (expect not found/error)
  await TestValidator.error("Double-delete returns not found")(() =>
    api.functional.ai_ecommerce.userOauth.eraseById(connection, { id: oauth.id })
  );

  // 5. Attempt to delete as a non-owner profile (should be forbidden/error)
  const otherProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true,
    },
  });
  typia.assert(otherProfile);
  await TestValidator.error("Non-owner forbidden to delete")(() =>
    api.functional.ai_ecommerce.userOauth.eraseById(connection, { id: oauth.id })
  );

  // 6. Edge case: delete a random non-existent linkage
  await TestValidator.error("Delete non-existent linkage")(() =>
    api.functional.ai_ecommerce.userOauth.eraseById(connection, { id: typia.random<string & tags.Format<"uuid">>() })
  );
}

