  // 3. Successfully create an onboarding log (all required props as administrator)
  const onboardingInput: IAiEcommerceSellerOnboardingLog.ICreate = {
    seller_id: seller.id,
    business_profile_id: businessProfile.id,
    step: 'application_submitted',
    action: 'accepted',
    actor_type: 'administrator',
    decision_state: 'pending',
    reason_detail: 'Application received and accepted for initial onboarding.',
  };
  const onboardingLog = await api.functional.ai_ecommerce.sellerOnboardingLogs.post(connection, {
    body: onboardingInput,
  });
