  TestValidator.equals('log links to seller')(onboardingLog.seller_id)(seller.id);
  TestValidator.equals('log links to business profile')(onboardingLog.business_profile_id)(businessProfile.id);

  // 4. Attempt to create onboarding log with missing required field 'action'
  await TestValidator.error('missing required field: action')(() =>
