}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_sellers } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_sellers";
import type { IAiEcommerceSellerOnboardingLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceSellerOnboardingLog";

/**
 * E2E test for updating seller onboarding logs (PUT /ai_ecommerce/sellerOnboardingLogs/{id}).
 *
 * Validates the following scenarios:
 * 1. Successfully updates mutable fields (step, action, decision_state, reason_detail) of a log by an authorized actor (simulate admin by default, as role API is not provided).
 * 2. Fails to update a completed/immutable onboarding log (by advancing the state, then attempting further update).
 * 3. Rejects invalid enum values (e.g., bogus step/action/decision_state), confirming a 400/409 error.
 * 4. Fails to update a non-existent log (random UUID).
 * 5. Attempts from unauthorized actor (cannot test without auth API, so not implemented).
 * 6. Attempt to update immutable fields or relations (not possible, as these don't exist in update DTO).
 * 7. Verifies system does not alter immutable parts or illegal updates are rejected.
 *
 * Steps:
 *  1. Register a seller and create a valid onboarding log.
 *  2. Update that log's step, action, state, reason_detail with valid values; assert success.
 *  3. Mark the log as 'completed' (custom state) and attempt further mutation; assert failure.
 *  4. Try update with invalid enum value; assert failure.
 *  5. Attempt update to non-existent id; assert 404 failure.
 *  6. (No immutable relation updates possible as body DTO only allows explicit fields.)
 */
export async function test_api_selleronboardinglogs_test_update_seller_onboarding_log_for_permitted_and_restricted_cases(
  connection: api.IConnection,
) {
  // 1. Register a new seller (with unique profile_id)
  const profileId: string = typia.random<string & tags.Format<"uuid">>();
  const seller = await api.functional.ai_ecommerce.sellers.post(connection, {
    body: { profile_id: profileId },
  });
  typia.assert(seller);

  // 2. Create an onboarding log for the new seller
  const onboardingLog = await api.functional.ai_ecommerce.sellerOnboardingLogs.post(connection, {
    body: {
      seller_id: seller.id,
      business_profile_id: typia.random<string & tags.Format<"uuid">>(),
      administrator_id: null,
      step: "application_submitted",
      action: "accepted",
      actor_type: "administrator",
      decision_state: "pending",
      reason_detail: "Initial application submitted.",
    },
  });
  typia.assert(onboardingLog);
  const onboardingLogId = onboardingLog.id;

  // 3. Successful update of mutable fields
  const updatedFields = {
    step: "manual_review",
    action: "info_requested",
    decision_state: "escalated",
    reason_detail: "Please provide missing tax document.",
  } satisfies IAiEcommerceSellerOnboardingLog.IUpdate;
  const updatedLog = await api.functional.ai_ecommerce.sellerOnboardingLogs.putById(connection, {
    id: onboardingLogId,
    body: updatedFields,
  });
  typia.assert(updatedLog);
  TestValidator.equals("step updated")(updatedLog.step)(updatedFields.step);
  TestValidator.equals("action updated")(updatedLog.action)(updatedFields.action);
  TestValidator.equals("decision_state updated")(updatedLog.decision_state)(updatedFields.decision_state);
  TestValidator.equals("reason_detail updated")(updatedLog.reason_detail)(updatedFields.reason_detail);

  // 4. Mark as completed/final state, expect further update failure
  const finalUpdate = await api.functional.ai_ecommerce.sellerOnboardingLogs.putById(connection, {
    id: onboardingLogId,
    body: { decision_state: "approved", reason_detail: "Final approval." },
  });
  typia.assert(finalUpdate);

  // Attempts to update immutable/locked log should fail (simulate with another reason update)
  await TestValidator.error("cannot update a completed onboarding log")(
    async () =>
      api.functional.ai_ecommerce.sellerOnboardingLogs.putById(connection, {
        id: onboardingLogId,
        body: { reason_detail: "Attempt illegally after completion." },
      }),
  );

  // 5. Validation: Invalid enum value (simulate illegal step)
  await TestValidator.error("invalid step value not allowed")(
    async () =>
      api.functional.ai_ecommerce.sellerOnboardingLogs.putById(connection, {
        id: onboardingLogId,
        body: { step: "not_valid_enum_value" },
      }),
  );

  // 6. Non-existent onboarding log
  await TestValidator.error("cannot update non-existent onboarding log")(
    async () =>
      api.functional.ai_ecommerce.sellerOnboardingLogs.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: { reason_detail: "Update non-existent" },
      }),
  );

  // 7. (Not possible to test unauthorized actor or updating immutable relations, as no such API or DTO fields exist)
}

