  const sku2 = await api.functional.ai_ecommerce.skus.post(connection, {
    body: {
      product_id: product1.id,
      code: RandomGenerator.alphaNumeric(8),
      price: 6500,
      currency: "KRW",
      is_active: false,
    },
  });
  typia.assert(sku2);

  const sku3 = await api.functional.ai_ecommerce.skus.post(connection, {
    body: {
      product_id: product2.id,
      code: RandomGenerator.alphaNumeric(8),
      price: 20000,
      currency: "USD",
      is_active: true,
    },
  });
  typia.assert(sku3);

  // 3. Create inventories across locations and SKUs
  const inventoryA = await api.functional.ai_ecommerce.inventories.post(connection, {
    body: {
      sku_id: sku1.id,
      location: "WarehouseA",
      quantity_available: 15,
      quantity_reserved: 2,
    },
  });
  typia.assert(inventoryA);

  const inventoryB = await api.functional.ai_ecommerce.inventories.post(connection, {
    body: {
      sku_id: sku1.id,
      location: "WarehouseB",
      quantity_available: 8,
      quantity_reserved: 0,
    },
  });
  typia.assert(inventoryB);

  const inventoryC = await api.functional.ai_ecommerce.inventories.post(connection, {
    body: {
      sku_id: sku2.id,
      location: "WarehouseA",
      quantity_available: 2,
      quantity_reserved: 1,
    },
  });
  typia.assert(inventoryC);

  const inventoryD = await api.functional.ai_ecommerce.inventories.post(connection, {
    body: {
      sku_id: sku3.id,
      location: "WarehouseC",
      quantity_available: 50,
      quantity_reserved: 5,
    },
  });
  typia.assert(inventoryD);

  // 4a. Filter: by SKU
  const pageBySku = await api.functional.ai_ecommerce.inventories.patch(connection, {
    body: { sku_id: sku1.id },
  });
  typia.assert(pageBySku);
  TestValidator.predicate("all inventories belong to sku1")(pageBySku.data.every(i => i.sku_id === sku1.id));

  // 4b. Filter: by warehouse location
  const pageByLocation = await api.functional.ai_ecommerce.inventories.patch(connection, {
    body: { location: "WarehouseA" },
  });
  typia.assert(pageByLocation);
  TestValidator.predicate("all inventories at WarehouseA")(pageByLocation.data.every(i => i.location === "WarehouseA"));

  // 4c. Filter: by min qty
  const pageMinQty = await api.functional.ai_ecommerce.inventories.patch(connection, {
    body: { min_quantity_available: 10 },
  });
  typia.assert(pageMinQty);
  TestValidator.predicate("all qty_available >= 10")(pageMinQty.data.every(i => i.quantity_available >= 10));

  // 4d. Filter: by max qty
  const pageMaxQty = await api.functional.ai_ecommerce.inventories.patch(connection, {
    body: { max_quantity_available: 10 },
  });
  typia.assert(pageMaxQty);
  TestValidator.predicate("all qty_available <= 10")(pageMaxQty.data.every(i => i.quantity_available <= 10));

  // 4e. Pagination test (limit 2, multiple pages)
  const firstPage = await api.functional.ai_ecommerce.inventories.patch(connection, {
    body: { limit: 2, page: 1 },
  });
  typia.assert(firstPage);
  TestValidator.equals("pagination limit 2")(firstPage.data.length)(2);
  TestValidator.equals("pagination page")(firstPage.pagination.current)(1);

  if (firstPage.pagination.pages > 1) {
    const nextPage = await api.functional.ai_ecommerce.inventories.patch(connection, {
      body: { limit: 2, page: 2 },
    });
    typia.assert(nextPage);
    TestValidator.equals("pagination page 2")(nextPage.pagination.current)(2);
  }

  // 5a. Error case: invalid filter (string instead of number)
  await TestValidator.error("invalid min_quantity_available should error")(async () => {
    await api.functional.ai_ecommerce.inventories.patch(connection, {
      body: { min_quantity_available: "notANumber" as any },
    });
  });

  // 5b. Error case: simulate unauthorized (remove auth header)
  const { Authorization, ...restHeaders } = connection.headers ?? {};
  const connectionWithoutAuth: typeof connection = {
    ...connection,
    headers: restHeaders,
  };
  await TestValidator.error("unauthorized inventory search should error")(async () => {
    await api.functional.ai_ecommerce.inventories.patch(connectionWithoutAuth, {
      body: {},
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_product } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_product";
import type { ai_ecommerce_skus } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_skus";
import type { ai_ecommerce_inventories } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_inventories";

/**
 * Validate retrieval of a single inventory record by its ID.
 *
 * This test ensures that after creating a product, a SKU for that product, and finally an inventory record referencing the SKU, the inventory can be correctly fetched using its ID. All major fields and relationships (including SKU, location, quantities) are verified for correctness. The test also covers error handling: requesting with a random, non-existent inventory ID must result in an error response.
 *
 * Steps:
 * 1. Create a product for association (required by SKU and inventory create flows)
 * 2. Create a SKU referencing the product
 * 3. Create an inventory record for the SKU
 * 4. Retrieve the inventory record by its id and verify all relevant fields
 * 5. Attempt to retrieve an inventory by a random (non-existent) ID and assert that an error is properly thrown
 */
export async function test_api_ai_ecommerce_inventories_test_get_inventory_by_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. Create a product for association
  const product = await api.functional.ai_ecommerce.products.post(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(2),
      description: RandomGenerator.content()()(),
      status: "draft",
      approval_state: "pending",
    } satisfies ai_ecommerce_product.ICreate,
  });
  typia.assert(product);

  // 2. Create SKU for the product
  const sku = await api.functional.ai_ecommerce.skus.post(connection, {
    body: {
      product_id: product.id,
      code: RandomGenerator.alphaNumeric(8),
      price: 10000,
      currency: "KRW",
      is_active: true,
    } satisfies ai_ecommerce_skus.ICreate,
  });
  typia.assert(sku);

  // 3. Create inventory record referencing the SKU
  const initialQuantity = 42;
  const initialReserved = 4;
  const inventory = await api.functional.ai_ecommerce.inventories.post(connection, {
    body: {
      sku_id: sku.id,
      location: RandomGenerator.alphaNumeric(6),
      quantity_available: initialQuantity,
      quantity_reserved: initialReserved,
    } satisfies ai_ecommerce_inventories.ICreate,
  });
  typia.assert(inventory);

  // 4. Retrieve by inventory id and verify
  const fetched = await api.functional.ai_ecommerce.inventories.getById(connection, {
    id: inventory.id,
  });
  typia.assert(fetched);

  TestValidator.equals("fetched id matches")(fetched.id)(inventory.id);
  TestValidator.equals("sku_id matches")(fetched.sku_id)(sku.id);
  TestValidator.equals("location matches")(fetched.location)(inventory.location);
  TestValidator.equals("quantity_available matches")(fetched.quantity_available)(initialQuantity);
  TestValidator.equals("quantity_reserved matches")(fetched.quantity_reserved)(initialReserved);

  // 5. Attempt to fetch with random (non-existent) UUID for error check
  await TestValidator.error("not found for random id")(() =>
    api.functional.ai_ecommerce.inventories.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_product } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_product";
import type { ai_ecommerce_skus } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_skus";
import type { ai_ecommerce_inventories } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_inventories";

/**
 * E2E test for inventory creation with valid and invalid input scenarios.
 *
 * This test exercises all business validation and constraint logic for the inventory creation API:
 *
 * 1. Creates a new Product and an associated SKU
 * 2. Successfully creates an inventory record for that SKU/location with all required fields
 * 3. Confirms the response has correct data
 * 4. Attempts creation with missing required fields and expects failures
 * 5. Attempts creation with an invalid/non-existent sku_id and expects error
 * 6. Attempts to create a duplicate inventory on (sku_id, location) and expects error
 * 7. Attempts creation with invalid (negative / too-large) quantity values to verify validation
 *
 * All API calls and object structures strictly follow the DTO/type definition and only test implementable business flows.
 */
export async function test_api_ai_ecommerce_inventories_test_create_inventory_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create product for SKU association
  const product = await api.functional.ai_ecommerce.products.post(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()(2)(1),
      status: "published",
      approval_state: "approved",
    } satisfies ai_ecommerce_product.ICreate,
  });
  typia.assert(product);

  // 2. Create a valid SKU for the product
  const skuCode = RandomGenerator.alphaNumeric(8);
  const sku = await api.functional.ai_ecommerce.skus.post(connection, {
    body: {
      product_id: product.id,
      code: skuCode,
      price: 19900,
      currency: "KRW",
      is_active: true,
    } satisfies ai_ecommerce_skus.ICreate,
  });
  typia.assert(sku);

  // 3. Create a valid inventory record (all required fields present, valid values)
  const inventoryLocation = "W01-RACKA";
  const inventory = await api.functional.ai_ecommerce.inventories.post(connection, {
    body: {
      sku_id: sku.id,
      location: inventoryLocation,
      quantity_available: 23,
      quantity_reserved: 3,
    } satisfies ai_ecommerce_inventories.ICreate,
  });
  typia.assert(inventory);
  TestValidator.equals("sku_id matches")(inventory.sku_id)(sku.id);
  TestValidator.equals("location matches")(inventory.location)(inventoryLocation);
  TestValidator.equals("available matches")(inventory.quantity_available)(23);
  TestValidator.equals("reserved matches")(inventory.quantity_reserved)(3);

  // 4. Attempt inventory creation with missing required fields (should fail)
  await TestValidator.error("missing sku_id")(() =>
    api.functional.ai_ecommerce.inventories.post(connection, {
      body: {
        // sku_id missing
        location: "W02-RACKB",
        quantity_available: 1,
        quantity_reserved: 0,
      } as any,
    }),
  );
  await TestValidator.error("missing location")(() =>
    api.functional.ai_ecommerce.inventories.post(connection, {
      body: {
        sku_id: sku.id,
        // location missing
        quantity_available: 1,
        quantity_reserved: 0,
      } as any,
    }),
  );
  await TestValidator.error("missing quantity_available")(() =>
    api.functional.ai_ecommerce.inventories.post(connection, {
      body: {
        sku_id: sku.id,
        location: "W02-RACKB",
        // quantity_available missing
        quantity_reserved: 0,
      } as any,
    }),
  );

  // 5. Invalid sku_id (syntactically valid UUID but not existent)
  await TestValidator.error("invalid/nonexistent sku_id")(() =>
    api.functional.ai_ecommerce.inventories.post(connection, {
      body: {
        sku_id: typia.random<string & tags.Format<"uuid">>(),
        location: "W03-UNKNOWN",
        quantity_available: 10,
        quantity_reserved: 0,
      },
    }),
  );

  // 6. Duplicate (sku_id, location) - try to create another inventory row with identical keys
  await TestValidator.error("duplicate sku_id, location")(() =>
    api.functional.ai_ecommerce.inventories.post(connection, {
      body: {
        sku_id: sku.id,
        location: inventoryLocation, // duplicate
        quantity_available: 15,
        quantity_reserved: 1,
      },
    }),
  );

  // 7. Invalid quantity values (negative and out-of-range for int32)
  await TestValidator.error("negative quantity_available")(() =>
    api.functional.ai_ecommerce.inventories.post(connection, {
      body: {
        sku_id: sku.id,
        location: "W02-BADNEG",
        quantity_available: -5,
        quantity_reserved: 1,
      } as any,
    }),
  );
  await TestValidator.error("negative quantity_reserved")(() =>
    api.functional.ai_ecommerce.inventories.post(connection, {
      body: {
        sku_id: sku.id,
        location: "W02-BADNEG",
        quantity_available: 2,
        quantity_reserved: -20,
      } as any,
    }),
  );
  await TestValidator.error("too large quantity_available (overflow int32)")(() =>
    api.functional.ai_ecommerce.inventories.post(connection, {
      body: {
        sku_id: sku.id,
        location: "W02-LARGE",
        quantity_available: 2147483648, // int32 max: 2147483647
        quantity_reserved: 0,
      } as any,
    }),
  );
  await TestValidator.error("too large quantity_reserved (overflow int32)")(() =>
    api.functional.ai_ecommerce.inventories.post(connection, {
      body: {
        sku_id: sku.id,
        location: "W02-LARGE",
        quantity_available: 5,
        quantity_reserved: 2147483648, // overflow
      } as any,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_product } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_product";
import type { ai_ecommerce_skus } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_skus";
import type { ai_ecommerce_inventories } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_inventories";

/**
 * 테스트: 재고 기록의 유효하고 유효하지 않은 업데이트 시나리오 검증
 *
 * 이 테스트에서는 다음 단계로 진행합니다.
 * 1. 새로운 상품(product) 등록
 * 2. 해당 상품에 SKU 등록
 * 3. SKU에 연결된 초기 재고(inventory) 기록 생성
 * 4. 생성된 재고 기록의 quantity_available과 location을 유효한 값으로 수정하고 변경사항 적용 검증
 * 5. 존재하지 않는 ID로 재고를 수정 시도 (존재하지 않는 id)
 * 6. quantity_available을 음수로 수정 시도 (비즈니스 규칙 위반)
 * 7. 이미 존재하는 (sku_id, location)으로 수정하여 unique 제약 위반 시도
 * 8. 불변(immutable) 필드(id 등) 업데이트가 실제로는 반영되지 않는지 간접적으로 검증
 *
 * 각 단계에서 API 응답이 스키마, 비즈니스 규칙, 유효성 검사에 맞는지 typia.assert 및 TestValidator의 error 검증을 통해 확인합니다.
 */
export async function test_api_inventories_test_update_inventory_with_valid_and_invalid_changes(
  connection: api.IConnection,
) {
  // 1. 신규 상품 생성
  const product = await api.functional.ai_ecommerce.products.post(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(2),
      description: RandomGenerator.content()()(2),
      status: "published",
      approval_state: "approved",
    },
  });
  typia.assert(product);

  // 2. SKU 생성
  const sku = await api.functional.ai_ecommerce.skus.post(connection, {
    body: {
      product_id: product.id,
      code: RandomGenerator.alphabets(8),
      price: 12000,
      currency: "KRW",
      is_active: true,
    },
  });
  typia.assert(sku);

  // 3. 초기 재고(inventory) 기록 생성
  const initialLocation = RandomGenerator.alphabets(8);
  const inventory = await api.functional.ai_ecommerce.inventories.post(connection, {
    body: {
      sku_id: sku.id,
      location: initialLocation,
      quantity_available: 100,
      quantity_reserved: 0,
    },
  });
  typia.assert(inventory);

  // 4. 유효한 값으로 quantity_available, location 업데이트 & 적용여부 검증
  const newLocation = RandomGenerator.alphabets(10);
  const newQuantity = 77;
  const updated = await api.functional.ai_ecommerce.inventories.putById(connection, {
    id: inventory.id,
    body: {
      quantity_available: newQuantity,
      location: newLocation,
    },
  });
  typia.assert(updated);
  TestValidator.equals("quantity_available updated")(updated.quantity_available)(newQuantity);
  TestValidator.equals("location updated")(updated.location)(newLocation);
  TestValidator.equals("sku_id remains unchanged")(updated.sku_id)(sku.id);
  TestValidator.equals("immutable id not changed")(updated.id)(inventory.id);
  TestValidator.notEquals("updated_at changes after update")(updated.updated_at)(inventory.updated_at);

  // 5. 존재하지 않는 id로 update 시도 (에러 발생 기대)
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("존재하지 않는 id로 update 시 에러 발생")(() =>
    api.functional.ai_ecommerce.inventories.putById(connection, {
      id: nonExistentId,
      body: {
        quantity_available: 50,
      },
    }),
  );

  // 6. 음수 quantity_available로 update 시도 (비즈니스 룰 위반 → 에러)
  TestValidator.error("quantity_available 음수 업데이트 시 에러")(() =>
    api.functional.ai_ecommerce.inventories.putById(connection, {
      id: inventory.id,
      body: {
        quantity_available: -10 as number & tags.Type<"int32">,
      },
    }),
  );

  // 7. (sku_id, location) unique 제약 위반
  const duplicateLocation = RandomGenerator.alphabets(12);
  // 새로운 재고 row 생성 (같은 sku, 다른 location)
  const anotherInventory = await api.functional.ai_ecommerce.inventories.post(connection, {
    body: {
      sku_id: sku.id,
      location: duplicateLocation,
      quantity_available: 5,
    },
  });
  typia.assert(anotherInventory);
  // 기존 재고의 location을 중복 값으로 업데이트 시 unique 제약 위배 오류 기대
  TestValidator.error("동일 sku/location unique 제약 업데이트 에러")(() =>
    api.functional.ai_ecommerce.inventories.putById(connection, {
      id: inventory.id,
      body: {
        location: duplicateLocation,
      },
    }),
  );

  // 8. 불변 필드(id 등)를 update body로 넘길 수 있는 구조 자체가 아니며,
  // PUT IUpdate에는 id/ski_id 등은 포함 불가. 실제로 불변성 간접적으로 검증.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_product } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_product";
import type { ai_ecommerce_skus } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_skus";
import type { ai_ecommerce_inventories } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_inventories";
import type { IAiEcommerceOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrder";
import type { IAiEcommerceOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrderItem";

/**
 * 다양한 조건에서 인벤토리(재고) 삭제 API를 검증하는 통합 테스트입니다.
 *
 * - 상품(Product), SKU, 인벤토리 엔티티를 순차적으로 생성한 뒤,
 *   만들어진 인벤토리 레코드를 삭제(eraseById)합니다.
 * - 이미 삭제된 인벤토리 레코드를 다시 삭제할 때의 idempotency/에러 처리를 검증합니다.
 * - 데이터베이스에 존재하지 않는 랜덤 인벤토리 ID로 삭제 시, NotFound 혹은 제약 위반 에러 발생을 검증합니다.
 * - SKU가 주문에 연결되어 있는 상태(새로 생성한 인벤토리가 신규 주문의 아이템으로 포함)의 경우, 해당 인벤토리 삭제 시 참조 무결성 또는 비즈니스 제약 위반 에러가 반환되는지 확인합니다.
 *
 * 각 단계에서 실제 DTO schema, 타입, 업무 규칙에 부합하는 랜덤 데이터를 사용하며,
 * 관계 참조와 API 사이드 이펙트(삭제 후 상태, 에러 발생 여부 등)를 검증합니다.
 */
export async function test_api_ai_ecommerce_inventories_test_delete_inventory_with_various_conditions(
  connection: api.IConnection,
) {
  // 1. 상품(Product) 생성
  const product = await api.functional.ai_ecommerce.products.post(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()(1)(),
      status: "published",
      approval_state: "approved",
    } satisfies ai_ecommerce_product.ICreate,
  });
  typia.assert(product);

  // 2. SKU 생성(Product에 종속)
  const sku = await api.functional.ai_ecommerce.skus.post(connection, {
    body: {
      product_id: product.id,
      code: RandomGenerator.alphaNumeric(8),
      price: 10000,
      currency: "KRW",
      is_active: true,
    } satisfies ai_ecommerce_skus.ICreate,
  });
  typia.assert(sku);

  // 3. 인벤토리 생성(SKU에 종속)
  const inventory = await api.functional.ai_ecommerce.inventories.post(connection, {
    body: {
      sku_id: sku.id,
      location: RandomGenerator.alphabets(5),
      quantity_available: 10,
      quantity_reserved: 0,
    } satisfies ai_ecommerce_inventories.ICreate,
  });
  typia.assert(inventory);

