 *
 * 이 테스트는 플랫폼 관리자(admin)가 올바른 데이터로 audit log를 생성할 수 있음을 검증하는 한편,
 * 다음과 같은 에러 상황도 함께 점검합니다:
 *
 * 1. 성공 케이스: 유효한 관리자 UUID, action_type, target_table, 타깃 UUID, 설명, 생성시각 등 올바른 입력으로 정상 생성
 * 2. 실패 케이스(각각 TestValidator.error로 점검)
 *    - 존재하지 않는 혹은 비허용 target_id 및 target_table 지정
 *    - 관리자가 아닌 customer/seller로 생성 시도 (권한 에러)
 *    - 동일 행위/타깃/관리자 조합 중복 레코드 작성 시도(허용하지 않을 때만)
 *
 * 각 error branch마다 API가 schema 정의 및 비즈니스 규칙에 따라 적절한 (400/403/409 등) 오류를 반환하는지 검증합니다.
 */
export async function test_api_ai_ecommerce_test_create_audit_log_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. 정상 관리자 로그 생성 케이스
  const admin_id = typia.random<string & tags.Format<"uuid">>();
  const target_id = typia.random<string & tags.Format<"uuid">>();
  const base: IAuditLog.ICreate = {
    actor_customer_id: null,
    actor_seller_id: null,
    actor_admin_id: admin_id,
    action_type: "UPDATE_USER_PRIVILEGE",
    target_table: "ai_ecommerce_admin",
    target_id: target_id,
    description: "관리자 권한 변경",
