  typia.assert(output);
  TestValidator.equals("admin_id match")(output.actor_admin_id)(admin_id);
  TestValidator.equals("target_id match")(output.target_id)(target_id);

  // 2. 존재하지 않는 target_id (비즈니스 로직 에러)
  await TestValidator.error("nonexistent target_id should fail")(
    async () => {
      await api.functional.ai_ecommerce.auditLog.post(connection, {
        body: {
          ...base,
          target_id: typia.random<string & tags.Format<"uuid">>(),
        },
      });
    }
  );

  // 3. 관리자가 아닌 고객, 셀러 ID 지정 (권한 부족)
  await TestValidator.error("as customer actor (not admin) should fail")(
    async () => {
      await api.functional.ai_ecommerce.auditLog.post(connection, {
        body: {
          ...base,
          actor_admin_id: null,
          actor_customer_id: typia.random<string & tags.Format<"uuid">>(),
        },
      });
    }
  );
  await TestValidator.error("as seller actor (not admin) should fail")(
    async () => {
      await api.functional.ai_ecommerce.auditLog.post(connection, {
        body: {
          ...base,
          actor_admin_id: null,
          actor_seller_id: typia.random<string & tags.Format<"uuid">>(),
        },
      });
    }
  );

  // 4. 중복 생성 방지 정책이 적용된다면(동일 행위/타깃/관리자 조합으로 재작성 불가 시)
  await TestValidator.error("duplicate audit log should fail if not allowed")(
    async () => {
      await api.functional.ai_ecommerce.auditLog.post(connection, { body: base });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuditLog";

/**
 * 감사 로그 레코드의 전체 대체(Full PUT) 업데이트 기능을 관리자 권한으로 검증합니다.
 *
 * 시나리오:
 * 1. 감사 로그를 생성(POST)한 후, 관리자 권한으로 허용된 필드(description)를 PUT으로 성공적으로 수정합니다.
 *    - 수정 후, immutable 필드들이 변하지 않았는지 확인합니다.
 * 2. 불변 필드(action_type 등)를 PUT으로 수정하려 시도하면 API(DTO) 수준에서 거부되거나(컴파일 타임 오류), 허용되지 않음으로 오류가 발생함을 확인합니다.
 *    - (TypeScript DTO에 없는 필드는 코드 상 전달 불가하므로 실행 에러만 검증)
 * 3. 존재하지 않는 감사 로그 ID로 업데이트를 요청할 시 404 오류가 발생하는지 확인합니다.
 * 4. (테스트 환경에서 일반 사용자/권한 없는 사용자의 접근 거부 시나리오는 별도 API 현실이 없으므로 생략 또는 주석 처리)
 * 5. 감사 로그 변경 이력 확인은 API에 별도 감사 trail 조회 기능이 없으므로 생략합니다.
 */
export async function test_api_ai_ecommerce_auditLog_test_update_audit_log_with_valid_and_forbidden_fields(
  connection: api.IConnection,
) {
  // 1. 감사 로그 신규 생성
  const originalCreate: IAuditLog.ICreate = {
    actor_admin_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: "system_update",
    target_table: "ai_ecommerce_order",
    target_id: typia.random<string & tags.Format<"uuid">>(),
    description: `original description for update test`,
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const created = await api.functional.ai_ecommerce.auditLog.post(connection, { body: originalCreate });
  typia.assert(created);

  // 2. 관리자(PUT)로 description만 성공적으로 수정
  const updatedDescription = `updated (by admin) at ${new Date().toISOString()}`;
  const updated = await api.functional.ai_ecommerce.auditLog.putById(connection, {
    id: created.id,
    body: { description: updatedDescription },
  });
  typia.assert(updated);

  TestValidator.equals("description 수정됨")(updated.description)(updatedDescription);
  // 불변 필드 불변 확인
  TestValidator.equals("actor_admin_id 불변")(updated.actor_admin_id)(created.actor_admin_id);
  TestValidator.equals("action_type 불변")(updated.action_type)(created.action_type);
  TestValidator.equals("target_table 불변")(updated.target_table)(created.target_table);
  TestValidator.equals("target_id 불변")(updated.target_id)(created.target_id);
  TestValidator.equals("created_at 불변")(updated.created_at)(created.created_at);

  // 3. 불변 필드(예: action_type) 수정 시도 -> 실행 오류 발생해야 함
  // 실제로는 DTO 구조상 컴파일 타임에 차단되어 코드로 구현 불가. 여기에선 description만 전달 가능
  // 테스트 프레임워크/런타임 관점에서는 불변 필드 변경 불가함이 이미 입증됨

  // 4. 존재하지 않는 ID로 업데이트 시도 -> 404 에러 발생해야 함
  await TestValidator.error("존재하지 않는 로그 ID로 업데이트 시 404")(async () => {
    await api.functional.ai_ecommerce.auditLog.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { description: "trying to update non-existent log" },
    });
  });

  // 5. (비관리자 접근 권한 거부 시나리오는 API나 테스트 환경에서 계정/역할 변경 API가 없다면 생략)
  // 6. 감사 로그 변경 기록 검증은 별도 API 미지원으로 생략
}

