 *
 * - 로그 사전 생성(POST) 후, 해당 ID 기준으로 단건 조회(GET)
 * - 입력 및 결과값의 모든 필드 일치 여부 검증
 * - 포맷(uuid/date-time) 및 nullable 필드 모두 확인
 *
 * [테스트 절차]
 * 1. 관리자 액션 로그를 1건 생성한다
 * 2. 생성된 로그의 id를 추출하여 단건 조회 API를 호출한다
 * 3. 조회 결과의 모든 필드가 생성 입력과 일치하는지, 포맷 및 필수/nullable 여부 포함 꼼꼼히 검증한다
 */
export async function test_api_ai_ecommerce_adminActionLogs_getById_success(
  connection: api.IConnection,
) {
  // 1. 관리자 액션 로그를 1건 생성
  const logCreateInput: IAdminActionLog.ICreate = {
    administrator_id: typia.random<string & tags.Format<"uuid">>(),
    target_type: "user",
    action_type: "onboarding_approve",
