    // nullable 필드는 랜덤 UUID 또는 null로 채움
    role_id: typia.random<string & tags.Format<"uuid">>(),
    seller_id: null,
    target_id: null,
  };
  const createdLog: IAdminActionLog = await api.functional.ai_ecommerce.adminActionLogs.post(
    connection,
    {
      body: logCreateInput,
    },
  );
  typia.assert(createdLog);

  // 2. 생성된 로그의 id 추출 및 단건 조회
  const fetched: IAdminActionLog = await api.functional.ai_ecommerce.adminActionLogs.getById(
    connection,
