  TestValidator.equals("target_type")(fetched.target_type)(logCreateInput.target_type);
  TestValidator.equals("target_id")(fetched.target_id)(logCreateInput.target_id);
  TestValidator.equals("action_type")(fetched.action_type)(logCreateInput.action_type);
  TestValidator.equals("action_detail")(fetched.action_detail)(logCreateInput.action_detail);

  // 4. created_at 포맷(rfc3339) 유효성
  TestValidator.predicate("created_at is valid date-time")(
    typeof fetched.created_at === "string" &&
      !isNaN(Date.parse(fetched.created_at)),
  );
