import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_sellers } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_sellers";
import type { IAiEcommerceSellerBusinessProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceSellerBusinessProfile";
import type { Pageable } from "@ORGANIZATION/PROJECT-api/lib/structures/Pageable";
import type { IAiEcommerceSellerVerificationDocument } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceSellerVerificationDocument";

/**
 * Validate paginated and filtered retrieval of seller verification documents.
 *
 * Ensures that an admin/seller can retrieve a paginated, filtered list:
 *
 * 1. Create a seller entity
 * 2. Create a business profile for the seller
 * 3. Register multiple seller verification documents with varying document_type,
 *    issue_date, verified_at, and one soft-deleted.
 * 4. Query for the list by business_profile_id to check all valid docs included (excluding soft-deleted)
 * 5. Query using document_type to verify correct filtering
 * 6. Query using verified_at_from/verified_at_to for date filter check
 * 7. Query with pagination (limit/page), verifying slicing and order
 * 8. Edge: Query with filter that should yield an empty result
 */
export async function test_api_ai_ecommerce_test_list_seller_verification_documents_with_valid_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a seller entity
  const sellerProfileId = typia.random<string & tags.Format<"uuid">>();
  const seller = await api.functional.ai_ecommerce.sellers.post(connection, {
    body: {
      profile_id: sellerProfileId,
    } satisfies ai_ecommerce_sellers.IRegister,
  });
  typia.assert(seller);

  // 2. Create a business profile for the seller
  const businessProfile = await api.functional.ai_ecommerce.sellerBusinessProfiles.post(
    connection,
    {
      body: {
        seller_id: seller.id,
        business_name: RandomGenerator.alphabets(12),
        business_registration_number: RandomGenerator.alphaNumeric(10),
        tax_id: RandomGenerator.alphaNumeric(9),
        contact_name: RandomGenerator.name(),
        contact_phone: RandomGenerator.mobile(),
        contact_email: `${RandomGenerator.alphabets(8)}@company.com`,
        address_line1: RandomGenerator.paragraph()(8),
        address_line2: null,
        city: "Seoul",
        state: "Seoul",
        postal_code: "06236",
        country: "South Korea",
      } satisfies IAiEcommerceSellerBusinessProfile.ICreate,
    },
  );
  typia.assert(businessProfile);

  // 3. Register multiple verification documents with different doc types, dates, and soft-deletion
  const now = new Date();
  const docsInput = [
    {
      document_type: "business_registration",
      verified_at: new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString(),
      issue_date: new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000).toISOString(),
      expiry_date: new Date(now.getTime() + 365 * 24 * 60 * 60 * 1000).toISOString(),
      deleted_at: null,
    },
    {
      document_type: "tax_certificate",
      verified_at: new Date(now.getTime() - 1 * 24 * 60 * 60 * 1000).toISOString(),
      issue_date: new Date(now.getTime() - 200 * 24 * 60 * 60 * 1000).toISOString(),
      expiry_date: null,
      deleted_at: null,
    },
    {
      document_type: "compliance_statement",
      verified_at: null,
      issue_date: new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000).toISOString(),
      expiry_date: null,
      deleted_at: null,
    },
    {
      document_type: "deprecated_doc",
      verified_at: null,
      issue_date: new Date(now.getTime() - 365 * 24 * 60 * 60 * 1000).toISOString(),
      expiry_date: null,
      deleted_at: new Date(now.getTime() - 1 * 60 * 60 * 1000).toISOString(), // Simulate soft-deletion
    },
  ];

  // Actually create the documents (excluding deleted_at, which is system set)
  const createdDocs = [] as IAiEcommerceSellerVerificationDocument[];
  for (const doc of docsInput) {
    const created = await api.functional.ai_ecommerce.sellerVerificationDocuments.post(connection, {
      body: {
        seller_id: seller.id,
        business_profile_id: businessProfile.id,
        document_type: doc.document_type,
        document_file_url: `https://files.example.com/${RandomGenerator.alphaNumeric(16)}.pdf`,
        issue_date: doc.issue_date,
        expiry_date: doc.expiry_date,
      } satisfies IAiEcommerceSellerVerificationDocument.ICreate,
    });
    typia.assert(created);
    createdDocs.push(created);
  }

  // Simulate soft-delete for the deprecated_doc: we cannot set deleted_at directly; so skip its returned row in expected later

  // 4. List all docs for the business profile (should NOT include soft-deleted)
  const allDocsResult = await api.functional.ai_ecommerce.sellerVerificationDocuments.patch(connection, {
    body: {
      business_profile_id: businessProfile.id,
    } satisfies Pageable.IAiEcommerceSellerVerificationDocuments.IRequest,
  });
  typia.assert(allDocsResult);
  // Check all non-deleted documents included
  TestValidator.equals("document count excluding soft-deleted")(allDocsResult.data.length)(3);
  for (const doc of createdDocs.slice(0, 3)) {
    TestValidator.predicate(`find doc by id ${doc.id}`)(
      allDocsResult.data.some((row) => row.id === doc.id),
    );
    TestValidator.equals(`correct business_profile_id for ${doc.id}`)(doc.business_profile_id)(businessProfile.id);
  }
  // Check that soft-deleted doc is not returned
  TestValidator.predicate("soft-deleted doc excluded")(
    !allDocsResult.data.some((row) => row.document_type === "deprecated_doc"),
  );

  // 5. Query using document_type filter
  const typeResult = await api.functional.ai_ecommerce.sellerVerificationDocuments.patch(connection, {
    body: {
      business_profile_id: businessProfile.id,
      document_type: "tax_certificate",
    } satisfies Pageable.IAiEcommerceSellerVerificationDocuments.IRequest,
  });
  typia.assert(typeResult);
  TestValidator.equals("tax_certificate document count")(typeResult.data.length)(1);
  TestValidator.equals("tax_certificate type matches")(typeResult.data[0].document_type)("tax_certificate");

  // 6. Query using verified_at_from / verified_at_to (e.g., only very recent verified)
  const verifiedFrom = new Date(now.getTime() - 2 * 24 * 60 * 60 * 1000).toISOString();
  const verifiedTo = now.toISOString();
  const dateResult = await api.functional.ai_ecommerce.sellerVerificationDocuments.patch(connection, {
    body: {
      business_profile_id: businessProfile.id,
      verified_at_from: verifiedFrom,
      verified_at_to: verifiedTo,
    } satisfies Pageable.IAiEcommerceSellerVerificationDocuments.IRequest,
  });
  typia.assert(dateResult);
  // Only the tax_certificate falls within 2 days range
  TestValidator.equals("recently verified_at document count")(dateResult.data.length)(1);
  TestValidator.equals("recent verified_at doc type")(dateResult.data[0].document_type)("tax_certificate");

  // 7. Query with pagination (2 per page, check page 1 & 2)
  const pagedFirst = await api.functional.ai_ecommerce.sellerVerificationDocuments.patch(connection, {
    body: {
      business_profile_id: businessProfile.id,
      page: 1,
      limit: 2,
    } satisfies Pageable.IAiEcommerceSellerVerificationDocuments.IRequest,
  });
  typia.assert(pagedFirst);
  TestValidator.equals("pagination page 1 size")(pagedFirst.data.length)(2);
  TestValidator.equals("pagination total count")(pagedFirst.total)(3);
  const pagedSecond = await api.functional.ai_ecommerce.sellerVerificationDocuments.patch(connection, {
    body: {
      business_profile_id: businessProfile.id,
      page: 2,
      limit: 2,
    } satisfies Pageable.IAiEcommerceSellerVerificationDocuments.IRequest,
  });
  typia.assert(pagedSecond);
  TestValidator.equals("pagination page 2 size")(pagedSecond.data.length)(1);

  // 8. Edge: Impossible filter (wrong doc type)
  const emptyResult = await api.functional.ai_ecommerce.sellerVerificationDocuments.patch(connection, {
    body: {
      business_profile_id: businessProfile.id,
      document_type: "totally_invalid_doc_type_for_testing",
    } satisfies Pageable.IAiEcommerceSellerVerificationDocuments.IRequest,
  });
  typia.assert(emptyResult);
  TestValidator.equals("empty doc result count")(emptyResult.data.length)(0);
}

