 *
 * Steps:
 * 1. Create a seller
 * 2. Create a business profile for the seller
 * 3. Create a seller verification document
 * 4. Update mutable fields: document_type, expiry_date, verified_at
 * 5. Assert these fields are updated as expected
 * 6. Attempt to update an immutable field (document_file_url) after verification and confirm it does not change
 */
export async function test_api_ai_ecommerce_sellerVerificationDocuments_test_update_seller_verification_document_success(
  connection: api.IConnection,
) {
  // 1. Create a seller
  const seller = await api.functional.ai_ecommerce.sellers.post(connection, {
    body: {
      profile_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(seller);

  // 2. Create a business profile for the seller
  const businessProfile = await api.functional.ai_ecommerce.sellerBusinessProfiles.post(
    connection,
    {
      body: {
        seller_id: seller.id,
        business_name: RandomGenerator.alphabets(10),
        business_registration_number: RandomGenerator.alphaNumeric(12),
        contact_name: RandomGenerator.name(),
        contact_phone: RandomGenerator.mobile(),
        contact_email: `${RandomGenerator.alphabets(6)}@company.com`,
        address_line1: RandomGenerator.alphabets(10),
        city: RandomGenerator.alphabets(7),
        state: RandomGenerator.alphabets(7),
        postal_code: RandomGenerator.alphaNumeric(6),
        country: "KOR",
      },
    },
  );
  typia.assert(businessProfile);

  // 3. Create a seller verification document
  const createdDoc = await api.functional.ai_ecommerce.sellerVerificationDocuments.post(
    connection,
    {
      body: {
        seller_id: seller.id,
        business_profile_id: businessProfile.id,
        document_type: "business_registration",
        document_file_url: `https://fileserver.com/docs/${typia.random<string & tags.Format<"uuid">>()}.pdf`,
        issue_date: new Date().toISOString(),
        expiry_date: null,
      },
    },
  );
  typia.assert(createdDoc);

  // 4. Update mutable fields: document_type, expiry_date, verified_at
  const nextDocumentType = "tax_certificate";
  const nextExpiryDate = new Date(Date.now() + 1000 * 60 * 60 * 24 * 365).toISOString();
  const nextVerifiedAt = new Date().toISOString();
  const updatedDoc = await api.functional.ai_ecommerce.sellerVerificationDocuments.putById(connection, {
    id: createdDoc.id,
    body: {
      document_type: nextDocumentType,
      expiry_date: nextExpiryDate,
      verified_at: nextVerifiedAt,
    },
  });
  typia.assert(updatedDoc);
  TestValidator.equals("seller_id unchanged")(updatedDoc.seller_id)(createdDoc.seller_id);
  TestValidator.equals("business_profile_id unchanged")(updatedDoc.business_profile_id)(createdDoc.business_profile_id);
  TestValidator.equals("document_type updated")(updatedDoc.document_type)(nextDocumentType);
  TestValidator.equals("expiry_date updated")(updatedDoc.expiry_date)(nextExpiryDate);
  TestValidator.equals("verified_at updated")(updatedDoc.verified_at)(nextVerifiedAt);
  TestValidator.equals("document_file_url unchanged")(updatedDoc.document_file_url)(createdDoc.document_file_url);

  // 5. Attempt to update document_file_url after verification (should not change)
  const attemptedNewFileUrl = `https://fileserver.com/docs/${typia.random<string & tags.Format<"uuid">>()}.pdf`;
  const afterVerifiedAttempt = await api.functional.ai_ecommerce.sellerVerificationDocuments.putById(
    connection,
