      id: createdDoc.id,
      body: {
        document_file_url: attemptedNewFileUrl,
      },
    },
  );
  typia.assert(afterVerifiedAttempt);
  // document_file_url is expected to remain as in updatedDoc
  TestValidator.equals("document_file_url must remain unchanged after verification")(
    afterVerifiedAttempt.document_file_url
  )(updatedDoc.document_file_url);
}

