import type { IAiEcommercePersonalizationAnalytics } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommercePersonalizationAnalytics";
import type { IPageIAiEcommercePersonalizationAnalytics } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiEcommercePersonalizationAnalytics";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test the search (filtered, paginated) listing of personalization analytics records.
 *
 * Business context:
 * The analytics dashboard queries must return only relevant event data for the requested filters (customer, event type, date range). This test guarantees the filtering logic, ensures that dashboard reports and exports will be accurate, and checks that the API honors strict pagination limits.
 *
 * Workflow Steps:
 * 1. Insert several analytics event records with diverse combinations of customer_id, event_type, and event_at via the creation endpoint (dependency: POST /ai_ecommerce/personalizationAnalytics).
 * 2. For each kind of filter (customer_id, event_type), call the search endpoint (/ai_ecommerce/personalizationAnalytics PATCH) with the filter set and verify:
 *    - Only matching records are returned (no records for other customers, events)
 *    - Pagination respects the page/limit arguments and sliced results are correct
 *    - Filters on time range return only events within specified window
 * 3. Edge: Querying a page beyond the result size should return an empty array.
 * 4. Validate the total, pages, and per-page record counts in returned pagination metadata.
 */
export async function test_api_ai_ecommerce_test_search_personalization_analytics_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Insert analytics records for two customers and several events
  const customerA: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const customerB: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  const baseTime = new Date();
  const events = [
    // Customer A: different event_types at baseTime, baseTime + 1min
    await api.functional.ai_ecommerce.personalizationAnalytics.post(connection, {
      body: {
        customer_id: customerA,
        event_type: "favorite_add",
        event_at: new Date(baseTime).toISOString(),
      } satisfies IAiEcommercePersonalizationAnalytics.ICreate,
    }),
    await api.functional.ai_ecommerce.personalizationAnalytics.post(connection, {
      body: {
        customer_id: customerA,
        event_type: "rec_click",
        event_at: new Date(baseTime.getTime() + 60000).toISOString(),
      } satisfies IAiEcommercePersonalizationAnalytics.ICreate,
    }),
    // Customer B: same event_types, later timestamps
    await api.functional.ai_ecommerce.personalizationAnalytics.post(connection, {
      body: {
        customer_id: customerB,
        event_type: "favorite_add",
        event_at: new Date(baseTime.getTime() + 120000).toISOString(),
      } satisfies IAiEcommercePersonalizationAnalytics.ICreate,
    }),
    await api.functional.ai_ecommerce.personalizationAnalytics.post(connection, {
      body: {
        customer_id: customerB,
        event_type: "rec_click",
        event_at: new Date(baseTime.getTime() + 180000).toISOString(),
      } satisfies IAiEcommercePersonalizationAnalytics.ICreate,
    }),
  ];
  events.forEach((r) => typia.assert(r));

  // 2. Search: filter by customer_id (A), all event_types, no date filter
  let result = await api.functional.ai_ecommerce.personalizationAnalytics.patch(
    connection,
    {
      body: { customer_id: customerA } satisfies IAiEcommercePersonalizationAnalytics.IRequest,
    },
  );
  typia.assert(result);
  TestValidator.predicate("All records for customerA")(
    result.data.every((e) => e.customer_id === customerA),
  );
  TestValidator.equals("Total customerA events")(result.pagination.records)(2);

  // 3. Search: filter by event_type ("favorite_add"), all customers
  result = await api.functional.ai_ecommerce.personalizationAnalytics.patch(
    connection,
    {
      body: { event_type: "favorite_add" } satisfies IAiEcommercePersonalizationAnalytics.IRequest,
    },
  );
  typia.assert(result);
  TestValidator.predicate("Only 'favorite_add' events")(
    result.data.every((e) => e.event_type === "favorite_add"),
  );
  TestValidator.equals("Total favorite_add events")(result.pagination.records)(2);

  // 4. Search: date window filter (catch only events from baseTime to baseTime + 1min)
  const from = new Date(baseTime).toISOString();
  const to = new Date(baseTime.getTime() + 60000).toISOString();
  result = await api.functional.ai_ecommerce.personalizationAnalytics.patch(
    connection,
    {
      body: { event_from: from, event_to: to } satisfies IAiEcommercePersonalizationAnalytics.IRequest,
    },
  );
  typia.assert(result);
  TestValidator.predicate("Events in date window")(
    result.data.every((e) => e.event_at >= from && e.event_at <= to),
  );
  TestValidator.equals("Events in window")(result.pagination.records)(2);

  // 5. Pagination test: limit=1, page=2 for event_type rec_click
  result = await api.functional.ai_ecommerce.personalizationAnalytics.patch(
    connection,
    {
      body: { event_type: "rec_click", limit: 1, page: 2 } satisfies IAiEcommercePersonalizationAnalytics.IRequest,
    },
  );
  typia.assert(result);
  TestValidator.equals("Pagination total for rec_click")(result.pagination.records)(2);
  TestValidator.equals("Pagination limit")(result.pagination.limit)(1);
  TestValidator.equals("Page 2 has 1 row or less")(result.data.length <= 1)(true);

  // 6. Edge: page beyond range (page > pages), should return empty data
  result = await api.functional.ai_ecommerce.personalizationAnalytics.patch(
    connection,
    {
      body: { customer_id: customerA, page: 99, limit: 10 } satisfies IAiEcommercePersonalizationAnalytics.IRequest,
    },
  );
  typia.assert(result);
  TestValidator.equals("No results for out-of-bounds page")(result.data.length)(0);
}

