  TestValidator.equals("details_json updated")(updated.details_json)(nextDetailsJson);

  // 4. Assert immutable fields remain
  TestValidator.equals("customer_id unaffected")(updated.customer_id)(analytics.customer_id);
  TestValidator.equals("id unchanged")(updated.id)(analytics.id);
}

