/**
 * 결제 인터그레이션 조회의 필터, 정렬, 페이징, 권한 및 에러 처리 E2E 검증.
 *
 * 이 테스트는 관리자 권한이 있는 유저가 결제 인터그레이션 목록을 다양한 조건(전체리스트, 제공자명, 활성화여부, 페이징, 정렬, 허용치 초과, 잘못된 필터 등)으로 제대로 조회할 수 있는지와,
 * 비관리자 사용자가 접근 차단되는지도 확인한다. 결과 데이터가 필터조건/정렬 기준에 맞는지, 페이징 메타데이터가 맞는지, 잘못된 요청시 적절한 에러가 반환되는지 검증한다.
 *
 * 1. 관리자 권한 유저로 로그인(세션 발급)
 * 2. (성공) 별도 조건 없이 전체 결제연동 목록 조회(정상 반환)
 * 3. (성공) provider_name 필터로 조회 - 해당 제공자만 반환됨 확인
 * 4. (성공) is_active=false 조합 필터로 조회 - 비활성만 노출 확인
 * 5. (성공) provider_name + is_active=true 중복필터 조합 조회 - 교집합만 반환
 * 6. (성공) page=2, limit=2로 페이징 요청 시 해당 페이지 데이터/메타 검증
 * 7. (성공) provider_name 기준 알파벳 오름차순 정렬로 조회(수작업 정렬 후 검증)
 * 8. (실패) 존재하지 않는 provider_name 조회 시 빈 data 배열 확인
 * 9. (실패) limit=99999처럼 허용치 초과 요청, 잘못된 필터 조합 등 시 에러 핸들링
 * 10. (실패) 비관리자 계정으로 동일 API 접근 시 권한거부 에러 확인
 */
export async function test_api_ai_ecommerce_test_list_payment_integrations_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. 관리자 권한 유저로 로그인(세션 발급) -- (테스트 환경에 따라 세션/권한 세팅 절차 필요, 예시는 직접 구현 대신 connection이 admin임을 가정)

  // 2. (성공) 전체 결제연동 조회 (필터 없음)
  const totalResult = await api.functional.ai_ecommerce.paymentIntegrations.patch(connection, {
    body: {}, // 조건없음
  });
  typia.assert(totalResult);
  TestValidator.predicate('전체 리스트 1페이지 내 data 정상 배열')(Array.isArray(totalResult.data));
  TestValidator.predicate('전체 리스트에 최소 1개 이상 있음')(totalResult.data.length >= 1);

  // 3. provider_name으로 필터
  const refProvider = totalResult.data[0].provider_name;
  const providerResult = await api.functional.ai_ecommerce.paymentIntegrations.patch(connection, {
    body: { provider_name: refProvider },
  });
  typia.assert(providerResult);
  TestValidator.predicate('provider_name=필터 결과 모두 해당 제공자임')(providerResult.data.every(v => v.provider_name === refProvider));

  // 4. is_active=false 필터
  const hasInactive = totalResult.data.some(v => v.is_active === false);
  if (hasInactive) {
    const inactiveResult = await api.functional.ai_ecommerce.paymentIntegrations.patch(connection, {
      body: { is_active: false },
    });
    typia.assert(inactiveResult);
    TestValidator.predicate('is_active=false 결과 모두 false')(inactiveResult.data.every(v => v.is_active === false));
  }

  // 5. provider_name + is_active=true 중복필터
  const activeProvider = totalResult.data.find(v => v.is_active === true)?.provider_name;
  if (activeProvider) {
    const comboResult = await api.functional.ai_ecommerce.paymentIntegrations.patch(connection, {
      body: { provider_name: activeProvider, is_active: true },
    });
    typia.assert(comboResult);
    TestValidator.predicate('provider_name+is_active=true 결과 모두 일치')(comboResult.data.every(v => v.provider_name === activeProvider && v.is_active === true));
  }

  // 6. page=2, limit=2: 페이징 메타와 data 반환
  const pagingResult = await api.functional.ai_ecommerce.paymentIntegrations.patch(connection, {
    body: { page: 2, limit: 2 },
  });
  typia.assert(pagingResult);
  TestValidator.equals('page=2 반영')(pagingResult.pagination.current)(2);
  TestValidator.equals('limit=2 반영')(pagingResult.pagination.limit)(2);

  // 7. provider_name 알파벳 오름차순 정렬 테스트 (API 기본정렬 없으므로 수작업-일관성확인)
  const listForSort = [...totalResult.data];
  listForSort.sort((a, b) => a.provider_name.localeCompare(b.provider_name));
  const sortedProviders = listForSort.map(v => v.provider_name);
  const sortedResult = await api.functional.ai_ecommerce.paymentIntegrations.patch(connection, {
    body: {},
  });
  typia.assert(sortedResult);
  const resultProviders = sortedResult.data.map(v => v.provider_name);
  TestValidator.equals('provider_name 오름차순 정렬')(resultProviders.join(','))(sortedProviders.join(','));

  // 8. (실패) 존재하지 않는 provider_name 필터 : 빈 배열
  const noneResult = await api.functional.ai_ecommerce.paymentIntegrations.patch(connection, {
    body: { provider_name: '@no_such_provider_asdfgh' },
  });
  typia.assert(noneResult);
  TestValidator.equals('존재X제공자 결과 data empty')(noneResult.data.length)(0);

  // 9. (실패-에러) 허용치 초과(limit=99999) 등: error 발생
  await TestValidator.error('limit 초과시 에러')(async () => {
    await api.functional.ai_ecommerce.paymentIntegrations.patch(connection, {
      body: { limit: 99999 },
    });
  });

  // 10. 비관리자 계정 권한거부(테스트 환경 세팅 필요, 실제 환경따라 로그인 구현 필요, 예시는 skip)
  // -- (별도 connection/토큰 세션으로 재호출: 권한 관련 403 error 기대)
}

