import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommercePaymentIntegration } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommercePaymentIntegration";

/**
 * 결제 연동(설정) 수정 기능의 동작을 검증한다.
 *
 * 테스트 목적 및 시나리오:
 * 1. 정상 수정: 하나의 결제 연동을 생성하고, configuration_json 또는 is_active 필드를 변경해 정상적으로 업데이트되는지 검증한다. 커스텀 업데이트 전후의 불변 필드는 그대로 저장되어 있는지도 확인(특히 created_at, id).
 * 2. provider_name 중복: 또 다른 결제 연동을 만든 후, 첫 번째 연동의 provider_name을 두 번째 연동의 provider_name으로 변경 시도하여 고유성 제약 오류가 발생함을 확인한다.
 * 3. 유효하지 않은 업데이트: configuration_json에 JSON이 아닌 문자열 등 비정상 입력을 보내거나, 존재하지 않는 속성 등 잘못된 페이로드로 업데이트하면 유효성 오류가 발생함을 확인한다.
 * 4. 존재하지 않는/삭제된 id의 업데이트: 잘못된 id(임의 uuid)로 수정을 요청했을 때 적절한 오류 응답이 발생해야 한다.
 * 
 * 절차:
 * - ai_ecommerce/paymentIntegrations 엔드포인트로 연동 2개 생성
 * - 하나의 연동에서 정상 업데이트(1회 이상)
 * - 하나의 연동에서 provider_name 충돌 시도
 * - 하나의 연동에서 configuration_json 등 유효성 오류 발생 시도
 * - 임의 uuid로 존재하지 않는 레코드 업데이트 시도
 */
export async function test_api_ai_ecommerce_test_update_payment_integration_valid_fields_and_conflict_error(
  connection: api.IConnection,
) {
  // 1. 결제 연동 2개 생성
  const baseIntegration = await api.functional.ai_ecommerce.paymentIntegrations.post(connection, {
    body: {
      provider_name: "Stripe",
      configuration_json: JSON.stringify({ key: "original-key", endpoint: "https://stripe.test" }),
      is_active: true,
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(baseIntegration);

  const conflictIntegration = await api.functional.ai_ecommerce.paymentIntegrations.post(connection, {
    body: {
      provider_name: "KakaoPay",
      configuration_json: JSON.stringify({ key: "kakao-api-key", endpoint: "https://kakao.test" }),
      is_active: true,
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(conflictIntegration);

  // 2. configuration_json, is_active 필드 정상 업데이트
  const updateRes = await api.functional.ai_ecommerce.paymentIntegrations.putById(connection, {
    id: baseIntegration.id,
    body: {
      configuration_json: JSON.stringify({ key: "updated-key", endpoint: "https://stripe-prod" }),
      is_active: false,
    },
  });
  typia.assert(updateRes);
  TestValidator.equals("id 불변 확인")(updateRes.id)(baseIntegration.id);
  TestValidator.equals("provider_name 불변 확인")(updateRes.provider_name)(baseIntegration.provider_name);
  TestValidator.equals("is_active 반영됨")(updateRes.is_active)(false);
  TestValidator.equals("configuration_json 변경")(JSON.parse(updateRes.configuration_json))({ key: "updated-key", endpoint: "https://stripe-prod" });
  TestValidator.equals("created_at 불변")(updateRes.created_at)(baseIntegration.created_at);

  // 3. provider_name 중복 시도(고유성 오류 확인)
  await TestValidator.error("provider_name 중복")(async () => {
    await api.functional.ai_ecommerce.paymentIntegrations.putById(connection, {
      id: baseIntegration.id,
      body: {
        provider_name: conflictIntegration.provider_name,
      },
    });
  });

  // 4. 유효하지 않은 configuration_json 등 페이로드 오류
  await TestValidator.error("malformed configuration_json")(async () => {
    await api.functional.ai_ecommerce.paymentIntegrations.putById(connection, {
      id: baseIntegration.id,
      body: {
        configuration_json: "{ this is not json }",
      },
    });
  });

  // 5. 존재하지 않는/삭제된 id 수정 시도(404 등 오류 확인)
  await TestValidator.error("존재하지 않는 id 수정")(async () => {
    await api.functional.ai_ecommerce.paymentIntegrations.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        provider_name: "NonExists",
      },
    });
  });
}

