/**
 * 결제 연동(payment integration) 설정 수정 권한이 관리자에게만 있는지 검증합니다.
 *
 * 본 테스트는 아래와 같은 시나리오를 다룹니다:
 * 1. 관리자 권한으로 결제 연동(paymentIntegration) 레코드를 생성합니다.
 * 2. 인증이 없는 (즉, 비관리자) 연결로 해당 integration의 PUT(수정) API를 호출합니다.
 * 3. 이때 반드시 권한 없음(Forbidden/Unauthorized) 에러가 발생해야 하며, 성공 응답은 허용되지 않습니다.
 * 4. 만약 권한 에러가 아닌 다른 에러이거나, 성공적으로 갱신된다면 테스트는 실패로 간주합니다.
 *
 * 이 검증을 통해 결제 설정 연동의 민감정보 노출·변조 방지와 관리자 전용 관리 정책이 제대로 동작하는지 보장합니다.
 */
export async function test_api_ai_ecommerce_test_update_payment_integration_permission_denied_for_non_admin(
  connection: api.IConnection,
) {
