  const integration = await api.functional.ai_ecommerce.paymentIntegrations.post(connection, {
    body: {
      provider_name: "TestProvider",
      configuration_json: JSON.stringify({ api_key: "sk_test_xxx" }),
      is_active: true,
      created_at: new Date().toISOString(),
    } satisfies IAiEcommercePaymentIntegration.ICreate,
