  const nonAdminConnection = { ...connection, headers: { ...connection.headers } };
  delete nonAdminConnection.headers.Authorization;

  // 3. 비관리자가 해당 결제 연동의 수정(putById)을 시도하면 반드시 권한 에러가 발생해야 함
  await TestValidator.error("Non-admin은 payment integration 수정이 불가해야 한다")(
    async () => {
