import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommercePaymentIntegration } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommercePaymentIntegration";

/**
 * 결제 연동(Integration) 삭제(비활성화) E2E 시나리오
 *
 * 본 테스트에서는 다음의 시나리오를 검증합니다.
 *
 * 1. 플랫폼 관리자 권한으로 결제 프로바이더 연동(Integration) 엔트리를 생성한다. (선행조건)
 * 2. 생성된 id로 정상적으로 삭제(비활성화) API를 호출하여 결제 연동이 비활성화됨을 확인한다.
 * 3. 동일한 id로 삭제 API를 한 번 더 호출하여, system이 이미 비활성화되었거나 존재하지 않음을 에러로 리턴하는지 확인한다.
 * 4. 존재하지 않거나 형식이 잘못된 id로 삭제를 시도할 시 명확한 validation 또는 not found 에러를 내는지 체크한다.
 * 5. 만약 결제연동에 의존성이(예: 진행중 결제 등)이 존재할 때 삭제를 차단하는 rule이 비즈니스 로직상 구현되어 있다면, 해당 케이스도 검증한다.
 *    (단, 본 테스트 자료에서는 해당 의존성 검증 경로가 없어 skip 처리)
 */
export async function test_api_ai_ecommerce_paymentIntegrations_test_delete_payment_integration_by_id_and_edge_cases(
  connection: api.IConnection,
) {
  // 1. 결제 연동(Integration) 생성 (선행조건)
  const integration: IAiEcommercePaymentIntegration =
    await api.functional.ai_ecommerce.paymentIntegrations.post(connection, {
      body: {
        provider_name: "TestProvider_" + RandomGenerator.alphaNumeric(6),
        configuration_json: JSON.stringify({ apiKey: RandomGenerator.alphaNumeric(16) }),
        is_active: true,
        created_at: new Date().toISOString(),
      } satisfies IAiEcommercePaymentIntegration.ICreate,
    });
  typia.assert(integration);

  // 2. 정상 삭제(비활성화) 시도
  const erased: IAiEcommercePaymentIntegration =
    await api.functional.ai_ecommerce.paymentIntegrations.eraseById(connection, {
      id: integration.id,
    });
  typia.assert(erased);
  TestValidator.equals("deactivated integration id matches")(erased.id)(integration.id);
  TestValidator.equals("deactivated integration is inactive")(erased.is_active)(false);

  // 3. 한 번 더 삭제 시도(이미 비활성화 또는 존재하지 않음)
  await TestValidator.error("already deleted integration returns error")(
    async () => {
      await api.functional.ai_ecommerce.paymentIntegrations.eraseById(connection, {
        id: integration.id,
      });
    },
  );

  // 4. 존재하지 않는/엉터리 id로 삭제 시도 (not found/validation)
  const dummyId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("nonexistent integration returns error")(
    async () => {
      await api.functional.ai_ecommerce.paymentIntegrations.eraseById(connection, {
        id: dummyId,
      });
    },
  );

  // 4-2. 형식 불일치 id(test)
  await TestValidator.error("malformed id (not uuid) returns error")(
    async () => {
      // 강제로 uuid 아닌 string을 사용 (컴파일러 타입 체크에 허락되는 범위 내)
      await api.functional.ai_ecommerce.paymentIntegrations.eraseById(connection, {
        id: "not-a-uuid" as string & tags.Format<"uuid">,
      });
    },
  );

  // 5. 연동에 의존성이 있는 경우(예: 진행중 결제/서비스) 삭제를 시도할 필요가 있으나,
  // 제공된 API/자료에서 이 의존성을 테스트할 추가 엔드포인트/구현이 없어 해당 파트는 SKIP 합니다.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
