/**
 * 결제연동(Payment Integration) 삭제 권한 검증 - 비관리자는 절대 불가
 *
 * 플랫폼 관리자인 경우에만 결제 연동 설정(통합/구성) 레코드 삭제(즉, 비활성화)가 허용되고,
 * 비관리자(일반 유저/오퍼레이터 등) 시도 시 모두 권한에러(Forbidden, Unauthorized)가 발생해야 함을 테스트.
 * 
 * 1. 관리자 계정(Authorization 포함된 connection)으로 결제연동 생성
 * 2. 비관리자 connection(mock: role=user)으로 삭제 시도하면 반드시 권한에러
 * 3. (확장) 비관리자가 본인이 생성한 결제 연동 레코드라도 삭제가 불가해야 하며,
 *    실제 생성 자체가 거부된다면 error 처리로 권한 정책이 적용됨을 간접 검증
 */
export async function test_api_ai_ecommerce_test_delete_payment_integration_permission_denied_for_non_admin(
  connection: api.IConnection,
) {
  // 1. 관리자 계정 - 결제연동 생성
  const adminIntegration = await api.functional.ai_ecommerce.paymentIntegrations.post(connection, {
    body: {
      provider_name: "KakaoPay",
      configuration_json: '{"api_key":"adminkey","secret":"secretadminkey"}',
      is_active: true,
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(adminIntegration);

  // 2. 비관리자 connection(권한 컨텍스트 mock)
  const userConnection = { ...connection, headers: { ...connection.headers, role: "user" } };

  // (2-1) 비관리자가 관리자 생성분을 삭제 시도 → Forbidden/Unauthorized error 체크
  await TestValidator.error("비관리자는 결제연동 삭제 불가")(() =>
    api.functional.ai_ecommerce.paymentIntegrations.eraseById(userConnection, {
      id: adminIntegration.id
