import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceDiscountRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceDiscountRule";
import type { IAiEcommercePageIAiEcommerceDiscountRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommercePageIAiEcommerceDiscountRule";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 할인 규칙(Discount Rule) 목록의 필터 및 페이징 기능, 그리고 권한/에러 케이스를 종합적으로 검증합니다.
 *
 * 할인/쿠폰/로열티 정책 관리자의 UX/백오피스에서 다양한 조건으로 룰을 검색 및 페이징 처리할 수 있으며,
 * 검색 결과, 페이징/메타데이터, 에러 및 인증 케이스를 모두 검증합니다.
 *
 * 1. 유효성 검증용 - 다양한 rule_type/description/created_at 으로 discount rule을 여러 개 생성합니다.
 * 2. rule_type, description(키워드), created_date_range 단일 및 복합조건으로 목록을 조회하며, 하위 모든 반환값이 필터조건과 일치하는지 검증합니다.
 * 3. 페이징(page/limit) 조합 요청 시 각 페이지별 데이터 개수, 총 페이지 수, records, 남은 페이지 여부, 빈 페이지(초과 페이지) 처리까지 검증합니다.
 * 4. 잘못된 필터 구조/값(잘못된 타입, 초과 limit, page=0/음수 등)에 대한 에러 케이스를 커버합니다.
 * 5. (구현 가능하다면) 비로그인/권한 미달 계정의 접근 시도 및 접근 거부 오류도 함께 확인합니다.
 */
export async function test_api_ai_ecommerce_discountRules_test_list_discount_rules_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. 다양한 type/description/created_at discount rule 생성(최소 3종)
  const now = new Date();
  const yesterday = new Date(now.getTime() - 24*60*60*1000);
  const twoDaysAgo = new Date(now.getTime() - 2*24*60*60*1000);

  // [테스트 데이터] 생성될 각각의 조건
  const rules = [
    {
      rule_type: "fixed_amount",
      description: "오늘등록 - 할인 고정 금액 keyword1",
      predicate_json: '{"min_amount":10000}'
    },
    {
      rule_type: "percentage",
      description: "어제등록 - 백분율 할인 keyword2",
      predicate_json: '{"min_purchase":5000}'
    },
    {
      rule_type: "stacking",
      description: "이틀전등록 - 중복할인 keyword1",
      predicate_json: '{"applicable_category":["Digital"]}'
    }
  ];

  // 실제 등록 시간 다양화 위해 기본적으로 post 호출 뒤 타임스탬프 활용
  const created_rules: IAiEcommerceDiscountRule[] = [];
  for (const input of rules) {
    const rule = await api.functional.ai_ecommerce.discountRules.post(connection, {
      body: input satisfies IAiEcommerceDiscountRule.ICreate,
    });
    typia.assert(rule);
    created_rules.push(rule);
  }

  // 2. rule_type별 필터 & 모든 반환값 rule_type 일치 검증
  for (const type of ["fixed_amount", "percentage", "stacking"]) {
    const resp = await api.functional.ai_ecommerce.discountRules.patch(connection, {
      body: { rule_type: type } satisfies IAiEcommerceDiscountRule.IRequest,
    });
    typia.assert(resp);
    for (const r of resp.data) {
      TestValidator.equals("rule_type 필터 일치")(r.rule_type)(type);
    }
  }

  // 3. description(키워드)로 검색 결과 필터
  for (const keyword of ["keyword1", "keyword2"]) {
    const resp = await api.functional.ai_ecommerce.discountRules.patch(connection, {
      body: { description: keyword } satisfies IAiEcommerceDiscountRule.IRequest,
    });
    typia.assert(resp);
    for (const r of resp.data) {
      TestValidator.predicate("description 키워드 포함")(
        r.description.includes(keyword)
      );
    }
  }

  // 4. created_date_range로만 필터 (오늘, 어제 ~ 오늘 등)
  // 오늘 생성된 룰만 찾기
  const today_iso = now.toISOString();
  const todayOnly = await api.functional.ai_ecommerce.discountRules.patch(connection, {
    body: {
      created_date_range: { from: today_iso.slice(0,10)+"T00:00:00.000Z", to: today_iso },
    } satisfies IAiEcommerceDiscountRule.IRequest,
  });
  typia.assert(todayOnly);
  // 반환된 모든 룰이 오늘 날짜인지 확인
  for (const r of todayOnly.data) {
    TestValidator.predicate("created_at이 오늘인지")(
      r.created_at >= today_iso.slice(0,10)+"T00:00:00.000Z" &&
      r.created_at <= today_iso
    );
  }

  // 5. 페이징 기능(page/limit 조합)
  // 전체 룰 중 2개씩 페이징 조회
  const paged = await api.functional.ai_ecommerce.discountRules.patch(connection, {
    body: {
      page: 1,
      limit: 2,
    } satisfies IAiEcommerceDiscountRule.IRequest,
  });
  typia.assert(paged);
  TestValidator.equals("limit 2 적용 여부")(paged.data.length)(2);
  TestValidator.predicate("총 레코드와 pagination.records 일치")(
    paged.pagination.records >= paged.data.length
  );
  TestValidator.predicate("총 pages 계산 올바름")(
    paged.pagination.pages === Math.ceil(paged.pagination.records / paged.pagination.limit)
  );

  // 페이지 초과 요청 시 빈 데이터와 pagination 유지
  const overPage = await api.functional.ai_ecommerce.discountRules.patch(connection, {
    body: {
      page: 99,
      limit: 2,
    } satisfies IAiEcommerceDiscountRule.IRequest,
  });
  typia.assert(overPage);
  TestValidator.equals("빈 배열")(overPage.data.length)(0);
  TestValidator.predicate("total/page 메타데이터 정상")(overPage.pagination.records >= 0 && overPage.pagination.pages >= 1);

  // 6. 잘못된 구조/에러 발생시
  await TestValidator.error("page=0 실패 여부")(async () =>
    api.functional.ai_ecommerce.discountRules.patch(connection, {
      body: { page: 0 } satisfies IAiEcommerceDiscountRule.IRequest,
    })
  );
  await TestValidator.error("limit 초과(201) 에러")(async () =>
    api.functional.ai_ecommerce.discountRules.patch(connection, {
      body: { limit: 201 } satisfies IAiEcommerceDiscountRule.IRequest,
    })
  );
  await TestValidator.error("타입오류 발생")(async () =>
    api.functional.ai_ecommerce.discountRules.patch(connection, {
      body: { limit: "not_a_number" as any } as any,
    })
  );

  // 7. 인증/권한 케이스는 실제 인증 API 미제공으로 실제 테스트 불가 시 테스트 코드 대신 설명 주석만 첨부
  // 예: 비로그인 상태, 일반회원 role 전환 등 어드민이 아닌 계정에서 patch 호출 시 접근거부/에러 테스트 필요
}

