import type { IAiEcommerceDiscountRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceDiscountRule";

/**
 * Validate deleting discount rules: normal case, rule with active reference, double deletion, and not found error.
 *
 * 비즈니스 시나리오:
 * 1. 참조되지 않은 할인 룰 삭제 (정상 처리)
 * 2. 쿠폰 등에서 참조중인 할인 룰 삭제 시도(무결성 오류)
 * 3. 존재하지 않거나 이미 삭제된 룰에 대한 재삭제 시도(에러 반환)
 * 
 * 검증 포인트:
 * - 정상 삭제 시 응답(삭제된 룰 id 포함) 및 실제 삭제 여부
 * - 참조중 할인 룰 삭제 차단/무결성 오류 발생
 * - 이미 삭제/없음 id 대상 시 not found 등 오류
 *
 * (주의: RBAC 인증은 connection context에서 이미 권한이 있다고 가정)
 *
 * 단계별 프로세스:
 * 1. 룰 생성 → 삭제 → 성공 반환 검증
 * 2. 삭제된 동일 id로 재삭제 → 에러 검증
 * 3. 쿠폰 참조룰 생성 → 쿠폰 생성 → 해당 룰 삭제 시도(에러)
 * 4. 랜덤(존재하지 않는) UUID로 삭제 시도(에러)
 */
export async function test_api_ai_ecommerce_discountRules_test_delete_discount_rule_success_and_error_cases(
  connection: api.IConnection,
) {
  // 1. 참조 없는 할인 룰 생성
  const plainRule = await api.functional.ai_ecommerce.discountRules.post(connection, {
    body: {
      rule_type: 'percentage',
      description: 'E2E plain rule — 삭제 검증용',
      predicate_json: '{"min_purchase":10000,"category":["Books"]}',
    } satisfies IAiEcommerceDiscountRule.ICreate,
  });
  typia.assert(plainRule);

  // 2. 삭제 — 성공
