  await TestValidator.error('이미 삭제된 discount rule은 에러')(async () => {
    await api.functional.ai_ecommerce.discountRules.eraseById(connection, { id: plainRule.id });
  });

  // 4. 참조되는 룰 생성
  const refedRule = await api.functional.ai_ecommerce.discountRules.post(connection, {
    body: {
      rule_type: 'fixed_amount',
      description: '쿠폰 참조 discount rule',
      predicate_json: '{"min_amount":7000}',
    } satisfies IAiEcommerceDiscountRule.ICreate,
  });
