}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerceReport } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerceReport";
import type { IAiEcommerceReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceReport";

/**
 * End-to-end test of abuse/violation report listing (ai_ecommerceReport.IPage) with filters and pagination,
 * including role access validation (admin/unauthorized) and edge-case defensive queries.
 *
 * Business context:
 * Reporting, searching and triage of abuse/violation reports are critical admin workflows for compliance and moderation.
 * This test ensures correct search/filtering, result pagination, system limits, and enforcement of access controls.
 *
 * Test Steps:
 * 1. Generate diverse abuse reports with known reporters, targets, reasons, and statuses via POST endpoint.
 * 2. Issue PATCH (list/search) queries as authorized role:
 *    - List all (default, no filter)
 *    - Filter by reporter_id, target id/type, status, reason, created date, combo/strict filters
 *    - Edge: keyword/reason with special characters, large page size/offset
 *    - Validate metadata (total/limit/offset/data)
 *    - Validate empty results for strict/no-match filters
 * 3. Issue PATCH queries as unauthorized user, expect access denied
 * 4. Issue PATCH with malformed filters (invalid UUID/date, negative offset), expect error/defense response
 * 5. Validate all error and metadata responses match business expectation
 */
export async function test_api_ai_ecommerce_test_list_abuse_reports_with_various_filters_pagination_and_access_control(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a diverse set of abuse reports for various filter scenarios
  const reporters: string[] = ArrayUtil.repeat(3)(() => typia.random<string & tags.Format<"uuid">>());
  const commentTargets: string[] = ArrayUtil.repeat(2)(() => typia.random<string & tags.Format<"uuid">>());
  const reviewTargets: string[] = ArrayUtil.repeat(2)(() => typia.random<string & tags.Format<"uuid">>());
  const threadTargets: string[] = ArrayUtil.repeat(1)(() => typia.random<string & tags.Format<"uuid">>());

  // Preset reasons, statuses for filter combos
  const REASONS = ["abuse", "spam", "ToS violation", "!@#特殊字符"];
  const STATUSES = ["open", "resolved", "pending"];

  const createdReports = await ArrayUtil.asyncRepeat(10)(async (i) => {
    const reporter_id = RandomGenerator.pick(reporters);
    // Pick only one target type per report
    const typePicker = RandomGenerator.pick([
      "comment", "review", "thread"
    ]);
    const reason = RandomGenerator.pick(REASONS);
    const status = RandomGenerator.pick(STATUSES);

    const targets =
      typePicker === "comment"
        ? {
            target_comment_id: RandomGenerator.pick(commentTargets),
            target_review_id: null,
            target_forum_thread_id: null,
          }
        : typePicker === "review"
        ? {
            target_comment_id: null,
            target_review_id: RandomGenerator.pick(reviewTargets),
            target_forum_thread_id: null,
          }
        : {
            target_comment_id: null,
            target_review_id: null,
            target_forum_thread_id: RandomGenerator.pick(threadTargets),
          };
    const detailed_comment =
      reason === "!@#特殊字符"
        ? "Searching edge with !@#特殊字符"
        : RandomGenerator.paragraph()();
    return await api.functional.ai_ecommerce.reports.post(connection, {
      body: {
        reporter_id,
        ...targets,
        reason,
        status,
        detailed_comment,
      } satisfies IAiEcommerceReport.ICreate,
    });
  });
  // All reports present
  TestValidator.equals("created count")(createdReports.length)(10);

  //--- 2. Patch: as admin (default context): full and filtered searches
  // 2.1 List all
  let res = await api.functional.ai_ecommerce.reports.patch(connection, {
    body: {} satisfies ai_ecommerceReport.IRequest,
  });
  typia.assert(res);
  // Validate returned objects
  TestValidator.equals("page total count")(res.total)(createdReports.length);

  // 2.2 Filter by reporter_id
  for (const reporter_id of reporters) {
    res = await api.functional.ai_ecommerce.reports.patch(connection, {
      body: { reporter_id } satisfies ai_ecommerceReport.IRequest,
    });
    typia.assert(res);
    for (const r of res.data) {
      TestValidator.equals("match filter: reporter_id")(r.reporter_id)(reporter_id);
    }
  }

  // 2.3 Filter by target types
  // Comments
  for (const target_comment_id of commentTargets) {
    res = await api.functional.ai_ecommerce.reports.patch(connection, {
      body: { target_comment_id } satisfies ai_ecommerceReport.IRequest,
    });
    typia.assert(res);
    for (const r of res.data) {
      TestValidator.equals("match filter: target_comment_id")(r.target_comment_id)(target_comment_id);
    }
  }
  // Reviews
  for (const target_review_id of reviewTargets) {
    res = await api.functional.ai_ecommerce.reports.patch(connection, {
      body: { target_review_id } satisfies ai_ecommerceReport.IRequest,
    });
    typia.assert(res);
    for (const r of res.data) {
      TestValidator.equals("match filter: target_review_id")(r.target_review_id)(target_review_id);
    }
  }
  // Threads
  for (const target_forum_thread_id of threadTargets) {
    res = await api.functional.ai_ecommerce.reports.patch(connection, {
      body: { target_forum_thread_id } satisfies ai_ecommerceReport.IRequest,
    });
    typia.assert(res);
    for (const r of res.data) {
      TestValidator.equals("match filter: target_forum_thread_id")(r.target_forum_thread_id)(target_forum_thread_id);
    }
  }

  // 2.4 Filter by reason, status
  for (const reason of REASONS) {
    res = await api.functional.ai_ecommerce.reports.patch(connection, {
      body: { reason } satisfies ai_ecommerceReport.IRequest,
    });
    typia.assert(res);
    for (const r of res.data) {
      TestValidator.equals("match filter: reason")(r.reason)(reason);
    }
  }
  for (const status of STATUSES) {
    res = await api.functional.ai_ecommerce.reports.patch(connection, {
      body: { status } satisfies ai_ecommerceReport.IRequest,
    });
    typia.assert(res);
    for (const r of res.data) {
      TestValidator.equals("match filter: status")(r.status)(status);
    }
  }

  // 2.5 Filter by created_after / created_before
  // Use min/max from createdReports for range
  const sortedByCreated = [...createdReports].sort((a, b) => (a.created_at < b.created_at ? -1 : 1));
  const minDate = sortedByCreated[0].created_at;
  const maxDate = sortedByCreated[sortedByCreated.length - 1].created_at;
  // after min (should include all except the very first if strict)
  res = await api.functional.ai_ecommerce.reports.patch(connection, {
    body: { created_after: minDate } satisfies ai_ecommerceReport.IRequest,
  });
  typia.assert(res);
  TestValidator.predicate("created_after filter count")(
    res.data.length <= createdReports.length,
  );
  // before max (should include all)
  res = await api.functional.ai_ecommerce.reports.patch(connection, {
    body: { created_before: maxDate } satisfies ai_ecommerceReport.IRequest,
  });
  typia.assert(res);
  TestValidator.predicate("created_before filter count")(
    res.data.length <= createdReports.length,
  );

  // 2.6 Pagination: limit/offset, edge values
  res = await api.functional.ai_ecommerce.reports.patch(connection, {
    body: {
      limit: 2,
      offset: 0,
    } satisfies ai_ecommerceReport.IRequest,
  });
  typia.assert(res);
  TestValidator.equals("pagination limit")(res.limit)(2);
  TestValidator.equals("pagination offset")(res.offset)(0);
  TestValidator.equals("pagination page size")(res.data.length)(2);

  // Offset to next page
  res = await api.functional.ai_ecommerce.reports.patch(connection, {
    body: { limit: 3, offset: 3 } satisfies ai_ecommerceReport.IRequest,
  });
  typia.assert(res);
  TestValidator.equals("pagination offset")(res.offset)(3);
  TestValidator.equals("page size (possibly less than limit) or total")(
    res.data.length <= 3 && res.data.length <= res.total,
  )(true);

  // Large limit requests (defensive: e.g. limit 1000)
  res = await api.functional.ai_ecommerce.reports.patch(connection, {
    body: { limit: 1000 } satisfies ai_ecommerceReport.IRequest, // exceeds typical page
  });
  typia.assert(res);
  TestValidator.equals("large page size present")(res.limit)(1000);
  TestValidator.predicate("large page: size not > total")(
    res.data.length <= res.total,
  );

  // No-match combo (random UUID likely yields zero)
  res = await api.functional.ai_ecommerce.reports.patch(connection, {
    body: {
      reporter_id: typia.random<string & tags.Format<"uuid">>(),
      reason: "non_existent_reason",
    } satisfies ai_ecommerceReport.IRequest,
  });
  typia.assert(res);
  TestValidator.equals("empty data page")(res.data.length)(0);

  // Special character reason 
  res = await api.functional.ai_ecommerce.reports.patch(connection, {
    body: { reason: "!@#特殊字符" } satisfies ai_ecommerceReport.IRequest,
  });
  typia.assert(res);
  for (const r of res.data) {
    TestValidator.equals("special char reason filter")(r.reason)("!@#特殊字符");
  }

  //--- 3. Authorization: attempt PATCH as unauthorized (simulate by clearing token, invalid headers)
  // For this test skeleton, simulate by forcibly removing headers
  const unauthorizedConnection = {
    ...connection,
    headers: {},
  };
  await TestValidator.error("access denied for unauthorized user")(
    async () =>
      await api.functional.ai_ecommerce.reports.patch(unauthorizedConnection, {
        body: {} satisfies ai_ecommerceReport.IRequest,
      })
  );

  //--- 4. Invalid/malformed filters: UUID and date, negative offset, too large negative/limit
  await TestValidator.error("invalid UUID in filter")(
    async () =>
      await api.functional.ai_ecommerce.reports.patch(connection, {
        body: {
          reporter_id: "not-a-uuid" as any,
        } satisfies ai_ecommerceReport.IRequest,
      })
  );
  await TestValidator.error("invalid date string")(
    async () =>
      await api.functional.ai_ecommerce.reports.patch(connection, {
        body: {
          created_before: "not-a-date" as any,
        } satisfies ai_ecommerceReport.IRequest,
      })
  );
  await TestValidator.error("negative offset defensively handled")(
    async () =>
      await api.functional.ai_ecommerce.reports.patch(connection, {
        body: {
          offset: -5 as any,
        } satisfies ai_ecommerceReport.IRequest,
      })
  );
  await TestValidator.error("negative limit defensively handled")(
    async () =>
      await api.functional.ai_ecommerce.reports.patch(connection, {
        body: {
          limit: -1 as any,
        } satisfies ai_ecommerceReport.IRequest,
      })
  );
}

