import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerceComment } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerceComment";
import type { IAiEcommerceReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceReport";

/**
 * Comprehensive E2E validation of abuse/violation report creation for community moderation.
 *
 * This test ensures:
 * - A valid report can be created for an existing comment by a legitimate reporter (customer).
 * - Reports can only target a single entity (comment, review, or thread) per submission, as enforced by the schema/business rules.
 * - Duplicate reporting (same reporter on same target) is rejected.
 * - Reporting a non-existent (invalid) comment is rejected.
 * - All business rule and validation error cases are captured.
 *
 * NOTE:
 * - Tests that rely on omitting required properties (e.g., reporter_id, reason, status) cannot be included because such code fails TypeScript compilation and is not expressible under strict type safety.
 * - Only negative tests for business rule violations (duplicate, invalid target, multiple targets) or referential integrity can be implemented.
 *
 * Test workflow:
 * 1. Create a valid comment as the abuse report's target.
 * 2. Successfully create a report targeting that comment, verifying all properties.
 * 3. Attempt to create a report targeting both a comment and a review (should fail if schema/business rules enforced at runtime).
 * 4. Attempt reporting a non-existent comment.
 * 5. Attempt to file the same report again (by the same reporter on the same target - duplicate), expecting rejection.
 */
export async function test_api_ai_ecommerce_test_create_abuse_report_with_valid_and_invalid_inputs(
  connection: api.IConnection,
) {
  // 1. Create a valid comment (abuse-reportable target)
  const commentAuthorId = typia.random<string & tags.Format<"uuid">>();
  const commentCreateInput: ai_ecommerceComment.ICreate = {
    customer_id: commentAuthorId,
    body: RandomGenerator.content()()(),
  };
  const comment = await api.functional.ai_ecommerce.comments.post(connection, { body: commentCreateInput });
  typia.assert(comment);

  // 2. Happy path: Create a valid report against an existing comment
  const reporterId = typia.random<string & tags.Format<"uuid">>();
  const reportInput = {
    reporter_id: reporterId,
    target_comment_id: comment.id,
    reason: "spam",
    status: "pending",
    detailed_comment: "This is clearly spam."
  } satisfies IAiEcommerceReport.ICreate;
  const report = await api.functional.ai_ecommerce.reports.post(connection, { body: reportInput });
  typia.assert(report);
  TestValidator.equals("target_comment_id matches")(report.target_comment_id)(comment.id);
  TestValidator.equals("reporter_id matches")(report.reporter_id)(reporterId);

  // 3. Negative case: attempt to target both a comment and a review in one report
  await TestValidator.error("multiple report targets in a single report should fail")(() =>
    api.functional.ai_ecommerce.reports.post(connection, {
      body: {
        reporter_id: reporterId,
        target_comment_id: comment.id,
        target_review_id: typia.random<string & tags.Format<"uuid">>(),
        reason: "abuse",
        status: "pending",
      } satisfies IAiEcommerceReport.ICreate
    })
  );

  // 4. Negative case: report a non-existent comment (random UUID target)
  await TestValidator.error("reporting non-existent comment fails referential integrity")(() =>
    api.functional.ai_ecommerce.reports.post(connection, {
      body: {
        reporter_id: reporterId,
        target_comment_id: typia.random<string & tags.Format<"uuid">>(),
        reason: "abuse",
        status: "pending",
      } satisfies IAiEcommerceReport.ICreate
    })
  );

  // 5. Negative case: duplicate reporting (same reporter, same target)
  await TestValidator.error("duplicate reporting with same reporter and comment should fail")(() =>
    api.functional.ai_ecommerce.reports.post(connection, {
      body: reportInput
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceReport";

/**
 * Validate updating of abuse/violation report status and rationale with correct authorization and workflow rules.
 *
 * This test covers both success (admin/authorized update) and failure (forbidden/invalid) scenarios:
 * 1. Create a new abuse report (as regular user, using provided dependency)
 * 2. Update report (as admin/authorized): Set status (e.g., 'resolved') and rationale (detailed_comment) + reason
 *    - Confirm returned record reflects updated fields correctly by checking only supported DTO fields
 * 3. Attempt to update report as regular/unauthorized user
 *    - Confirm update is rejected (TestValidator.error)
 * 4. Attempt to change immutable fields (report target/comment/review/thread IDs)
 *    - Confirm update is rejected, only allowed fields can be changed
 * 5. Attempt update for already deleted report (simulate deletion using status), and for a non-existent report ID
 *    - Confirm both return errors and are not allowed
 *
 * All updates use PUT /ai_ecommerce/reports/:id and validate API contract and business logic using only available fields.
 */
export async function test_api_ai_ecommerce_test_update_abuse_report_status_and_rationale_with_authorization_checks(
  connection: api.IConnection,
) {
  // 1. Create a new abuse/violation report as a normal user
  const reporterId = typia.random<string & tags.Format<"uuid">>();
  const createBody: IAiEcommerceReport.ICreate = {
    reporter_id: reporterId,
    target_comment_id: typia.random<string & tags.Format<"uuid">>(),
    target_review_id: null,
    target_forum_thread_id: null,
    reason: "spam",
    status: "pending",
    detailed_comment: "User reported abusive comment: spam detected."
  };
  const created: IAiEcommerceReport = await api.functional.ai_ecommerce.reports.post(connection, {
    body: createBody,
  });
  typia.assert(created);
  TestValidator.equals("reporter matches")(created.reporter_id)(reporterId);
  TestValidator.equals("reason matches")(created.reason)(createBody.reason);
  TestValidator.equals("status matches")(created.status)(createBody.status);
  TestValidator.equals("target comment matches")(created.target_comment_id)(createBody.target_comment_id);

  // 2. Simulate update as admin/authorized user with status/rationale/reason
  const updateBody: IAiEcommerceReport.IUpdate = {
    status: "resolved",
    reason: "review completed, violation confirmed",
    detailed_comment: "Confirmed spam content. Action taken."
    // No resolved_by_id or resolved_at: not available in IAiEcommerceReport
  };
  const updated: IAiEcommerceReport = await api.functional.ai_ecommerce.reports.putById(connection, {
    id: created.id,
    body: updateBody,
  });
  typia.assert(updated);
  TestValidator.equals("status updated")(updated.status)(updateBody.status);
  TestValidator.equals("rationale updated")(updated.reason)(updateBody.reason);
  TestValidator.equals("report id unchanged")(updated.id)(created.id);
  TestValidator.equals("target comment unchanged")(updated.target_comment_id)(created.target_comment_id);

  // 3. Attempt to update the report as an unauthorized user (should fail)
  const unauthBody: IAiEcommerceReport.IUpdate = {
    status: "reviewed",
