import api from "@ORGANIZATION/PROJECT-api";
import type { Iai_ecommerceReviewSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/Iai_ecommerceReviewSnapshot";
import type { IPageIai_ecommerceReviewSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIai_ecommerceReviewSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated and filtered search of review snapshots (admin only).
 *
 * This test verifies the /ai_ecommerce/reviewSnapshots PATCH endpoint—which supports advanced filters and pagination for review snapshot records—properly applies various filters, handles pagination, covers edge and invalid input cases, and enforces admin-only access. Scenarios cover well-formed and malformed queries as well as permission checks.
 *
 * Steps:
 * 1. As admin, search with all filters (review_id, captured_by_id, status, rating, created_at range, reason, page, limit, sort), asserting the result structure and filter application.
 * 2. Try single-filter, no-filter, and edge time (from==to) queries; confirm results and type.
 * 3. Test pagination extremes (high page/limit, zero/negative values).
 * 4. Send invalid queries (bad UUIDs, dates, or pagination); verify error is thrown.
 * 5. Remove admin authorization and check access is rejected.
 */
export async function test_api_ai_ecommerce_test_search_review_snapshots_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Search with all filters
  const filters: Iai_ecommerceReviewSnapshot.IRequest = {
    review_id: typia.random<string & tags.Format<"uuid">>(),
    captured_by_id: typia.random<string & tags.Format<"uuid">>(),
    status: "active",
    rating: 5,
    created_at_from: new Date(Date.now() - 86400000).toISOString(), // 1 day ago
    created_at_to: new Date().toISOString(),
    snapshot_reason: "edit",
    page: 1,
    limit: 10,
    sort: "created_at,desc",
  };
  const result = await api.functional.ai_ecommerce.reviewSnapshots.patch(connection, { body: filters });
  typia.assert(result);
  TestValidator.predicate("pagination fields exist")(!!result.pagination && !!result.data);

  // 2. Filter variations and edges
  // a) Single filter
  const singleFilterResult = await api.functional.ai_ecommerce.reviewSnapshots.patch(connection, { body: { review_id: filters.review_id } });
  typia.assert(singleFilterResult);
  // b) No filters (all data)
  const allDataResult = await api.functional.ai_ecommerce.reviewSnapshots.patch(connection, { body: {} });
  typia.assert(allDataResult);
  // c) created_at_from == created_at_to
  const sameTime = new Date().toISOString();
  const edgeTimeResult = await api.functional.ai_ecommerce.reviewSnapshots.patch(connection, { body: { created_at_from: sameTime, created_at_to: sameTime } });
  typia.assert(edgeTimeResult);

  // 3. Pagination extremes
  const highPageResult = await api.functional.ai_ecommerce.reviewSnapshots.patch(connection, { body: { page: 99999, limit: 10 } });
  typia.assert(highPageResult);
  const zeroLimitResult = await api.functional.ai_ecommerce.reviewSnapshots.patch(connection, { body: { limit: 0 } });
  typia.assert(zeroLimitResult);
  const highLimitResult = await api.functional.ai_ecommerce.reviewSnapshots.patch(connection, { body: { limit: 999 } });
  typia.assert(highLimitResult);

  // 4. Invalid queries
  await TestValidator.error("invalid UUID")(async () => {
    await api.functional.ai_ecommerce.reviewSnapshots.patch(connection, { body: { review_id: "not-a-uuid" as any } });
  });
  await TestValidator.error("invalid date")(async () => {
    await api.functional.ai_ecommerce.reviewSnapshots.patch(connection, { body: { created_at_from: "not-a-date" as any } });
  });
  await TestValidator.error("invalid pagination")(async () => {
    await api.functional.ai_ecommerce.reviewSnapshots.patch(connection, { body: { page: -1 } });
  });

  // 5. Permission/authorization check: non-admin
  const nonAdminConnection = { ...connection, headers: { ...connection.headers } };
  delete nonAdminConnection.headers.Authorization;
  await TestValidator.error("unauthorized, non-admin")(async () => {
    await api.functional.ai_ecommerce.reviewSnapshots.patch(nonAdminConnection, { body: {} });
  });
}

