/**
 * 리뷰 스냅샷 단건 상세조회 API 테스트 (정상/에러/보안권한)
 *
 * 리뷰 스냅샷은 리뷰의 audit/history 관점의 변경 이력, 복구 또는 감사 등의 목적으로 생성/조회된다.
 * 본 테스트는 다음 시나리오를 검증한다:
 *
 * 1. 준비: 리뷰 생성을 위해 customer, product, order UUID 준비
 * 2. 신규 리뷰를 생성한다 (POST /ai_ecommerce/reviews)
 * 3. 생성된 리뷰를 기반으로 review 스냅샷을 생성한다 (POST /ai_ecommerce/reviewSnapshots)
 * 4. 해당 스냅샷의 id로 단건 상세조회 요청한다 (GET /ai_ecommerce/reviewSnapshots/{id})
 *    - 응답이 스냅샷 생성 시점 데이터와 일치하는지 상세히 검증한다
 * 5. 존재하지 않는 uuid로 조회 시 404 (혹은 적절한 NotFound) 에러가 발생하는지 검증한다
 * 6. 권한 부적합(Authorization 없는) 유저가 조회 시도시 권한에러(401/403)이 발생함을 검증한다
 */
export async function test_api_ai_ecommerce_test_get_review_snapshot_by_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. 임의 UUID로 엔티티 FK 준비 (고객, 상품, 주문)
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const productId = typia.random<string & tags.Format<"uuid">>();
  const orderId = typia.random<string & tags.Format<"uuid">>();

  // 2. 리뷰 생성 (POST)
  const review = await api.functional.ai_ecommerce.reviews.post(connection, {
    body: {
      customer_id: customerId,
      product_id: productId,
      order_id: orderId,
      rating: 5,
      body: "테스트 리뷰 본문",
      title: "테스트 리뷰 제목",
      is_private: false,
    } satisfies IAiEcommerceReview.ICreate,
  });
  typia.assert(review);

  // 3. 리뷰 스냅샷 생성 (POST)
  const snapshot = await api.functional.ai_ecommerce.reviewSnapshots.post(connection, {
    body: {
      review_id: review.id,
      captured_by_id: customerId,
      title: review.title,
      body: review.body,
      rating: review.rating,
      status: "active",
      snapshot_reason: "edit",
    } satisfies Iai_ecommerceReviewSnapshot.ICreate,
  });
  typia.assert(snapshot);

  // 4. 정상 case: 생성한 스냅샷 ID로 조회 및 값 상세 검증
  const found = await api.functional.ai_ecommerce.reviewSnapshots.getById(connection, {
    id: snapshot.id,
  });
  typia.assert(found);
  TestValidator.equals("스냅샷 id")(found.id)(snapshot.id);
  TestValidator.equals("review_id")(found.review_id)(snapshot.review_id);
  TestValidator.equals("captured_by_id")(found.captured_by_id)(snapshot.captured_by_id);
  TestValidator.equals("title")(found.title)(snapshot.title);
  TestValidator.equals("body")(found.body)(snapshot.body);
  TestValidator.equals("rating")(found.rating)(snapshot.rating);
  TestValidator.equals("status")(found.status)(snapshot.status);
  TestValidator.equals("snapshot_reason")(found.snapshot_reason)(snapshot.snapshot_reason);

  // 5. 에러 case: 임의의 uuid로 NotFound 발생 확인
  await TestValidator.error("404: 존재하지 않는 reviewSnapshot id")(async () => {
    await api.functional.ai_ecommerce.reviewSnapshots.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });

  // 6. 비인가 (Authorization 누락) 커넥션으로 권한 에러 검증
  const headers = { ...connection.headers };
  delete headers.Authorization;
  const unauthorizedConnection = { ...connection, headers };
  await TestValidator.error("권한 없는 유저의 접근")(async () => {
    await api.functional.ai_ecommerce.reviewSnapshots.getById(unauthorizedConnection, {
      id: snapshot.id,
    });
  });
}

