import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceFavorite } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceFavorite";
import type { IAiEcommercePageIAiEcommerceFavorite } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommercePageIAiEcommerceFavorite";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing customer favorites with full pagination and sorting edge cases.
 *
 * This test creates a batch of favorite product records for a single customer, then queries the /ai_ecommerce/favorites PATCH endpoint
 * for a variety of paging and sort parameter combinations. It covers:
 *  - Multiple pages (limit < total records)
 *  - Different page numbers
 *  - Sorting by created_at in ascending and descending order
 *  - Pagination metadata correctness (total pages, record counts)
 *
 * Steps:
 * 1. Bulk-create N favorite entries (N>limit*2) for a new customer, each with distinct products and diverse timestamps.
 * 2. Run .patch with limit < N (e.g., 5), requesting page 1 and confirm order/count.
 * 3. Run .patch for page 2, 3, ... up to total_pages. Confirm correct entries and metadata per each.
 * 4. Repeat same queries with sort_order switched (asc/desc)
 * 5. Query with a different limit, check page recalculation.
 * 6. Spot-check that correct favorites (by product_id or created_at) are returned as expected for each page/sort permutation.
 *
 * This ensures robust, accurate, and fully usable pagination/sorting on favorites list endpoint.
 */
export async function test_api_ai_ecommerce_test_list_favorite_products_pagination_limits_and_sorting(connection: api.IConnection) {
  // Test setup constants
  const LIMIT = 5;
  const TOTAL = 13; // Det. non-multiple of LIMIT for edge-case last page

  // 1. Set up a new test customer
  const testCustomerId = typia.random<string & tags.Format<"uuid">>();

  // 2. Generate N distinct product IDs
  const productIds = ArrayUtil.repeat(TOTAL)(() => typia.random<string & tags.Format<"uuid">>());

  // 3. Bulk-create favorites for this customer
  const favoriteRecords: IAiEcommerceFavorite[] = [];
  for (let i = 0; i < TOTAL; ++i) {
    const favorite = await api.functional.ai_ecommerce.favorites.post(connection, {
      body: {
        customer_id: testCustomerId,
        product_id: productIds[i],
      } satisfies IAiEcommerceFavorite.ICreate,
    });
    typia.assert(favorite);
    favoriteRecords.push(favorite);
  }

  // Helper: Sort favorites by created_at ascend/descend for expected order calc
  const sortByCreatedAt = (arr: IAiEcommerceFavorite[], order: "asc"|"desc") =>
    arr.slice().sort((a, b) =>
      (order === "asc"
        ? a.created_at.localeCompare(b.created_at)
        : b.created_at.localeCompare(a.created_at)
      )
    );

  // Try both sort orders, different limits
  for (const sort_order of ["desc", "asc"] as const) {
    for (const limit of [LIMIT, 3]) {
      const sorted = sortByCreatedAt(favoriteRecords, sort_order);
      const pages = Math.ceil(TOTAL / limit);
      for (let page = 1; page <= pages; ++page) {
        // List one page
        const resp = await api.functional.ai_ecommerce.favorites.patch(connection, {
          body: {
            customer_id: testCustomerId,
            page,
            limit,
            sort_key: "created_at",
            sort_order,
          } satisfies IAiEcommerceFavorite.IRequest,
        });
        typia.assert(resp);
        // Metadata validation
        TestValidator.equals("current page")(resp.pagination.current)(page);
        TestValidator.equals("limit")(resp.pagination.limit)(limit);
        TestValidator.equals("records")(resp.pagination.records)(TOTAL);
        TestValidator.equals("pages")(resp.pagination.pages)(pages);
        // Row IDs
        const expectedStart = (page - 1) * limit;
        const expected = sorted.slice(expectedStart, expectedStart + limit);
        TestValidator.equals("favorite page data")(resp.data.map(fv => fv.id))(expected.map(fv => fv.id));
      }
    }
  }
}

