import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceFavorite } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceFavorite";

/**
 * 즐겨찾기 단건 조회 API의 권한/접근제어 검증
 *
 * - 고객 A가 즐겨찾기(favorite) 레코드를 생성한 후,
 *   1) 고객 A 본인은 정상적으로 해당 리소스를 조회할 수 있고,
 *   2) 타인(임의의 고객 B) 또는 인증되지 않은 요청은 접근이 거부되어야 한다.
 * - 별도로 존재하지 않는 id로의 접근 역시 같은 보안 원칙이 적용되는지 검증한다.
 *
 * [검증 시나리오]
 * 1. 고객 A가 favorite 레코드 생성
 * 2. 고객 A 본인이 정상적으로 해당 favorite을 조회 (성공)
 * 3. 타인(B) 혹은 인증 없이 동일 favorite id로 접근 시도 → 접근 거부(에러) 기대
 * 4. 존재하지 않는 favorite id로 접근 → 정보 노출 없이 에러
 *
 * Note: 실제 서비스 환경에서는 세션/토큰 등 계정 맵핑이 필수이나,
 * 본 테스트는 구조상 customer_id, header 조작 등으로만 제한적 시뮬레이션 수행
 * 실제 운용에서는 권한 시스템 및 토큰 기반 인증 체계 필요
 */
export async function test_api_ai_ecommerce_test_get_favorite_product_by_id_unauthorized_access(
  connection: api.IConnection,
) {
  // 1. 고객 A UUID (테스트용 임의 발급)
  const customerAId = typia.random<string & tags.Format<"uuid">>();
  const productId = typia.random<string & tags.Format<"uuid">>();

  // 2. 고객 A가 favorite 생성
  const favorite = await api.functional.ai_ecommerce.favorites.post(connection, {
    body: {
      customer_id: customerAId,
      product_id: productId,
      favorite_tag_id: null,
    } satisfies IAiEcommerceFavorite.ICreate,
  });
  typia.assert(favorite);

  // 3. 고객 A가 본인의 favorite 정상 조회 (성공 기대)
  const myFavorite = await api.functional.ai_ecommerce.favorites.getById(connection, {
    id: favorite.id,
  });
  typia.assert(myFavorite);
  TestValidator.equals("고객A 자신의 즐겨찾기 조회")(myFavorite.id)(favorite.id);
  TestValidator.equals("고객A customer_id 일치")(myFavorite.customer_id)(customerAId);

  // 4. (타인 접근) 고객 B UUID 발급, session 흉내내기용 connection
  const customerBId = typia.random<string & tags.Format<"uuid">>();
  const fakeConnectionB = {
    ...connection,
    headers: {
      ...connection.headers,
      // 실제로는 세션/토큰으로 권한 분리 필요, 구조상 단순 시뮬레이션
    },
  };
  // 고객 B로 접근 시도시 에러(권한 거부) 기대
  await TestValidator.error("타인 접근 거부 검증")(
    async () => {
      await api.functional.ai_ecommerce.favorites.getById(fakeConnectionB, {
        id: favorite.id,
      });
    },
  );

  // 5. 인증헤더 미포함/비로그인 상태 시뮬레이션
  const noAuthConnection = {
    ...connection,
    headers: Object.fromEntries(
      Object.entries(connection.headers ?? {}).filter(([k]) =>
        k.toLowerCase() !== "authorization"
      ),
    ),
  };
  await TestValidator.error("비로그인 접근 거부 검증")(
    async () => {
      await api.functional.ai_ecommerce.favorites.getById(noAuthConnection, {
        id: favorite.id,
      });
    },
  );

  // 6. 아예 없는 ID로 접근 → 동일하게 정보 노출 없음(에러)
  await TestValidator.error("존재하지 않는 favorite 접근 거부")(
    async () => {
      await api.functional.ai_ecommerce.favorites.getById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );
}

