  typia.assert(beyondOffset);
  TestValidator.equals("offset beyond result => data empty")(beyondOffset.data.length)(0);

  // 8. Include soft-deleted comments by filtering with deleted_at
  const withDeleted = await api.functional.ai_ecommerce.comments.patch(connection, {
    body: { deleted_at: new Date().toISOString() },
