 *   - Validate that the author information, associated context (forum thread, inquiry, review, parent comment), and audit properties (created_at, updated_at, depth, etc.) are correctly populated.
 *   - Confirm that sensitive fields are masked appropriately, if relevant (for this test, we focus on required data fields).
 *   - This operation supports frontend scenarios where detailed per-comment review/inquiry/forum context is rendered.
 *
 * Steps:
 *   1. Create a new comment using POST /ai_ecommerce/comments to ensure known test data.
 *   2. Use the returned comment's id to call GET /ai_ecommerce/comments/{id}.
 *   3. Assert the GET returns a non-deleted comment matching the initial creation input for key fields.
 *   4. Confirm that all atomic properties including context FKs and audit fields are correct and conform to type constraints.
 *   5. Validate that audit timestamps are valid ISO date-time strings.
 */
export async function test_api_ai_ecommerce_comments_getById(
  connection: api.IConnection,
) {
  // 1. Create a new comment as test fixture
  const createInput: ai_ecommerceComment.ICreate = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    body: "This is a test comment for retrieval.",
    // Single association: providing only forum_thread_id for atomic context
    forum_thread_id: typia.random<string & tags.Format<"uuid">>(),
    parent_id: null,
    inquiry_id: null,
    review_id: null,
  };
  const created: ai_ecommerceComment = await api.functional.ai_ecommerce.comments.post(connection, { body: createInput });
  typia.assert(created);

  // 2. Retrieve the comment by its id
  const retrieved: ai_ecommerceComment = await api.functional.ai_ecommerce.comments.getById(connection, { id: created.id });
  typia.assert(retrieved);

  // 3. Assertions: validate key atomic fields and associations
  TestValidator.equals("comment id matches")(retrieved.id)(created.id);
  TestValidator.equals("customer_id matches")(retrieved.customer_id)(created.customer_id);
  TestValidator.equals("body matches")(retrieved.body)(created.body);
  TestValidator.equals("forum_thread_id matches")(retrieved.forum_thread_id)(created.forum_thread_id);
  TestValidator.equals("parent_id is null")(retrieved.parent_id)(null);
  TestValidator.equals("inquiry_id is null")(retrieved.inquiry_id)(null);
  TestValidator.equals("review_id is null")(retrieved.review_id)(null);
  TestValidator.equals("not deleted")(retrieved.deleted_at)(null);
  TestValidator.predicate("depth is non-negative")(retrieved.depth >= 0);

  // 4. Verify audit fields: must be present and ISO date-time parsable
  TestValidator.predicate("created_at and updated_at are ISO date-time")(
    typeof retrieved.created_at === "string" &&
    typeof retrieved.updated_at === "string" &&
    !isNaN(Date.parse(retrieved.created_at)) &&
    !isNaN(Date.parse(retrieved.updated_at))
  );

  // 5. Required fields are non-empty and valid types
  TestValidator.predicate("all required fields populated")(
    !!retrieved.id &&
    !!retrieved.customer_id &&
    !!retrieved.body &&
    typeof retrieved.depth === "number"
  );
}

