import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerceComment } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerceComment";

/**
 * Validate creating a nested comment by specifying a parent_id.
 *
 * This test covers the case when a reply is created to an existing comment, forming a nested comment hierarchy. The following steps are performed:
 * 1. Create a parent comment (top-level/root, with parent_id null).
 * 2. Create a nested comment by specifying parent_id set to the parent's id.
 * 3. Confirm that the nested comment references the correct parent, its depth is parent's depth + 1, and the hierarchical structure is valid.
 * 4. Attempt to create an invalid nested comment (e.g., setting parent_id to the new nested comment's own id), and confirm the API rejects circular/self-nesting.
 * 5. Attempt to reference a non-existent parent_id and expect an error.
 *
 * The aim is to comprehensively verify threaded comment logic including acceptance of valid hierarchy and prevention of inconsistent/circular nesting.
 */
export async function test_api_ai_ecommerce_test_create_nested_comment_by_specifying_parent_id(
  connection: api.IConnection,
) {
  // 1. Create a parent (root) comment
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const forumThreadId = typia.random<string & tags.Format<"uuid">>();
  const parentBody = RandomGenerator.paragraph()();

  const parentComment = await api.functional.ai_ecommerce.comments.post(connection, {
    body: {
      customer_id: customerId,
      parent_id: null,
      forum_thread_id: forumThreadId,
      inquiry_id: null,
      review_id: null,
      body: parentBody,
    } satisfies ai_ecommerceComment.ICreate,
  });
  typia.assert(parentComment);
  TestValidator.equals("parent_id is null")(parentComment.parent_id)(null);
  TestValidator.equals("depth is zero for root")(parentComment.depth)(0);
  TestValidator.equals("forum_thread_id matches")(parentComment.forum_thread_id)(forumThreadId);

  // 2. Create a nested comment under the parent
  const childBody = RandomGenerator.paragraph()();
  const nestedComment = await api.functional.ai_ecommerce.comments.post(connection, {
    body: {
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      parent_id: parentComment.id,
      forum_thread_id: forumThreadId,
      inquiry_id: null,
      review_id: null,
      body: childBody,
    } satisfies ai_ecommerceComment.ICreate,
  });
  typia.assert(nestedComment);
  TestValidator.equals("parent_id references parent")(nestedComment.parent_id)(parentComment.id);
  TestValidator.equals("depth is parent.depth+1")(nestedComment.depth)(parentComment.depth + 1);
  TestValidator.equals("forum_thread_id matches for child")(nestedComment.forum_thread_id)(forumThreadId);

  // 3. Attempt to create a comment referencing itself (simulate circular nesting)
  // Note: Since comment creation returns an id, but there is no update endpoint,
  // we simulate by immediately using the new id as a parent in a follow-up post.
  await TestValidator.error("circular self-nesting should be rejected")(
    async () => {
      // Create an initial reply (not root, arbitrary parent)
      const initialReply = await api.functional.ai_ecommerce.comments.post(connection, {
        body: {
          customer_id: typia.random<string & tags.Format<"uuid">>(),
          parent_id: nestedComment.id,
          forum_thread_id: forumThreadId,
          inquiry_id: null,
          review_id: null,
          body: RandomGenerator.paragraph()(),
        } satisfies ai_ecommerceComment.ICreate,
      });
      // Attempt to set parent_id equal to newly created comment's own id (simulate circular)
      return api.functional.ai_ecommerce.comments.post(connection, {
        body: {
          customer_id: typia.random<string & tags.Format<"uuid">>(),
          parent_id: initialReply.id,
          forum_thread_id: forumThreadId,
          inquiry_id: null,
          review_id: null,
          body: RandomGenerator.paragraph()(),
        } satisfies ai_ecommerceComment.ICreate,
      });
    },
  );

  // 4. Attempt to use a non-existent parent_id
  await TestValidator.error("invalid parent_id should be rejected")(
    async () => {
      return api.functional.ai_ecommerce.comments.post(connection, {
        body: {
          customer_id: typia.random<string & tags.Format<"uuid">>(),
          parent_id: typia.random<string & tags.Format<"uuid">>(), // random id, not created
          forum_thread_id: forumThreadId,
          inquiry_id: null,
          review_id: null,
          body: RandomGenerator.paragraph()(),
        } satisfies ai_ecommerceComment.ICreate,
      });
    },
  );
}

