import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerceComment } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerceComment";

/**
 * Test that a comment author can update their own comment's body text using the PUT endpoint.
 *
 * Business context:
 * - Comments may be posted on forum threads, inquiries, reviews, or as replies (parent_id).
 * - Only the comment's author (customer) or an admin may edit the comment.
 * - Only the body (content) is allowed to be updated; all association fields and audit fields are immutable.
 * - Timestamps and fields such as updated_at should change after edit, others must remain static.
 * - Test will ensure that the PUT endpoint allows self-edit and respects business immutability rules.
 *
 * Steps:
 * 1. Create a comment as a particular "author" (customer_id) with body text and valid target (forum/inquiry/review or parent_id).
 * 2. Call PUT endpoint as that author to change only the body text.
 * 3. Validate:
 *    - Response contains body reflecting the new value.
 *    - updated_at is changed compared to original comment.
 *    - id, customer_id, parent_id, forum_thread_id, inquiry_id, review_id, created_at, and depth are unchanged.
 *    - deleted_at is still null (active comment).
 */
export async function test_api_ai_ecommerce_comments_test_update_comment_body_by_author(
  connection: api.IConnection,
) {
  // Step 1: Create a comment as a specific author
  const author_id = typia.random<string & tags.Format<"uuid">>();
  const initialBody = RandomGenerator.paragraph()();
  const createPayload = {
    customer_id: author_id,
    body: initialBody,
    // Attach the comment to a valid context (choose one at random)
    forum_thread_id: typia.random<string & tags.Format<"uuid">>(),
    parent_id: null,
    inquiry_id: null,
    review_id: null,
  } satisfies ai_ecommerceComment.ICreate;
  const original = await api.functional.ai_ecommerce.comments.post(connection, {
    body: createPayload,
  });
  typia.assert(original);

  // Step 2: As the author, update only the body
  const newBody = RandomGenerator.paragraph()();
  const updated = await api.functional.ai_ecommerce.comments.putById(connection, {
    id: original.id,
    body: {
      body: newBody,
    } satisfies ai_ecommerceComment.IUpdate,
  });
  typia.assert(updated);

  // Step 3: Validate update results
  // Unchanged fields
  TestValidator.equals("id remains")(updated.id)(original.id);
  TestValidator.equals("customer_id remains")(updated.customer_id)(original.customer_id);
  TestValidator.equals("parent_id unchanged")(
    updated.parent_id === undefined ? null : updated.parent_id,
  )(original.parent_id === undefined ? null : original.parent_id);
  TestValidator.equals("forum_thread_id unchanged")(
    updated.forum_thread_id === undefined ? null : updated.forum_thread_id,
  )(original.forum_thread_id === undefined ? null : original.forum_thread_id);
  TestValidator.equals("inquiry_id unchanged")(
    updated.inquiry_id === undefined ? null : updated.inquiry_id,
  )(original.inquiry_id === undefined ? null : original.inquiry_id);
  TestValidator.equals("review_id unchanged")(
    updated.review_id === undefined ? null : updated.review_id,
  )(original.review_id === undefined ? null : original.review_id);
  TestValidator.equals("created_at unchanged")(updated.created_at)(original.created_at);
  TestValidator.equals("depth unchanged")(updated.depth)(original.depth);
  TestValidator.equals("deleted_at still null")(
    updated.deleted_at === undefined ? null : updated.deleted_at,
  )(null);

  // Changed fields
  TestValidator.notEquals("updated_at must change")(updated.updated_at)(original.updated_at);
  TestValidator.equals("body updated")(updated.body)(newBody);
}

