import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrder";
import type { IAiEcommerceOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrderItem";
import type { ai_ecommerce_return_request } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_return_request";

/**
 * 관리자 권한으로 반품/취소요청 목록을 다양한 필터 조건 및 페이지네이션과 함께 조회하여, 필터/페이지 동작을 검증합니다.
 * 
 * - 테스트용 주문(order) 및 반품요청(returnRequest) 1건을 먼저 준비합니다.
 * - status, 날짜, customer_id, order_id 별 정상 조회 및 페이지네이션을 시도하고, 정확히 필터링된 결과가 반환됨을 확인합니다.
 * - 논리삭제(삭제되지 않은 것만 노출) 규칙 확인: deleted_at==null 데이터만 목록에 포함되는지 체크합니다. ← 해당 필드 없음(생략)
 * - 조합 필터로 결과가 빈 케이스(불가능 조건에 대한 total=0, data=[])도 검증합니다.
 * - 권한 없는 사용자의 접근 시 permission(권한오류)이 발생하는지 확인합니다.
 */
export async function test_api_ai_ecommerce_test_list_return_requests_with_various_filters_as_admin(
  connection: api.IConnection
) {
  // 1. 테스트용 주문 생성
  const order = await api.functional.ai_ecommerce.orders.post(connection, {
    body: {
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      cart_id: typia.random<string & tags.Format<"uuid">>(),
      shipping_address_id: typia.random<string & tags.Format<"uuid">>(),
      order_status: "pending",
      order_channel: "web",
      items: [
        {
          sku_id: typia.random<string & tags.Format<"uuid">>(),
          quantity: 1,
        } satisfies IAiEcommerceOrderItem.ICreate,
      ],
    } satisfies IAiEcommerceOrder.ICreate,
  });
  typia.assert(order);

  // 2. 반품요청 1건 생성
  const returnReq = await api.functional.ai_ecommerce.returnRequests.post(connection, {
    body: {
      order_id: order.id,
      customer_id: order.customer_id,
      status: "pending",
      request_type: "return",
      reason: "단순변심",
    } satisfies ai_ecommerce_return_request.ICreate,
  });
  typia.assert(returnReq);

  // 3. status 필터 ("pending")
  const byStatus = await api.functional.ai_ecommerce.returnRequests.patch(connection, {
    body: { status: "pending" },
  });
  typia.assert(byStatus);
  TestValidator.predicate("status filter: 모두 pending인지 확인")(
    byStatus.data.every(row => row.status === "pending")
  );
  TestValidator.predicate("status filter: 새로 등록한 id 포함")(
    byStatus.data.some(row => row.id === returnReq.id)
  );

  // 4. 날짜 범위 필터(created_at_from~to), 최신 데이터 포함 확인
  const from = new Date(Date.now() - 1000 * 60 * 1).toISOString();
  const to = new Date(Date.now() + 1000 * 60 * 1).toISOString();
  const byDate = await api.functional.ai_ecommerce.returnRequests.patch(connection, {
    body: { created_at_from: from, created_at_to: to },
  });
  typia.assert(byDate);
  TestValidator.predicate("날짜범위 filter: 생성건 id 포함")(
    byDate.data.some(row => row.id === returnReq.id)
  );

  // 5. customer_id + order_id 필터
  const byUserOrder = await api.functional.ai_ecommerce.returnRequests.patch(connection, {
    body: { customer_id: order.customer_id, order_id: order.id },
  });
  typia.assert(byUserOrder);
  TestValidator.predicate("customer+order filter: 생성건만 반환")(
    byUserOrder.data.length === 1 && byUserOrder.data[0].id === returnReq.id
  );

  // 6. pageination: limit=1, offset=0,1 확인
  const paged1 = await api.functional.ai_ecommerce.returnRequests.patch(connection, {
    body: { limit: 1, offset: 0 },
  });
  const paged2 = await api.functional.ai_ecommerce.returnRequests.patch(connection, {
    body: { limit: 1, offset: 1 },
  });
  typia.assert(paged1);
  typia.assert(paged2);
  TestValidator.predicate("limit=1 반환(최대 1개)")(paged1.data.length <= 1 && paged2.data.length <= 1);
  TestValidator.notEquals("페이지 결과 불변")(paged1.data[0]?.id)(paged2.data[0]?.id);

  // ~~ 논리삭제: 기본값(삭제되지 않은 것만 노출) → 해당 필드 없음, 불가 ~~

  // 7. 빈 결과(존재불가 조합, 미래 날짜)
  const futureFrom = new Date(Date.now() + 1000 * 60 * 60 * 24 * 730).toISOString();
  const empty = await api.functional.ai_ecommerce.returnRequests.patch(connection, {
    body: { created_at_from: futureFrom, status: "completed" },
  });
  typia.assert(empty);
  TestValidator.equals("빈 목록, total 확인")(empty.data.length)(0);
  TestValidator.equals("빈 목록, total 확인")(empty.total)(0);

  // 8. 권한 없는 사용자(예: 인증정보 제거 후 호출)
  const noAuthConn = { ...connection, headers: { ...connection.headers } };
  delete noAuthConn.headers.Authorization;
  await TestValidator.error("권한없는 사용자 접근 실패")(
    async () => {
      await api.functional.ai_ecommerce.returnRequests.patch(noAuthConn, {
        body: {},
      });
    },
  );
}

