/**
 * Validate fetching and soft-deleting ai_ecommerce_return_request details by id.
 *
 * This test scenario verifies:
 * 1. Creation of a valid order for a customer
 * 2. Creation of a return/cancellation request for that order
 * 3. Successful fetch of the return request by id and validation of expected fields
 * 4. Soft-deletion of the return request and confirmation of its deleted status
 * 5. Ensures fetching a deleted return request triggers error or indicates deletion
 * 6. (Skipped: Attempting to fetch as a different customer—requires auth switching API not present)
 *
 * Overall, this flow covers happy path (success), deletion-reflection, and deleted-access error conditions.
 */
export async function test_api_ai_ecommerce_test_get_return_request_details_by_id_success_and_soft_deleted(
  connection: api.IConnection,
) {
  // 1. Create a valid order record for a customer
  const customer_id = typia.random<string & tags.Format<'uuid'>>();
  const cart_id = typia.random<string & tags.Format<'uuid'>>();
  const shipping_address_id = typia.random<string & tags.Format<'uuid'>>();
  const sku_id = typia.random<string & tags.Format<'uuid'>>();

  const order = await api.functional.ai_ecommerce.orders.post(connection, {
    body: {
      customer_id,
      cart_id,
      shipping_address_id,
      order_status: 'pending',
      order_channel: 'web',
      items: [
        {
          sku_id,
          quantity: 1,
        } satisfies IAiEcommerceOrderItem.ICreate,
      ],
    } satisfies IAiEcommerceOrder.ICreate,
  });
  typia.assert(order);

  // 2. Create a return/cancellation request for that order
  const request = await api.functional.ai_ecommerce.returnRequests.post(connection, {
    body: {
      order_id: order.id,
      customer_id,
      status: 'pending',
      request_type: 'return',
      reason: 'Test auto return',
    } satisfies ai_ecommerce_return_request.ICreate,
  });
  typia.assert(request);

  // 3. Fetch return request details by id and check expected fields
  const fetched = await api.functional.ai_ecommerce.returnRequests.getById(connection, { id: request.id });
  typia.assert(fetched);
  TestValidator.equals('id matches')(fetched.id)(request.id);
  TestValidator.equals('order matches')(fetched.order_id)(order.id);
  TestValidator.equals('customer matches')(fetched.customer_id)(customer_id);
  TestValidator.equals('request_type')(fetched.request_type)(request.request_type);
  TestValidator.equals('status')(fetched.status)(request.status);
  TestValidator.equals('reason')(fetched.reason)(request.reason);
  TestValidator.predicate('created at present')(!!fetched.created_at);
  TestValidator.predicate('updated at present')(!!fetched.updated_at);

  // 4. Soft-delete the return request
  const erase = await api.functional.ai_ecommerce.returnRequests.eraseById(connection, { id: request.id });
  typia.assert(erase);
  TestValidator.equals('delete success')(erase.success)(true);
  TestValidator.equals('deleted id matches')(erase.id)(request.id);
  TestValidator.predicate('deletedAt present')(!!erase.deletedAt);

  // 5. Try to fetch again - must error (or have no object) if properly deleted
  await TestValidator.error('fetching deleted request fails or indicates deleted')(async () => {
    const afterErase = await api.functional.ai_ecommerce.returnRequests.getById(connection, { id: request.id });
    if (afterErase && (afterErase as any).deleted_at == null)
      throw new Error('Should be deleted');
  });

  // 6. Cross-customer permission scenario skipped: no customer auth/context switching function available
}

