import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IRole";
import type { IPageRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageRole";

/**
 * Test paginated and filtered retrieval of RBAC roles as admin
 *
 * This test verifies:
 * 1. Role list endpoint properly handles multiple roles, pagination, and name filtering
 * 2. Roles with names matching a keyword can be queried with filters
 * 3. Pagination values are correct and only the requested page is returned
 * 4. Validation for invalid filters and excessive limits (e.g., too high per-page)
 *
 * Steps:
 * 1. Prepare by creating ~5-7 roles with varying names/descriptions
 * 2. Query with filter (e.g., name contains a specific keyword), and check only matching roles returned
 * 3. Check correct pagination info (total, page, limit) and data length logic
 * 4. Send invalid request (e.g., limit exceeds allowed max) and expect validation/resource error
 * 5. Send invalid filter types/values (e.g., page=-1, limit=null), and expect validation errors
 */
export async function test_api_ai_ecommerce_test_list_roles_with_pagination_and_filters_as_administrator(connection: api.IConnection) {
  // 1. Prepare roles
  const keyword = "qa_role_" + RandomGenerator.alphaNumeric(3);
  const roleNames: string[] = [
    `${keyword}alpha`,
    `${keyword}beta`,
    `${keyword}gamma`,
    "unfiltered_role_delta",
    "unfiltered_role_epsilon",
    "unfiltered_role_zeta",
  ];
  const createdRoles: IRole[] = [];
  for (const name of roleNames) {
    const created = await api.functional.ai_ecommerce.roles.post(connection, {
      body: {
        name: name,
        description: RandomGenerator.paragraph()(),
      },
    });
    typia.assert(created);
    createdRoles.push(created);
  }

  // 2. Query with filter (name includes keyword)
  const page = 1;
  const limit = 2;
  const filterOutput = await api.functional.ai_ecommerce.roles.patch(connection, {
    body: {
      page: page,
      limit: limit,
      name: keyword,
    },
  });
  typia.assert(filterOutput);
  // Only roles matching the keyword should be returned
  TestValidator.predicate("filtered data all match keyword")(filterOutput.data.every(r => r.name.includes(keyword)));
  // Pagination info correct
  TestValidator.equals("page matches")(filterOutput.page)(page);
  TestValidator.equals("limit matches")(filterOutput.limit)(limit);
  // If at least 3 roles match, first page should have 'limit' records
  if (filterOutput.total >= limit) {
    TestValidator.equals("length equals limit")(filterOutput.data.length)(limit);
  }
  TestValidator.predicate("total >= data length")(filterOutput.total >= filterOutput.data.length);

  // 3. Next page
  if (filterOutput.total > limit) {
    const nextPageOut = await api.functional.ai_ecommerce.roles.patch(connection, {
      body: {
        page: 2,
        limit: limit,
        name: keyword,
      },
    });
    typia.assert(nextPageOut);
    TestValidator.equals("next page")(nextPageOut.page)(2);
    // Data length checks
    TestValidator.predicate("next page data length ≤ limit")(nextPageOut.data.length <= limit);
    TestValidator.predicate("all match keyword")(nextPageOut.data.every(r => r.name.includes(keyword)));
  }

  // 4. Excessive limit (should error)
  await TestValidator.error("excessive page size should error")(() =>
    api.functional.ai_ecommerce.roles.patch(connection, {
      body: {
        page: 1,
        limit: 9999,
      },
    })
  );

  // 5. Invalid filter (negative page)
  await TestValidator.error("negative page should error")(() =>
    api.functional.ai_ecommerce.roles.patch(connection, {
      body: {
        page: -1,
        limit: 2,
      },
    })
  );
  // 6. Invalid type/null limit
  await TestValidator.error("null limit should error")(() =>
    api.functional.ai_ecommerce.roles.patch(connection, {
      body: {
        page: 1,
        // intentionally incorrect type
        limit: null as any,
      },
    })
  );
}

