import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IRole";

/**
 * Validate the retrieval of detailed information for a specific RBAC role by its UUID as an administrator.
 *
 * This test ensures that, after creating a new role, administrators can fetch its details by ID and that the returned data matches the expected role values. All schema fields are verified, and the test confirms that no sensitive or extraneous properties are leaked in the response. Special care is taken to cover the case where the description is null or omitted at creation time.
 *
 * Test steps:
 * 1. Create a new RBAC role using POST /ai_ecommerce/roles, providing randomized name and (optionally) description.
 * 2. Retrieve that role by its ID using GET /ai_ecommerce/roles/{id} as administrator.
 * 3. Assert that the detail response matches the creation input and returned creation record for id, name, and (nullable) description. Validate created_at and updated_at consistency.
 * 4. Confirm full schema adherence with typia.assert and that no non-schema fields are present.
 */
export async function test_api_ai_ecommerce_roles_test_get_role_details_by_valid_id_as_administrator(
  connection: api.IConnection,
) {
  // 1. Create a new role for the test, with randomized name and (optionally null) description.
  const roleInput: IRole.ICreate = {
    name: RandomGenerator.alphabets(12),
    description: Math.random() < 0.5 ? null : RandomGenerator.paragraph()(),
  };
  const created: IRole = await api.functional.ai_ecommerce.roles.post(
    connection,
    { body: roleInput },
  );
  typia.assert(created);

  // 2. Administrator fetches details for the new role by ID.
  const detail: IRole = await api.functional.ai_ecommerce.roles.getById(
    connection,
    { id: created.id },
  );
  typia.assert(detail);

  // 3. Check that returned details match created role and creation input
  TestValidator.equals("role id matches")(detail.id)(created.id);
  TestValidator.equals("role name matches")(detail.name)(roleInput.name);
  TestValidator.equals("role description matches")(
    detail.description ?? null
  )(roleInput.description ?? null);
  TestValidator.equals("created_at matches")(detail.created_at)(created.created_at);
  TestValidator.equals("updated_at matches")(detail.updated_at)(created.updated_at);

  // 4. Confirm no non-schema fields are present (strict type check)
  typia.assert(detail);
}

