/**
 * 관리자 권한으로 고유한 이름을 가진 새로운 RBAC 역할 생성 검증
 *
 * 이 테스트는 시스템 관리자가 고유한 이름의 새로운 역할(RBAC role)을 성공적으로 생성할 수 있는지 검증합니다.
 * 1. 새로운 역할에 사용할 고유한 이름(name)을 생성.
 * 2. (선택) description을 포함한 역할 데이터를 준비.
 * 3. POST /ai_ecommerce/roles API를 호출하여 역할 생성 요청 전송.
 * 4. 응답으로 반환되는 역할 객체가 고유 ID, 입력한 이름, description, 생성 및 수정 시각 등 시스템 메타데이터를 포함하는지 검증.
 * 5. 같은 이름으로 한 번 더 역할을 생성 시도하여 중복 불가(유니크 제약)에 의한 오류 발생 확인(실패 케이스).
 */
export async function test_api_ai_ecommerce_roles_post_test_create_role_with_unique_name_as_administrator(connection: api.IConnection) {
  // 1. 고유한 역할 이름 생성
  const uniqueRoleName: string = `auto_e2e_${RandomGenerator.alphabets(8)}`;

  // 2. description 값 준비
  const description: string = `자동화 테스트 생성 역할 at ${new Date().toISOString()}`;

  // 3. POST /ai_ecommerce/roles 호출: 정상 케이스
  const created = await api.functional.ai_ecommerce.roles.post(connection, {
    body: {
      name: uniqueRoleName,
      description: description,
    } satisfies IRole.ICreate,
  });
  typia.assert(created);

  // 4. 반환 필드 검증: 고유 이름, 설명, id, created/updated_at 등
  TestValidator.equals('역할 이름과 입력값')(created.name)(uniqueRoleName);
  TestValidator.equals('역할 설명과 입력값')(created.description)(description);
  TestValidator.predicate('id는 uuid여야 함')(!!created.id && created.id.length > 10); // uuid 최소 길이
  TestValidator.predicate('created_at 존재')(!!created.created_at);
  TestValidator.predicate('updated_at 존재')(!!created.updated_at);

  // 5. 동일 이름 중복 역할 생성이 불가능함을 검증 (유니크 제약)
  await TestValidator.error('역할명 중복 생성 금지')(async () => {
    await api.functional.ai_ecommerce.roles.post(connection, {
      body: {
        name: uniqueRoleName,
        description: RandomGenerator.paragraph()(),
      } satisfies IRole.ICreate,
    });
  });
}

