import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IRole";

/**
 * 역할 생성 엔드포인트의 관리자 권한 제한 검증
 *
 * 이 테스트는 RBAC 정책에 따라 역할을 생성할 수 있는 권한이 관리자에게만 부여되는지를 검증합니다.
 *
 * [검증 시나리오]
 * 1. 비관리자(일반 사용자) 자격으로 새 역할 생성 요청 시도 → 접근 거부(권한 없음) 오류가 발생해야 합니다.
 * 2. 인증되지 않은(로그아웃 상태) 사용자로 새 역할 생성 요청 시도 → 인증/권한 오류가 발생해야 합니다.
 *
 * [프로세스]
 * 1. (비관리자 계정) POST /ai_ecommerce/roles 엔드포인트를 호출하여 유효한 역할 생성 요청을 시도하고,
 *    런타임 오류(권한 거부)를 기대합니다.
 * 2. (비인증 상태) 인증정보 없는 connection 객체로 동일 요청을 시도하고,
 *    마찬가지로 인증/권한 오류가 발생하는지 검증합니다.
 * 3. 두 경우 모두 TestValidator.error를 사용하여 실제로 오류가 발생하는지만 검증합니다
 *    (에러 메시지나 세부 타입까지는 검증하지 않습니다).
 *
 * 성공(정상) 케이스는 본 테스트 범위에 포함하지 않습니다.
 */
export async function test_api_ai_ecommerce_test_create_role_requires_administrator_permission(
  connection: api.IConnection,
) {
  // 1. 비관리자 계정에서 역할 생성 시도(권한 없음)
  await TestValidator.error("비관리자 권한에서는 역할 생성이 거부되어야 합니다.")(() =>
    api.functional.ai_ecommerce.roles.post(connection, {
      body: {
        name: RandomGenerator.alphabets(8),
        description: "RBAC 실패 테스트용 역할 설명",
      } satisfies IRole.ICreate,
    })
  );

  // 2. 인증되지 않은(로그아웃) 상태에서 역할 생성 시도(인증 오류)
  //    기존 connection 객체를 복제 후 Authorization 헤더 안전하게 삭제
  const anonymous: api.IConnection = {
    ...connection,
    headers: { ...connection.headers }, // If headers is undefined, ...undefined gives {} so it's safe
  };
  if (anonymous.headers) delete anonymous.headers.Authorization;

  await TestValidator.error("비로그인 상태에서는 역할 생성이 거부되어야 합니다.")(() =>
    api.functional.ai_ecommerce.roles.post(anonymous, {
      body: {
        name: RandomGenerator.alphabets(8),
        description: "RBAC 인증 실패 테스트용 역할 설명",
      } satisfies IRole.ICreate,
    })
  );
}

