 *
 * 관리자 권한으로 역할(예: 'auditor', 'product_manager' 등)의 name, description 변경 성공 시나리오를 테스트합니다.
 * 1. POST로 신규 role을 하나 생성해서 테스트용 id 확보
 * 2. PUT으로 해당 역할의 name, description을 수정
 * 3. 반환 결과의 name/description이 정확히 반영됐고, updated_at이 갱신됐는지 검증
 * 4. (감사로그 등 외부 연동된 비즈니스 검증은 e2e 대상 외로 스킵)
 *
 * 단계별로 생성, 수정, business 검증까지 진행하여 core update 기능의 정상 동작을 보장합니다.
 */
export async function test_api_roles_test_update_role_success(
  connection: api.IConnection,
) {
  // 1. 신규 역할 생성 (테스트용 ID 확보)
  const originName = `${RandomGenerator.alphaNumeric(8)}-role`;
  const created = await api.functional.ai_ecommerce.roles.post(
    connection,
    {
      body: {
        name: originName,
        description: "초기 역할입니다.",
      } satisfies IRole.ICreate,
    },
  );
  typia.assert(created);

  // 2. 역할 정보 수정(name/description 변경)
  const updatedName = `${originName}-updated`;
  const updatedDesc = "설명이 풍부하게 수정됨";
  const updated = await api.functional.ai_ecommerce.roles.putById(
    connection,
    {
      id: created.id,
      body: {
        name: updatedName,
        description: updatedDesc,
      } satisfies IRole.IUpdate,
    },
  );
  typia.assert(updated);

  // 3. business 결과 검증(name, description, updated_at)
  TestValidator.equals("이름이 수정됨")(updated.name)(updatedName);
  TestValidator.equals("설명 변경됨")(updated.description)(updatedDesc);
  TestValidator.notEquals("updated_at이 갱신됨")(updated.updated_at)(created.updated_at);
  TestValidator.equals("동일 id 유지")(updated.id)(created.id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
