import api from "@ORGANIZATION/PROJECT-api";
import type { IRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IRole";

/**
 * 역할 이름의 고유성(unique constraint) 제약 검증
 *
 * 역할 관리 시스템에서 각 역할의 이름(name)은 고유해야 하며, 중복된 이름으로 변경 시도 시
 * 시스템은 이를 거절해야 합니다.
 *
 * 본 테스트는 두 개의 역할(role)을 생성한 뒤, 두 번째 역할의 이름을 첫 번째 역할과 일치하게
 * 바꾸려 하면 고유성 제약 조건 위반 오류가 반드시 발생하는지를 검증합니다.
 *
 * Step-by-step:
 * 1. 첫 번째 역할을 고유 name(name1)으로 생성
 * 2. 두 번째 역할을 다른 name(name2)으로 생성
 * 3. 두 번째 역할의 name을 첫 번째 name(name1)으로 변경 시도
 * 4. 시스템은 고유성 제약 오류(DB duplicate error 등)를 반환해야 하며, update가 불가함을 확정
 */
export async function test_api_ai_ecommerce_roles_test_update_role_to_duplicate_name_fails(
  connection: api.IConnection,
) {
  // 1. 첫 번째 역할 생성 (고유 name)
  const name1: string = RandomGenerator.alphaNumeric(10);
  const role1 = await api.functional.ai_ecommerce.roles.post(connection, {
    body: { name: name1, description: "desc1" } satisfies IRole.ICreate,
  });
  typia.assert(role1);
  TestValidator.equals("역할 이름 일치")(role1.name)(name1);

  // 2. 두 번째 역할 생성 (다른 고유 name)
  const name2: string = RandomGenerator.alphaNumeric(10);
  const role2 = await api.functional.ai_ecommerce.roles.post(connection, {
    body: { name: name2, description: "desc2" } satisfies IRole.ICreate,
  });
  typia.assert(role2);
  TestValidator.notEquals("서로 다른 역할 이름")(role2.name)(role1.name);

  // 3. 두 번째 역할의 name을 첫 번째 name으로 변경 시도 → 중복 오류 기대
  await TestValidator.error("중복 이름 변경 거절됨")(async () => {
    await api.functional.ai_ecommerce.roles.putById(connection, {
      id: role2.id,
      body: { name: name1 } satisfies IRole.IUpdate,
    });
  });
}

