import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IRole";

/**
 * 성공적으로 할당되지 않은 역할을 soft-delete(삭제)하는 시나리오를 검증합니다.
 *
 * - 시스템 어드민이 신규 RBAC 역할을 생성한 후, 해당 역할이 아무 사용자에게도 할당되지 않았음을 전제합니다.
 * - 역할 삭제(soft-delete)는 실제 데이터 삭제가 아니라 상태/플래그 변경으로 처리될 수 있으며,
 *   삭제 이후 반환되는 객체를 통해 id나 name 등이 원본과 동일함을 검증합니다.
 * - 목록/조회 등에서 실제로 미노출되는지는 제공 API에 따라 검증 불가하며, 감사 로그 확인도 엔드포인트 미제공으로 일부 생략합니다.
 *
 * 1. 미할당 신규 역할을 생성한다.
 * 2. 생성된 역할 id로 soft-delete(삭제) 호출
 * 3. DELETE 응답 객체에서 id 및 역할명 등 주요 필드 변형/유지 확인
 * 4. (목록/조회/API cascade, 감사 로그 검증 등은 해당 API 미제공 시 생략)
 */
export async function test_api_ai_ecommerce_test_delete_unused_role_successfully(
  connection: api.IConnection,
) {
  // 1. 미할당 신규 역할을 생성한다.
  const role = await api.functional.ai_ecommerce.roles.post(connection, {
    body: {
      name: `test_role_${typia.random<string>()}`,
      description: "테스트용 임시 역할(삭제 예정)",
    } satisfies IRole.ICreate,
  });
  typia.assert(role);

  // 2. 생성된 역할의 id로 soft-delete(삭제) 호출
  const deleted = await api.functional.ai_ecommerce.roles.eraseById(connection, {
    id: role.id,
  });
  typia.assert(deleted);

  // 3. 삭제 후, 반환 객체의 id와 이름이 원본과 동일한지 검증
  TestValidator.equals("역할 id 일치")(deleted.id)(role.id);
  TestValidator.equals("역할 이름 일치")(deleted.name)(role.name);
  // (삭제 상태 플래그, 실제 미노출 여부 등은 DTO/API 미제공으로 생략)
  // (감사 로그 확인 불가: 엔드포인트 미제공)
}

