/**
 * Validate that deleting a role which is currently assigned to a user is blocked.
 *
 * This test ensures proper business logic for RBAC integrity: a role that is
 * assigned to any user cannot be deleted and must yield a business logic error
 * on deletion attempt. This protects system security, as deleting in-use roles
 * would compromise both access control and audit trail soundness.
 *
 * Step-by-step process:
 * 1. Create a new role via POST /ai_ecommerce/roles
 * 2. (Assignment step: would assign this role to a user, but assignment endpoint is unavailable—see comment)
 * 3. Attempt deletion via DELETE /ai_ecommerce/roles/{id}
 * 4. Assert that deletion fails (business logic error thrown)
 *
 * Note: Role assignment cannot be simulated with current API/SDK; only the attempted delete can be validated for business logic error.
 */
export async function test_api_ai_ecommerce_test_delete_role_that_is_assigned_to_user_fails(
  connection: api.IConnection,
) {
  // 1. Create a new role (which we will pretend is assigned to a user)
  const roleName = `test-role-${typia.random<string>()}`;
  const role = await api.functional.ai_ecommerce.roles.post(connection, {
    body: {
      name: roleName,
      description: "Test role that will be assigned to a user for deletion blocking validation",
    } satisfies IRole.ICreate,
  });
  typia.assert(role);

  /**
   * 2. ASSIGNMENT STEP
   * --------------------------------------
   * If there were a user-role assignment endpoint, we would assign this role
   * to a test user here to ensure it is 'in use.' Since such endpoint is not
   * available from provided APIs, we explicitly document this limitation.
   *
   * For test/contract purposes, assume the role is assigned.
   */

  // 3. Attempt to delete the (presumed in-use) role, expect an error response
  await TestValidator.error("cannot delete assigned role")(() =>
    api.functional.ai_ecommerce.roles.eraseById(connection, {
      id: role.id,
    })
  );
}

