/**
 * Validate creation of a new trending products analytic record (mvTrendingProducts) as an administrator, covering both success and failure scenarios.
 *
 * This test verifies the analytics creation endpoint for trending products. It ensures:
 * - A successful record can be created by providing a complete, valid payload as an administrator.
 * - Each output field precisely matches the input (as per the analytics interface contract).
 * - Attempting creation with missing required fields fails gracefully with an error.
 * - Attempting to insert an exact duplicate record results in an error response.
 * - Using a non-existent product_id (simulated as a random UUID) returns a foreign key/validation error.
 * - Invalid period strings or malformed dates are rejected with validation errors.
 *
 * As user/role switching APIs are not exposed in the provided SDK, validation of administrator-only access is only described, not implemented in this test.
 *
 * Steps:
 * 1. Prepare a valid analytics input (all required fields)
 * 2. Create the analytic record (assumed admin privileges)
 * 3. Assert the response matches the input
 * 4. Attempt creation with various invalid inputs: missing fields, duplicates, invalid references/values
 * 5. Assert each failure returns an error as expected
 */
export async function test_api_ai_ecommerce_mvTrendingProducts_post(
  connection: api.IConnection,
) {
  // 1. Prepare valid analytics payload (simulate required fields)
  const analyticInput: mvTrendingProducts.ICreate = {
    product_id: typia.random<string & tags.Format<"uuid">>(),
    stat_period: RandomGenerator.pick(["daily", "weekly", "monthly"]),
    stat_date: new Date().toISOString().split("T")[0],
    trend_rank: typia.random<number & tags.Type<"int32"> & tags.Minimum<1>>(),
    sales_count: typia.random<number & tags.Type<"int32"> & tags.Minimum<0>>(),
    views_count: typia.random<number & tags.Type<"int32"> & tags.Minimum<0>>(),
    composite_score: typia.random<number>(),
  };

  // 2. Create an analytics record (admin context assumed)
  const created = await api.functional.ai_ecommerce.mvTrendingProducts.post(
    connection,
    { body: analyticInput },
  );
  typia.assert(created);
  TestValidator.equals("product_id matches")(created.product_id)(analyticInput.product_id);
  TestValidator.equals("stat_period matches")(created.stat_period)(analyticInput.stat_period);
  TestValidator.equals("stat_date matches")(created.stat_date)(analyticInput.stat_date);
  TestValidator.equals("trend_rank matches")(created.trend_rank)(analyticInput.trend_rank);
  TestValidator.equals("sales_count matches")(created.sales_count)(analyticInput.sales_count);
  TestValidator.equals("views_count matches")(created.views_count)(analyticInput.views_count);
  TestValidator.equals("composite_score matches")(created.composite_score)(analyticInput.composite_score);

  // 3. Failure: missing required stat_date
  const missingStatDate = { ...analyticInput };
  delete (missingStatDate as any).stat_date;
  await TestValidator.error("missing stat_date should fail")(
    () => api.functional.ai_ecommerce.mvTrendingProducts.post(connection, { body: missingStatDate as any }),
  );

  // 4. Failure: missing required trend_rank
  const missingTrendRank = { ...analyticInput };
  delete (missingTrendRank as any).trend_rank;
  await TestValidator.error("missing trend_rank should fail")(
    () => api.functional.ai_ecommerce.mvTrendingProducts.post(connection, { body: missingTrendRank as any }),
  );

  // 5. Failure: duplicate record insertion
  await TestValidator.error("duplicate insertion should fail")(
    () => api.functional.ai_ecommerce.mvTrendingProducts.post(connection, { body: analyticInput }),
  );

  // 6. Failure: invalid foreign key (non-existent product_id)
  const badProductId = { ...analyticInput, product_id: typia.random<string & tags.Format<"uuid">>() };
  await TestValidator.error("invalid product_id should fail")(
    () => api.functional.ai_ecommerce.mvTrendingProducts.post(connection, { body: badProductId }),
  );

  // 7. Failure: invalid stat_period (nonsense value)
  const badPeriod = { ...analyticInput, stat_period: "nonsense_period" };
  await TestValidator.error("invalid stat_period should fail")(
    () => api.functional.ai_ecommerce.mvTrendingProducts.post(connection, { body: badPeriod }),
  );

  // 8. Failure: invalid stat_date (bad format)
  const badDate = { ...analyticInput, stat_date: "bad-date" };
  await TestValidator.error("invalid stat_date should fail")(
    () => api.functional.ai_ecommerce.mvTrendingProducts.post(connection, { body: badDate }),
  );

  // Note: Non-admin privilege check could be performed if account context controls were provided in API.
}

