import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 권한(Permission) 목록을 필터(이름에 'order' 포함)와 페이징(page=2, size=10)으로 성공적으로 조회하는 시나리오 검증
 *
 * - 관리자 권한 계정이 유효한 커넥션으로 PATCH 호출
 * - 'order'가 포함된 이름의 권한만 반환되는지 확인
 * - 페이지네이션 메타(현재 페이지, limit, 전체 records, 전체 pages)가 정확하게 반환되는지 확인
 * - 실패 케이스(존재하지 않는 이름: 'xxxxxxxxx')는 빈 data와 records=0 반환
 *
 * 순서:
 * 1. 필터 조건(name: 'order')과 페이징(page 2, size 10) 변수 준비
 * 2. 패치 API 호출 후 결과 목록 확인 및 각 권한 name에 'order' 포함되는지 개별 검증
 * 3. 페이지네이션 메타: current=2, limit=10, records/pages ≥ 0 등 체크
 * 4. 실패 케이스: 존재하지 않는 name(예: 'xxxxxxxxx')로 empty data, records=0 확인
 */
export async function test_api_ai_ecommerce_permissions_test_list_permissions_with_valid_filters_and_pagination(connection: api.IConnection) {
  // 1. (filter 준비)
  const filter = { name: 'order' } satisfies ai_ecommerce_permission.IRequest;
  const page = 2;
  const limit = 10;

  // 2. (API 호출 및 결과 확인)
  const result = await api.functional.ai_ecommerce.permissions.patch(connection, {
    body: filter,
  });
  typia.assert(result);

  // 2-1. (data 검증) 모든 권한 name에 'order'가 포함되는지 개별 확인
  for (const perm of result.data)
    TestValidator.predicate("name contains order")(perm.name.includes("order"));

  // 3. (페이지네이션 메타 검증)
  TestValidator.equals("페이지 번호")(result.pagination.current)(page);
  TestValidator.equals("페이지 크기")(result.pagination.limit)(limit);
  TestValidator.predicate("결과 수 0 이상 10 이하")(result.data.length >= 0 && result.data.length <= limit);
