  //    - 본 테스트는 negative(권한 없음) 상태의 검증이기 때문에, 인증/인가 시나리오에 따라 유효한 ID만 확보
  const created: ai_ecommerce_permission = await api.functional.ai_ecommerce.permissions.post(connection, {
    body: {
      name: `negative.e2e.${RandomGenerator.alphabets(8)}`,
