  // 2. (권한 없는 상태) Permission 상세조회 시도 → 인가 없는 사용자(혹은 비인증)에서 동작해야 함
  // 실제 테스트 환경에서 권한 없는 connection context로 대체 필요
  // 2-1. 유효한 ID로 접근 시도
  await TestValidator.error("권한 없는 사용자의 GET /ai_ecommerce/permissions/:id 접근 시 Forbidden/Unauthorized이어야 함")(
    async () => {
      await api.functional.ai_ecommerce.permissions.getById(connection, {
        id: created.id,
      });
    },
  );
  // 2-2. 무작위 UUID로 접근 시도
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("권한 없는 사용자의 임의 UUID Permission 접근도 마찬가지로 거절되어야 함")(
    async () => {
      await api.functional.ai_ecommerce.permissions.getById(connection, {
        id: randomId,
      });
    },
  );
}

