 * 관리자 권한을 가진 사용자가 POST 요청을 통해 새로운 permission을 등록할 때,
 * 고유한 name(필수)과 description(선택, 한글 설명 등)을 포함한 데이터로 요청합니다.
 *
 * 서비스는 다음을 보장해야 합니다:
 * - name의 유일성 보장 (동일 name 불가)
 * - description은 null, undefined, 한글/영문 등 다양한 값 허용
 * - 생성된 permission 엔티티는 id(UUID), name, description, created_at(타임스탬프) 등 전체 정보를 반환
 *
 * 1. name, description 모두 유효한 데이터로 신규 권한 생성 요청
 * 2. 응답 결과의 id, name, description, created_at 필드 모두 유효 형태, 내용으로 반환
 * 3. id는 UUID 포맷, created_at은 ISO date-time 포맷
 * 4. description이 없는 경우(null/생략 포함), 생성 성공(별도 케이스 커버)
 */
export async function test_api_ai_ecommerce_permissions_post_create_permission_with_unique_name_and_valid_data(
  connection: api.IConnection,
) {
  // 1. 고유한 name/description으로 신규 권한 생성
  const uniqueName: string = `perm_${RandomGenerator.alphaNumeric(12)}`;
  const description: string = `테스트 권한 - ${RandomGenerator.paragraph()(10)}`;
  const created = await api.functional.ai_ecommerce.permissions.post(connection, {
    body: { name: uniqueName, description } satisfies ai_ecommerce_permission.ICreate,
  });
  typia.assert(created);

  // 2. 반환 정보 검증
  TestValidator.equals("name 일치")(created.name)(uniqueName);
  TestValidator.equals("description 일치")(created.description)(description);
  TestValidator.predicate("id는 UUID 포맷, 비어있지 않음")(!!created.id && /^[0-9a-fA-F\-]{36}$/.test(created.id));
  TestValidator.predicate("생성시각 ISO date-time")(!!created.created_at && !isNaN(Date.parse(created.created_at)));

  // 3. description 미입력 케이스도 문제 없이 생성
  const nameNoDesc = `perm_${RandomGenerator.alphaNumeric(12)}`;
  const createdNoDesc = await api.functional.ai_ecommerce.permissions.post(connection, {
    body: { name: nameNoDesc } satisfies ai_ecommerce_permission.ICreate,
  });
  typia.assert(createdNoDesc);
  TestValidator.equals("name만 입력했을 때 name 일치")(createdNoDesc.name)(nameNoDesc);
  // description이 undefined 또는 null로 반환될 수 있음 (스키마상)
  TestValidator.predicate("description은 undefined, null, 혹은 빈 문자열 아님")(createdNoDesc.description === undefined || createdNoDesc.description === null || typeof createdNoDesc.description === "string");
  TestValidator.predicate("id, created_at도 정상")(!!createdNoDesc.id && /^[0-9a-fA-F\-]{36}$/.test(createdNoDesc.id) && !!createdNoDesc.created_at && !isNaN(Date.parse(createdNoDesc.created_at)));
}

