 *
 * Note: Based on provided DTOs, description cannot be updated via PUT; only name is permitted to change.
 * This test verifies that attempting to update (by only changing name or leaving unchanged) leaves description untouched.
 */
export async function test_api_ai_ecommerce_permissions_test_update_permission_description_as_admin(
  connection: api.IConnection,
) {
  // 1. Create a new permission entity
  const permissionName = RandomGenerator.alphaNumeric(10);
  const permissionDesc = RandomGenerator.paragraph()(1);
  const created = await api.functional.ai_ecommerce.permissions.post(connection, {
    body: {
      name: permissionName,
      description: permissionDesc,
    } satisfies ai_ecommerce_permission.ICreate,
  });
  typia.assert(created);

  // 2. Update this permission's description with a new valid string.
  // But IUpdate DTO only allows name update, so pass unchanged name (no effect on description).
  const updated = await api.functional.ai_ecommerce.permissions.putById(connection, {
    id: created.id,
    body: {
      name: created.name,
    } satisfies ai_ecommerce_permission.IUpdate,
  });
  typia.assert(updated);

  // 3. Validate: Only name is updatable; description must remain unchanged.
  TestValidator.equals("permission id unchanged")(updated.id)(created.id);
  TestValidator.equals("permission name unchanged")(updated.name)(created.name);
  TestValidator.equals("permission description unchanged")(updated.description)(created.description);
  TestValidator.equals("permission created_at unchanged")(updated.created_at)(created.created_at);
}

