 *
 * 이 테스트는 두 개의 Permission을 순차적으로 생성한 뒤, 두 번째 Permission의 이름을 첫 번째 Permission과 중복되게 변경(Update) 시도할 때 시스템의 유일성 제약(Unique Constraint) 정책을 검증한다.
 *
 * [비즈니스 배경]
 * RBAC 정책에서 Permission name은 고유해야 하며, 이미 존재하는 이름으로의 갱신 시도는 오류로 반환되어야 한다.
 *
 * [테스트 시나리오]
 * 1. 첫 번째 Permission(name1) 생성
 * 2. 두 번째 Permission(name2) 생성
 * 3. 두 번째 Permission의 name을 name1로 변경 시도(유일성 위반 → 시스템 오류 발생 기대)
 *
 * @param connection API 연결 정보 (인증 context)
 */
export async function test_api_ai_ecommerce_permissions_test_update_permission_with_duplicate_name(
  connection: api.IConnection,
) {
  // 1. 첫 번째 Permission 생성
  const name1 = RandomGenerator.alphabets(10) + "-A";
  const permission1 = await api.functional.ai_ecommerce.permissions.post(connection, {
    body: {
      name: name1,
      description: RandomGenerator.paragraph()(),
    } satisfies ai_ecommerce_permission.ICreate,
  });
  typia.assert(permission1);

  // 2. 두 번째 Permission 생성
  const name2 = RandomGenerator.alphabets(10) + "-B";
  const permission2 = await api.functional.ai_ecommerce.permissions.post(connection, {
    body: {
      name: name2,
      description: RandomGenerator.paragraph()(),
    } satisfies ai_ecommerce_permission.ICreate,
  });
  typia.assert(permission2);

  // 3. 두 번째 Permission의 name을 첫 번째 Permission의 name으로 변경 시도 → 유일성 정책 위반 오류 반환 기대
  await TestValidator.error("permission name 중복 update 시 오류 발생해야 함")(() =>
    api.functional.ai_ecommerce.permissions.putById(connection, {
      id: permission2.id,
      body: { name: name1 } satisfies ai_ecommerce_permission.IUpdate,
    })
  );
}

