import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceAdministrator";
import type { IModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationAction";
import type { IPageIModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIModerationAction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test: Moderation Actions List (PATCH - /ai_ecommerce/moderationActions)
 *
 * Validates listing, filtering, paging, and permission checks for moderation action records.
 *
 * Business context & necessity:
 * - Moderation action logs underpin regulatory audit, internal review, and admin analytics. Reliable listing and filtering ensures tools show correct, compliant data.
 *
 * Steps:
 * 1. Create administrator accounts (minimum 2, with distinct profile_id).
 * 2. Create multiple moderation actions by these admins, covering comment, review, thread as targets, several action_types, rationale values, reversed status.
 * 3. Execute PATCH /ai_ecommerce/moderationActions for:
 *    a. No filters: all records (default paging)
 *    b. Filter by administrator_id
 *    c. Filter by action_type
 *    d. Filter by target_comment_id, target_review_id, target_thread_id
 *    e. Filter by reversed (true/false)
 *    f. Filter by rationale keyword
 *    g. Filter by created_at_from / to (date window)
 *    h. Maximum page size (limit boundary)
 *    i. Invalid filter (schema violation - runtime error expectation)
 *    j. Permission edge (unknown admin_id - expect logical error)
 * 4. Assert pagination metadata, that filter is respected, and only permitted records are shown
 * 5. Validate error responses for schema mismatch and permission breach
 */
export async function test_api_ai_ecommerce_test_list_moderation_actions_with_complex_filtering_and_pagination(
  connection: api.IConnection,
) {
  // 1. Provision 2 distinct admin accounts
  const adminA = await api.functional.ai_ecommerce.administrators.post(connection, {
    body: {
      profile_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(adminA);
  const adminB = await api.functional.ai_ecommerce.administrators.post(connection, {
    body: {
      profile_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(adminB);

  // 2. Create moderation actions for all filter axes
  const commentTarget = typia.random<string & tags.Format<"uuid">>();
  const reviewTarget = typia.random<string & tags.Format<"uuid">>();
  const threadTarget = typia.random<string & tags.Format<"uuid">>();

  const delete_comment = await api.functional.ai_ecommerce.moderationActions.post(connection, {
    body: {
      administrator_id: adminA.id,
      comment_id: commentTarget,
      action_type: "delete",
      rationale: "Delete spam comment",
    },
  });
  typia.assert(delete_comment);

  const block_review = await api.functional.ai_ecommerce.moderationActions.post(connection, {
    body: {
      administrator_id: adminB.id,
      review_id: reviewTarget,
      action_type: "block",
      rationale: "Block abusive review",
    },
  });
  typia.assert(block_review);

  const warn_thread = await api.functional.ai_ecommerce.moderationActions.post(connection, {
    body: {
      administrator_id: adminA.id,
      thread_id: threadTarget,
      action_type: "warn",
      rationale: "Warn for off-topic",
    },
  });
  typia.assert(warn_thread);

  const revert_comment = await api.functional.ai_ecommerce.moderationActions.post(connection, {
    body: {
      administrator_id: adminB.id,
      comment_id: commentTarget,
      action_type: "revert",
      rationale: "Revert action incorrectly applied",
    },
  });
  typia.assert(revert_comment);

  const manual_delete_review = await api.functional.ai_ecommerce.moderationActions.post(connection, {
    body: {
      administrator_id: adminA.id,
      review_id: reviewTarget,
      action_type: "delete",
      rationale: "Manual moderation delete",
    },
  });
  typia.assert(manual_delete_review);

  // 3a. No filters (all moderation actions)
  const pageAll = await api.functional.ai_ecommerce.moderationActions.patch(connection, { body: {} });
  typia.assert(pageAll);
  TestValidator.predicate("should retrieve all moderation actions")(pageAll.data.length >= 5);
  TestValidator.predicate("pagination: minimum total records")(pageAll.pagination.records >= 5);

  // 3b. Filter by administrator_id
  const pageAdminA = await api.functional.ai_ecommerce.moderationActions.patch(connection, {
    body: { administrator_id: adminA.id },
  });
  typia.assert(pageAdminA);
  TestValidator.predicate("filter: all by adminA")(pageAdminA.data.every((a) => a.administrator_id === adminA.id));

  // 3c. Filter by action_type (delete)
  const pageDeleteType = await api.functional.ai_ecommerce.moderationActions.patch(connection, {
    body: { action_type: "delete" },
  });
  typia.assert(pageDeleteType);
  TestValidator.predicate("filter: only delete actions")(pageDeleteType.data.every((a) => a.action_type === "delete"));

  // 3d. Filter by target_comment_id
  const pageComment = await api.functional.ai_ecommerce.moderationActions.patch(connection, {
    body: { target_comment_id: commentTarget },
  });
  typia.assert(pageComment);
  TestValidator.predicate("filter: all target comment")(pageComment.data.every((a) => a.comment_id === commentTarget));

  //     ...by target_review_id
  const pageReview = await api.functional.ai_ecommerce.moderationActions.patch(connection, {
    body: { target_review_id: reviewTarget },
  });
  typia.assert(pageReview);
  TestValidator.predicate("filter: all target review")(pageReview.data.every((a) => a.review_id === reviewTarget));

  //     ...by target_thread_id
  const pageThread = await api.functional.ai_ecommerce.moderationActions.patch(connection, {
    body: { target_thread_id: threadTarget },
  });
  typia.assert(pageThread);
  TestValidator.predicate("filter: all target thread")(pageThread.data.every((a) => a.thread_id === threadTarget));

  // 3e. Filter by reversed: true
  const pageReversed = await api.functional.ai_ecommerce.moderationActions.patch(connection, {
    body: { reversed: true },
  });
  typia.assert(pageReversed);
  TestValidator.predicate("filter: all reversed")(pageReversed.data.every((a) => a.reversed === true));

  //     ...by reversed: false
  const pageNotReversed = await api.functional.ai_ecommerce.moderationActions.patch(connection, {
    body: { reversed: false },
  });
  typia.assert(pageNotReversed);
  TestValidator.predicate("filter: all not reversed")(pageNotReversed.data.every((a) => !a.reversed));

  // 3f. Filter by rationale (partial match)
  const pageRationale = await api.functional.ai_ecommerce.moderationActions.patch(connection, {
    body: { rationale: "spam" },
  });
  typia.assert(pageRationale);
  TestValidator.predicate("filter: rationale includes 'spam'")(pageRationale.data.some((a) => a.rationale.toLowerCase().includes("spam")));

  // 3g. Filter by created_at_from/to (window around delete_comment)
  const pageDateRange = await api.functional.ai_ecommerce.moderationActions.patch(connection, {
    body: {
      created_at_from: delete_comment.created_at,
      created_at_to: delete_comment.created_at,
    },
  });
  typia.assert(pageDateRange);
  TestValidator.predicate("filter: match by date")(pageDateRange.data.some((a) => a.id === delete_comment.id));

  // 3h. Maximum page size
