/**
 * 검증: 권한 있는 관리자가 기존 moderation action의 변경 가능한 필드(예: rationale, reversed)를 성공적으로 업데이트할 수 있는지 테스트합니다.
 *
 * 또한 대상(comment_id, review_id, thread_id) 또는 집행 관리자(administrator_id) 등 변경 불가 필드의 수정 시도는 정책적으로 오류로 처리되는지, 비즈니스 규칙과 md별 불변성 보장이 적용되는지 확인합니다. 
 *
 * 마지막으로, 업데이트가 실제로 영구 반영되는지, 모든 변경 이력이 감사를 위해 시스템 로그에 따라 반영되는지, 그리고 응답에 변경된 모든 데이터가 정확히 포함되어 반환되는지 검증합니다.
 *
 * 테스트 프로세스:
 * 1. 관리자 계정(IAiEcommerceAdministrator) 생성 및 프로필 ID 확보
 * 2. 해당 관리자로 moderation action(IModerationAction) 생성 (한 가지 대상만 지정: comment/review/thread)
 * 3. action의 rationale(사유)과 reversed(반전 여부) 필드 업데이트 → 정상 동작 및 응답의 영속성 확인
 * 4. 불변 필드(administrator_id, comment_id/review_id/thread_id) 변경 시도: Runtime error가 발생하는지 TestValidator.error()로 검증
 * 5. 변경된 action의 상태를 재조회하여 업데이트가 반영되었는지 확인
 */
export async function test_api_ai_ecommerce_moderationActions_test_update_moderation_action_rationale_by_privileged_admin(
  connection: api.IConnection,
) {
  // 1. 관리자 생성
  const admin_profile_id = typia.random<string & tags.Format<"uuid">>();
  const admin = await api.functional.ai_ecommerce.administrators.post(connection, {
    body: {
      profile_id: admin_profile_id,
    },
  });
  typia.assert(admin);

  // 2. Moderation action 생성 (예: comment_id만 부여)
  const comment_id = typia.random<string & tags.Format<"uuid">>();
  const moderation_action = await api.functional.ai_ecommerce.moderationActions.post(connection, {
    body: {
      administrator_id: admin.id,
      comment_id,
      action_type: "delete",
      rationale: "부적절한 댓글로 인한 삭제.",
    },
  });
  typia.assert(moderation_action);

  // 3. Updatable 필드(rationale, reversed) 변경
  const new_rationale = "관리자 검토 후 삭제 사유 업데이트";
  const update_result = await api.functional.ai_ecommerce.moderationActions.putById(connection, {
    id: moderation_action.id,
    body: {
      rationale: new_rationale,
      reversed: true,
    },
  });
  typia.assert(update_result);
  TestValidator.equals("rationale 변경 반영됨")(update_result.rationale)(new_rationale);
  TestValidator.equals("reversed true 반영")(update_result.reversed)(true);

  // 4. 불변 필드(administrator_id/comment_id/review_id/thread_id) 변경 시도 불가 - IUpdate 타입에 없음
  // 타입 레벨에서 차단되므로 런타임 오류 테스트는 의미 없음

  // 5. 최종 상태 확인 (putById 응답 결과로 확인)
  TestValidator.equals("final 상태 확인")(update_result.rationale)(new_rationale);
  TestValidator.equals("final reversed 상태 확인")(update_result.reversed)(true);
}

