 * - An unrelated, non-admin user must not be able to update the moderation action.
 * - The API returns 403 Forbidden when an unauthorized update is attempted.
 * - The moderation action record remains unchanged after the attempt.
 *
 * Test Workflow:
 * 1. Create an admin user profile (moderation actor)
 * 2. Create an unrelated, non-admin user profile
 * 3. Admin creates a moderation action
 * 4. Attempt to update the moderation action using the non-admin user's account
 * 5. Verify API returns 403 Forbidden (error)
 * 6. (If possible) Confirm no changes were made (not possible if no GET API)
 */
export async function test_api_ai_ecommerce_test_update_moderation_action_unauthorized_user_rejected(
  connection: api.IConnection,
) {
  // 1. Register admin profile (the legitimate moderation actor)
  const adminProfile = await api.functional.ai_ecommerce.userProfiles.post(
    connection,
