/**
 * 테스트 목적: 관리자가 모더레이션 액션을 소프트 삭제하는 엔드투엔드 시나리오 검증
 *
 * - 관리자 계정 사전 생성 및 유효한 profile_id 매핑 필요
 * - 유효한 moderation action record 직접 생성 (특정 comment_id, action_type, rationale 등 지정)
 * - 생성된 moderation action 을 삭제(Delete) 요청
 *   - 요청 이후 moderation action 의 deleted_at이 날짜로 세팅되어 있음을 검증
 *   - moderation action 레코드는 완전 삭제되지 않고 반환됨을 검증
 *   - 비즈니스 규칙상 일반 조회 시 정상적으로 필터되어 나오지 않음을 테스트하는 것은 별도의 쿼리 API 필요 (현재 미구현이므로 생략)
 *   - 삭제가 성공적으로 audit/compliance 로그에 기록되었는지는 로그 API 미제공 시 검증 생략
 * - 동일 record에 대해 2회 이상 삭제 요청시 idempotency 보장(첫 삭제시 이후는 deleted_at 변경 등 side effect 없어야 하며 동일 응답 반환)
 */
export async function test_api_ai_ecommerce_moderationActions_test_delete_moderation_action_soft_delete_by_admin(
  connection: api.IConnection,
) {
  // 1. 사전: 관리자를 생성한다 (profile_id는 실제 시스템에서 유효해야 하나 여기서는 placeholder 사용)
  const mockProfileId: string = typia.random<string & tags.Format<"uuid">>();

  const administrator = await api.functional.ai_ecommerce.administrators.post(connection, {
    body: {
      profile_id: mockProfileId,
    } satisfies IAiEcommerceAdministrator.ICreate,
  });
  typia.assert(administrator);

  // 2. 모더레이션 액션 생성 (관리자가 실행, comment_id만 임의 설정, action_type 등 지정)
  const mockCommentId: string = typia.random<string & tags.Format<"uuid">>();
  const action = await api.functional.ai_ecommerce.moderationActions.post(connection, {
    body: {
      administrator_id: administrator.id,
      comment_id: mockCommentId,
      action_type: "delete",
      rationale: "규정 위반 댓글로 판단되어 삭제 처리",
    } satisfies IModerationAction.ICreate,
  });
  typia.assert(action);
  TestValidator.equals("삭제 전 deleted_at 없음")(action.deleted_at)(null);

  // 3. moderationActions 삭제 요청
  const erased = await api.functional.ai_ecommerce.moderationActions.eraseById(connection, {
    id: action.id,
  });
  typia.assert(erased);
  TestValidator.equals("삭제 후 id 동일함")(erased.id)(action.id);
  TestValidator.predicate("삭제 후 deleted_at 이 날짜로 변경됨")(erased.deleted_at !== null && typeof erased.deleted_at === "string");

  // 4. 같은 moderationAction에 대해 다시 DELETE 요청 (idempotency)
  const erased2 = await api.functional.ai_ecommerce.moderationActions.eraseById(connection, {
    id: action.id,
  });
  typia.assert(erased2);
  TestValidator.equals("idempotent 삭제: id 같음")(erased2.id)(action.id);
  TestValidator.equals("idempotent 삭제: deleted_at 동일")(erased2.deleted_at)(erased.deleted_at);
}

