import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationAction";

/**
 * 존재하지 않거나 이미 삭제된 moderation action 삭제 시 404 반환 및 idempotency 검증
 *
 * 이 테스트는 moderation action의 삭제 API가 다음 비정상 상태를 올바르게 처리하는지 확인합니다.
 *   1. 존재하지 않는 moderation action id를 삭제 시도 시 404 Not Found를 반환
 *   2. 논리적으로 이미 삭제(deleted_at 할당된 상태)된 id를 반복 삭제 시 404 Not Found 및 idempotent(멱등) 보장
 *
 * 클린업 목적의 moderation action 생성/삭제 API가 없으므로, 랜덤 uuid를 활용해 실제로 존재하지 않는 id나 이미 삭제된 상태를 시뮬레이션합니다.
 * 만약 시스템에서 중복 삭제 등에 대해 상세 메시지를 보장하지 않는다면, 에러 발생 여부만 확인하며 error 객체 구조 파악은 생략합니다.
 *
 * 테스트 단계:
 * 1. 존재하지 않는 id (랜덤 uuid)로 삭제 시도시 404 에러 발생 확인
 * 2. 이미 삭제된 id (랜덤 uuid)로 2회 연속 삭제 시도 -> 모두 404 및 멱등 보장
 */
export async function test_api_ai_ecommerce_test_delete_moderation_action_returns_404_for_nonexistent_or_already_deleted(
  connection: api.IConnection,
) {
  // 1. 완전히 비존재하는 랜덤 uuid로 삭제 시도 → 404 에러여야 함
  const nonexistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("존재하지 않는 moderation action id → 404")(async () => {
    await api.functional.ai_ecommerce.moderationActions.eraseById(connection, { id: nonexistentId });
  });

  // 2. 논리적으로 이미 삭제된 moderation action (idempotency check): 같은 랜덤 uuid를 두 번 연속 삭제 시도
  const deletedId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("이미 삭제된 moderation action 첫 시도 → 404")(async () => {
    await api.functional.ai_ecommerce.moderationActions.eraseById(connection, { id: deletedId });
  });
  await TestValidator.error("이미 삭제된 moderation action 두 번째 시도 → 404")(async () => {
    await api.functional.ai_ecommerce.moderationActions.eraseById(connection, { id: deletedId });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
