import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceSnapshot";
import type { IPageIAiEcommerceSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiEcommerceSnapshot";

/**
 * Test retrieving a paginated, filtered list of personalization snapshots using valid filter criteria and pagination parameters.
 *
 * This test ensures:
 * - Only snapshots matching provided filters (customer_id, snapshot_type) are returned.
 * - Pagination metadata (page, limit) in the response is accurate.
 * - Filtering by known valid parameters yields expected, predictable results.
 * - Applying rare filter combinations yields an empty result set without error.
 * - (Within capability) Security boundaries are not breached—no cross-user data is retrieved.
 *
 * Steps:
 * 1. Create a snapshot that matches the filter criteria (customer_id, snapshot_type).
 * 2. Create a snapshot that does NOT match the planned filter (different customer_id or type).
 * 3. Retrieve paginated snapshot list using filters that only match the first record; verify it is present, and properties/paging metadata are correct.
 * 4. Try a rare filter combination (snapshot_type that does not exist for this customer): verify the result set is empty but no errors are thrown, and pagination info is still correct.
 * 5. (If supported) Security: No attempt to cross security boundaries, as API does not expose user/role endpoints or allow for such simulation here.
 */
export async function test_api_ai_ecommerce_test_list_personalization_snapshots_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a snapshot that matches the intended filter
  const matchingSnapshot = await api.functional.ai_ecommerce.snapshots.post(connection, {
    body: {
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      snapshot_type: "favorites",
      taken_at: new Date().toISOString(),
      blob_uri: "https://s3.example.com/snapshot1.bin",
    } satisfies IAiEcommerceSnapshot.ICreate,
  });
  typia.assert(matchingSnapshot);

  // 2. Create another snapshot intentionally not matching the test filter
  const nonMatchingSnapshot = await api.functional.ai_ecommerce.snapshots.post(connection, {
    body: {
      customer_id: typia.random<string & tags.Format<"uuid">>(), // different customer_id
      snapshot_type: "settings",
      taken_at: new Date().toISOString(),
      blob_uri: "https://s3.example.com/snapshot2.bin",
    } satisfies IAiEcommerceSnapshot.ICreate,
  });
  typia.assert(nonMatchingSnapshot);

  // 3. List using filter to retrieve only the matching snapshot
  const page = await api.functional.ai_ecommerce.snapshots.patch(connection, {
    body: {
      customer_id: matchingSnapshot.customer_id,
      snapshot_type: matchingSnapshot.snapshot_type,
      limit: 10,
      offset: 0,
    } satisfies IAiEcommerceSnapshot.IRequest,
  });
  typia.assert(page);

  // 4. Validate that exactly the matching snapshot(s) are returned
  TestValidator.predicate("only matching snapshot(s) are returned")(
    page.data.length >= 1 && page.data.some((s) => s.id === matchingSnapshot.id)
  );
  TestValidator.equals("customer_id matches")(page.data[0].customer_id)(matchingSnapshot.customer_id);
  TestValidator.equals("snapshot_type matches")(page.data[0].snapshot_type)(matchingSnapshot.snapshot_type);

  // 5. Validate pagination metadata
  TestValidator.equals("page number should be 1")(page.page)(1);
  TestValidator.equals("limit matches query")(page.limit)(10);

  // 6. Attempt rare+unmatched filter (should return empty result, no error)
  const emptyPage = await api.functional.ai_ecommerce.snapshots.patch(connection, {
    body: {
      customer_id: matchingSnapshot.customer_id,
      snapshot_type: "non-existent-type",
      limit: 10,
      offset: 0,
    } satisfies IAiEcommerceSnapshot.IRequest,
  });
  typia.assert(emptyPage);
  TestValidator.equals("empty result set")(emptyPage.data.length)(0);
}

