 *    - Validate: No record is created, error is thrown.
 * 2. Attempt to create a snapshot using a completely invalid customer_id (does not exist in DB).
 *    - Expect: 403 Forbidden or 400 Bad Request (depending on business logic).
 *    - Validate: Error thrown, no record is created.
 * 3. Attempt to create a snapshot with an unrecognized snapshot_type (e.g. "___INVALID___").
 *    - Expect: 400 Bad Request.
 *    - Validate: Error thrown, no record is created.
 * 4. Successfully create a valid snapshot.
 *    - Expect: 201 Created, valid snapshot record returned.
 * 5. Re-submit the exact same payload as in #4 (should trigger duplicate prevention logic).
 *    - Expect: 409 Conflict (or appropriate error for duplicate), no new record created.
 *    - Validate: Error thrown, only a single record exists for that snapshot.
 *
 * All error scenarios should keep transactional state clean (no partial or extra records created after failure).
 */
export async function test_api_ai_ecommerce_test_create_personalization_snapshot_with_invalid_or_duplicate_data(connection: api.IConnection) {
