  await TestValidator.error("nonexistent customer triggers 400/403")(() =>
    api.functional.ai_ecommerce.snapshots.post(connection, {
      body: {
        customer_id: "bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb",
        snapshot_type: "favorites",
        taken_at: new Date().toISOString(),
        blob_uri: "s3://valid-bucket/snapshot-xyz"
      } satisfies IAiEcommerceSnapshot.ICreate
    })
  );

  // 3. Create with unrecognized snapshot_type
  await TestValidator.error("invalid snapshot_type triggers 400")(() =>
    api.functional.ai_ecommerce.snapshots.post(connection, {
      body: {
        customer_id: typia.random<string & tags.Format<"uuid">>(),
        snapshot_type: "___INVALID___",
        taken_at: new Date().toISOString(),
        blob_uri: "s3://valid-bucket/snapshot-abc"
      } satisfies IAiEcommerceSnapshot.ICreate
    })
  );

  // 4. Successfully create a valid snapshot
  const payload: IAiEcommerceSnapshot.ICreate = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    snapshot_type: "favorites",
