/**
 * Test updating mutable fields of a personalization snapshot by ID (blob_uri update).
 *
 * This test simulates a realistic business case where a user or admin updates the blob_uri of a personalization snapshot record.
 * Immutable fields (id, customer_id, snapshot_type, taken_at) must not be changed; only blob_uri, as defined by the update DTO, is mutable.
 *
 * Workflow:
 * 1. Create an initial personalization snapshot via POST endpoint.
 * 2. Update the snapshot's blob_uri via PUT endpoint.
 * 3. Assert that only blob_uri has changed and all other fields are unchanged.
 * 4. Verify strict type safety and immutability constraints.
 */
export async function test_api_ai_ecommerce_snapshots_test_update_personalization_snapshot_with_valid_update(
  connection: api.IConnection,
) {
  // 1. Create an initial snapshot
  const createInput: IAiEcommerceSnapshot.ICreate = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
