import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceSnapshot";

/**
 * 유효하지 않은 데이터 변경 또는 권한 없는 사용자의 시도에 대해 AI 개인화 스냅샷 업데이트의 거부 동작을 검증합니다.
 *
 * 비즈니스 맥락: ai_ecommerce_snapshots의 entity는 customer_id, snapshot_type, taken_at 필드가 불변(immutable)이어야 하며, 유일하게 blob_uri만 수정 가능합니다.
 *   또한, 권한이 없는 사용자가 수정하거나, 요청 형식이 올바르지 않은 경우(예: blob_uri의 잘못된 포맷), API는 적절한 400 혹은 403 에러로 거절해야 하며 실제 데이터가 변하지 않아야 합니다.
 *
 * 테스트 시나리오:
 * 1. 베이스라인 스냅샷을 생성합니다.
 * 2. (성공 케이스) blob_uri만 정상적으로 변경하여 업데이트가 허용됨을 확인합니다.
 * 3. (실패 케이스1) 불변 필드 변경 시도는 타입상 compile error로 인해 E2E에서 SKIP (IUpdate에 지원하지 않음)
 * 4. (실패 케이스2) 잘못된 포맷(blob_uri가 빈 문자열 등)에 대한 400 에러를 검증합니다.
 * 5. (실패 케이스3) 권한 없는 사용자가 업데이트 시도시 403 에러를 검증(가능한 경우, 해당 인증 로직이 없는 본 예시는 SKIP)
 * 6. 실패 케이스 이후, 스냅샷에 변화가 없는지(원본 값과 동일한지) 확인합니다.
 */
export async function test_api_ai_ecommerce_snapshots_test_update_personalization_snapshot_with_invalid_data_or_permissions(
  connection: api.IConnection,
) {
  // 1. 베이스라인 스냅샷 생성
  const createInput: IAiEcommerceSnapshot.ICreate = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    snapshot_type: "favorites",
    taken_at: new Date().toISOString(),
    blob_uri: `https://storage.example.com/snapshots/${typia.random<string & tags.Format<"uuid">>()}.bin`,
  };
  const baseline: IAiEcommerceSnapshot = await api.functional.ai_ecommerce.snapshots.post(connection, { body: createInput });
  typia.assert(baseline);

  // 2. (성공) blob_uri 정상 업데이트
  const updateInput: IAiEcommerceSnapshot.IUpdate = {
    blob_uri: `https://storage.example.com/snapshots/${typia.random<string & tags.Format<"uuid">>()}.bin`,
  };
  const updated: IAiEcommerceSnapshot = await api.functional.ai_ecommerce.snapshots.putById(connection, { id: baseline.id, body: updateInput });
  typia.assert(updated);
  TestValidator.equals("blob_uri updated")(updated.blob_uri)(updateInput.blob_uri);

  // 3. (실패1) 불변 필드 변경 시도는 타입상 compile error로 인해 E2E에서 SKIP (IUpdate에 지원하지 않음)
  // (실제 IUpdate에는 customer_id, taken_at 등 필드가 없어 타입상 전달 불가)

  // 4. (실패2) 잘못된 blob_uri(빈 문자열) - 400 에러
  await TestValidator.error("잘못된 blob_uri - 빈 문자열 - 400 에러")(() =>
    api.functional.ai_ecommerce.snapshots.putById(connection, {
      id: baseline.id,
      body: { blob_uri: "" },
    })
  );

  // 5. (실패3) 권한 없는 사용자는 별도 인증/권한 API 없으므로 SKIP

  // 6. 실패 케이스 이후, blob_uri가 변동 없이 최신값(성공 케이스 반영) 유지되는지 체크
  const after: IAiEcommerceSnapshot = await api.functional.ai_ecommerce.snapshots.putById(connection, {
    id: baseline.id,
    body: {}, // 변경 없음 => blob_uri 그대로
  });
  typia.assert(after);
  TestValidator.equals("blob_uri unchanged after failed attempts")(after.blob_uri)(updated.blob_uri);
}

