 * 1. Create a product to ensure there is a valid catalog item and seller reference.
 * 2. Create a SKU for that product to be referenced in order items.
 * 3. Create an order (simulate a customer with all required foreign keys, e.g., customer, cart, address), supplying items inline as part of creation.
 * 4. Optionally, create another order with an item for negative verification.
 * 5. Issue a search (patch) on orderItems with filters for order_id and sku_id and pagination (limit/offset).
 * 6. Assert that the returned items all match the filter criteria: correct order_id, correct sku_id, correct quantity, and are within the expected page.
 * 7. Validate pagination meta (total_count, etc.) and that no out-of-scope items are present.
 */
export async function test_api_ai_ecommerce_orderItems_test_search_order_items_with_valid_filter(connection: api.IConnection) {
  // 1. Create product
  const seller_id = typia.random<string & tags.Format<"uuid">>();
