    body: {
      customer_id,
      cart_id,
      shipping_address_id,
      order_status: "pending",
      items: [
        { sku_id: sku.id, quantity: quantityA },
        { sku_id: sku.id, quantity: quantityB },
      ],
    } satisfies IAiEcommerceOrder.ICreate,
  });
  typia.assert(order);

  // 4. Optionally, create another order and item for negative verification
