      ],
    } satisfies IAiEcommerceOrder.ICreate,
  });
  typia.assert(otherOrder);

  // 5. Search for order items, filtered by order_id and sku_id, with pagination
  const limit = 1;
  const offset = 0;
  const searchResult = await api.functional.ai_ecommerce.orderItems.patch(connection, {
    body: {
