 * 2. SKU(ai_ecommerce_skus) 생성
 * 3. SKU id로 주문아이템(ai_ecommerce_order_item) 생성 및 검증 (order_id는 DTO상 사용 불가)
 * 4. quantity=0 등 허용되지 않는 값은 실패(error)를 잘 내는지 검증
 */
export async function test_api_ai_ecommerce_orderItems_test_create_order_item_with_valid_data(
