  const skuCreate: ai_ecommerce_skus.ICreate = {
    product_id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphaNumeric(8),
    price: 9900,
    currency: "KRW",
    is_active: true,
  };
