  // 3. 주문아이템 생성(정상케이스): IAiEcommerceOrderItem.ICreate에는 order_id 필드가 없으므로 사용 불가
  const orderItemCreate: IAiEcommerceOrderItem.ICreate = {
    sku_id: sku.id,
    quantity: 3,
  };
  const orderItem = await api.functional.ai_ecommerce.orderItems.post(connection, {
