  );

  // 4. 에러케이스: 수량 0 입력 시 실패 (order_id없이 시도)
  await TestValidator.error("quantity가 0이면 실패해야 함")(
    async () => {
      await api.functional.ai_ecommerce.orderItems.post(connection, {
        body: { sku_id: sku.id, quantity: 0 },
      });
    },
  );
}

