 * 2. Create an order referencing minimal required resources. Actual creation APIs for product, customer, cart, or address are not available, so random valid UUIDs are used.
 * 3. Create an order item linked to that SKU and order.
 * 4. Update the order item's quantity to a new valid number using the API.
 * 5. Assert the response contains the new quantity, unchanged SKU and item id, and type safety is ensured for the response.
 */
export async function test_api_ai_ecommerce_orderItems_test_update_order_item_quantity_success(
  connection: api.IConnection,
) {
  // 1. Register a valid SKU for use in the order item
  const productId = typia.random<string & tags.Format<"uuid">>();
  const sku = await api.functional.ai_ecommerce.skus.post(connection, {
    body: {
      product_id: productId,
      code: RandomGenerator.alphaNumeric(8),
      price: 3000,
      currency: "USD",
      is_active: true,
    } satisfies ai_ecommerce_skus.ICreate,
  });
