/**
 * 상품 태그 상세 조회 성공 케이스 검증
 *
 * - 유효한 상품 태그의 UUID로 상세 정보를 요청하면, id, name, created_at만 정확히 반환되는지 검증한다.
 * - 태그 생성 후 곧바로 상세조회를 통해 생성 정보와의 정합성, 타입 안전, 불필요/민감 정보 노출 위험이 없는지 등 실무 정책을 모두 점검한다.
 * - 보안/권한 정책은 현재 퍼블릭 플로우(제약 없음)이므로 생략하나, 이후 내부용 등 확장시 이 플로우를 기반으로 검증 추가 필요.
 *
 * 1. 신규 태그를 생성한다.
 * 2. 생성한 태그의 UUID로 상세 조회를 수행한다.
 * 3. 필수 필드(id, name, created_at)만 응답되고 그 값이 일치하는지 검증한다.
 * 4. 그 외 불필요/민감 필드가 추가로 딸려오지 않는지 구조적으로 체크한다.
 */
export async function test_api_ai_ecommerce_productTags_test_get_product_tag_detail_successfully_when_tag_exists(
  connection: api.IConnection,
) {
  // 1. 신규 태그 생성
  const tagName = `TestTag_${RandomGenerator.alphaNumeric(7)}`;
  const createdTag = await api.functional.ai_ecommerce.productTags.post(connection, {
    body: { name: tagName } satisfies ai_ecommerce_product_tags.ICreate,
  });
  typia.assert(createdTag);

  // 2. 해당 id로 상세 조회
  const fetchedTag = await api.functional.ai_ecommerce.productTags.getById(connection, {
    id: createdTag.id,
  });
  typia.assert(fetchedTag);

  // 3. 값 정합성 및 필수 필드 검증
  TestValidator.equals("tag id")(fetchedTag.id)(createdTag.id);
  TestValidator.equals("tag name")(fetchedTag.name)(tagName);
  TestValidator.equals("tag created_at")(fetchedTag.created_at)(createdTag.created_at);

  // 4. 응답에서 의도치 않은 필드 유출이 없는지(정확히 3개) 구조 체크
  TestValidator.equals("tag property keys")(Object.keys(fetchedTag).sort())(["created_at", "id", "name"].sort());
}

