import type { ai_ecommerce_product_tags } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_product_tags";

/**
 * 상품 태그를 신규로 정상 생성하고, 비즈니스 규약에 맞는 중복 및 필드 유출 제어까지 검증
 *
 * 본 테스트는 ai_ecommerce_product_tags 엔터티의 create API에 대해 '해피 패스' 정상 생성과 중복 방지 비즈니스 룰,
 * 응답 필드 보안성을 E2E 수준에서 종합적으로 점검한다.
 *
 * 테스트 절차
 * 1. 랜덤·유니크 상품 태그명을 입력해 정상 생성 요청 수행 (name 50자 이내, null/공백X)
 * 2. 반환값에서 name, id(UUID), created_at(ISO8601) 등 필드 유효성 및 입력값 일치 확인
 * 3. 동일 name 재시도로 중복 에러 유발, 비즈니스 중복불가 정책 효력 검증
 * 4. 응답에 name/id/created_at 외의 필드 유출/노출이 없는지 확인 (스키마 외 필드 없음)
 */
export async function test_api_ai_ecommerce_productTags_test_create_product_tag_with_valid_data(
  connection: api.IConnection,
) {
  // 1. 유니크한 상품 태그명 생성 및 create 요청
  const tagName = `tag_${RandomGenerator.alphaNumeric(16)}`;
  const created = await api.functional.ai_ecommerce.productTags.post(connection, {
    body: {
      name: tagName,
    } satisfies ai_ecommerce_product_tags.ICreate,
  });
  typia.assert(created);

  // 2. 반환 필드 유효성 검증: name == tagName, id UUID, created_at ISO 8601
