  TestValidator.predicate("id는 UUID")(typeof created.id === "string" && /^[a-f0-9\-]{36}$/i.test(created.id));
  TestValidator.predicate("created_at은 ISO 8601")(typeof created.created_at === "string" && !isNaN(Date.parse(created.created_at)));

  // 3. 중복 name 생성 시 비즈니스 에러 발생 확인
  await TestValidator.error("태그명 중복 생성 불가")(
    async () => {
      await api.functional.ai_ecommerce.productTags.post(connection, {
        body: {
          name: tagName,
        } satisfies ai_ecommerce_product_tags.ICreate,
      });
    },
  );

  // 4. 응답 필드 유출 방지 - name/id/created_at 외 불필요한 데이터 없음 검증
  const keys = Object.keys(created).sort();
