/**
 * 상품 태그 이름을 기존 다른 태그 이름으로 변경하려 시도할 때의 중복 방지 검증을 수행합니다.
 *
 * 이 테스트는 다음을 검증합니다:
 * 1. 서로 다른 이름으로 태그를 두 개(Alpha, Beta) 정상 생성 가능함
 * 2. 두 번째 태그(Beta)의 이름을 첫 번째 태그(Alpha) 이름으로 변경(PUT) 시도할 경우,
 *    시스템이 고유성(UK) 제약에 따라 중복을 거부하며, 적절한 에러(예: conflict/validation)를 반환함
 *
 * 비즈니스 운영상 중요한 태그명 중복 금지 측면의 핵심 시나리오입니다.
 *
 * 테스트 절차:
 * 1. "Alpha" 이름의 상품 태그 생성
 * 2. "Beta" 이름의 상품 태그 생성
 * 3. "Beta" 태그의 이름을 "Alpha"로 변경하는 업데이트 시도 (중복, 실패 기대)
 * 4. 각 태그가 정상적으로 생성되었는지와, 중복 업데이트가 거절(에러)되는지 확인
 */
export async function test_api_ai_ecommerce_productTags_test_update_product_tag_to_duplicate_name_rejected(
  connection: api.IConnection,
) {
  // 1. Alpha 태그 생성
  const tagAlpha = await api.functional.ai_ecommerce.productTags.post(connection, {
    body: { name: "Alpha" } satisfies ai_ecommerce_product_tags.ICreate,
  });
  typia.assert(tagAlpha);
  TestValidator.equals("tagAlpha name")(tagAlpha.name)("Alpha");

  // 2. Beta 태그 생성
  const tagBeta = await api.functional.ai_ecommerce.productTags.post(connection, {
    body: { name: "Beta" } satisfies ai_ecommerce_product_tags.ICreate,
  });
  typia.assert(tagBeta);
  TestValidator.equals("tagBeta name")(tagBeta.name)("Beta");

  // 3. Beta의 이름을 Alpha로 변경 (중복 시도 - 실패 기대)
  await TestValidator.error("duplicate tag name should be rejected")(async () => {
    await api.functional.ai_ecommerce.productTags.putById(connection, {
      id: tagBeta.id,
      body: { name: "Alpha" } satisfies ai_ecommerce_product_tags.IUpdate,
    });
  });
}

