import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrder";
import type { IAiEcommerceOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrderItem";
import type { IAiEcommerceOrderStatusLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrderStatusLog";
import type { IPageIAiEcommerceOrderStatusLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiEcommerceOrderStatusLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 주문 상태 로그 검색 및 필터/페이지네이션 E2E 검증 테스트.
 *
 * 주문 상태 이력(log) 리스트 API(/ai_ecommerce/orderStatusLogs PATCH)에서
 * 다음 주요 동작을 검증합니다:
 *
 * 1. 테스트용 주문을 생성하고(orders.post), 상태 변경 로그들을 최소 2건 등록합니다(orderStatusLogs.post).
 *
 * 2. 다양한 필터/조건(주문ID, 행위자ID, 상태, 날짜범위 등)으로 상태 로그를 패치 요청하고,
 *    - 전체 리스트(파라미터 없이)
 *    - order_id 단일 필터
 *    - actor_id/actor_type 복합 필터
 *    - old_status/new_status로 필터
 *    - 날짜 범위를 포함/제외하는 경우
 *    - page, limit 등 페이지네이션
 *    - 과한 page/limit 등 엣지케이스
 *   결과가 정확하게 반환되는지 검증합니다.
 *
 * 3. 타입불일치/포맷오류/허용범위 외 값(예: 잘못된 UUID, 음수 페이지 등) 입력시
 *    오류가 발생하는지도 테스트합니다.
 *
 * - 각 단계별로 typia.assert, TestValidator 등으로 타입 및 비즈니스 논리 검증을 수행합니다.
 * - 계정권한(Actor-Security)에 대한 직접적 권한 변경/통제 API가 없으므로,
 *   role별 data 노출 제한은 범위 내에서만 검증합니다.
 */
export async function test_api_ai_ecommerce_test_list_order_status_logs_with_pagination_and_filters(connection: api.IConnection) {
  // 1. 테스트 데이터: 주문 및 상태 로그 생성
  const order = await api.functional.ai_ecommerce.orders.post(connection, {
    body: typia.random<IAiEcommerceOrder.ICreate>()
  });
  typia.assert(order);
  // 두 건의 상태 변경 로그 추가
  const log1 = await api.functional.ai_ecommerce.orderStatusLogs.post(connection, {
    body: {
      order_id: order.id,
      old_status: "pending",
      new_status: "paid",
      actor_id: order.customer_id,
      actor_type: "customer",
      changed_at: new Date().toISOString()
    }
  });
  typia.assert(log1);
  const log2 = await api.functional.ai_ecommerce.orderStatusLogs.post(connection, {
    body: {
      order_id: order.id,
      old_status: "paid",
      new_status: "shipped",
      actor_id: order.customer_id,
      actor_type: "customer",
      changed_at: new Date(Date.now() + 1000).toISOString()
    }
  });
  typia.assert(log2);

  // 2. 필터 없이 전체 조회
  const resAll = await api.functional.ai_ecommerce.orderStatusLogs.patch(connection, {
    body: {}
  });
  typia.assert(resAll);
  TestValidator.predicate("생성한 로그 포함됨")(
    resAll.data.some(l => l.id === log1.id || l.id === log2.id)
  );

  // 3. order_id 필터
  const resByOrder = await api.functional.ai_ecommerce.orderStatusLogs.patch(connection, {
    body: { order_id: order.id }
  });
  typia.assert(resByOrder);
  TestValidator.predicate("order_id로만 필터")(
    resByOrder.data.every(l => l.order_id === order.id)
  );

  // 4. actor_id, actor_type 복합 필터
  const resByActor = await api.functional.ai_ecommerce.orderStatusLogs.patch(connection, {
    body: { actor_id: order.customer_id, actor_type: "customer" }
  });
  typia.assert(resByActor);
  TestValidator.predicate("actor 완전일치")(
    resByActor.data.every(l => l.actor_id === order.customer_id && l.actor_type === "customer")
  );

  // 5. 상태(값) old/new로 필터
  const resByStatus = await api.functional.ai_ecommerce.orderStatusLogs.patch(connection, {
    body: { old_status: "pending", new_status: "paid" }
  });
  typia.assert(resByStatus);
  TestValidator.predicate("상태 일치 로그만 반환")(
    resByStatus.data.every(l => l.old_status === "pending" && l.new_status === "paid")
  );

  // 6a. 날짜 범위: log2만 포함
  const from = log2.changed_at;
  const to = log2.changed_at;
  const resByDate = await api.functional.ai_ecommerce.orderStatusLogs.patch(connection, {
    body: { from, to }
  });
  typia.assert(resByDate);
  TestValidator.predicate("범위 내 log2만 존재")(
    resByDate.data.every(l => l.id === log2.id)
  );

  // 6b. 범위 제외(결과 없음)
  const yesterday = new Date(Date.now() - 24*3600*1000).toISOString();
  const resEmptyByDate = await api.functional.ai_ecommerce.orderStatusLogs.patch(connection, {
    body: { from: yesterday, to: yesterday }
  });
  typia.assert(resEmptyByDate);
  TestValidator.equals("결과 없음")(
    resEmptyByDate.data
  )([]);

  // 7a. 페이지번호 & limit
  const resPaging = await api.functional.ai_ecommerce.orderStatusLogs.patch(connection, {
    body: { page: 1, limit: 1 }
  });
  typia.assert(resPaging);
  TestValidator.equals("페이지 1")(
    resPaging.pagination.current
  )(1);
  TestValidator.equals("limit=1")(
    resPaging.pagination.limit
  )(1);
  TestValidator.predicate("최대 1건")(
    resPaging.data.length <= 1
  );

  // 7b. 마지막 페이지 넘어감
  const resExcessPage = await api.functional.ai_ecommerce.orderStatusLogs.patch(connection, {
    body: { page: 999, limit: 2 }
  });
  typia.assert(resExcessPage);
  TestValidator.equals("마지막page 넘어가면 empty")(
    resExcessPage.data
  )([]);

  // 7c. 과다 limit
  const resLargeLimit = await api.functional.ai_ecommerce.orderStatusLogs.patch(connection, {
    body: { limit: 9999, page: 1 }
  });
  typia.assert(resLargeLimit);
  TestValidator.predicate("시스템상 한도 이내")(
    resLargeLimit.data.length <= 9999
  );

  // 8a. 잘못된 UUID (order_id)
  await TestValidator.error("order_id 포맷오류 반려")(async () => {
    await api.functional.ai_ecommerce.orderStatusLogs.patch(connection, {
      body: { order_id: "NOT-A-UUID" as any }
    });
  });

  // 8b. 음수/0 page/limit 오류
  for (const [page, limit] of [[0,1],[1,0],[0,0]]) {
    await TestValidator.error("잘못된 page/limit 반려")(async () => {
      await api.functional.ai_ecommerce.orderStatusLogs.patch(connection, {
        body: { page: page as any, limit: limit as any }
      });
    });
  }

  // 8c. 허용 외 actor_type
  await TestValidator.error("actor_type 에러")(async () => {
    await api.functional.ai_ecommerce.orderStatusLogs.patch(connection, {
      body: { actor_type: "not-a-type" }
    });
  });

}

