/**
 * Test updating a wallet's active status (activate/deactivate) via PUT.
 *
 * This test validates the scenario of toggling the `is_active` status of a wallet
 * between active and inactive using the update endpoint. It covers the full flow:
 *
 * 1. Create a user profile (wallet owner)
 * 2. Create a wallet for that user
 * 3. Deactivate wallet via update and check state
 * 4. Reactivate wallet via update and check state
 * 5. Ensure only allowed fields (is_active/currency_code) are changed and other fields remain immutable
 *
 * Steps:
 * - Each update is followed by assertions to confirm state transitions.
 * - All relevant fields are checked for consistency across the updates.
 * - Coverage includes both activating and deactivating the wallet as well as a no-op update on currency_code.
 */
export async function test_api_ai_ecommerce_wallets_test_update_wallet_activate_and_deactivate(
  connection: api.IConnection,
) {
  // 1. Create a user profile to own the wallet
  const userProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true,
      avatar_uri: null,
      phone_number: null,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(userProfile);

  // 2. Create a wallet for that user
  const initialCurrency = "KRW";
  const wallet = await api.functional.ai_ecommerce.wallets.post(connection, {
    body: {
      customer_id: userProfile.id,
      currency_code: initialCurrency,
      is_active: true,
    } satisfies ai_ecommerce_wallet.ICreate,
  });
  typia.assert(wallet);
  TestValidator.equals("customer_id matches")(wallet.customer_id)(userProfile.id);
  TestValidator.equals("currency_code matches")(wallet.currency_code)(initialCurrency);
  TestValidator.equals("is_active is true")(wallet.is_active)(true);

  // 3. Deactivate the wallet
  const updatedInactive = await api.functional.ai_ecommerce.wallets.putById(connection, {
    id: wallet.id,
    body: { is_active: false } satisfies ai_ecommerce_wallet.IUpdate,
  });
  typia.assert(updatedInactive);
  TestValidator.equals("id unchanged")(updatedInactive.id)(wallet.id);
  TestValidator.equals("customer_id unchanged")(updatedInactive.customer_id)(wallet.customer_id);
  TestValidator.equals("currency_code unchanged")(updatedInactive.currency_code)(wallet.currency_code);
  TestValidator.equals("is_active is false")(updatedInactive.is_active)(false);

  // 4. Reactivate the wallet
  const updatedActive = await api.functional.ai_ecommerce.wallets.putById(connection, {
    id: wallet.id,
    body: { is_active: true } satisfies ai_ecommerce_wallet.IUpdate,
  });
  typia.assert(updatedActive);
  TestValidator.equals("id unchanged")(updatedActive.id)(wallet.id);
  TestValidator.equals("customer_id unchanged")(updatedActive.customer_id)(wallet.customer_id);
  TestValidator.equals("currency_code unchanged")(updatedActive.currency_code)(wallet.currency_code);
  TestValidator.equals("is_active is true again")(updatedActive.is_active)(true);

  // 5. Update currency_code to the same value (should not affect state or id/customer)
  const updateCurrency = await api.functional.ai_ecommerce.wallets.putById(connection, {
    id: wallet.id,
    body: { currency_code: initialCurrency } satisfies ai_ecommerce_wallet.IUpdate,
  });
  typia.assert(updateCurrency);
  TestValidator.equals("currency_code unchanged")(updateCurrency.currency_code)(initialCurrency);
  TestValidator.equals("is_active unchanged")(updateCurrency.is_active)(updatedActive.is_active);
  TestValidator.equals("customer_id unchanged")(updateCurrency.customer_id)(wallet.customer_id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
