/**
 * Validate that attempting to update immutable fields (customer_id, wallet id) fails for ai_ecommerce_wallet.
 *
 * Business context: Wallet records are permanently bound to their customer (customer_id) and wallet ID. These fields must remain immutable for security, ownership, and audit traceability. The API enforces this by only allowing currency_code and is_active to be changed via PUT /ai_ecommerce/wallets/{id}.
 *
 * Test process:
 * 1. Create a user profile (customer).
 * 2. Create a wallet belonging to that customer.
 * 3. (Documented) Attempt to update the immutable fields (customer_id, id) with a PUT. As these fields are not present in .IUpdate, a type-safe client cannot set them—document limitation.
 * 4. Verify mutable fields (currency_code) update via PUT as expected.
 * 5. Assert wallet id and customer_id remain unchanged after update.
 */
export async function test_api_ai_ecommerce_wallets_test_update_wallet_with_immutable_fields(
  connection: api.IConnection,
) {
  // 1. Create a user profile to obtain customer_id
  const profile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true,
    },
  });
  typia.assert(profile);

  // 2. Create a wallet bound to this user
  const wallet = await api.functional.ai_ecommerce.wallets.post(connection, {
    body: {
      customer_id: profile.id,
      currency_code: "KRW",
      is_active: true,
    },
  });
  typia.assert(wallet);

  // 3. (Not possible in type-safe TypeScript SDK): Attempt to update immutable fields (customer_id/id).\n
  /*
   * It is technically impossible to send customer_id or id via the PUT API, because .IUpdate only permits
   * currency_code and is_active (immutable fields are not in the schema). This test should be handled at the API boundary.
   * For E2E as a type-safe SDK client, this scenario cannot be simulated. Including this documentation for completeness.
   */

  // 4. Successfully update a mutable field (currency_code)
  const newCurrency = "USD";
  const updatedWallet = await api.functional.ai_ecommerce.wallets.putById(connection, {
    id: wallet.id,
    body: {
      currency_code: newCurrency,
    },
  });
  typia.assert(updatedWallet);
  TestValidator.equals("currency_code updated")(updatedWallet.currency_code)(newCurrency);
  TestValidator.equals("wallet id unchanged")(updatedWallet.id)(wallet.id);
  TestValidator.equals("customer_id unchanged")(updatedWallet.customer_id)(wallet.customer_id);
}

