import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrder";
import type { IAiEcommerceOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrderItem";
import type { ai_ecommerce_shipment } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_shipment";

/**
 * Validate paginated and filtered retrieval of shipment records as an admin.
 *
 * This test ensures that the shipment listing endpoint returns only shipments matching the provided filter criteria, paginates results correctly, and enforces business and access rules (RBAC, non-deleted shipments).
 *
 * Steps:
 * 1. Create multiple orders (at least two), acting as parents for shipments.
 * 2. For each order, create at least two shipments with varied carriers, shipping statuses, tracking numbers, and timestamps (created_at).
 * 3. Attempt several list/filter queries on /ai_ecommerce/shipments (PATCH), each time using a different combination of filters:
 *    - by shipping_status (e.g., 'pending')
 *    - by carrier (e.g., 'CJ Logistics'), or by both carrier+status
 *    - by created_at_from/created_at_to for a precise date window
 *    - using limit/offset for pagination
 * 4. For each query, assert that:
 *    - all results exactly match the filter(s) used
 *    - results are limited to active (non-deleted) shipments only
 *    - pagination fields (total/limit/offset) are correct
 *    - no fields leak unauthorized data
 * 5. Optionally, test that offset>0 works correctly.
 *
 * (No authentication step since the scenario assumes admin privileges are present in the connection.)
 */
export async function test_api_ai_ecommerce_shipments_test_list_shipments_with_valid_filters_and_pagination_as_admin(
  connection: api.IConnection,
) {
  // 1. Create multiple orders (parent order records for shipment)
  const order1 = await api.functional.ai_ecommerce.orders.post(connection, {
    body: { ...typia.random<IAiEcommerceOrder.ICreate>(), order_status: "pending" },
  });
  typia.assert(order1);
  const order2 = await api.functional.ai_ecommerce.orders.post(connection, {
    body: { ...typia.random<IAiEcommerceOrder.ICreate>(), order_status: "pending" },
  });
  typia.assert(order2);

  // 2. Create shipments with varying statuses, carriers, and dates
  const now = new Date();
  const shipmentA = await api.functional.ai_ecommerce.shipments.post(connection, {
    body: {
      order_id: order1.id,
      carrier: "CJ Logistics",
      tracking_number: "111-222-333",
      shipping_status: "pending"
      // shipped_at and delivered_at undefined on purpose
    },
  });
  typia.assert(shipmentA);
  const shipmentB = await api.functional.ai_ecommerce.shipments.post(connection, {
    body: {
      order_id: order1.id,
      carrier: "KoreaPost",
      tracking_number: "444-555-666",
      shipping_status: "shipped",
      shipped_at: new Date(now.getTime() - 86400000).toISOString(),
    },
  });
  typia.assert(shipmentB);
  const shipmentC = await api.functional.ai_ecommerce.shipments.post(connection, {
    body: {
      order_id: order2.id,
      carrier: "CJ Logistics",
      tracking_number: "888-999-000",
      shipping_status: "delivered",
      shipped_at: new Date(now.getTime() - 172800000).toISOString(),
      delivered_at: now.toISOString(),
    },
  });
  typia.assert(shipmentC);
  const shipmentD = await api.functional.ai_ecommerce.shipments.post(connection, {
    body: {
      order_id: order2.id,
      carrier: "KoreaPost",
      tracking_number: "321-654-987",
      shipping_status: "pending"
      // shipped_at/delivered_at undefined
    },
  });
  typia.assert(shipmentD);

  // 3. Shipping status filter test ('pending')
  const statusPage = await api.functional.ai_ecommerce.shipments.patch(connection, {
    body: {
      shipping_status: "pending",
    },
  });
  typia.assert(statusPage);
  TestValidator.predicate("all pending")(statusPage.data.every(s => s.shipping_status === "pending"));

  // 4. Carrier filter test ('CJ Logistics')
  const carrierPage = await api.functional.ai_ecommerce.shipments.patch(connection, {
    body: {
      carrier: "CJ Logistics",
    },
  });
  typia.assert(carrierPage);
  TestValidator.predicate("all CJ Logistics")(
    carrierPage.data.every(s => s.carrier === "CJ Logistics")
  );

  // 5. Carrier + status filter (carrier='KoreaPost', status='pending')
  const comboPage = await api.functional.ai_ecommerce.shipments.patch(connection, {
    body: {
      carrier: "KoreaPost",
      shipping_status: "pending",
    },
  });
  typia.assert(comboPage);
  TestValidator.predicate("all KoreaPost & pending")(
    comboPage.data.every(
      s => s.carrier === "KoreaPost" && s.shipping_status === "pending"
    )
  );

  // 6. Date window filter (only shipments created in the last 2 days)
  const dateFrom = new Date(now.getTime() - 2 * 86400000).toISOString();
  const dateTo = now.toISOString();
  const datePage = await api.functional.ai_ecommerce.shipments.patch(connection, {
    body: {
      created_at_from: dateFrom,
      created_at_to: dateTo,
    },
  });
  typia.assert(datePage);
  TestValidator.predicate("all in date window")(
    datePage.data.every(s => s.created_at >= dateFrom && s.created_at <= dateTo)
  );

  // 7. Pagination test (limit=2)
  const paged = await api.functional.ai_ecommerce.shipments.patch(connection, {
    body: {
      limit: 2,
      offset: 0,
    },
  });
  typia.assert(paged);
  TestValidator.equals("limit=2")(paged.data.length)(2);
  TestValidator.equals("pagination offset")(paged.offset ?? 0)(0);

  // 8. Pagination offset test (offset=2, limit=2)
  const pagedOffset = await api.functional.ai_ecommerce.shipments.patch(connection, {
    body: {
      limit: 2,
      offset: 2,
    },
  });
  typia.assert(pagedOffset);
  TestValidator.predicate("limit=2(offset=2)")(pagedOffset.data.length <= 2);
  TestValidator.equals("pagination offset=2")(pagedOffset.offset ?? 0)(2);

  // 9. (REMOVED) No deleted_at check: ai_ecommerce_shipment has no deleted_at field.
}

