import type { ai_ecommerce_shipment } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_shipment";

/**
 * Validate shipment detail retrieval by ID as an admin.
 *
 * This test ensures that a newly created shipment can be correctly retrieved using its ID by an authorized administrator. It checks that the detail endpoint returns all fields accurately, matching the original creation input, including status, carrier, order reference, and metadata.
 *
 * Steps:
 * 1. Create a valid order with a random customer, cart, address, and item—supplying a valid order_id for shipment.
 * 2. Create a shipment using that order's ID with carrier, tracking info, pending status, etc.
 * 3. Retrieve the shipment by its ID as admin; assert all fields are present and correct.
 * 4. Validate returned shipment matches all values from creation (esp. order_id, carrier, tracking, status).
 * 5. Assert timestamps, UUIDs, and field types for schema conformance.
 * 6. Attempt to get a shipment with a random (non-existent) ID and ensure an error is thrown (not found).
 *
 * Notes:
 * - No delete/soft-delete testing is possible (since no delete API exists in this SDK).
 * - API access control is assumed correct if detail is retrievable as admin (test simulates admin access).
 */
export async function test_api_ai_ecommerce_shipments_test_get_shipment_detail_with_valid_id_as_admin(
  connection: api.IConnection,
) {
  // 1. Create a valid order (dependency for shipment creation)
  /**
   * Generate all required UUIDs for the order structure.
   */
  const customer_id = typia.random<string & tags.Format<"uuid">>();
  const cart_id = typia.random<string & tags.Format<"uuid">>();
  const shipping_address_id = typia.random<string & tags.Format<"uuid">>();
  const sku_id = typia.random<string & tags.Format<"uuid">>();
  const order_items = [
    {
      sku_id,
      quantity: 1,
    } satisfies IAiEcommerceOrderItem.ICreate,
  ];
  const order = await api.functional.ai_ecommerce.orders.post(connection, {
    body: {
      customer_id,
      cart_id,
      shipping_address_id,
      order_status: "pending",
      order_channel: null,
      items: order_items,
    } satisfies IAiEcommerceOrder.ICreate,
  });
  typia.assert(order);

  // 2. Create a shipment linked to this order
  /**
   * Use typical values for fulfillment (carrier, tracking, etc.)
   * shipped_at, delivered_at are left undefined (not supplied)
   */
  const carrier = "KoreaPost";
  const tracking_number = "KR1234567890";
  const shipmentInput = {
    order_id: order.id,
    carrier,
    tracking_number,
    shipping_status: "pending"
    // shipped_at, delivered_at not supplied
  } satisfies ai_ecommerce_shipment.ICreate;
  const shipment = await api.functional.ai_ecommerce.shipments.post(connection, {
    body: shipmentInput,
  });
  typia.assert(shipment);

  // 3. Fetch shipment by its ID
  const detail = await api.functional.ai_ecommerce.shipments.getById(connection, {
    id: shipment.id,
  });
  typia.assert(detail);

  // 4. Verify returned fields match creation input and schema expectations
  TestValidator.equals("order_id")(detail.order_id)(shipmentInput.order_id);
  TestValidator.equals("carrier")(detail.carrier)(shipmentInput.carrier);
  TestValidator.equals("tracking_number")(detail.tracking_number)(shipmentInput.tracking_number);
  TestValidator.equals("shipping_status")(detail.shipping_status)(shipmentInput.shipping_status);
  // shipped_at/delivered_at must be undefined as not provided at creation
  TestValidator.equals("shipped_at")(detail.shipped_at)(undefined);
  TestValidator.equals("delivered_at")(detail.delivered_at)(undefined);

  // 5. Assert presence/type of shipment ID/UUIDs & timestamps
  TestValidator.predicate("shipment id is valid UUID")(
    typeof detail.id === "string" && !!detail.id && /[a-fA-F0-9\-]{36}/.test(detail.id)
  );
  TestValidator.equals("linked order id matches")(detail.order_id)(order.id);
  TestValidator.predicate("created_at is ISO8601")(
    typeof detail.created_at === "string" && !isNaN(Date.parse(detail.created_at))
  );
  TestValidator.predicate("updated_at is ISO8601")(
    typeof detail.updated_at === "string" && !isNaN(Date.parse(detail.updated_at))
  );

  // 6. Attempt to fetch with a random UUID (should error)
  await TestValidator.error("non-existent shipment id should error")(async () => {
    await api.functional.ai_ecommerce.shipments.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

