import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrder";
import type { IAiEcommerceOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrderItem";
import type { ai_ecommerce_shipment } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_shipment";

/**
 * Test updating shipment status, carrier, and tracking number as admin.
 *
 * This test covers the following real-world admin workflow scenarios:
 *
 * 1. Create an order that will later receive a shipment (admin context)
 * 2. Create a shipment for the order (required context for update)
 * 3. Update mutable shipment fields (carrier, tracking_number, shipping_status)
 *    - Transition from 'pending' → 'shipped', then 'shipped' → 'delivered', using business-allowed transitions
 *    - Ensure updated values are reflected and audit/history timestamps advance
 * 4. Attempt to update immutable shipment fields (e.g., order_id): should be rejected
 * 5. Attempt to update status with an invalid value or unauthorized transition (e.g., 'delivered'→'pending'): should fail
 * 6. Attempt mutation on a non-existent shipment: should fail with error
 *
 * Assertions:
 * - All successful transitions result in correct updated fields and advancing audit timestamps
 * - Attempts to mutate order_id or make illegal status transitions throw errors
 * - Updating a non-existent shipment throws errors
 */
export async function test_api_ai_ecommerce_shipments_test_update_shipment_status_and_tracking_as_admin(
  connection: api.IConnection,
) {
  // 1. Create an order (required context for shipment)
  const orderInput: IAiEcommerceOrder.ICreate = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    cart_id: typia.random<string & tags.Format<"uuid">>(),
    shipping_address_id: typia.random<string & tags.Format<"uuid">>(),
    order_status: "pending",
    order_channel: "web",
    items: [
      {
        sku_id: typia.random<string & tags.Format<"uuid">>(),
        quantity: 1,
      },
    ],
  };
  const order = await api.functional.ai_ecommerce.orders.post(connection, { body: orderInput });
  typia.assert(order);

  // 2. Create a shipment for the order
  const shipmentInput: ai_ecommerce_shipment.ICreate = {
    order_id: order.id,
    carrier: "InitialCarrier",
    tracking_number: undefined,
    shipping_status: "pending",
    shipped_at: undefined,
    delivered_at: undefined,
  };
  const shipment = await api.functional.ai_ecommerce.shipments.post(connection, { body: shipmentInput });
  typia.assert(shipment);

  // 3. First update: pending → shipped, set carrier and tracking
  const updateToShipped: ai_ecommerce_shipment.IUpdate = {
    carrier: "CarrierCo",
    tracking_number: "TRACK1234567890",
    shipping_status: "shipped",
    shipped_at: new Date().toISOString(),
  };
  const shipmentShipped = await api.functional.ai_ecommerce.shipments.putById(connection, {
    id: shipment.id,
    body: updateToShipped,
  });
  typia.assert(shipmentShipped);
  TestValidator.equals("status shipped")(shipmentShipped.shipping_status)("shipped");
  TestValidator.equals("carrier updated")(shipmentShipped.carrier)("CarrierCo");
  TestValidator.equals("tracking number updated")(shipmentShipped.tracking_number)("TRACK1234567890");
  TestValidator.predicate("updated_at advanced")(Date.parse(shipmentShipped.updated_at) > Date.parse(shipment.updated_at));
  TestValidator.predicate("shipped_at set")(!!shipmentShipped.shipped_at);

  // 4. Second update: shipped → delivered
  const updateToDelivered: ai_ecommerce_shipment.IUpdate = {
    shipping_status: "delivered",
    delivered_at: new Date().toISOString(),
  };
  const shipmentDelivered = await api.functional.ai_ecommerce.shipments.putById(connection, {
    id: shipment.id,
    body: updateToDelivered,
  });
  typia.assert(shipmentDelivered);
  TestValidator.equals("status delivered")(shipmentDelivered.shipping_status)("delivered");
  TestValidator.predicate("delivered_at set")(!!shipmentDelivered.delivered_at);
  TestValidator.predicate("updated_at advanced")(Date.parse(shipmentDelivered.updated_at) > Date.parse(shipmentShipped.updated_at));

  // 5. Attempt to update immutable order_id field (should fail business rule)
  TestValidator.error("Cannot mutate immutable field order_id")(() =>
    api.functional.ai_ecommerce.shipments.putById(connection, {
      id: shipment.id,
      body: {
        // @ts-expect-error: purposely inserting forbidden field
        order_id: typia.random<string & tags.Format<"uuid">>(),
        shipping_status: "shipped",
      },
    })
  );

  // 6. Attempt invalid status transition: delivered → pending (should fail)
  TestValidator.error("Illegal reverse status transition")(() =>
    api.functional.ai_ecommerce.shipments.putById(connection, {
      id: shipment.id,
      body: {
        shipping_status: "pending",
      },
    })
  );

  // 7. Attempt update on non-existent shipment (random UUID)
  TestValidator.error("Update on non-existent shipment should throw error")(() =>
    api.functional.ai_ecommerce.shipments.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        shipping_status: "shipped",
      },
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrder";
import type { IAiEcommerceOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrderItem";
import type { ai_ecommerce_shipment } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_shipment";

/**
 * Validate the soft deletion process for ai_ecommerce_shipment records.
 *
 * This test simulates the workflow of a privileged admin performing a soft-delete
 * against an active shipment. It verifies business logic, persistence, and audit
 * compliance. The process is as follows:
 *
 * 1. Create a fresh ai_ecommerce_order (unfulfilled, valid for shipment association).
 * 2. Create a shipment associated with the order (status: e.g., 'pending', not delivered).
 * 3. Execute DELETE /ai_ecommerce/shipments/{id} as admin.
 *    - Assert response success and populated deleted_at property.
 *    - Assert returned id matches the target shipment id and success: true.
 *    - Validate deleted_at is a non-empty ISO8601 string.
 * 4. (Negative test) If a shipment is already delivered, deletion should be blocked;
 *    this is checked by creating a shipment with shipping_status: 'delivered' and delivered_at.
 *    Assert the deletion attempt triggers an error as per business logic.
 *
 * Notes:
 * - No GET endpoint for shipment, so post-delete absence/hidden listing cannot be checked.
 * - Compliance/audit log validation is inferred via deleted_at/result message, as no explicit log API exists.
 * - Only endpoints and DTOs provided are used; all logic adheres to official contracts.
 */
export async function test_api_ai_ecommerce_shipments_test_soft_delete_shipment_with_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a fresh order (for shipment association)
  const order = await api.functional.ai_ecommerce.orders.post(connection, {
    body: {
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      cart_id: typia.random<string & tags.Format<"uuid">>(),
      shipping_address_id: typia.random<string & tags.Format<"uuid">>(),
      order_status: "pending",
      order_channel: null,
      items: [
        {
          sku_id: typia.random<string & tags.Format<"uuid">>(),
          quantity: 1,
        },
      ],
    } satisfies IAiEcommerceOrder.ICreate,
  });
  typia.assert(order);

  // 2. Create a shipment (READY for deletion)
  const shipment = await api.functional.ai_ecommerce.shipments.post(connection, {
    body: {
      order_id: order.id,
      carrier: "TestCarrier",
      shipping_status: "pending",
    } satisfies ai_ecommerce_shipment.ICreate,
  });
  typia.assert(shipment);

  // 3. DELETE shipment (as admin)
  const deleteResult = await api.functional.ai_ecommerce.shipments.eraseById(connection, {
    id: shipment.id,
  });
  typia.assert(deleteResult);
  TestValidator.equals("deletion succeeded")(deleteResult.success)(true);
  TestValidator.equals("deleted id matches")(deleteResult.id)(shipment.id);
  TestValidator.predicate("deleted_at is valid ISO date-time")(
    !!deleteResult.deleted_at &&
    typeof deleteResult.deleted_at === "string" &&
    /\d{4}-\d{2}-\d{2}T.+Z/.test(deleteResult.deleted_at)
  );

  // 4. Negative: Attempt to delete an already-delivered shipment (should be blocked by business logic)
  const deliveredShipment = await api.functional.ai_ecommerce.shipments.post(connection, {
    body: {
      order_id: order.id,
      carrier: "TestCarrier",
      shipping_status: "delivered",
      shipped_at: new Date().toISOString(),
      delivered_at: new Date().toISOString(),
    } satisfies ai_ecommerce_shipment.ICreate,
  });
  typia.assert(deliveredShipment);
  await TestValidator.error("cannot delete delivered shipment")(() =>
    api.functional.ai_ecommerce.shipments.eraseById(connection, {
      id: deliveredShipment.id,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_inquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_inquiry";
import type { IInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IInquirySnapshot";
import type { IPageIInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIInquirySnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated inquiry snapshot search for a specific inquiry with various filters and pagination controls.
 *
 * This test verifies that an administrator can accurately search and paginate through inquiry snapshots for a given inquiry, ensuring compliance and rollback tracking for audit workflows. It prepares an inquiry, generates multiple snapshots representing inquiry edits/status changes, and exercises the admin search endpoint with paging and filter queries.
 *
 * Main steps:
 * 1. Create an inquiry via POST /ai_ecommerce/inquiries
 * 2. Simulate multiple edits by creating multiple snapshots for this inquiry via POST /ai_ecommerce/inquirySnapshots
 * 3. Search inquiry snapshots via PATCH /ai_ecommerce/inquirySnapshots filtering by inquiry_id (test first page, limit, total count)
 * 4. Validate only relevant snapshots are returned; verify correct pagination metadata (page, limit, records, pages)
 * 5. Search an out-of-bounds page and assert empty snapshot results
 * 6. (Edge) Test that soft-deleted or unauthorized snapshots are not included in search result (not possible to test unauthorized snapshot without auth context)
 */
export async function test_api_ai_ecommerce_inquirySnapshots_test_search_inquiry_snapshots_by_inquiry_id_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a new inquiry (prerequisite)
  const customer_id = typia.random<string & tags.Format<"uuid">>();
  const product_id = typia.random<string & tags.Format<"uuid">>();
  const create_input: ai_ecommerce_inquiry.ICreate = {
    customer_id,
    product_id,
    order_id: null,
    title: `Inquiry Title - ${RandomGenerator.paragraph()(1)}`,
    body: `First inquiry body - ${RandomGenerator.content()()(1)}`,
    is_private: false,
  };
  const inquiry = await api.functional.ai_ecommerce.inquiries.post(connection, { body: create_input });
  typia.assert(inquiry);

  // 2. Generate 5 inquiry snapshots for different edits (simulate revisions)
  const admin_id = typia.random<string & tags.Format<"uuid">>();
  const base_title = "Base Title";
  const base_body = "Base body revision.";
  const base_status = "open";
  let created_snapshots: IInquirySnapshot[] = [];
  for (let i = 0; i < 5; ++i) {
    const snapshot_input: IInquirySnapshot.ICreate = {
      inquiry_id: inquiry.id,
      captured_by_id: admin_id,
      title: `${base_title} v${i+1}`,
      body: `${base_body} Revision ${i+1}`,
      status: base_status,
      snapshot_reason: i === 0 ? "initial" : "edit",
      created_at: new Date(Date.now() + i * 1000).toISOString(),
    };
    const snapshot = await api.functional.ai_ecommerce.inquirySnapshots.post(connection, { body: snapshot_input });
    typia.assert(snapshot);
    created_snapshots.push(snapshot);
  }

  // 3 & 4. Search inquiry snapshots by inquiry_id with pagination (limit = 2)
  const page_size = 2;
  const total_snapshots = created_snapshots.length;
  const total_pages = Math.ceil(total_snapshots / page_size);
  for (let page_num = 1; page_num <= total_pages; ++page_num) {
    const search_input: IInquirySnapshot.IRequest = {
      inquiry_id: inquiry.id,
      page: page_num,
      limit: page_size,
    };
    const page_output = await api.functional.ai_ecommerce.inquirySnapshots.patch(connection, { body: search_input });
    typia.assert(page_output);
    // Validate pagination meta
    TestValidator.equals("current page")(page_output.pagination.current)(page_num);
    TestValidator.equals("limit")(page_output.pagination.limit)(page_size);
    TestValidator.equals("records")(page_output.pagination.records)(total_snapshots);
    TestValidator.equals("pages")(page_output.pagination.pages)(total_pages);
    // Validate page data are correct snapshots
    const expected_page = created_snapshots.slice((page_num-1)*page_size, page_num*page_size);
    TestValidator.equals("page data actual vs expected")(page_output.data)(expected_page);
    // Validate all snapshots match the requested inquiry_id
    for (const snap of page_output.data) {
      TestValidator.equals("snapshot inquiry_id match")(snap.inquiry_id)(inquiry.id);
    }
  }

  // 5. Edge: query out-of-bounds page (should be empty data)
  const search_oob: IInquirySnapshot.IRequest = {
    inquiry_id: inquiry.id,
    page: total_pages+1,
    limit: page_size,
  };
  const page_oob = await api.functional.ai_ecommerce.inquirySnapshots.patch(connection, { body: search_oob });
  typia.assert(page_oob);
  TestValidator.equals("oob page snapshot count")(page_oob.data.length)(0);
}

