/**
 * Validate retrieval of a single inquiry snapshot by its unique id.
 *
 * This test verifies that an administrator (or any privileged actor) is able to fetch the complete detail
 * of an inquiry snapshot using its id. We first create an inquiry snapshot (this will produce a valid snapshot id),
 * then fetch that created snapshot by its id and assert that all essential fields are present and matched.
 *
 * Steps:
 * 1. Create an inquiry snapshot (to get a valid id for retrieval)
 * 2. Retrieve that snapshot detail by id
 * 3. Validate all relevant fields are present and match the creation values
 */
export async function test_api_ai_ecommerce_inquirySnapshots_test_get_inquiry_snapshot_by_id_success(
  connection: api.IConnection,
) {
  // 1. Create a new inquiry snapshot (dependency to generate a valid id for querying)
  const snapshotCreateInput: IInquirySnapshot.ICreate = {
    inquiry_id: typia.random<string & tags.Format<"uuid">>(),
    captured_by_id: typia.random<string & tags.Format<"uuid">>(),
    title: "Test Inquiry Title",
    body: "Test Inquiry Body for snapshot retrieval",
    status: "open",
    snapshot_reason: "edit",
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const createdSnapshot: IInquirySnapshot = await api.functional.ai_ecommerce.inquirySnapshots.post(connection, {
    body: snapshotCreateInput,
  });
  typia.assert(createdSnapshot);

  // 2. Fetch the snapshot by its id for detail validation
  const fetchedSnapshot: IInquirySnapshot = await api.functional.ai_ecommerce.inquirySnapshots.getById(connection, {
    id: createdSnapshot.id,
  });
