  // 3. Assert all fields are present and values match those from creation
  TestValidator.equals("fetched snapshot id matches")(fetchedSnapshot.id)(createdSnapshot.id);
  TestValidator.equals("fetched inquiry linkage matches")(fetchedSnapshot.inquiry_id)(snapshotCreateInput.inquiry_id);
  TestValidator.equals("captured_by_id matches")(fetchedSnapshot.captured_by_id)(snapshotCreateInput.captured_by_id);
  TestValidator.equals("title matches")(fetchedSnapshot.title)(snapshotCreateInput.title);
  TestValidator.equals("body matches")(fetchedSnapshot.body)(snapshotCreateInput.body);
  TestValidator.equals("status matches")(fetchedSnapshot.status)(snapshotCreateInput.status);
  TestValidator.equals("snapshot reason matches")(fetchedSnapshot.snapshot_reason)(snapshotCreateInput.snapshot_reason);
  TestValidator.equals("created_at matches")(fetchedSnapshot.created_at)(snapshotCreateInput.created_at);
}

