  // 2. 인증정보 없는 connection(Authorization header 제거)
  const unauthConnection: api.IConnection = {
    ...connection,
    headers: Object.fromEntries(Object.entries(connection.headers ?? {}).filter(([k]) => k.toLowerCase() !== 'authorization')),
  };

  // 3. 비인증 상태에서 상세조회 시도시 접근 에러 반드시 발생해야 함
  await TestValidator.error("unauthorized user is forbidden from viewing inquiry snapshot")(
    async () => {
      await api.functional.ai_ecommerce.inquirySnapshots.getById(unauthConnection, {
        id: snapshot.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_inquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_inquiry";
import type { IInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IInquirySnapshot";

/**
 * 상품/주문 문의 이력 스냅샷 생성의 엔드투엔드 흐름 검증
 *
 * 본 테스트는 실존하는 inquiry(문의) 엔트리를 대상으로, 정당한 캡처자에 의해 inquiry 스냅샷이 생성될 때의 정상 동작을 검증합니다.
 *
 * 1. 신규 inquiry(문의) 생성 (테스트용 문의 데이터 세팅)
 * 2. 방금 생성된 inquiry의 상태(title, body, status 등)를 스냅샷용 데이터로 준비
 * 3. 스냅샷 생성 actor(캡처자)는 일반적으로 inquiry의 소유 고객이나, 시스템 사용자 UUID를 활용 가능 (여기선 문의 생성자를 활용)
 * 4. /ai_ecommerce/inquirySnapshots 엔드포인트에 inquiry_id, 캡처자, 내용, 상태, 사유, 생성일시 포함하여 POST 요청
 * 5. 정상 생성된 inquiry snapshot의 모든 필드가 요청 데이터 일치 및 immutable(불변) 성격임을 확인
 * 6. 추가적으로 동일 inquiry 대상 반복 생성 시 이전과 다른 snapshot이 독립적으로 쌓이는지도 확인할 수 있음(스냅샷 고유성)
 */
export async function test_api_ai_ecommerce_inquirySnapshots_test_create_inquiry_snapshot_with_valid_data(
  connection: api.IConnection,
) {
  // 1. 신규 문의 생성
  const inquiryCreate: ai_ecommerce_inquiry.ICreate = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    order_id: null, // 주문관련 아님
    title: "테스트 문의 제목" + RandomGenerator.alphaNumeric(5),
    body: "문의 본문 내용 " + RandomGenerator.paragraph()(2),
    is_private: false,
  };
  const inquiry: ai_ecommerce_inquiry = await api.functional.ai_ecommerce.inquiries.post(connection, {
    body: inquiryCreate,
  });
  typia.assert(inquiry);

  // 2. inquiry 현 상태로 snapshot 데이터 준비
  const now = new Date().toISOString();
  const snapshotCreate: IInquirySnapshot.ICreate = {
    inquiry_id: inquiry.id,
    captured_by_id: inquiry.customer_id, // 캡처 주체(일반적으론 문의 작성자)
    title: inquiry.title,
    body: inquiry.body,
    status: inquiry.status,
    snapshot_reason: "edit", // 편집 이력 예시
    created_at: now,
  };

  // 3. inquirySnapshots POST로 실제 스냅샷 생성
  const snapshot: IInquirySnapshot = await api.functional.ai_ecommerce.inquirySnapshots.post(connection, {
    body: snapshotCreate,
  });
  typia.assert(snapshot);

  // 4. 반환된 snapshot의 주요 필드가 요청값과 정확히 일치하는지 검증, immutability(불변성)도 논리적으로 확인
  TestValidator.equals("inquiry_id")(snapshot.inquiry_id)(snapshotCreate.inquiry_id);
  TestValidator.equals("captured_by_id")(snapshot.captured_by_id)(snapshotCreate.captured_by_id);
  TestValidator.equals("title")(snapshot.title)(snapshotCreate.title);
  TestValidator.equals("body")(snapshot.body)(snapshotCreate.body);
  TestValidator.equals("status")(snapshot.status)(snapshotCreate.status);
  TestValidator.equals("snapshot_reason")(snapshot.snapshot_reason)(snapshotCreate.snapshot_reason);
  // created_at은 ms 단위까지 같을 필요없이, ISO8601 형식, 근접성만 체크
  TestValidator.predicate("created_at timestamp matches")(
    Math.abs(new Date(snapshot.created_at).getTime() - new Date(snapshotCreate.created_at).getTime()) < 1000,
  );
}

