import type { ai_ecommerce_inquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_inquiry";
import type { IInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IInquirySnapshot";

/**
 * 문의글 스냅샷 생성 API의 권한 체계를 검증합니다.
 *
 * 관리자 또는 시스템이 아닌 권한이 부족한 배우(특히 고객)가 직접 Inquiry Snapshot 생성 API를 호출할 경우,
 * Permssion denied/Forbidden(403) 오류가 반드시 발생해야 하며, 실제 InquirySnapshot 데이터가 새로 생성되면 안됩니다.
 *
 * 주요 검증 단계는 다음과 같습니다:
