import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_inquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_inquiry";
import type { IInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IInquirySnapshot";

/**
 * 문의 스냅샷의 허용된 감사 필드(snapshot_reason)를 관리자 권한으로 수정하는 E2E 테스트.
 *
 * 1. 문의(inquiry)를 생성
 * 2. 문의 스냅샷(snapshot) 생성 (최초 이력)
 * 3. 스냅샷의 허용 필드(snapshot_reason)를 PUT으로 수정
 * 4. 변경 내용 반영 확인 (변경된 snapshot_reason, 감사 로그/불변 필드 유지)
 * 5. 불변 필드 변경 시도시 에러 발생 검증 (타입이 허용치 않으므로 business validation에 집중)
 */
export async function test_api_ai_ecommerce_inquirySnapshots_test_update_inquiry_snapshot_allowed_fields_admin_only(
  connection: api.IConnection,
) {
  // 1. 문의(inquiry) 생성
  const inquiry = await api.functional.ai_ecommerce.inquiries.post(connection, {
    body: {
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      product_id: typia.random<string & tags.Format<"uuid">>(),
      title: "환불 문의",
      body: "상품에 문제가 있어 환불을 요청합니다.",
    } satisfies ai_ecommerce_inquiry.ICreate,
  });
  typia.assert(inquiry);

  // 2. 문의 snapshot 레코드 생성 (최초 이력)
  const snapshot = await api.functional.ai_ecommerce.inquirySnapshots.post(connection, {
    body: {
      inquiry_id: inquiry.id,
      captured_by_id: typia.random<string & tags.Format<"uuid">>(),
      title: inquiry.title,
      body: inquiry.body,
      status: "open",
      snapshot_reason: "init",
      created_at: new Date().toISOString(),
    } satisfies IInquirySnapshot.ICreate,
  });
  typia.assert(snapshot);

  // 3. 허용 필드(snapshot_reason)만 PUT으로 변경
  const updatedReason = "관리자 감사로 설명 변경";
  const updated = await api.functional.ai_ecommerce.inquirySnapshots.putById(connection, {
    id: snapshot.id,
    body: {
      snapshot_reason: updatedReason,
    } satisfies IInquirySnapshot.IUpdate,
  });
  typia.assert(updated);

  // 4. 변경 반영 및 불변 필드/감사 이력 검증
  TestValidator.equals("snapshot_reason 변경")(updated.snapshot_reason)(updatedReason);
  TestValidator.equals("inquiry_id 불변")(updated.inquiry_id)(snapshot.inquiry_id);
  TestValidator.equals("captured_by_id 불변")(updated.captured_by_id)(snapshot.captured_by_id);
  TestValidator.equals("title 불변")(updated.title)(snapshot.title);
  TestValidator.equals("body 불변")(updated.body)(snapshot.body);
  TestValidator.equals("status 불변")(updated.status)(snapshot.status);

  // 5. 에러 케이스: 불변 필드 등 mutable 이외 필드 변경 불가(타입상 불가)
  await TestValidator.error("불변 필드 변경 불가")(
    async () => {
      await api.functional.ai_ecommerce.inquirySnapshots.putById(connection, {
        id: snapshot.id,
        body: {
          // 아래 필드는 IUpdate 타입 구조상 허용하지 않으므로 as unknown으로 런타임 에러를 유도
          snapshot_reason: "불법 필드 변경",
          // inquiry_id: "잘못된 값",
        } as unknown as IInquirySnapshot.IUpdate,
      });
    },
  );
}

