/**
 * E2E test for retrieving the customer list with default pagination (no filters).
 *
 * Business context: Admins can view a paginated list of customers. This endpoint must not leak sensitive or relational data, should only be available to authorized administrative users, and must reflect proper pagination structure.
 *
 * Step-by-step process:
 * 1. Ensure there is at least one customer in the system (by creating one as a precondition).
 * 2. Attempt to access this endpoint as a non-admin (if API supports non-admin/account context, expect failure).
 * 3. Access the customer list as an authorized admin (the default test context, since SDK likely presumes admin connection).
 * 4. Verify the response structure:
 *    a. Response contains correct pagination block (`pagination` key).
 *    b. At least one customer exists in `data` array, matching the newly-created customer ID.
 *    c. No extra sensitive or unauthorized relational fields are included in the output (see DTO definitions).
 *    d. Check pagination fields for proper type and minimal range (e.g., page >= 1, limit >=1, records >= 1).
 */
export async function test_api_ai_ecommerce_customers_test_list_customers_with_default_pagination(
  connection: api.IConnection,
) {
  // 1. Create a new customer (dependency)
  const profileId: string = typia.random<string & tags.Format<"uuid">>();
  const customer = await api.functional.ai_ecommerce.customers.post(connection, {
    body: {
      profile_id: profileId,
    } satisfies ai_ecommerce_customers.IRegister,
  });
  typia.assert(customer);

  // 2. Retrieve customers with default parameters (no filters)
  const page = await api.functional.ai_ecommerce.customers.patch(connection, {
    body: {},
  });
  typia.assert(page);

  // 3. Response validation: ensure pagination and at least the created customer appears
  TestValidator.predicate("pagination block is object")(typeof page.pagination === "object" && page.pagination !== null);
  TestValidator.predicate("data is array")(Array.isArray(page.data));
  TestValidator.predicate("at least one customer exists")(page.data.length >= 1);

  // 4. All customers: field-level validation (no sensitive/relational fields)
  for (const item of page.data) {
    typia.assert<ai_ecommerce_customers>(item);
    // Only check for schema-mandated keys
    const allowedKeys = ["id", "profile_id", "created_at", "updated_at", "deleted_at"];
    for (const key of Object.keys(item)) {
      TestValidator.predicate(`customer[${key}] is allowed field`)(allowedKeys.includes(key));
    }
  }

  // 5. Pagination block field validation
  TestValidator.predicate("current page is >= 1")(page.pagination.current >= 1);
  TestValidator.predicate("limit is >= 1")(page.pagination.limit >= 1);
  TestValidator.predicate("records is >= 1")(page.pagination.records >= 1);
  TestValidator.predicate("pages is >= 1")(page.pagination.pages >= 1);

  // 6. Confirm our created customer is present
  const found = page.data.find((c) => c.id === customer.id);
  TestValidator.predicate("created customer appears in list")(!!found);
}

