export async function test_api_ai_ecommerce_customers_test_list_customers_with_deleted_filter(
  connection: api.IConnection,
) {
  // 1. Create a user profile
  const profile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true,
      avatar_uri: null,
      phone_number: null,
    } satisfies IAiEcommerceUserProfile.ICreate,
