  const deletedInResult = deletedList.data.find((c) => c.id === customer.id);
  TestValidator.predicate("deleted customer is listed")(!!deletedInResult);
  if (deletedInResult)
    TestValidator.predicate("deleted_at is set in list")(!!deletedInResult.deleted_at);

  // 6. List active customers (status: 'active')
  const activeList = await api.functional.ai_ecommerce.customers.patch(connection, {
    body: { status: "active", limit: 20 } satisfies ai_ecommerce_customers.IRequest,
  });
