  // 7. Deleted customer should NOT be in the active customer list
  const activeInResult = activeList.data.find((c) => c.id === customer.id);
  TestValidator.predicate("deleted customer not in active list")(!activeInResult);

  // 8. Pagination and metadata assertion (limits, record counts)
  TestValidator.equals("deleted list page limit")(deletedList.pagination.limit)(20);
  TestValidator.equals("active list page limit")(activeList.pagination.limit)(20);
  TestValidator.predicate("pagination records non-negative")(deletedList.pagination.records >= 0 && activeList.pagination.records >= 0);
