 * 2. 기존 고객 정보를 조회(생성 결과)하여 초기 상태를 기록합니다
 * 3. 허용된 필드(예: status, deleted_at 등)를 일부 값으로 PATCH/PUT합니다
 * 4. 수정된 결과의 updated_at이 변경되었는지, immutable 필드(id, profile_id, created_at)가 변하지 않았는지 검증합니다
 * 5. 변경된 결과에 요청값이 올바르게 반영되었는지 확인합니다 (단, 응답에 없는 필드는 체크하지 않음)
 */
export async function test_api_ai_ecommerce_customers_test_update_customer_fields_success(
  connection: api.IConnection,
) {
  // 1. profile_id 임의 생성
  const profileId: string = typia.random<string & tags.Format<"uuid">>();

  // 2. 고객 생성
  const created = await api.functional.ai_ecommerce.customers.post(connection, {
    body: {
      profile_id: profileId,
    } satisfies ai_ecommerce_customers.IRegister,
  });
  typia.assert(created);

  // 3. 기존 고객 정보 보관
  const original = created;

  // 4. 고객 정보 업데이트(허용 필드만 변경: status 및 deleted_at 임의 값)
  const updateInput: ai_ecommerce_customers.IUpdate = {
    status: "deleted",
    deleted_at: typia.random<string & tags.Format<"date-time">>()
  };
  const updated = await api.functional.ai_ecommerce.customers.putById(connection, {
    id: created.id,
    body: updateInput,
  });
  typia.assert(updated);

  // 5. updated_at이 변경되었는지, immutable 필드(id, profile_id, created_at)는 불변인지 확인
  TestValidator.notEquals("updated_at 변경됨")(updated.updated_at)(original.updated_at);
  TestValidator.equals("id 불변")(updated.id)(original.id);
  TestValidator.equals("profile_id 불변")(updated.profile_id)(original.profile_id);
  TestValidator.equals("created_at 불변")(updated.created_at)(original.created_at);

  // 6. update가 잘 반영됐는지(논리 삭제)
  TestValidator.equals("deleted_at 반영됨")(updated.deleted_at)(updateInput.deleted_at);
}

