 *
 * ai_ecommerce_customers 엔티티는 물리 삭제가 아닌 deleted_at 값을 세팅하는 soft-delete 방식을 채택합니다. 고객이 한 번 삭제되고 나면, 추가적인 삭제 시도는 오류로 처리되어야 하며 데이터 상태는 변경되지 않아야 합니다.
 *
 * 테스트 시나리오:
 * 1. (의미상 프로필 엔티티가 필요하나, 해당 생성 API 미제공이므로 임의 UUID 사용) profile_id 준비
 * 2. 해당 profile_id로 고객 생성
 * 3. 생성 고객을 soft-delete하여 deleted_at이 세팅됐음을 확인
 * 4. 이미 deleted_at이 존재하는 고객을 한 번 더 삭제 시도 → 명확한 에러 발생 확인
 * 5. 삭제 후 데이터 상태(특히 deleted_at)가 변하지 않았는지 재확인 (조회 API 없음 — 최초 삭제 반환값 기준)
 */
export async function test_api_ai_ecommerce_customers_test_soft_delete_customer_already_deleted(
  connection: api.IConnection,
) {
  // 1. 임의 profile_id 생성 (실제 유효 profile 엔티티 계정이 필요하다면 변경)
  const profile_id: string = typia.random<string & tags.Format<"uuid">>();

  // 2. 고객 등록
  const customer = await api.functional.ai_ecommerce.customers.post(connection, {
    body: {
      profile_id,
    } satisfies ai_ecommerce_customers.IRegister,
  });
  typia.assert(customer);
  TestValidator.equals("최초 deleted_at null/null 또는 미지정")(customer.deleted_at)(null);

  // 3. 최초 soft-delete 수행
  const deleted = await api.functional.ai_ecommerce.customers.eraseById(connection, {
    id: customer.id,
  });
  typia.assert(deleted);
  TestValidator.predicate("첫 삭제 후 deleted_at 세팅 여부")(
    typeof deleted.deleted_at === "string" && deleted.deleted_at.length > 0,
  );

  // 4. 동일 고객 두 번째 삭제 (이미 삭제됨) → 반드시 에러 발생 검증
  const deleted_at_backup = deleted.deleted_at;
  await TestValidator.error("이미 삭제된 고객 재삭제시 에러 발생 여부")(
    async () => {
      await api.functional.ai_ecommerce.customers.eraseById(connection, {
        id: customer.id,
      });
    },
  );

  // 5. 이전 deleted_at과 변동 없음을 보장
  TestValidator.equals("deleted_at 불변성 보장")(deleted.deleted_at)(deleted_at_backup);
}

