import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_product } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_product";
import type { ai_ecommerce_skus } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_skus";
import type { IAiEcommerceProductOptions } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceProductOptions";
import type { IPageIAiEcommerceProductOptions } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiEcommerceProductOptions";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for product option listing with filters and pagination.
 *
 * This test verifies:
 *   - Product option creation for one product/SKU
 *   - Filter by option name and value returns correct results
 *   - Pagination (limit/page) functions as expected
 *   - Filtering for unknown options yields empty results
 *   - Paging past available range yields empty results
 *
 * Test steps:
 * 1. Create a product (unique for test)
 * 2. Create a SKU for the product
 * 3. Create multiple options for product (with known names/values)
 * 4. Filter by product_id and option_name ('Color') and assert all returned are correct
 * 5. Filter by product_id and option_value ('Cotton') and assert correctness
 * 6. Paginate with limit/page, validate count, and pagination math
 * 7. Filter by non-existent option_name, expect empty result
 * 8. Request out-of-range page, expect empty result
 */
export async function test_api_ai_ecommerce_productOptions_test_list_product_options_with_filters_and_pagination(connection: api.IConnection) {
  // 1. Create a product
  const product = await api.functional.ai_ecommerce.products.post(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      title: `TestProduct_${RandomGenerator.alphaNumeric(6)}`,
      description: RandomGenerator.paragraph()(),
      status: "active",
      approval_state: "approved",
    } satisfies ai_ecommerce_product.ICreate,
  });
  typia.assert(product);

  // 2. Create a SKU for the product
  const sku = await api.functional.ai_ecommerce.skus.post(connection, {
    body: {
      product_id: product.id,
      code: `SKU${RandomGenerator.alphaNumeric(5)}`,
      price: 10000,
      currency: "KRW",
      is_active: true,
    } satisfies ai_ecommerce_skus.ICreate,
  });
  typia.assert(sku);

  // 3. Create several options (hooked to product and SKU, with known names/values for test)
  let createdOptions: IAiEcommerceProductOptions[] = [];
  const optionSpecs = [
    { name: "Color", value: "Red" },
    { name: "Color", value: "Blue" },
    { name: "Color", value: "Green" },
    { name: "Size", value: "M" },
    { name: "Size", value: "L" },
    { name: "Material", value: "Cotton" },
  ];
  for (const spec of optionSpecs) {
    const option = await api.functional.ai_ecommerce.productOptions.post(connection, {
      body: {
        product_id: product.id,
        sku_id: sku.id,
        option_name: spec.name,
        option_value: spec.value,
      } satisfies IAiEcommerceProductOptions.ICreate,
    });
    typia.assert(option);
    createdOptions.push(option);
  }

  // 4. Filter by product + option_name ('Color')
  const filterByName = await api.functional.ai_ecommerce.productOptions.patch(connection, {
    body: {
      product_id: product.id,
      sku_id: sku.id,
      option_name: "Color",
    },
  });
  typia.assert(filterByName);
  TestValidator.predicate("all results have option_name=Color")(
    filterByName.data.every(opt => opt.option_name === "Color")
  );
  TestValidator.equals("correct number of Color options returned")(filterByName.data.length)(3);
  TestValidator.equals("pagination matches total records")(filterByName.pagination.records)(3);

  // 5. Filter by product + option_value ('Cotton')
  const filterByValue = await api.functional.ai_ecommerce.productOptions.patch(connection, {
    body: {
      product_id: product.id,
      sku_id: sku.id,
      option_value: "Cotton",
    },
  });
  typia.assert(filterByValue);
  TestValidator.equals("Cotton filter returns 1 option")(filterByValue.data.length)(1);
  TestValidator.equals("Material type returned for Cotton")(filterByValue.data[0].option_name)("Material");

  // 6. Test pagination (limit/page = 2 per page, get page 2)
  const paged = await api.functional.ai_ecommerce.productOptions.patch(connection, {
    body: {
      product_id: product.id,
      sku_id: sku.id,
      limit: 2,
      page: 2,
    },
  });
  typia.assert(paged);
  TestValidator.equals("pagination limit set to 2")(paged.pagination.limit)(2);
  TestValidator.equals("page is 2")(paged.pagination.current)(2);
  TestValidator.equals("total record count matches created count")(paged.pagination.records)(createdOptions.length);
  TestValidator.equals("pages calculated correctly")(
    paged.pagination.pages
  )(Math.ceil(createdOptions.length / 2));
  TestValidator.predicate("no more than 2 records returned")(
    paged.data.length <= 2
  );

  // 7. Filter by nonexistent option_name => expect no results
  const filterNone = await api.functional.ai_ecommerce.productOptions.patch(connection, {
    body: {
      product_id: product.id,
      sku_id: sku.id,
      option_name: "NonExistentOption",
    },
  });
  typia.assert(filterNone);
  TestValidator.equals("zero records for nonexistent option_name")(filterNone.data.length)(0);
  TestValidator.equals("pagination records zero for nonexistent option_name")(filterNone.pagination.records)(0);

  // 8. Paginate with out-of-range page => expect empty result
  const pageOut = await api.functional.ai_ecommerce.productOptions.patch(connection, {
    body: {
      product_id: product.id,
      sku_id: sku.id,
      limit: 2,
      page: 999,
    },
  });
  typia.assert(pageOut);
  TestValidator.equals("no records for out-of-range page")(pageOut.data.length)(0);
