/**
 * Validate rejection of creating a duplicate product option (same name/value for same SKU or product).
 *
 * Business context:
 * - Product options (name/value pairs) must be unique per (product, sku). Creating a duplicate should fail to enforce catalog integrity.
 *
 * Steps:
 * 1. Create a product entity as test context
 * 2. Create a SKU linked to that product
 * 3. Create a product option (with distinct name+value, linked either to the product or SKU)
 * 4. Attempt to create a second product option with the EXACT same name+value for the same product/SKU (should fail with validation or conflict error)
 * 5. Confirm error thrown on duplicate creation
 * 6. Also, confirm creating an option with the same name+value under a DIFFERENT SKU or product is allowed (edge case: uniqueness is per product/SKU, not global)
 */
export async function test_api_ai_ecommerce_productOptions_test_create_product_option_with_duplicate_name_for_same_sku(
  connection: api.IConnection,
) {
  // 1. Create a new product
  const product = await api.functional.ai_ecommerce.products.post(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.alphabets(12),
      description: RandomGenerator.paragraph()(),
      status: "published",
      approval_state: "approved"
    } satisfies ai_ecommerce_product.ICreate,
  });
  typia.assert(product);

  // 2. Create a SKU for that product
  const sku = await api.functional.ai_ecommerce.skus.post(connection, {
    body: {
      product_id: product.id,
      code: RandomGenerator.alphaNumeric(10),
      price: 19900,
      currency: "KRW",
      is_active: true,
    } satisfies ai_ecommerce_skus.ICreate,
  });
  typia.assert(sku);

  // 3. Create a product option (with unique name/value)
  const option_name = "color";
  const option_value = "red";
  const option = await api.functional.ai_ecommerce.productOptions.post(
    connection,
    {
      body: {
        product_id: product.id,
        sku_id: sku.id,
        option_name,
        option_value,
      } satisfies IAiEcommerceProductOptions.ICreate,
    },
  );
  typia.assert(option);

  // 4. Attempt to create a duplicate product option (same product_id, sku_id, option_name, option_value)
  await TestValidator.error("duplicate option name/value for same SKU should fail")(
    async () =>
      api.functional.ai_ecommerce.productOptions.post(connection, {
        body: {
          product_id: product.id,
          sku_id: sku.id,
          option_name,
          option_value,
        } satisfies IAiEcommerceProductOptions.ICreate,
      }),
  );

  // 5. Confirm it works for other SKUs or products: Create another product
  const otherProduct = await api.functional.ai_ecommerce.products.post(
    connection,
    {
      body: {
        seller_id: typia.random<string & tags.Format<"uuid">>(),
        title: RandomGenerator.alphabets(12),
        description: RandomGenerator.paragraph()(),
        status: "published",
        approval_state: "approved",
      } satisfies ai_ecommerce_product.ICreate,
    },
  );
  typia.assert(otherProduct);

  // 6. Create SKU for other product
  const otherSku = await api.functional.ai_ecommerce.skus.post(connection, {
    body: {
      product_id: otherProduct.id,
      code: RandomGenerator.alphaNumeric(10),
      price: 19900,
      currency: "KRW",
      is_active: true,
    } satisfies ai_ecommerce_skus.ICreate,
  });
  typia.assert(otherSku);

  // 7. Create product option with same name/value on the other product+sku (should succeed)
  const option2 = await api.functional.ai_ecommerce.productOptions.post(connection, {
    body: {
      product_id: otherProduct.id,
      sku_id: otherSku.id,
      option_name,
      option_value,
    } satisfies IAiEcommerceProductOptions.ICreate,
  });
  typia.assert(option2);
}

