/**
 * Test successful update of a product option's value in the AI e-commerce system.
 *
 * This test validates the end-to-end workflow for updating an existing product option's value, ensuring changes are persisted
 * and all other fields remain unchanged.
 *
 * Workflow:
 * 1. Create a product (to serve as the context for the option)
 * 2. Create a SKU (linked to the product for more realistic association)
 * 3. Create a product option for the above product (option_name/option_value)
 * 4. Update the option's value using PUT /ai_ecommerce/productOptions/{id} with a new value
 * 5. Validate the response: option_value in the response matches the new value, unchanged fields match the original state
 */
export async function test_api_ai_ecommerce_productOptions_test_update_product_option_value_successfully(
  connection: api.IConnection,
) {
  // 1. Create product
  const productTitle = RandomGenerator.paragraph()(2);
  const productDescription = RandomGenerator.content()(1)();
  const productInput: ai_ecommerce_product.ICreate = {
    seller_id: typia.random<string & tags.Format<"uuid">>(),
    title: productTitle,
    description: productDescription,
    status: "published",
    approval_state: "approved",
  };
  const product = await api.functional.ai_ecommerce.products.post(connection, { body: productInput });
  typia.assert(product);

  // 2. Create SKU for product
  const skuInput: ai_ecommerce_skus.ICreate = {
    product_id: product.id,
    code: RandomGenerator.alphaNumeric(8),
    price: 19900,
    currency: "KRW",
    is_active: true,
  };
  const sku = await api.functional.ai_ecommerce.skus.post(connection, { body: skuInput });
  typia.assert(sku);

  // 3. Create product option
  const optionName = "color";
  const optionValue = "Red";
  const optionInput: IAiEcommerceProductOptions.ICreate = {
    product_id: product.id,
    sku_id: sku.id,
    option_name: optionName,
    option_value: optionValue,
  };
  const option = await api.functional.ai_ecommerce.productOptions.post(connection, { body: optionInput });
  typia.assert(option);

  // 4. Update the product option's value
  const newValue = "Blue";
  const updated = await api.functional.ai_ecommerce.productOptions.putById(connection, {
    id: option.id,
    body: { option_value: newValue },
  });
  typia.assert(updated);

  // 5. Validate: updated value is reflected, unchanged fields intact
  TestValidator.equals("option_value was updated")(updated.option_value)(newValue);
  TestValidator.equals("option_name unchanged")(updated.option_name)(option.option_name);
  TestValidator.equals("sku_id unchanged")(updated.sku_id)(option.sku_id);
  TestValidator.equals("product_id unchanged")(updated.product_id)(option.product_id);
  // No assertion on created_at as it is a timestamp that may change due to update
}

