  // 4. 첫 번째 옵션을 두 번째 옵션과 동일한 name/value로 update 시도 → 중복 에러 기대
  await TestValidator.error(
    "동일 SKU 내 옵션 이름/값 중복 변경 시도시 에러 발생해야 함",
  )(async () => {
    await api.functional.ai_ecommerce.productOptions.putById(connection, {
      id: optionA.id,
      body: {
