import type { IAiEcommerceProductOptions } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceProductOptions";

/**
 * Test successful deletion of a product option by ID.
 *
 * This test verifies the ability to delete a product option via its unique ID, ensuring the full flow from creation to deletion and post-deletion validation.
 *
 * Steps:
 * 1. Create a product (retain its ID for downstream reference).
 * 2. Create a SKU associated with the created product.
 * 3. Create a product option associated with both product and SKU.
 * 4. Execute DELETE for the product option by its ID.
 * 5. (GET by ID to confirm deletion is not available – omitted by scenario/contract.)
 *
 * The core validation: the product option can be deleted by its unique ID without error. Post-deletion absence verification is omitted as the API does not support get-by-id for productOptions.
 */
export async function test_api_ai_ecommerce_productOptions_test_delete_product_option_successfully(
  connection: api.IConnection,
) {
  // 1. Create a product
  const product = await api.functional.ai_ecommerce.products.post(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<'uuid'>>(),
      title: RandomGenerator.paragraph()(2),
      description: RandomGenerator.paragraph()(5),
      status: 'published',
      approval_state: 'approved',
    } satisfies ai_ecommerce_product.ICreate,
  });
  typia.assert(product);

  // 2. Create a SKU associated with the product
  const sku = await api.functional.ai_ecommerce.skus.post(connection, {
    body: {
      product_id: product.id,
      code: RandomGenerator.alphaNumeric(8),
      price: 19900,
      currency: 'KRW',
      is_active: true,
    } satisfies ai_ecommerce_skus.ICreate,
  });
  typia.assert(sku);

  // 3. Create a product option associated with product and SKU
  const option = await api.functional.ai_ecommerce.productOptions.post(connection, {
    body: {
      product_id: product.id,
      sku_id: sku.id,
      option_name: '색상',
      option_value: '블랙',
    } satisfies IAiEcommerceProductOptions.ICreate,
  });
  typia.assert(option);

  // 4. Delete the product option by its ID
  await api.functional.ai_ecommerce.productOptions.eraseById(connection, {
    id: option.id,
  });

  // 5. (Omitted) No way to fetch product option by ID post-deletion as per current API.
}

