import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_administrators } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_administrators";
import type { IPageai_ecommerce_administrators } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageai_ecommerce_administrators";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAiEcommerceAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceAdministrator";

/**
 * Validate the paginated and filtered list-retrieval of administrators.
 *
 * This test exercises the admin listing search endpoint by performing:
 * 1. Dependency creation: ensures at least one administrator exists for visibility in page results, testing for proper pagination update when new entries are added.
 * 2. Multiple PATCH admin-list operations with various valid filters (free-text search, created_from/to, status, sort_key, sort_order, pagination page/limit).
 * 3. Each response must only contain admin summary fields (id, profile_id, created_at, updated_at, deleted_at) -- never exposing unauthorized or related profile fields.
 * 4. Validate paging metadata (current, limit, total records, pages), never exceeding allowed limits, and that changing page/limit updates returned data accordingly.
 * 5. Search filter and sort combo: Insert a uniquely-identifiable admin, then use search+sort+filters to confirm its presence/absence in data.
 * 6. Oversized resource request: Query with high (100) limit for safe handling and correct capping.
 *
 * Steps:
 * 1. Create a new administrator (dependency) with a distinct random profile_id
 * 2. Retrieve the administrator list with default parameters
 * 3. Retrieve second page with small limit (e.g. 1) to test pagination
 * 4. Retrieve list with filter for the known profile_id (should always include the created admin)
 * 5. Retrieve with large limit (100)
 * 6. Retrieve with sort_key/sort_order set (e.g. sort by created_at desc)
 * 7. For each result, validate all fields match expected contracts, and that unauthorized data is not present
 * 8. For each paging response, check that limit/current/records/pages are correct and consistent with the data volume
 */
export async function test_api_ai_ecommerce_administrators_test_list_administrators_with_valid_pagination_and_filters(
  connection: api.IConnection,
) {
  // 1. Create a new administrator with a unique profile_id
  const profileId: string = typia.random<string & tags.Format<"uuid">>();
  const createdAdmin = await api.functional.ai_ecommerce.administrators.post(connection, {
    body: { profile_id: profileId } satisfies IAiEcommerceAdministrator.ICreate,
  });
  typia.assert(createdAdmin);

  // 2. Retrieve administrator list with default parameters
  let output = await api.functional.ai_ecommerce.administrators.patch(connection, {
    body: {},
  });
  typia.assert(output);
  // Validate schema and at least one admin present
  TestValidator.predicate("at least one admin exists")(output.data.length >= 1);
  TestValidator.predicate("summary fields only")(output.data.every((admin) => {
    const allowedKeys = ["id", "profile_id", "created_at", "updated_at", "deleted_at"];
    return Object.keys(admin).every((k) => allowedKeys.includes(k));
  }));

  // Validate pagination contract
  const { pagination } = output;
  TestValidator.predicate("pagination shape")(typeof pagination.current === "number" && typeof pagination.limit === "number" && typeof pagination.records === "number" && typeof pagination.pages === "number");
  TestValidator.equals("limit in system default")(pagination.limit)(20);

  // 3. Small limit, test pagination, page 1 & 2
  output = await api.functional.ai_ecommerce.administrators.patch(connection, {
    body: { limit: 1 },
  });
  typia.assert(output);
  TestValidator.equals("page1 limit")(output.pagination.limit)(1);
  TestValidator.equals("page1 length")(output.data.length)(1);
  const adminOnPage1 = output.data[0];
  output = await api.functional.ai_ecommerce.administrators.patch(connection, {
    body: { limit: 1, page: 2 },
  });
  typia.assert(output);
  TestValidator.equals("page2 limit")(output.pagination.limit)(1);
  // Optional: data[0] should not equal adminOnPage1 if >1 entries
  if (output.data.length > 0 && output.pagination.records > 1) TestValidator.notEquals("page2 is new admin")(output.data[0].id)(adminOnPage1.id);

  // 4. Filter by profile_id - should return the created admin
  output = await api.functional.ai_ecommerce.administrators.patch(connection, {
    body: { search: profileId },
  });
  typia.assert(output);
  TestValidator.predicate("at least one admin matches")(output.data.find((a) => a.profile_id === profileId) !== undefined);

  // 5. Large limit capped to 100
  output = await api.functional.ai_ecommerce.administrators.patch(connection, {
    body: { limit: 100 },
  });
  typia.assert(output);
  TestValidator.equals("limit capped")(output.pagination.limit)(100);
  TestValidator.predicate("no over-fetch")(output.data.length <= 100);

  // 6. Sort by created_at desc
  output = await api.functional.ai_ecommerce.administrators.patch(connection, {
    body: { sort_key: "created_at", sort_order: "desc" },
  });
  typia.assert(output);
  const isSorted = output.data.every((admin, idx) => !output.data[idx+1] || admin.created_at >= output.data[idx+1].created_at);
  TestValidator.predicate("sorted by created_at desc")(isSorted);

  // 7. Summary field safety (again)
  TestValidator.predicate("summary fields only 2")(output.data.every((admin) => {
    const allowedKeys = ["id", "profile_id", "created_at", "updated_at", "deleted_at"];
    return Object.keys(admin).every((k) => allowedKeys.includes(k));
  }));
}

