import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_administrators } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_administrators";
import type { IAiEcommerceAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceAdministrator";

/**
 * Validate successful retrieval of an administrator's details via UUID lookup.
 *
 * This test ensures that an authorized administrator can retrieve another administrator's entity details using a valid UUID. It confirms all standard (but non-sensitive) fields are present and properly typed, including created_at, updated_at, profile_id, and potential deleted_at (should be null for non-deleted, or a string otherwise). The test does not check for sensitive or private fields not documented in the DTO, as these should never be present.
 *
 * Edge cases include handling soft-deleted admins and confirming the deleted_at field is surfaced as appropriate. Additionally, test that error cases (such as invalid or non-existent IDs, though this test focuses on happy path with a known valid ID) do not leak sensitive data in the error response.
 *
 * The dependency step creates a fresh administrator to provide a real, valid admin UUID for this test.
 *
 * Step-by-step process:
 * 1. Create a new administrator to get a valid UUID (by POST).
 * 2. Fetch details of the created administrator via GET by UUID.
 * 3. Validate that all returned fields match the created entity, and that type and presence align with ai_ecommerce_administrators type definition.
 * 4. Confirm soft-delete field (deleted_at) is either null or absent (unless explicitly set in creation or by following up with a delete call).
 * 5. Ensure no extra or sensitive fields are present and no sensitive data is exposed.
 * 6. Confirm access is valid and responses are correct; confirm non-exposure of any unintended fields.
 */
export async function test_api_ai_ecommerce_administrators_test_get_administrator_detail_with_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a new administrator (dependency step)
  const newProfileId: string = typia.random<string & tags.Format<"uuid">>();
  const created: IAiEcommerceAdministrator = await api.functional.ai_ecommerce.administrators.post(connection, {
    body: { profile_id: newProfileId } satisfies IAiEcommerceAdministrator.ICreate,
  });
  typia.assert(created);

  // 2. Retrieve the administrator entity by UUID
  const retrieved: ai_ecommerce_administrators = await api.functional.ai_ecommerce.administrators.getById(connection, {
    id: created.id,
  });
  typia.assert(retrieved);

  // 3. Validate that keys exist and match expected values
  TestValidator.equals("id matches")(retrieved.id)(created.id);
  TestValidator.equals("profile_id matches")(retrieved.profile_id)(created.profile_id);
  TestValidator.equals("created_at matches")(retrieved.created_at)(created.created_at);
  TestValidator.equals("updated_at matches")(retrieved.updated_at)(created.updated_at);

  // 4. Soft-delete transparency
  TestValidator.predicate("deleted_at must be null or string")(retrieved.deleted_at === null || typeof retrieved.deleted_at === "string" || retrieved.deleted_at === undefined);

  // 5. No extra/sensitive fields
  const allowedFields = ["id", "profile_id", "created_at", "updated_at", "deleted_at"];
  const retrievedKeys = Object.keys(retrieved);
  TestValidator.equals("no extra/sensitive fields")(retrievedKeys.sort())(allowedFields.filter(key => retrievedKeys.includes(key)).sort());
}

