import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceAdministrator";
import type { IAiEcommerceUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserProfile";

/**
 * E2E test for creating a new administrator with a unique user profile.
 *
 * This test validates the onboarding workflow for a new administrator:
 * 1. Create a unique user profile
 * 2. Use the profile to create an administrator entry (enforcing 1:1 admin/profile mapping)
 * 3. Validate response fields: id (uuid), profile_id match, created_at/updated_at (ISO date-time), deleted_at
 *
 * Ensures the admin record references the correct profile, audit fields are set, and that only permitted fields are exposed.
 */
export async function test_api_ai_ecommerce_administrators_test_create_administrator_with_valid_unique_profile(
  connection: api.IConnection,
) {
  // Step 1: Create a new, unique user profile for admin linkage
  const profileInput: IAiEcommerceUserProfile.ICreate = {
    nickname: RandomGenerator.alphaNumeric(12),
    email: typia.random<string & tags.Format<"email">>(),
    communication_consent: true,
    avatar_uri: null,
    phone_number: null,
  };
  const userProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: profileInput,
  });
  typia.assert(userProfile);

  // Step 2: Create administrator using the unique profile ID
  const adminInput: IAiEcommerceAdministrator.ICreate = {
    profile_id: userProfile.id,
  };
  const administrator = await api.functional.ai_ecommerce.administrators.post(connection, {
    body: adminInput,
  });
  typia.assert(administrator);

  // Step 3: Validation of created administrator entity
  // 1. id is a UUID
  TestValidator.predicate("admin.id is a uuid string")(/^[0-9a-fA-F\-]{36}$/.test(administrator.id));
  // 2. profile_id matches the just-created user profile's id
  TestValidator.equals("profile link matches")(administrator.profile_id)(userProfile.id);
  // 3. created_at and updated_at are string ISO datetimes
  TestValidator.predicate("created_at is ISO8601 string")(!!administrator.created_at && !isNaN(Date.parse(administrator.created_at)));
  TestValidator.predicate("updated_at is ISO8601 string")(!!administrator.updated_at && !isNaN(Date.parse(administrator.updated_at)));
  // 4. deleted_at is null or undefined (should be active upon creation)
  TestValidator.equals("deleted_at is null or undefined")(administrator.deleted_at === null || administrator.deleted_at === undefined)(true);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceAdministrator";
import type { IAiEcommerceUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserProfile";

/**
 * 테스트: ai_ecommerce_administrators에서 관리자 생성 시의 충돌과 유일성 제약 검증
 *
 * 이 테스트는 다음 두 가지 상황에서 관리자를 새로 생성하려 할 때 실패하는지 확인합니다:
 * - profile_id가 이미 다른 관리자(활성 또는 soft-deleted)에 할당되어 있는 경우
 * - email이 이미 ai_ecommerce_user_profiles에 등록되어 있고, 해당 프로필이 관리자에 연결되어 있는 경우
 *
 * 두 경우 모두, 시스템은 설명적인 오류 메시지를 반환해야 하며, 신규 레코드(관리자 또는 프로필) 생성이 없어야 합니다.
 *
 * 업무 규칙: 한 프로필당 한 명의 관리자만 허용되며, 이메일 역시 유일해야 합니다. soft-deleted 관리자라도 profile_id 재사용이 불가해야 하며, 충돌 시 중간 레코드가 DB에 남지 않아야 합니다.
 *
 * 단계별 절차:
 * 1. 고유 이메일로 user profile 두 개(profileA, profileB) 생성
 * 2. profileA로 관리자(adminA) 생성
 * 3. 동일 profile_id로 관리자 생성 시도 → 실패 및 오류 확인
 * 4. profileA와 동일 이메일로 user profile 생성 시도 → 실패 및 오류 확인
 * 5. (soft-delete API 없어 soft-delete 충돌 확인은 생략)
 * 6. profileB를 이용한 정상 관리자 생성 성공 확인
 */
export async function test_api_ai_ecommerce_administrators_test_create_administrator_with_duplicate_profile_or_email(
  connection: api.IConnection,
) {
  // 1. 고유한 user profile A 생성
  const profileAInput = {
    nickname: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    communication_consent: true,
  } satisfies IAiEcommerceUserProfile.ICreate;
  const profileA = await api.functional.ai_ecommerce.userProfiles.post(connection, { body: profileAInput });
  typia.assert(profileA);

  // 2. 고유한 user profile B 생성 (이메일 다름)
  const profileBInput = {
    nickname: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
