import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceAdministrator";
import type { IAiEcommerceUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserProfile";

/**
 * Validates updating only allowed fields for an existing administrator by an authorized actor.
 *
 * Business context:
 * - Admin records permit only updating non-identifier, non-profile fields (here, only updated_at).
 * - Attempt to modify profile_id or other immutable properties must be explicitly rejected.
 * - System should refresh updated_at and return the updated entity on success.
 * - All updates must set updated_at to current time for audit traceability.
 * - Attempts to mutate immutable fields are expected to yield error responses (compliance).
 *
 * Process:
 * 1. Create a user profile.
 * 2. Create an administrator with that profile.
 * 3. Update the admin's updated_at (success path).
 * 4. Confirm only allowed fields changed; all others unchanged.
 * 5. Attempt to update immutable field (profile_id) and validate error.
 */
export async function test_api_ai_ecommerce_administrators_test_update_administrator_valid_fields_with_proper_privilege(
  connection: api.IConnection,
) {
  // 1. Create a user profile
  const profileInput = {
    nickname: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    communication_consent: true,
    avatar_uri: null,
    phone_number: null,
  } satisfies IAiEcommerceUserProfile.ICreate;
  const profile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: profileInput,
  });
  typia.assert(profile);

  // 2. Create an administrator with the profile
  const adminInput = {
    profile_id: profile.id,
  } satisfies IAiEcommerceAdministrator.ICreate;
  const admin = await api.functional.ai_ecommerce.administrators.post(connection, {
    body: adminInput,
  });
  typia.assert(admin);

  // 3. Update admin (only allowed field: updated_at)
  const now = new Date().toISOString();
  const updated = await api.functional.ai_ecommerce.administrators.putById(connection, {
    id: admin.id,
    body: { updated_at: now } satisfies IAiEcommerceAdministrator.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("id unchanged")(updated.id)(admin.id);
  TestValidator.equals("profile_id unchanged")(updated.profile_id)(admin.profile_id);
  TestValidator.equals("created_at unchanged")(updated.created_at)(admin.created_at);
  TestValidator.equals("updated_at changed")(updated.updated_at)(now);
  TestValidator.equals("deleted_at unchanged")(updated.deleted_at)(admin.deleted_at);

  // 4. Attempt to update immutable field (profile_id) -- should error
  await TestValidator.error("Cannot update profile_id - must be rejected")(
    async () => {
      // Instead of bypassing type safety, construct update object inline with extra property
      // and cast through unknown to allow sending, so test will still compile.
      const invalidUpdate = {
        updated_at: new Date().toISOString(),
        profile_id: typia.random<string & tags.Format<"uuid">>(),
      } as unknown as IAiEcommerceAdministrator.IUpdate;
      await api.functional.ai_ecommerce.administrators.putById(connection, {
        id: admin.id,
        body: invalidUpdate,
      });
    },
  );
}

