 *  1. Attempting to update a soft-deleted administrator (deleted_at set) must be rejected with a clear error, with no changes permitted.
 *  2. Attempting to update forbidden/immutable fields (such as profile_id) is impossible via the API as the DTO does not allow it; any client attempt is a compile-time error, not a runtime API error.
 *
 * Steps:
 * 1. Create a user profile to attach to the administrator.
 * 2. Create an administrator with a unique profile_id.
 * 3. Soft-delete the administrator (deleted_at is set).
 * 4. Attempt to update the soft-deleted administrator (must fail, error thrown).
 * 5. (Immutable field update cannot be attempted – omitted by DTO constraint.)
 *
 * If a GET endpoint existed for administrators, we would verify the admin state did not change. Since only create and erase are exposed, we rely on API errors and soft-delete validation.
 */
export async function test_api_ai_ecommerce_administrators_test_update_administrator_with_deleted_status_or_forbidden_fields(
  connection: api.IConnection,
) {
  // 1. Create a new user profile for the admin
  const userProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(userProfile);

  // 2. Create the administrator using the above user profile
  const admin = await api.functional.ai_ecommerce.administrators.post(connection, {
    body: {
      profile_id: userProfile.id,
    } satisfies IAiEcommerceAdministrator.ICreate,
  });
  typia.assert(admin);

  // 3. Soft-delete (deactivate) the administrator
  const deletedAdmin = await api.functional.ai_ecommerce.administrators.eraseById(connection, {
    id: admin.id,
  });
  typia.assert(deletedAdmin);
  TestValidator.predicate("administrator soft deleted: deleted_at set")(
    typeof deletedAdmin.deleted_at === "string" && !!deletedAdmin.deleted_at
  );

  // 4. Attempt to update the soft-deleted admin, should throw error
  await TestValidator.error("update on soft-deleted admin is forbidden")(
    () => api.functional.ai_ecommerce.administrators.putById(connection, {
      id: admin.id,
      body: {
        updated_at: new Date().toISOString(),
      } satisfies IAiEcommerceAdministrator.IUpdate,
    })
  );

  // 5. Attempting to set immutable field (profile_id) is a compile-time error and cannot be tested at runtime.
  // (Any such attempt would be rejected by TypeScript before executing the test.)
}

