/**
 * Test retrieving a filtered and paginated list of audit logs as an administrator.
 *
 * Validates that the audit logs list endpoint correctly applies multiple search filters and pagination parameters.
 * This includes ensuring that only logs matching the provided filters (actor_admin_id, action_type, date range, etc.)
 * are returned, and that pagination metadata (current page, limit, records, pages) is accurate and consistent with the data set.
 *
 * Scenario outline:
 * 1. Create several audit log records with a variety of actor_admin_id, action_type, and created_at values.
 * 2. Choose a unique actor_admin_id and action_type for filter criteria, and determine a date range covering known logs.
 * 3. Call the audit log list endpoint with these filters and valid pagination params (page, limit).
 * 4. Verify only logs matching all filter criteria are returned.
 * 5. Check pagination metadata for consistency with data and filter set.
 * 6. (Assume admin privileges are already present in connection.)
 */
export async function test_api_ai_ecommerce_test_list_audit_logs_with_search_and_pagination_success(
  connection: api.IConnection,
) {
  // 1. Create audit logs for varying admins, actions, and times
  const adminA = typia.random<string & tags.Format<"uuid">>();
  const adminB = typia.random<string & tags.Format<"uuid">>();
  const actionTypes = ["login", "update_order", "delete_user"];
  const now = new Date();
  const logs: IAiEcommerceAuditLogs[] = [];
  for (let i = 0; i < 10; ++i) {
    // Create logs alternating admins and action types
    const log = await api.functional.ai_ecommerce.auditLogs.post(connection, {
      body: {
        actor_admin_id: i % 2 === 0 ? adminA : adminB,
        action_type: actionTypes[i % actionTypes.length],
        target_table: "orders",
        target_id: typia.random<string & tags.Format<"uuid">>(),
        description: `Log #${i}`,
        created_at: new Date(now.getTime() - i * 3600 * 1000).toISOString(),
      } as any,
    });
    typia.assert(log);
    logs.push(log);
  }

  // 2. Filtering criteria: pick adminA, actionTypes[1], and determine a relevant date range
  const filterAdmin = adminA;
  const filterAction = actionTypes[1];
  // Find logs matching the filter (for later manual validation)
  const filtered = logs.filter(
    (log) =>
      log.actor_admin_id === filterAdmin && log.action_type === filterAction,
  );
  // Determine date range: from most recent to oldest among those
  const dateFrom = filtered.length > 0 ? filtered[filtered.length - 1].created_at : now.toISOString();
  const dateTo = filtered.length > 0 ? filtered[0].created_at : now.toISOString();

  // 3. Query using the chosen filters and pagination settings
  const page = 1;
  const limit = 2;
  const result = await api.functional.ai_ecommerce.auditLogs.patch(connection, {
    body: {
      actor_admin_id: filterAdmin,
      action_type: filterAction,
      created_from: dateFrom,
      created_to: dateTo,
      page,
      limit,
