import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing and searching of favorite tags for an authenticated customer with pagination and filtering.
 *
 * This test ensures:
 * - A customer can create a profile and add multiple favorite tags.
 * - The PATCH /ai_ecommerce/favoriteTags API only returns tags owned by the requesting customer, regardless of filters/pagination.
 * - Listing supports filtering by tag name and pagination parameters. Results must never include other users' tags.
 * - Checks both non-empty (some tags exist) and empty (no tags) edge cases.
 * - Verifies pagination metadata (total, page, etc.) and correct page data boundaries.
 * - Tests invalid filter/edge params, confirming robust error or empty result handling.
 *
 * Steps:
 * 1. Create a customer profile (POST /ai_ecommerce/userProfiles)
 * 2. Add multiple favorite tags for this customer (POST /ai_ecommerce/favoriteTags)
 * 3. (Edge) Create a second customer with no tags
 * 4. Retrieve tags using PATCH /ai_ecommerce/favoriteTags with various filters (by name substring, exact name, all, page beyond, limit, etc.)
 * 5. Ensure only current customer's tags appear no matter the filter, never another user's tags
 * 6. Validate pagination correctness and total counts
 * 7. Use edge-case filters (nonexistent tag name, page out of bounds, min/max limit) and validate result/metadata
 */
export async function test_api_ai_ecommerce_test_list_favorite_tags_for_authenticated_customer_with_pagination_and_filtering(
  connection: api.IConnection,
) {
  // 1. Create the main customer profile
  const mainProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true,
    },
  });
  typia.assert(mainProfile);

  // 2. Add several favorite tags for this customer
  const tagNames = ["Books", "Electronics", "Summer", "shopping", "Birthday Gifts"];
  const createdTags = await Promise.all(
    tagNames.map(name => api.functional.ai_ecommerce.favoriteTags.post(connection, {
        body: {
          customer_id: mainProfile.id,
          name,
        },
      })
    )
  );
  createdTags.forEach(tag => typia.assert(tag)); // FIXED: proper assertion on each tag

  // 3. Create a second customer with NO tags (to test isolation)
  const otherProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true,
    },
  });
  typia.assert(otherProfile);

  // 4. Search for tags with NO filters (should get all own tags paginated)
  const allTagsResponse = await api.functional.ai_ecommerce.favoriteTags.patch(connection, {
    body: {
      customer_id: mainProfile.id,
      page: 1,
      limit: 3,
    },
  });
  typia.assert(allTagsResponse);
  TestValidator.equals("returns only own tags count")(allTagsResponse.pagination.records)(createdTags.length);
  TestValidator.predicate("max 3 returned for limit 3")(allTagsResponse.data.length <= 3);
  allTagsResponse.data.forEach(tag => {
    TestValidator.equals("only own tags")(tag.customer_id)(mainProfile.id);
    TestValidator.predicate("data in original created tags")(tagNames.includes(tag.name));
  });

  // 5. Search by tag name substring (e.g., 'Book')
  const bookTags = await api.functional.ai_ecommerce.favoriteTags.patch(connection, {
    body: {
      customer_id: mainProfile.id,
      name: "Book",
      page: 1,
      limit: 10,
    },
  });
  typia.assert(bookTags);
  bookTags.data.forEach(tag => {
    TestValidator.predicate("name contains Book")(tag.name.toLowerCase().includes("book".toLowerCase()));
    TestValidator.equals("is own tag")(tag.customer_id)(mainProfile.id);
  });

  // 6. Searching with filter that yields NO result
  const noTag = await api.functional.ai_ecommerce.favoriteTags.patch(connection, {
    body: {
      customer_id: mainProfile.id,
      name: "NonexistentTagName",
      page: 1,
      limit: 10,
    },
  });
  typia.assert(noTag);
  TestValidator.equals("empty on no match")(noTag.data.length)(0);
  TestValidator.equals("records 0 on no match")(noTag.pagination.records)(0);

  // 7. Pagination edge: Request a page out-of-bounds (e.g., page 100)
  const outOfBounds = await api.functional.ai_ecommerce.favoriteTags.patch(connection, {
    body: {
      customer_id: mainProfile.id,
      page: 100,
      limit: 10,
    },
  });
  typia.assert(outOfBounds);
  TestValidator.equals("no results for out of bounds")(outOfBounds.data.length)(0);
  TestValidator.equals("pagination still correct")(outOfBounds.pagination.records)(createdTags.length);

  // 8. Min/max limit edge (min 1, max 100)
  const minLimitTags = await api.functional.ai_ecommerce.favoriteTags.patch(connection, {
    body: {
      customer_id: mainProfile.id,
      page: 1,
      limit: 1,
    },
  });
  typia.assert(minLimitTags);
  TestValidator.equals("returns 1 tag for limit 1")(minLimitTags.data.length)(1);

  const maxLimitTags = await api.functional.ai_ecommerce.favoriteTags.patch(connection, {
    body: {
      customer_id: mainProfile.id,
      page: 1,
      limit: 100,
    },
  });
  typia.assert(maxLimitTags);
  TestValidator.equals("max 100, sees all tags")(maxLimitTags.data.length)(createdTags.length);

  // 9. Make sure other's tags never leak to this user
  const searchOther = await api.functional.ai_ecommerce.favoriteTags.patch(connection, {
    body: {
      customer_id: otherProfile.id,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(searchOther);
  TestValidator.equals("no tags for another profile")(searchOther.data.length)(0);
  TestValidator.equals("records 0 for another profile")(searchOther.pagination.records)(0);
}

