import type { IAiEcommerceFavoriteTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceFavoriteTag";

/**
 * Validate unique constraint violation when updating a favorite tag name to duplicate another's for the same customer.
 *
 * This test ensures the API enforces the business rule that a customer cannot have two favorite tags with the same name, even via update.
 *
 * Steps:
 * 1. Create a new customer user profile (with unique email).
 * 2. Register two favorite tags for this customer, each with distinct names.
 * 3. Attempt to update the name of the second tag to be identical to the first tag's name.
 * 4. Assert that the system rejects the update, raising an error due to the name uniqueness violation (business logic error, not type error).
 */
export async function test_api_ai_ecommerce_favoriteTags_test_update_favorite_tag_name_to_duplicate_fails(
  connection: api.IConnection,
) {
  // 1. Create a new customer user profile
  const email = typia.random<string & tags.Format<"email">>();
  const profile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email,
      communication_consent: true,
      avatar_uri: null,
      phone_number: null,
    },
  });
  typia.assert(profile);

  // 2. Register two favorite tags for this customer, each with distinct names
  const tagA = await api.functional.ai_ecommerce.favoriteTags.post(connection, {
    body: {
      customer_id: profile.id,
      name: RandomGenerator.alphaNumeric(10),
    },
  });
  typia.assert(tagA);

  let tagBName: string;
  do {
    tagBName = RandomGenerator.alphaNumeric(10);
  } while (tagBName === tagA.name);
  const tagB = await api.functional.ai_ecommerce.favoriteTags.post(connection, {
    body: {
      customer_id: profile.id,
      name: tagBName,
    },
  });
  typia.assert(tagB);

  // 3. Attempt to update the second tag's name to be identical to the first tag's name
  await TestValidator.error("duplicate tag name for customer should fail")(async () => {
    await api.functional.ai_ecommerce.favoriteTags.putById(connection, {
      id: tagB.id,
      body: {
        name: tagA.name,
      },
    });
  });
}

