import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceForumThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceForumThread";
import type { IPageIAiEcommerceForumThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiEcommerceForumThread";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test paginated listing of forum threads with default pagination and minimal criteria.
 *
 * This test ensures that the API's paginated list endpoint for forum threads
 * behaves correctly under default conditions. It focuses on verifying core aspects such as:
 *   - At least one thread exists (created up front)
 *   - The endpoint supports minimal search/filter criteria (such as none, or a basic title filter)
 *   - The response structure includes valid pagination metadata and a data array
 *   - Only non-deleted threads are returned
 *   - Returned threads match the given filter criteria, including when no match yields an empty list
 *
 * Steps:
 * 1. Create a forum thread with known, search-friendly attributes
 * 2. Search for threads with no filter (should return at least the created one)
 * 3. Search for threads with a matching criterion (e.g., matching title)
 * 4. Search with a criterion that doesn't match any thread (should return empty data array with valid pagination)
 * 5. Validate pagination metadata and data structure correctness
 */
export async function test_api_ai_ecommerce_test_list_forum_threads_with_default_pagination(connection: api.IConnection) {
  // 1. Create a forum thread with a specific title
  const uniqueTitle = `DefaultPaginationTest_${typia.random<string & tags.Format<"uuid">>()}`;
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const createdThread = await api.functional.ai_ecommerce.forumThreads.post(connection, {
    body: {
      customer_id: customerId,
      title: uniqueTitle,
      body: "Test forum thread for default pagination logic.",
      is_private: false
    } satisfies IAiEcommerceForumThread.ICreate
  });
  typia.assert(createdThread);
  TestValidator.equals("created thread title matches")(createdThread.title)(uniqueTitle);
  TestValidator.equals("created thread not deleted")(createdThread.deleted_at)(null);

  // 2. Search for threads with no filter (should find the created one)
  const searchAll = await api.functional.ai_ecommerce.forumThreads.patch(connection, {
    body: {}
  });
  typia.assert(searchAll);
  TestValidator.equals("pagination present")(typeof searchAll.pagination)("object");
  TestValidator.predicate("at least one thread present")(searchAll.data.length >= 1);
  TestValidator.predicate("created thread present")(
    searchAll.data.some(thread => thread.title === uniqueTitle)
  );
  searchAll.data.forEach(thread => {
    TestValidator.equals("no soft deleted threads in listing")(thread.deleted_at)(null);
  });

  // 3. Search for threads matching the unique title
  const matchingSearch = await api.functional.ai_ecommerce.forumThreads.patch(connection, {
    body: { title: uniqueTitle }
  });
  typia.assert(matchingSearch);
  TestValidator.predicate("matching thread found")(
    matchingSearch.data.some(thread => thread.title === uniqueTitle)
  );
  matchingSearch.data.forEach(thread => {
    TestValidator.equals("each result matches the title")(thread.title)(uniqueTitle);
    TestValidator.equals("no soft deleted threads in match listing")(thread.deleted_at)(null);
  });

  // 4. Search with an impossible title filter to yield no results
  const noMatchSearch = await api.functional.ai_ecommerce.forumThreads.patch(connection, {
    body: { title: "DefinitelyNoThreadWithThisTitle" }
  });
  typia.assert(noMatchSearch);
  TestValidator.equals("no threads match 'impossible' title")(noMatchSearch.data.length)(0);

  // 5. Validate pagination metadata is still correct and complete
  [searchAll, matchingSearch, noMatchSearch].forEach(page => {
    TestValidator.predicate("current has value")(typeof page.pagination.current === "number");
    TestValidator.predicate("limit has value")(typeof page.pagination.limit === "number");
    TestValidator.predicate("records >= 0")(page.pagination.records >= 0);
    TestValidator.predicate("pages >= 0")(page.pagination.pages >= 0);
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceForumThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceForumThread";
import type { IPageIAiEcommerceForumThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiEcommerceForumThread";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E Test for listing forum threads with search and filter.
 *
 * This test ensures that the forum thread listing endpoint works correctly with filter and search parameters, including:
 * - Exact matching by customer, category, and keyword (title)
 * - That privacy rules are enforced: private threads should only be listed for their owner (the creating customer)
 * - Results only contain expected/matching records
 * - (Status filter: can only filter for default backend behavior, since status isn't writable on creation)
 *
 * Steps:
 * 1. Create several forum threads with diverse attributes (different customers, categories, privacy, etc.)
 * 2. Filter by customer_id and check only that customer's threads returned
 * 3. Filter by category_id and check correct threads returned
 * 4. Filter by is_private and check expected visibility (all threads authored by test user)
 * 5. Search by partial title and validate presence of correct threads
 * 6. (Status) Only filter status if there are non-empty values in created set; can't create with explicit status
 * 7. (Pagination) Since pagination is not supported by schema, just ensure listing result isn't empty and covers all created threads.
 */
export async function test_api_ai_ecommerce_test_list_forum_threads_with_search_and_filter(
  connection: api.IConnection,
) {
  // 1. Create diverse sample threads (multi-customer, categories, privacy, etc.)
  const customerA = typia.random<string & tags.Format<"uuid">>();
  const customerB = typia.random<string & tags.Format<"uuid">>();
  const categoryA = typia.random<string & tags.Format<"uuid">>();
  const categoryB = typia.random<string & tags.Format<"uuid">>();

  // Create 6 threads with controlled attributes for robust filter testing
  const threads: IAiEcommerceForumThread[] = [];
  // 3 threads for customerA
  threads.push(
    await api.functional.ai_ecommerce.forumThreads.post(connection, {
      body: {
        customer_id: customerA,
        title: "Filter Test A1",
        body: "Body A1",
        is_private: false,
      },
    }),
  );
  threads.push(
    await api.functional.ai_ecommerce.forumThreads.post(connection, {
      body: {
        customer_id: customerA,
        title: "Private Thread A2",
        body: "Body A2",
        is_private: true,
        category_id: categoryA,
      },
    }),
  );
  threads.push(
    await api.functional.ai_ecommerce.forumThreads.post(connection, {
      body: {
        customer_id: customerA,
        title: "Pinned Open A3",
        body: "Body A3",
        is_private: false,
        category_id: categoryB,
        is_pinned: true,
      },
    }),
  );
  // 3 threads for customerB
  threads.push(
    await api.functional.ai_ecommerce.forumThreads.post(connection, {
      body: {
        customer_id: customerB,
        title: "Filter Test B1",
        body: "Body B1",
        is_private: false,
        category_id: categoryB,
      },
    }),
  );
  threads.push(
    await api.functional.ai_ecommerce.forumThreads.post(connection, {
      body: {
        customer_id: customerB,
        title: "Private Thread B2",
        body: "Body B2",
        is_private: true,
      },
    }),
  );
  threads.push(
    await api.functional.ai_ecommerce.forumThreads.post(connection, {
      body: {
        customer_id: customerB,
        title: "Open Thread B3",
        body: "Body B3",
        is_private: false,
        category_id: categoryA,
      },
    }),
  );

  // 2. Filter by customer_id
  let result = await api.functional.ai_ecommerce.forumThreads.patch(connection, {
    body: { customer_id: customerA },
  });
  typia.assert(result);
  for (const t of result.data)
    TestValidator.equals("customer_id matches A")(t.customer_id)(customerA);
  TestValidator.predicate("returns only A threads")(result.data.length > 0);

  // 3. Filter by category_id
  result = await api.functional.ai_ecommerce.forumThreads.patch(connection, {
    body: { category_id: categoryA },
  });
  typia.assert(result);
  for (const t of result.data)
    TestValidator.equals("category_id matchesA")(t.category_id)(categoryA);
  TestValidator.predicate("category A included")(result.data.length > 0);

  // 4. Filter by is_private true, expect only private
  result = await api.functional.ai_ecommerce.forumThreads.patch(connection, {
    body: { is_private: true },
  });
  typia.assert(result);
  for (const t of result.data)
    TestValidator.equals("is_private true")(t.is_private)(true);
  TestValidator.predicate("all are private")(result.data.length > 0);

  // 4b. Filter by is_private false, expect only public
  result = await api.functional.ai_ecommerce.forumThreads.patch(connection, {
    body: { is_private: false },
  });
  typia.assert(result);
  for (const t of result.data)
    TestValidator.equals("is_private false")(t.is_private)(false);
  TestValidator.predicate("all are public")(result.data.length > 0);

  // 5. Search by partial title (substring)
  result = await api.functional.ai_ecommerce.forumThreads.patch(connection, {
    body: { title: "Pinned" },
  });
  typia.assert(result);
  TestValidator.predicate("at least one contains 'Pinned'")(
    result.data.some((t) => t.title.includes("Pinned")),
  );

  // 6. (Status) Only filter if status is present in created threads
  // Use first returned status to test status search
  const statusToTest = result.data.length > 0 ? result.data[0].status : undefined;
  if (statusToTest) {
    result = await api.functional.ai_ecommerce.forumThreads.patch(connection, {
      body: { status: statusToTest },
    });
    typia.assert(result);
    for (const t of result.data)
      TestValidator.equals("status matches")(t.status)(statusToTest);
    TestValidator.predicate("status present")(result.data.length > 0);
  }

  // 7. Search no matches
  result = await api.functional.ai_ecommerce.forumThreads.patch(connection, {
    body: { title: "SuperNotPresentTitleZZZ" },
  });
  typia.assert(result);
  TestValidator.equals("should be empty for no match")(result.data.length)(0);

  // 8. Listing covers all created threads (no explicit pagination in schema)
  result = await api.functional.ai_ecommerce.forumThreads.patch(connection, {
    body: {},
  });
  typia.assert(result);
  // List should include all created thread ids
  const allCreatedIds = threads.map((t) => t.id);
  const returnedIds = result.data.map((t) => t.id);
  for (const createdId of allCreatedIds) {
    TestValidator.predicate(`created thread ${createdId} found in result`)(
      returnedIds.includes(createdId),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceForumThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceForumThread";
import type { IPageIAiEcommerceForumThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiEcommerceForumThread";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 인증되지 않은 사용자가 포럼 스레드를 검색/목록 조회할 때
 * private(비공개) 스레드 보호와 권한 경계 검증
 *
 * - 인증이 필요 없는 connection(Authorization 헤더 미포함)으로 실행
 * - 공개 스레드는 정상 응답되고, 비공개 스레드는 반환되지 않거나, 접근 자체가 에러가 남을 확인
 *
 * [테스트 절차]
 * 1. 공개 스레드 목록 요청 → 모든 스레드가 is_private=false 인지 검증
 * 2. 비공개 스레드만 명시적으로 요청 → 반환 값이 비어있거나(0개), 에러가 나는지 검증
 * 3. 만약 미인증에서 private thread 요청이 아예 거부된다면, 에러가 발생하는지 체크
 */
export async function test_api_ai_ecommerce_test_list_forum_threads_with_unauthorized_access(
  connection: api.IConnection,
) {
  // 1. 공개 스레드 목록 요청 (is_private: false)
  const publicThreads = await api.functional.ai_ecommerce.forumThreads.patch(
    connection,
    {
      body: { is_private: false } satisfies IAiEcommerceForumThread.IRequest,
    },
  );
  typia.assert(publicThreads);
  for (const thread of publicThreads.data) {
    TestValidator.equals("only non-private threads returned")(thread.is_private)(false);
  }

  // 2. 비공개 스레드만 요청 (is_private: true)
  try {
    const privateThreads = await api.functional.ai_ecommerce.forumThreads.patch(
      connection,
      {
        body: { is_private: true } satisfies IAiEcommerceForumThread.IRequest,
      },
    );
    typia.assert(privateThreads);
    TestValidator.equals("private threads not returned for unauthorized user")(privateThreads.data.length)(0);
  } catch {
    // 3. 미인증으로 완전히 private thread 요청 시 에러가 나는 것도 통과
    // (플랫폼 정책에 따라 에러가 나는 것도 허용)
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceForumThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceForumThread";

/**
 * Validate normal detail retrieval for a forum thread by ID.
 *
 * This test ensures that when requesting the details of an existing forum thread (created just before in the dependency), the API returns the complete thread fields including privacy, pinned, and status flags, along with relational references if present. It checks the basic scenario where the requesting user is permitted to view the thread (as the owner/creator, or, in a future scenario, an admin or other allowed role).
 *
 * Steps:
 * 1. Create a new forum thread using valid input (dependency)
 * 2. Fetch the thread by its returned UUID using the GET endpoint
 * 3. Validate that all fields on the thread match what was provided during creation (except system-generated fields like timestamps/status)
 * 4. Validate privacy flag, pinned status, and core relational references (customer_id, optional product/category)
 * 5. Ensure the thread is visible to the user who created it (and check the privacy rule is not violated in this case).
 */
export async function test_api_ai_ecommerce_forumThreads_test_get_forum_thread_by_id_success(
  connection: api.IConnection,
) {
  // Step 1: Create a forum thread (dependency)
  const createInput: IAiEcommerceForumThread.ICreate = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    title: "Integration Test Thread Title",
    body: "Integration test body content for forum thread get-by-id.",
    is_private: false,
    is_pinned: true,
    product_id: null,
    category_id: null,
  };
  const created: IAiEcommerceForumThread = await api.functional.ai_ecommerce.forumThreads.post(connection, {
    body: createInput,
  });
  typia.assert(created);

  // Step 2: Retrieve the thread by its UUID
  const output: IAiEcommerceForumThread = await api.functional.ai_ecommerce.forumThreads.getById(connection, {
    id: created.id,
  });
  typia.assert(output);

  // Step 3: Validate returned fields (except system managed ones)
  TestValidator.equals("title")(output.title)(createInput.title);
  TestValidator.equals("body")(output.body)(createInput.body);
  TestValidator.equals("customer_id")(output.customer_id)(createInput.customer_id);
  TestValidator.equals("is_private")(output.is_private)(createInput.is_private);
  TestValidator.equals("is_pinned")(output.is_pinned)(createInput.is_pinned ?? false);
  TestValidator.equals("product_id")(output.product_id)(createInput.product_id);
  TestValidator.equals("category_id")(output.category_id)(createInput.category_id);

  // System managed fields: id, status, timestamps should exist and have correct types
  TestValidator.predicate("id is uuid")(typeof output.id === "string" && output.id.length > 0);
  TestValidator.predicate("status is string")(typeof output.status === "string" && output.status.length > 0);
  TestValidator.predicate("created_at is date-time string")(typeof output.created_at === "string" && output.created_at.length > 0);
  TestValidator.predicate("updated_at is date-time string")(typeof output.updated_at === "string" && output.updated_at.length > 0);
}

