 *
 * This test validates that a customer who owns a forum thread can successfully update
 * its editable fields (title, body, status, is_pinned, and is_private). It ensures
 * that the thread's returned state reflects all changes, updates the 'updated_at' timestamp,
 * and keeps immutable properties stable (id, customer_id, created_at).
 *
 * Steps performed:
 * 1. Create an initial forum thread (with test fixture values)
 * 2. Update various fields using the thread owner account
 * 3. Validate that changes are present in the API response and that metadata is
 *    properly refreshed
 * 4. Ensure that only allowed fields are changed—other fields must remain the same
 */
export async function test_api_forumThreads_test_update_forum_thread_by_id_success(
  connection: api.IConnection,
) {
  // 1. Create a forum thread as test fixture
  const initialThread: IAiEcommerceForumThread = await api.functional.ai_ecommerce.forumThreads.post(
    connection,
    {
      body: {
        customer_id: typia.random<string & tags.Format<"uuid">>(),
        product_id: null,
        category_id: null,
        title: "Original Title",
        body: "Original thread body.",
        is_pinned: false,
        is_private: false,
      } satisfies IAiEcommerceForumThread.ICreate,
    },
  );
  typia.assert(initialThread);

  // 2. Prepare updated values
  const updatePayload: IAiEcommerceForumThread.IUpdate = {
    title: "Updated Title",
    body: "Updated thread body.",
    status: "closed",
    is_pinned: true,
    is_private: true,
  };

  // 3. Perform the update as the thread owner
  const updatedThread: IAiEcommerceForumThread = await api.functional.ai_ecommerce.forumThreads.putById(
