  // 4. Validate updated fields
  TestValidator.equals("title updated")(updatedThread.title)(updatePayload.title);
  TestValidator.equals("body updated")(updatedThread.body)(updatePayload.body);
  TestValidator.equals("status updated")(updatedThread.status)(updatePayload.status);
  TestValidator.equals("is_pinned updated")(updatedThread.is_pinned)(updatePayload.is_pinned);
  TestValidator.equals("is_private updated")(updatedThread.is_private)(updatePayload.is_private);

  // 5. Check stable fields remain unchanged
  TestValidator.equals("id stable")(updatedThread.id)(initialThread.id);
  TestValidator.equals("customer_id stable")(updatedThread.customer_id)(initialThread.customer_id);
  TestValidator.equals("created_at stable")(updatedThread.created_at)(initialThread.created_at);

  // 6. Timestamp must update
  TestValidator.predicate("updated_at should change")(updatedThread.updated_at !== initialThread.updated_at);

  // 7. There is no audit/history field per DTO, so no further audit checks here
}

