import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IMvCommunityLastActivity } from "@ORGANIZATION/PROJECT-api/lib/structures/IMvCommunityLastActivity";
import type { IPageIMvCommunityLastActivity } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIMvCommunityLastActivity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test paginated & filtered listing of last community activity records via mvCommunityLastActivity.
 *
 * This test covers:
 * - Fetching a filtered/paginated list by customer_id, activity type, date range.
 * - Ensuring pagination metadata and data structure correctness.
 * - Error conditions: invalid UUIDs, date formats, negative page.
 * - Access control: as admin (allowed) vs unauthorized user (denied).
 *
 * Success workflow:
 * 1. Simulate valid admin connection.
 * 2. Query with combinations of valid filters (customer_id, type, date range, page, limit).
 * 3. Assert structure, pagination fields, and all results match filter criteria.
 * 4. Check pagination: request next page, confirm data/content is different, validate page metadata.
 *
 * Error scenarios:
 * 1. Invalid/malformed UUID for customer_id => expects error.
 * 2. last_activity_at_gte > last_activity_at_lte => expects error or empty result.
 * 3. Negative page/limit => expects error.
 *
 * Access Control:
 * 1. As unauthorized user (without admin role), attempt request => expects error/denied.
 */
export async function test_api_ai_ecommerce_test_list_mv_community_last_activity_with_filters_and_pagination(connection: api.IConnection) {
  // 1. Simulate admin connection (assume already authenticated; role switching not in scenario)

  // 2. Fetch one page with filter by valid customer_id, activity type, and date range
  const req: IMvCommunityLastActivity.IRequest = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    last_activity_type: "comment",
    last_activity_at_gte: new Date(Date.now() - 1000 * 60 * 60 * 24 * 7).toISOString(),
    last_activity_at_lte: new Date().toISOString(),
    page: 1,
    limit: 2,
  };
  const result = await api.functional.ai_ecommerce.mvCommunityLastActivity.patch(connection, { body: req });
  typia.assert(result);
  // Validate result structure, pagination info, and all entries match filter
  result.data.forEach(row => {
    if (req.customer_id) TestValidator.equals("customer_id matches")(row.customer_id)(req.customer_id);
    if (req.last_activity_type) TestValidator.equals("activity type matches")(row.last_activity_type)(req.last_activity_type);
    if (req.last_activity_at_gte) TestValidator.predicate("after or on gte")(row.last_activity_at >= req.last_activity_at_gte!);
    if (req.last_activity_at_lte) TestValidator.predicate("before or on lte")(row.last_activity_at <= req.last_activity_at_lte!);
  });
  TestValidator.predicate("pagination object valid")(typeof result.pagination === "object" && typeof result.pagination.current === "number");

  // 3. Check pagination: request next page, ensure data/content is different, and page metadata reflects paging
  if (result.pagination.pages > 1) {
    const result2 = await api.functional.ai_ecommerce.mvCommunityLastActivity.patch(connection, { body: { ...req, page: 2 } });
    typia.assert(result2);
    TestValidator.notEquals("paging data differs")(result.data)(result2.data);
    TestValidator.equals("page is 2")(result2.pagination.current)(2);
  }

  // 4. Error: malformed customer_id
  await TestValidator.error("malformed customer_id UUID")(() =>
    api.functional.ai_ecommerce.mvCommunityLastActivity.patch(connection, { body: { ...req, customer_id: "not-a-uuid" as any } })
  );

  // 5. Error: gte > lte
  await TestValidator.error("gte after lte")(() => {
    const gte = "2025-04-01T00:00:00.000Z";
    const lte = "2024-04-01T00:00:00.000Z";
    return api.functional.ai_ecommerce.mvCommunityLastActivity.patch(connection, {
      body: { ...req, last_activity_at_gte: gte, last_activity_at_lte: lte },
    });
  });

  // 6. Error: negative page
  await TestValidator.error("negative page")(() =>
    api.functional.ai_ecommerce.mvCommunityLastActivity.patch(connection, { body: { ...req, page: -1 as any } })
  );

  // 7. Error: negative limit
  await TestValidator.error("negative limit")(() =>
    api.functional.ai_ecommerce.mvCommunityLastActivity.patch(connection, { body: { ...req, limit: -5 as any } })
  );

  // 8. Access – simulate unauthorized: strip authorization
  const unauthorizedConnection = { ...connection, headers: { ...connection.headers } };
  delete unauthorizedConnection.headers.Authorization;
  await TestValidator.error("unauthorized")(async () => {
    await api.functional.ai_ecommerce.mvCommunityLastActivity.patch(unauthorizedConnection, { body: req });
  });
}

