 *
 * 1. Creating a last activity record (using POST).
 * 2. Updating all available fields (using PUT by id) with new valid data, reflecting a completely changed last activity context.
 * 3. Retrieving the same record with GET by id to assert all changes are persisted:
 *    - All fields must exactly match the new updated values provided in the PUT.
 *    - The `id` must remain unchanged.
 *    - No extraneous fields exist; missing fields remain absent or null as per schema.
 *    - `last_activity_at` correctly updates (timestamp changes).
 *
 * 4. Also tests that the API response types are validated.
 */
export async function test_api_ai_ecommerce_test_update_last_activity_with_valid_data(
  connection: api.IConnection,
) {
  // Step 1: Create initial record
  const initialInput: IMvCommunityLastActivity.ICreate = {
    // Set all nullable fields to non-null values where schema allows
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    thread_id: typia.random<string & tags.Format<"uuid">>(),
    comment_id: typia.random<string & tags.Format<"uuid">>(),
