  // This includes switching some nullable FKs from set to null and vice versa
  const updatedInput: mvCommunityLastActivity.IUpdate = {
    customer_id: typia.random<string & tags.Format<"uuid">>(), // new customer context
    thread_id: null, // remove thread context
    comment_id: typia.random<string & tags.Format<"uuid">>(),
    inquiry_id: typia.random<string & tags.Format<"uuid">>(), // add inquiry context
    review_id: null,
    last_activity_type: "comment", // change type
    last_activity_at: new Date("2025-07-16T08:26:55.069Z").toISOString(), // update timestamp
  };
  const updated = await api.functional.ai_ecommerce.mvCommunityLastActivity.putById(connection, {
    id: created.id,
    body: updatedInput,
  });
  typia.assert(updated);

  // The ID must remain unchanged
  TestValidator.equals("id unchanged")(updated.id)(created.id);

  // Step 3: Retrieve to confirm update and field persistency
  const fetched = await api.functional.ai_ecommerce.mvCommunityLastActivity.getById(connection, {
    id: created.id,
  });
  typia.assert(fetched);

  // For each updatable property, assert it matches the new value provided
  TestValidator.equals("updated customer_id")(fetched.customer_id)(updatedInput.customer_id);
  TestValidator.equals("updated thread_id")(fetched.thread_id)(updatedInput.thread_id);
  TestValidator.equals("updated comment_id")(fetched.comment_id)(updatedInput.comment_id);
