  TestValidator.equals("updated review_id")(fetched.review_id)(updatedInput.review_id);
  TestValidator.equals("updated last_activity_type")(fetched.last_activity_type)(updatedInput.last_activity_type);
  TestValidator.equals("updated last_activity_at")(fetched.last_activity_at)(updatedInput.last_activity_at);
  TestValidator.equals("no id change")(fetched.id)(created.id);
}

