      body: typia.random<IComplianceAudit.ICreate>(),
    },
  );
  typia.assert(audit);

  // IComplianceAudit 타입에 id 필드가 없으나, 실제 API 동작 위한 키 식별자는 존재한다고 간주
  // 실제에서는 audit.id의 타입 명확화 필요, 현재는 as any로 처리
  const auditId = (audit as any).id;

  // 2. 해당 레코드 소프트 삭제 (DELETE)
  await api.functional.ai_ecommerce.complianceAudits.eraseById(
    connection,
    {
      id: auditId,
    },
