    async () => {
      await api.functional.ai_ecommerce.complianceAudits.eraseById(
        connection,
        {
          id: auditId,
        },
      );
    },
  );

  // 4. deleted_at 필드, 감사 로그 검증은 현재 조회/search API 미지원으로 skip
}

