  const { Authorization, ...otherHeaders } = connection.headers ?? {};
  const nonAdminConnection: api.IConnection = {
    ...connection,
    headers: otherHeaders,
  };

  // 3. putById 호출 시도 → 반드시 권한 오류
  await TestValidator.error("비관리자 putById는 허용되지 않아야 함")(
    async () => {
      await api.functional.ai_ecommerce.systemEvents.putById(nonAdminConnection, {
        id: (event as any).id ?? typia.random<string & tags.Format<"uuid">>(),
        body: {} satisfies IAiEcommerceSystemEvents.IUpdate,
      });
