export async function test_api_ai_ecommerce_test_get_system_event_details_with_valid_id(
  connection: api.IConnection,
) {
  // 1. 테스트 이벤트 사전 등록
  const testEventInput: IAiEcommerceSystemEvent.ICreate = {
    event_type: RandomGenerator.alphaNumeric(16),
    target_table: RandomGenerator.alphaNumeric(12),
    target_id: typia.random<string & tags.Format<"uuid">>(),
    payload_json: JSON.stringify({ foo: "bar", random: RandomGenerator.alphaNumeric(8) }),
