  TestValidator.equals("event_type 일치")(retrievedEvent.event_type)(createdEvent.event_type);
  TestValidator.equals("target_table 일치")(retrievedEvent.target_table)(createdEvent.target_table);
  TestValidator.equals("target_id 일치")(retrievedEvent.target_id)(createdEvent.target_id);
  TestValidator.equals("payload_json 일치")(retrievedEvent.payload_json)(createdEvent.payload_json);
  TestValidator.equals("created_at 일치")(retrievedEvent.created_at)(createdEvent.created_at);
}

