import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceSystemEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceSystemEvent";

/**
 * Validate creation and append-only semantics of ai_ecommerce system event logs.
 *
 * This test ensures that an administrator can POST to /ai_ecommerce/systemEvent to create system event log entries in the ai_ecommerce_system_event table with a valid payload. Both common and rare event types are tested, and the function confirms that each event is append-only and immutable after creation. Since there is no direct GET or update API, immutability is tested by re-use of target_id and comparison of returned records (UUID, timestamp, payload, etc.).
 *
 * Steps:
 * 1. Compose and POST a payload with a common event type (e.g., 'order_created'). Assert that the response matches input fields and formats.
 * 2. Compose and POST a payload with a rare event type (e.g., 'ai_monitor'). Assert that the response matches input fields and is accepted.
 * 3. POST another event for the same target_id with a new payload and event_type. Assert that a new record is appended, not overwritten (new id, new created_at).
 * 4. Validate that all returned events are distinct (id/created_at) and strictly reflect their posted payloads.
 */
export async function test_api_ai_ecommerce_test_create_system_event_with_valid_payload(connection: api.IConnection) {
  // 1. POST event with a common event_type
  const target_id: string = typia.random<string & tags.Format<"uuid">>();
  const now_iso: string = new Date().toISOString();
  const event_payload_common: IAiEcommerceSystemEvent.ICreate = {
    event_type: "order_created",
    target_table: "orders",
    target_id,
    payload_json: JSON.stringify({ orderId: target_id, amount: 3900, currency: "KRW" }),
    created_at: now_iso,
  };
  const created_common = await api.functional.ai_ecommerce.systemEvent.post(connection, { body: event_payload_common });
  typia.assert(created_common);
  // Validate returned fields match sent payload (except id is generated by server)
  TestValidator.equals("event_type matches")(created_common.event_type)(event_payload_common.event_type);
  TestValidator.equals("target_table matches")(created_common.target_table)(event_payload_common.target_table);
  TestValidator.equals("target_id matches")(created_common.target_id)(event_payload_common.target_id);
  TestValidator.equals("payload_json matches")(created_common.payload_json)(event_payload_common.payload_json);
  TestValidator.equals("created_at matches")(created_common.created_at)(event_payload_common.created_at);
  TestValidator.predicate("Returned event id is uuid type")(typeof created_common.id === "string" && /^[0-9a-fA-F-]{36}$/.test(created_common.id));

  // 2. POST event with a rare event_type
  const event_payload_rare: IAiEcommerceSystemEvent.ICreate = {
    event_type: "ai_monitor",
    target_table: "ai_service",
    target_id: typia.random<string & tags.Format<"uuid">>(),
    payload_json: JSON.stringify({ anomaly: "spike", probability: 0.9911 }),
    created_at: new Date(Date.now() + 1000).toISOString(),
  };
  const created_rare = await api.functional.ai_ecommerce.systemEvent.post(connection, { body: event_payload_rare });
  typia.assert(created_rare);
  TestValidator.equals("event_type matches")(created_rare.event_type)(event_payload_rare.event_type);
  TestValidator.equals("target_table matches")(created_rare.target_table)(event_payload_rare.target_table);
  TestValidator.equals("target_id matches")(created_rare.target_id)(event_payload_rare.target_id);
  TestValidator.equals("payload_json matches")(created_rare.payload_json)(event_payload_rare.payload_json);
  TestValidator.equals("created_at matches")(created_rare.created_at)(event_payload_rare.created_at);
  TestValidator.predicate("Returned event id is uuid type")(typeof created_rare.id === "string" && /^[0-9a-fA-F-]{36}$/.test(created_rare.id));
  TestValidator.notEquals("event ids differ")(created_common.id)(created_rare.id);

  // 3. POST another event for the same target_id (should append, not overwrite)
  const event_payload_append: IAiEcommerceSystemEvent.ICreate = {
    event_type: "custom_audit",
    target_table: "orders",
    target_id, // same as first event
    payload_json: JSON.stringify({ trace: "manual action", user: "admin01" }),
    created_at: new Date(Date.now() + 2000).toISOString(),
  };
  const created_append = await api.functional.ai_ecommerce.systemEvent.post(connection, { body: event_payload_append });
  typia.assert(created_append);

  // Validate that this is a NEW record (id/created_at)
  TestValidator.notEquals("id for appended event is unique")(created_append.id)(created_common.id);
  TestValidator.notEquals("id for appended event is unique vs rare")(created_append.id)(created_rare.id);
  TestValidator.equals("target_id matches")(created_append.target_id)(target_id);
  TestValidator.equals("event_type matches")(created_append.event_type)(event_payload_append.event_type);
  TestValidator.equals("target_table matches")(created_append.target_table)(event_payload_append.target_table);
  TestValidator.equals("payload_json matches")(created_append.payload_json)(event_payload_append.payload_json);
  TestValidator.equals("created_at matches")(created_append.created_at)(event_payload_append.created_at);

  // 4. The three records must all be independent (append-only)
  TestValidator.notEquals("all ids must differ")(created_append.id)(created_common.id);
  TestValidator.notEquals("all ids must differ")(created_append.id)(created_rare.id);
  TestValidator.notEquals("all ids must differ")(created_common.id)(created_rare.id);
}

