import type { IPageMvDailyStats } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageMvDailyStats";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test paginated, filtered retrieval of daily platform statistics (mvDailyStats)
 * by an administrator, ensuring that valid filters (like stat_date range and
 * revenue thresholds) return correct paginated analytics snapshots with all
 * expected fields populated. This test supports dashboard/reporting validity.
 *
 * Steps:
 * 1. Prepare a filter object for mvDailyStats search with stat_date range,
 *    min/max revenue_amount, minibatch pagination, etc.
 * 2. Call the mvDailyStats.patch endpoint with filter and pagination params.
 * 3. Validate the response:
 *    - Is paginated (pagination metadata populated; limit/page/records/pages)
 *    - Data array is present, each item is a fully populated mvDailyStats object
 *    - All numeric and required fields are present and correctly typed
 *    - All data matches filter constraints (date range, revenue range, etc.)
 * 4. Test both: (a) result set present, and (b) edge case: filters returning zero data
 */
export async function test_api_ai_ecommerce_test_list_mvdailystats_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // Step 1: Prepare filter with stat_date range and revenue threshold, plus pagination
  const filter = {
    stat_date_gte: "2024-04-01",
    stat_date_lte: "2024-05-01",
    min_revenue_amount: 5000,
    max_revenue_amount: 1000000,
    page: 1,
    limit: 10,
    sort_by: "stat_date",
    sort_order: "desc"
  } satisfies mvDailyStats.IRequest;

  // Step 2: Retrieve filtered data via PATCH endpoint
  const output = await api.functional.ai_ecommerce.mvDailyStats.patch(connection, {
    body: filter
  });
  typia.assert(output);

  // Step 3: Validate pagination structure
  TestValidator.predicate("pagination - current page")(output.pagination.current === 1);
  TestValidator.predicate("pagination - limit is 10")(output.pagination.limit === 10);
  TestValidator.predicate("pagination - pages positive")(output.pagination.pages >= 0);
  TestValidator.predicate("pagination - records >= 0")(output.pagination.records >= 0);
  TestValidator.predicate("data is array")(Array.isArray(output.data));

  // Step 4: If records present, validate filter criteria and record shape
  if (output.data.length > 0) {
    for (const row of output.data) {
      typia.assert(row);
      TestValidator.predicate("stat_date in range")(row.stat_date >= filter.stat_date_gte && row.stat_date <= filter.stat_date_lte);
      TestValidator.predicate("revenue in range")(row.revenue_amount >= filter.min_revenue_amount && row.revenue_amount <= filter.max_revenue_amount);
      TestValidator.predicate("count fields int32")(Number.isInteger(row.order_count) && Number.isInteger(row.login_count) && Number.isInteger(row.signups_count) && Number.isInteger(row.review_count));
      TestValidator.predicate("id UUID")(typeof row.id === "string" && row.id.length > 0);
    }
  }

  // Step 5: Negative case - filter for impossible revenue range (should yield zero records)
  const impossibleFilter = {
    stat_date_gte: "2000-01-01",
    stat_date_lte: "2000-01-02",
    min_revenue_amount: 9999999999,
    max_revenue_amount: 9999999999,
    page: 1,
    limit: 5,
    sort_by: "stat_date",
    sort_order: "asc"
  } satisfies mvDailyStats.IRequest;
  const impossible = await api.functional.ai_ecommerce.mvDailyStats.patch(connection, { body: impossibleFilter });
  typia.assert(impossible);
  TestValidator.equals("no data for impossible filter")(impossible.data.length)(0);
}

