 *
 * This test verifies that an existing mvDailyStats record (daily platform analytics snapshot) can be fully replaced via the PUT endpoint by providing a new IUpdate payload, and that the response reflects the replacement values.
 *
 * Steps:
 * 1. Create a mvDailyStats record for a specific day using the POST endpoint (so there is a valid ID to update)
 * 2. Update every field of that record using a new IUpdate payload via PUT
 * 3. Assert that the response from PUT matches the full replacement and carries the submitted fields exactly.
 * 4. Validate the id remains the same (referential integrity check)
 *
 * Business Constraints:
 * - stat_date in the update should stay consistent with its format and is allowed to be changed (if business logic allows)
 * - All atomic value fields (order_count, revenue_amount, login_count, signups_count, review_count) must be updated correctly
 * - The returned entity must reflect all these new values 1:1 from the PUT payload
 */
export async function test_api_ai_ecommerce_mvDailyStats_test_update_mvdailystats_full_replacement_success(
  connection: api.IConnection,
) {
  // 1. Create a mvDailyStats entry (to update)
  const createInput = {
    stat_date: "2025-07-16",
    order_count: 123,
    revenue_amount: 55543.89,
    login_count: 87,
    signups_count: 15,
    review_count: 6,
  } satisfies mvDailyStats.ICreate;
  const initial = await api.functional.ai_ecommerce.mvDailyStats.post(connection, {
    body: createInput,
  });
  typia.assert(initial);

  // 2. Prepare a new IUpdate payload with new analytics
  const updateInput = {
    stat_date: "2025-07-17",
    order_count: 222,
    revenue_amount: 87999.99,
    login_count: 100,
    signups_count: 18,
    review_count: 12,
  } satisfies mvDailyStats.IUpdate;

  // 3. Perform PUT for full replacement
  const updated = await api.functional.ai_ecommerce.mvDailyStats.putById(connection, {
    id: initial.id,
    body: updateInput,
  });
  typia.assert(updated);

  // 4. Assert all fields match the update payload (including id remains the same)
  TestValidator.equals("id unchanged")(updated.id)(initial.id);
  TestValidator.equals("stat_date matches")(updated.stat_date)(updateInput.stat_date);
  TestValidator.equals("order_count matches")(updated.order_count)(updateInput.order_count);
