  TestValidator.equals("login_count matches")(updated.login_count)(updateInput.login_count);
  TestValidator.equals("signups_count matches")(updated.signups_count)(updateInput.signups_count);
  TestValidator.equals("review_count matches")(updated.review_count)(updateInput.review_count);
}

