import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_inquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_inquiry";

/**
 * 상품/주문 문의 리스트 검색, 필터 및 페이징 기능을 검증합니다.
 *
 * 이 테스트는 두 개 이상의 서로 다른 상품, 상태, 공개/비공개 문의 글이 존재하는 전제에서,
 * 인증된(권한 보유) 사용자가 필터(상품, 주문, 고객, 상태, 생성일, 비공개 여부 등)를 조합해 페이징 검색을 했을 때
 * RBAC/가시성 정책상 사용자가 접근가능한 문의만 반환하고,
 * 전체 개수(total)·페이지(page)·limit 등 페이지네이션 메타데이터와 필터 결과가 정확한지 검증합니다.
 *
 * 1. 서로 다른 속성(상품, 상태, is_private)이 부여된 문의 두 건 생성
 * 2. 인증 사용자가 필터 없이 전체 문의(본인권한 범위)를 페이징 조회하고, 메타데이터·데이터배열 검증
 * 3. 상품별, 상태별, 비공개·공개여부별 등으로 각각 조회 필터해 결과 건수와 데이터 일치 확인
 * 4. 존재하지 않는 상품ID, 고객ID 등의 부정 필터에 대해 빈 목록/zero total 반환하는지 확인
 * 5. open/closed 등 상태별 필터 동작 및 is_private true/false별 조회 결과 일치 확인
 *
 * (사전조건: 문의 두 건은 post API로 테스트 내에서 생성)
 */
export async function test_api_ai_ecommerce_test_list_inquiries_with_pagination_and_filters_for_authorized_user(connection: api.IConnection) {
  // 1. 서로 다른 속성(상품, 상태, 비공개/공개)이 부여된 문의 두 건 생성(POST)
  const customer_id = typia.random<string & tags.Format<"uuid">>();
  const product_id1 = typia.random<string & tags.Format<"uuid">>();
  const product_id2 = typia.random<string & tags.Format<"uuid">>();

  // 첫 번째 문의(open/공개)
  const inquiry1 = await api.functional.ai_ecommerce.inquiries.post(connection, {
    body: {
      customer_id,
      product_id: product_id1,
      title: "Test Inquiry Open",
      body: "Test content open",
      is_private: false,
    } satisfies ai_ecommerce_inquiry.ICreate,
  });
  typia.assert(inquiry1);

  // 두 번째 문의(closed/비공개)
  const inquiry2 = await api.functional.ai_ecommerce.inquiries.post(connection, {
    body: {
      customer_id,
      product_id: product_id2,
      title: "Test Inquiry Closed",
      body: "Test content closed",
      is_private: true,
    } satisfies ai_ecommerce_inquiry.ICreate,
  });
  typia.assert(inquiry2);

  // 2. 전체 목록 조회(필터 없음, 본인권한 범위)
  const resAll = await api.functional.ai_ecommerce.inquiries.patch(connection, {
    body: {
      customer_id,
      page: 0,
      limit: 10,
    } satisfies ai_ecommerce_inquiry.IRequest,
  });
  typia.assert(resAll);
  // 두 건 모두 조회되어야 함
  TestValidator.predicate("all inquiries listed")(
    resAll.data.some((row) => row.id === inquiry1.id) &&
    resAll.data.some((row) => row.id === inquiry2.id)
  );
  TestValidator.equals("total inquiries")(resAll.total)(2);

  // 3. 상품별 필터: product_id1로만 조회시(inquiry1만)
  const resByProduct = await api.functional.ai_ecommerce.inquiries.patch(connection, {
    body: {
      customer_id,
      product_id: product_id1,
      page: 0,
      limit: 10,
    } satisfies ai_ecommerce_inquiry.IRequest,
  });
  typia.assert(resByProduct);
  TestValidator.equals("inquiry by product1")(resByProduct.total)(1);
  TestValidator.equals("data by product1")(resByProduct.data[0].id)(inquiry1.id);

  // 3-2. 비공개만 필터
  const resPrivate = await api.functional.ai_ecommerce.inquiries.patch(connection, {
    body: {
      customer_id,
      is_private: true,
      page: 0,
      limit: 10,
    } satisfies ai_ecommerce_inquiry.IRequest,
  });
  typia.assert(resPrivate);
  TestValidator.equals("inquiry private only")(resPrivate.total)(1);
  TestValidator.equals("data private")(resPrivate.data[0].id)(inquiry2.id);

  // 3-3. 공개만 필터
  const resPublic = await api.functional.ai_ecommerce.inquiries.patch(connection, {
    body: {
      customer_id,
      is_private: false,
      page: 0,
      limit: 10,
    } satisfies ai_ecommerce_inquiry.IRequest,
  });
  typia.assert(resPublic);
  TestValidator.equals("inquiry public only")(resPublic.total)(1);
  TestValidator.equals("data public")(resPublic.data[0].id)(inquiry1.id);

  // 4. 존재하지 않는 상품ID(필터) 요청(빈 배열/zero total)
  const resNotExist = await api.functional.ai_ecommerce.inquiries.patch(connection, {
    body: {
      customer_id,
      product_id: typia.random<string & tags.Format<"uuid">>(), // 없는 ID
      page: 0,
      limit: 10,
    } satisfies ai_ecommerce_inquiry.IRequest,
  });
  typia.assert(resNotExist);
  TestValidator.equals("empty when no matching product")(resNotExist.total)(0);
  TestValidator.equals("empty data array")(resNotExist.data.length)(0);

  // 5. 생성일 기준 필터 - 한 inquiry만 노출
  const createdFrom = inquiry2.created_at; // 두 번째 문의 생성일로 필터(첫 문의는 조회 안 됨)
  const resByCreatedFrom = await api.functional.ai_ecommerce.inquiries.patch(connection, {
    body: {
      customer_id,
      created_from: createdFrom,
      page: 0,
      limit: 10,
    } satisfies ai_ecommerce_inquiry.IRequest,
  });
  typia.assert(resByCreatedFrom);
  TestValidator.predicate("filtered by created_from")(
    resByCreatedFrom.data.every((row) => row.created_at >= createdFrom)
  );
}

