import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_inquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_inquiry";

/**
 * Validate that the inquiry listing API properly rejects invalid search or pagination parameters.
 *
 * This test targets robustness when users attempt to execute list queries with invalid, incomplete, or conflicting options:
 * - Use a clearly invalid status value (e.g., a random string that is not an allowed status).
 * - Set negative values for required pagination parameters (e.g., page or limit < 0).
 * - Send incomplete objects omitting required fields (e.g., no 'page' or no 'limit').
 * - Provide logically contradictory parameters (e.g., created_from > created_to).
 * In every case:
 *   1. The server MUST reject the request, respond with a well-formed error (not unhandled 500), and never leak actual inquiry data.
 *   2. Output MUST NOT contain any inquiries (data[] should be empty or undefined in error).
 *
 * Steps:
 * 1. Attempt request with status set to a non-existent value.
 * 2. Attempt request with negative page number.
 * 3. Attempt request with negative limit.
 * 4. Attempt request with 'created_from' date after 'created_to' (contradictory dates).
 * 5. (Omit required fields is not allowed in TypeScript, so skip)
 * In all above cases, validate error is thrown, and no inquiries are returned.
 */
export async function test_api_ai_ecommerce_inquiries_test_list_inquiries_with_invalid_filter_or_pagination_request(
  connection: api.IConnection,
) {
  // 1. Invalid status value
  await TestValidator.error("invalid status value should be rejected")(() =>
    api.functional.ai_ecommerce.inquiries.patch(connection, {
      body: {
        page: 1,
        limit: 20,
        status: "not_a_real_status___", // definitely not valid
      },
    }),
  );

  // 2. Negative page number
  await TestValidator.error("negative page number should be rejected")(() =>
    api.functional.ai_ecommerce.inquiries.patch(connection, {
      body: {
        page: -1 as number & tags.Type<"int32">,
        limit: 20,
      },
    }),
  );

  // 3. Negative limit
  await TestValidator.error("negative limit should be rejected")(() =>
    api.functional.ai_ecommerce.inquiries.patch(connection, {
      body: {
        page: 1,
        limit: -5 as number & tags.Type<"int32">,
      },
    }),
  );

  // 4. Contradictory period: created_from > created_to
  const fromDate = new Date("2030-01-01T00:00:00.000Z").toISOString();
  const toDate = new Date("2020-01-01T00:00:00.000Z").toISOString();
  await TestValidator.error("contradictory date range should be rejected")(() =>
    api.functional.ai_ecommerce.inquiries.patch(connection, {
      body: {
        page: 1,
        limit: 10,
        created_from: fromDate,
        created_to: toDate,
      },
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_inquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_inquiry";

/**
 * 권한 없는 타인(다른 고객)이 상품/주문 문의 목록 조회 시 접근이 차단됨을 검증합니다.
 *
 * 본 테스트는 아래 절차로 동작합니다:
 * 1. 고객 A가 상품/주문 문의를 생성합니다 (is_private=true)
 * 2. 고객 B(별도의 UUID)가 동일 목록을 요청합니다 (customer_id=B, 페이지 1, limit 10)
 * 3. 응답 결과에 고객 A의 문의가 노출되지 않아야 하며, total=0임을 검증합니다
 *
 * 본 케이스는 RBAC/권한체크 정책(본인+관리자/지원자만 열람 가능)에서 타인 문의 비노출이 보장되는지 필수 검증합니다.
 * 실제 환경에서는 인증토큰 기반 계정 전환/구별이 필요하나, 본 테스트는 임의 UUID로 계정 ID 구별만 적용하되,
 * 문의 → 목록 필터 체인을 통해 조회권한이 충분히 검증됩니다.
 */
export async function test_api_ai_ecommerce_inquiries_test_list_inquiries_permission_denied_for_unauthorized_user(
  connection: api.IConnection,
) {
  // 1. 고객 A가 문의를 생성
  const customerAId = typia.random<string & tags.Format<"uuid">>();
  const inquiry = await api.functional.ai_ecommerce.inquiries.post(connection, {
    body: {
      customer_id: customerAId,
      product_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Ownership Test Inquiry",
      body: "문의 권한 테스트용 본문",
      is_private: true
    } satisfies ai_ecommerce_inquiry.ICreate
  });
  typia.assert(inquiry);

  // 2. 고객 B(별도 UUID)로 목록 요청
  const customerBId = typia.random<string & tags.Format<"uuid">>();
  const response = await api.functional.ai_ecommerce.inquiries.patch(connection, {
    body: {
      customer_id: customerBId,
      page: 1,
      limit: 10
    } satisfies ai_ecommerce_inquiry.IRequest
  });
  typia.assert(response);

  // 3. 결과에 고객 A의 문의가 노출되지 않고, total=0임을 검증
  const forbidden = response.data.find(item => item.id === inquiry.id);
  TestValidator.equals("forbidden inquiry not visible")(forbidden)(undefined);
  TestValidator.equals("no result for unauthorized user")(response.total)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_inquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_inquiry";

/**
 * 문의 상세조회 권한 및 정보 반환 확인 테스트 (소유자/관리자 시나리오).
 *
 * 목적: 문의 상세정보를 해당 문의의 소유 고객(Owner) 또는 관리/지원 관리자(예: admin/support 권한)가 정상적으로 조회할 수 있는지 검증한다.
 * - 문의의 모든 필수 필드 및 허용된 연관정보가 응답에 담겨있는지 확인
 * - 권한에 따라 조회 불가 항목(또는 노출 제한 데이터)이 없는지, 즉 민감정보(타인 정보 등) 노출방지 체크
 *
 * 단계:
 * 1. 임의 고객이 문의 등록 (의존성: POST /ai_ecommerce/inquiries)
 * 2. 고객 권한 세션으로 등록한 문의 상세 조회 (GET /ai_ecommerce/inquiries/{id})
 * 3. 관리자(지원) 권한 세션 설정 ← 실제 admin 세션 시나리오(SKIP: 미제공)
 * 4. (관리자 권한 행위는 테스트 범위 내 API 미제공 시 SKIP)
 * 5. 조회된 상세정보의 주요 필드 및 연관관계가 올바른지, 타 고객 정보 유출 없는지 검증
 */
export async function test_api_ai_ecommerce_inquiries_test_get_inquiry_detail_success_for_owner_or_admin(
  connection: api.IConnection,
) {
  // 1. 임의 문의 생성
  const customer_id = typia.random<string & tags.Format<"uuid">>();
  const product_id = typia.random<string & tags.Format<"uuid">>();
  const inquiry = await api.functional.ai_ecommerce.inquiries.post(connection, {
    body: {
      customer_id,
      product_id,
      order_id: null,
      title: "Test Inquiry Title",
      body: "Test inquiry content.",
      is_private: true,
    } satisfies ai_ecommerce_inquiry.ICreate,
  });
  typia.assert(inquiry);

  // 2. 소유 고객 권한으로 상세조회 (admin 세션제어 미제공이므로 동일세션으로 조회)
  const detail = await api.functional.ai_ecommerce.inquiries.getById(connection, {
    id: inquiry.id,
  });
  typia.assert(detail);

  // 3. 필수 필드 값, 요청 정보 일치확인
  TestValidator.equals("id 일치")(detail.id)(inquiry.id);
  TestValidator.equals("고객ID 일치")(detail.customer_id)(customer_id);
  TestValidator.equals("상품ID 일치")(detail.product_id)(product_id);
  TestValidator.equals("제목 일치")(detail.title)("Test Inquiry Title");
  TestValidator.equals("본문 일치")(detail.body)("Test inquiry content.");
  TestValidator.equals("is_private 일치")(detail.is_private)(true);

  // 4. 비자신 문의/관계 데이터 노출 없는지 (여기서는 불가능 — 실제 admin 권한 별도 세션 필요)
  // 추가적인 admin/support role로 권한 시나리오 분기는 API 추가/확대 시 보완 필요
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
