/**
 * 존재하지 않거나 이미 삭제된 문의 ID로 상세 조회를 시도했을 때 not-found(404) 오류 동작 검증
 *
 * 이 테스트는 ai_ecommerce_inquiry의 getById 엔드포인트에 실제로 존재하지 않는(invalid or deleted) inquiry id로 요청했을 때,
 * 시스템이 반드시 404 not-found HttpError를 반환하는지 검증합니다. 실제 문의 엔트리 정보가 노출되지 않아야 하며,
 * 정상적인 조회 성공은 일어나선 안 됩니다. 별도 사전 데이터 준비나 삭제 작업 없이, 랜덤 uuid 입력만으로 not-found 에러 처리를 확인합니다.
 *
 * 1. 존재하지 않는 랜덤 inquiry id(uuid) 생성
 * 2. 해당 id로 상세 조회 요청 시 반드시 404 HttpError/not found 에러가 발생함을 검증
 * 3. (실패 조건) 실제 문의 데이터가 반환되거나 예외가 발생하지 않으면 테스트 실패
 */
export async function test_api_ai_ecommerce_inquiries_test_get_inquiry_detail_not_found_for_nonexistent_id(
  connection: api.IConnection,
) {
  // 1. 존재하지 않는 랜덤 inquiry id(uuid)를 생성
  const unknownId = typia.random<string & tags.Format<"uuid">>();

  // 2. 상세 조회 요청 시 404 not found 에러를 반드시 발생해야 함을 확인
  await TestValidator.error("존재하지 않는 문의 id 조회는 404 not-found 에러여야 함")(
    async () => {
      await api.functional.ai_ecommerce.inquiries.getById(connection, { id: unknownId });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_inquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_inquiry";

/**
 * 비공개 문의 상세 정보 접근 권한 검증 테스트.
 *
 * - 타 사용자가 생성한 비공개 상품/주문 문의에 대해, 소유자(작성 고객), 관리자, 혹은 공식 지원 인력이 아닌 일반 사용자가 상세 조회를 시도할 때
 *   접근이 금지(denied)되어야 하며, API는 적절한 권한 오류(예: 403 Forbidden)를 반환해야 합니다.
 * - 본 테스트는 아래와 같은 흐름을 검증합니다.
 *   1. (선행) 타 고객(혹은 외부인) 계정으로 비공개 문의 생성
 *   2. 본인(혹은 미인증/권한 없는 사용자) 시나리오로 해당 문의 상세 REST API 접근 시도
 *   3. 접근 거부(권한 오류/Forbidden 등) 응답 및 민감정보(본문, 고객번호 등) 노출 차단 확인
 *
 * 본 테스트는 민감 데이터 및 권한 정책 보호 검증을 통해 문의 데이터 프라이버시가 제대로 유지되는지 확인합니다.
 */
export async function test_api_ai_ecommerce_inquiries_test_get_inquiry_detail_forbidden_for_unauthorized_user(
  connection: api.IConnection,
) {
  // 1. (선행) 타 사용자의 고객UUID, 상품UUID 준비
  const otherCustomerId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const productId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 2. 타 고객이 비공개 문의 등록
  const privateInquiry = await api.functional.ai_ecommerce.inquiries.post(connection, {
    body: {
      customer_id: otherCustomerId,
      product_id: productId,
      order_id: null,
      title: "Third-party private question",
      body: "This is private to me only.",
      is_private: true,
    } satisfies ai_ecommerce_inquiry.ICreate,
  });
  typia.assert(privateInquiry);

  // 3. 본인(혹은 일반 무관 사용자)으로 해당 문의 상세 접근 시도 (권한 없음)
  await TestValidator.error("권한 없는 비공개 문의 상세 접근 시 Forbidden 등 오류")(
    async () => {
      await api.functional.ai_ecommerce.inquiries.getById(connection, {
        id: privateInquiry.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_inquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_inquiry";

/**
 * 고객이 상품 또는 주문 문의를 정상적으로 등록하는지 검증하는 E2E 테스트
 *
 * 비즈니스 목적:
 * - 고객이 상품 또는 주문에 대해 문의 접수를 할 수 있어야 하며, 필수/허용 필드를 올바르게 전달하면 정상적으로 문의가 등록되는지 확인합니다.
 * - order_id를 입력하지 않은 일반 상품 문의와, order_id가 포함된 주문 관련 문의 각각 정상 등록되는지 케이스 분리 검증
 *
 * 테스트 플로우:
 * 1. (사전) 고객/상품/주문 UUID 등 랜덤 생성 및 준비
 * 2. 주문ID 없는 상품 문의 생성(case1): customer_id/product_id/title/body/is_private 입력, order_id는 미입력
 * 3. 주문ID 포함한 주문 문의 생성(case2): customer_id/product_id/order_id/title/body/is_private 입력
 * 4. 각 케이스별 POST /ai_ecommerce/inquiries 호출 및 응답 필드 값/구조 일치(assert)
 *
 * 검증 포인트:
 * - 응답 inquiry 구조가 ai_ecommerce_inquiry 타입 완전히 만족하는가(typia.assert)
 * - 입력값과 실제 저장 필드 값 일치 여부
 * - order_id 미입력/입력에 따른 처리 및 반환 값
 */
export async function test_api_ai_ecommerce_inquiries_test_create_inquiry_with_valid_data(
  connection: api.IConnection,
): Promise<void> {
  // 1. 사전 준비: 고객, 상품, 주문 UUID 랜덤 생성
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const productId = typia.random<string & tags.Format<"uuid">>();
  const orderId = typia.random<string & tags.Format<"uuid">>();

  // 2. 주문ID 없이 상품 문의 생성(is_private true)
  const body1 = {
    customer_id: customerId,
    product_id: productId,
    title: "상품 문의드립니다.",
    body: "이 상품의 상세 정보가 궁금합니다. 색상 옵션도 알려주세요.",
    is_private: true,
  } satisfies ai_ecommerce_inquiry.ICreate;
  const result1 = await api.functional.ai_ecommerce.inquiries.post(connection, { body: body1 });
  typia.assert(result1);
  TestValidator.equals("문의 고객ID")(result1.customer_id)(customerId);
  TestValidator.equals("문의 상품ID")(result1.product_id)(productId);
  TestValidator.equals("제목")(result1.title)(body1.title);
  TestValidator.equals("본문")(result1.body)(body1.body);
  TestValidator.equals("비공개여부")(result1.is_private)(body1.is_private);
  TestValidator.equals("주문ID 미입력시 null or undefined")(result1.order_id)(undefined);

  // 3. 주문ID 입력한 주문 문의 생성(is_private false)
  const body2 = {
    customer_id: customerId,
    product_id: productId,
    order_id: orderId,
    title: "주문 관련 문의드립니다.",
    body: "해당 주문의 배송 상태를 확인하고 싶어요.",
    is_private: false,
  } satisfies ai_ecommerce_inquiry.ICreate;
  const result2 = await api.functional.ai_ecommerce.inquiries.post(connection, { body: body2 });
  typia.assert(result2);
  TestValidator.equals("문의 고객ID")(result2.customer_id)(customerId);
  TestValidator.equals("문의 상품ID")(result2.product_id)(productId);
  TestValidator.equals("주문ID")(result2.order_id)(orderId);
  TestValidator.equals("제목")(result2.title)(body2.title);
  TestValidator.equals("본문")(result2.body)(body2.body);
  TestValidator.equals("비공개여부")(result2.is_private)(body2.is_private);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_inquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_inquiry";

/**
 * 상품/주문 문의 생성 API의 실패 케이스 시나리오 테스트
 *
 * 상품 또는 주문 관련 문의를 생성할 때, 잘못된 입력값(필수 필드 누락, 잘못된 UUID, 존재하지 않는 ID, 빈 문자열 등)에 대해
 * 시스템이 올바르게 오류를 반환하는지 검증합니다. 문의가 실제로 생성되지 않아야 하며, 각 케이스별로 명확한 런타임 에러가 발생하면 성공입니다.
 *
 * 테스트 흐름:
 * 1. 필수 필드(customer_id 등) 누락 - 런타임에서 실제 검증 불가, 타입 검사 오류
 * 2. 잘못된 UUID 포맷 입력 - customer_id, product_id, order_id 등에 문자열 포맷 오류
 * 3. 존재하지 않는 customer_id, product_id - 실제 존재하지 않는 UUID 입력
 * 4. title/body 등에 빈 문자열 등 비정상 입력
 *
 * 각 케이스별로 TestValidator.error를 사용해 명확히 런타임 오류가 발생하는지 검증합니다.
 */
