 * - 성공 응답 없이 에러 반환 → 실제 DB에 문의 불생성 보장
 *
 * [테스트 프로세스]
 * 1. 인증정보(Authorization) 없이 문의 생성 시도 → 에러 발생해야 함
 * 2. 실제 문의(리소스)는 생성되지 않아야 함
 */
export async function test_api_ai_ecommerce_inquiries_test_create_inquiry_permission_denied_for_unauthenticated_user(
  connection: api.IConnection,
) {
