      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_inquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_inquiry";
import type { IAiEcommerceInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceInquiry";

/**
 * 문의 소유자(고객)가 문의가 open(진행 중) 상태일 때 title, body, status 등 허용된 필드만 update 할 수 있는지 검증합니다.
 *
 * - 문의가 open 상태인 경우에만 title, body, status 필드 update 가능해야 하며,
 *   성공 시 응답 데이터에 변경 내용 및 updated_at 값이 적절히 반영되어야 함을 검증합니다.
 * - 또한 status를 'closed'로 변경 후 재수정을 시도할 때, 정책상 수정이 금지됨을 확인(예외 검증)합니다.
 *
 * [테스트 시나리오]
 * 1. (고객) open 상태 문의 1건을 생성 (/ai_ecommerce/inquiries POST)
 * 2. 문의 수정 (PUT: title, body, status) → 성공 확인 (각 필드 및 updated_at 반영)
 * 3. status를 'closed'로 변경 후 재수정 시도 → 금지되어 있어야 함 (실패/예외 발생 확인)
 */
export async function test_api_ai_ecommerce_inquiries_test_update_inquiry_with_valid_fields_by_owner(
  connection: api.IConnection
) {
  // 1. 선행 작업 - 고객이 문의 생성 (open 상태)
  const customer_id: string = typia.random<string & tags.Format<"uuid">>();
  const product_id: string = typia.random<string & tags.Format<"uuid">>();
  const initial_title = "문의 제목";
  const initial_body = "상품 문의 드립니다.";
  const createResp = await api.functional.ai_ecommerce.inquiries.post(connection, {
    body: {
      customer_id,
      product_id,
      title: initial_title,
      body: initial_body,
      is_private: false,
    }
  });
  typia.assert(createResp);

  // 2. 상태가 open인 문의의 title, body, status를 update (정상 케이스)
  const new_title = "수정된 제목";
  const new_body = "수정된 본문입니다.";
  const new_status = "pending";

  const before_updated_at = createResp.updated_at;
  const updateResp = await api.functional.ai_ecommerce.inquiries.putById(connection, {
    id: createResp.id,
    body: {
      title: new_title,
      body: new_body,
      status: new_status,
    },
  });
  typia.assert(updateResp);

  // 응답이 정상적으로 변경되었는지 확인
  TestValidator.equals("제목 수정 여부")(updateResp.title)(new_title);
  TestValidator.equals("본문 수정 여부")(updateResp.body)(new_body);
  TestValidator.equals("상태 수정 여부")(updateResp.status)(new_status);
  TestValidator.predicate("updated_at이 갱신됨")(updateResp.updated_at > before_updated_at);

  // 3. status를 closed로 바꾼 뒤에 다시 title 등 수정 → 규칙상 금지, 예외 발생해야 함
  const closedResp = await api.functional.ai_ecommerce.inquiries.putById(connection, {
    id: createResp.id,
    body: {
      status: "closed",
    },
  });
  typia.assert(closedResp);
  TestValidator.equals("status closed 확정")(closedResp.status)("closed");

  await TestValidator.error("closed 상태에서 추가 수정은 거부되어야 함")(() =>
    api.functional.ai_ecommerce.inquiries.putById(connection, {
      id: createResp.id,
      body: {
        title: "더 이상 수정 불가 제목",
      },
    })
  );
}

