      body: "테스트 문의 내용",
      is_private: false,
    } satisfies ai_ecommerce_inquiry.ICreate,
  });
  typia.assert(inquiry);

  // 2. 비정상 status(예: closed 등)로 업데이트 시도 – 반드시 거부되어야 함
  await TestValidator.error("허용되지 않은 status 값에 대한 업데이트 거절")(
    async () => {
      await api.functional.ai_ecommerce.inquiries.putById(connection, {
        id: inquiry.id,
        body: {
          status: "closed",
          title: "비정상 상태에서의 변경시도",
        } satisfies IAiEcommerceInquiry.IUpdate,
      });
    }
  );

  // 3. (TypeScript로 불가하므로 생략) customer_id/product_id 등 금지 필드 업데이트 시도
}

