import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_inquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_inquiry";
import type { IAiEcommerceInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceInquiry";

/**
 * 검증: 문의 소유자가 ai_ecommerce_inquiry의 inquiry를 소프트 삭제(논리 삭제)할 수 있는지 E2E 시나리오 테스트.
 *
 * - inquiry 소유자(고객)가 문의를 삭제하면 deleted_at이 세팅되어 논리 삭제되고,
 *   해당 레코드는 일반 목록·UI에 더이상 표시되지 않음(여기선 목록 API 미구현으로 확인 불가)
 * - 리턴된 레코드는 논리 삭제된 상태여야 하고, id/customer_id/product_id/title/body 등의 핵심값이 원본과 일치하는지 검증함
 * - status가 의도치 않게 변경되는지 체크
 * - 관리자, 감사 권한 등 특수 endpoint 접근 가능성이나 리스트 invisible 테스트는 본 API셋에 없음(생략)
 *
 * 절차:
 * 1. 고객 UUID 및 임의 상품 UUID 준비
 * 2. 해당 고객으로 문의 생성(필수 필드 포함)
 * 3. DELETE API로 논리 삭제(소유자로서)
 * 4. deleted_at 포함 여부, 주요 필드 불변성, status 유지 검증
 */
export async function test_api_ai_ecommerce_inquiries_test_soft_delete_inquiry_by_owner(
  connection: api.IConnection,
) {
  // 1. 고객 UUID 및 상품 UUID 준비 (유효한 UUID 포맷, 비즈니스 스코프로 분리)
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const productId = typia.random<string & tags.Format<"uuid">>();

  // 2. 고객 문의 생성. 타이틀/본문은 읽기 쉬운 랜덤데이터로 작성
  const inquiryCreate = {
    customer_id: customerId,
    product_id: productId,
    order_id: null, // 상품 문의만 테스트
    title: RandomGenerator.paragraph()(3), // 짧은 문장 3개 랜덤
    body: RandomGenerator.content()()(3),  // 긴 텍스트 3개 랜덤
    is_private: false, // 비공개 아닌 상태도 커버
  } satisfies ai_ecommerce_inquiry.ICreate;

  const created = await api.functional.ai_ecommerce.inquiries.post(connection, {
    body: inquiryCreate
  });
  typia.assert(created);

  // 3. 해당 고객(소유자)로 문의 소프트 삭제
  const deleted = await api.functional.ai_ecommerce.inquiries.eraseById(connection, {
    id: created.id
  });
  typia.assert(deleted);

  // 4. 주요 필드/상태값 검증: deleted_at 세팅, core 필드(불변성), status 유지
  TestValidator.predicate("deleted_at 존재")(!!deleted.deleted_at);
  TestValidator.equals("id 일치")(deleted.id)(created.id);
  TestValidator.equals("고객 일치")(deleted.customer_id)(customerId);
  TestValidator.equals("상품 일치")(deleted.product_id)(productId);
  TestValidator.equals("제목 일치")(deleted.title)(inquiryCreate.title);
  TestValidator.equals("본문 일치")(deleted.body)(inquiryCreate.body);
  TestValidator.equals("status 유지")(deleted.status)(created.status);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_inquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_inquiry";
import type { IAiEcommerceInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceInquiry";

/**
 * 문의 소유자가 아니고, 관리자 권한이 없는 사용자가 특정 문의(inquiry)를 삭제(소프트 딜리트) 시도하는 시나리오를 테스트합니다.
