  });
  typia.assert(list);
  TestValidator.predicate("all status match")(
    list.data.every(x => x.status === audit2.status)
  );

  // 2c. Filter by subject_table
  list = await api.functional.ai_ecommerce.complianceAudit.patch(connection, {
    body: { subject_table: audit3.subject_table }
  });
  typia.assert(list);
  TestValidator.predicate("all subject_table match")(
    list.data.every(x => x.subject_table === audit3.subject_table)
  );

  // 2d. Filter by admin_id
  list = await api.functional.ai_ecommerce.complianceAudit.patch(connection, {
    body: { admin_id: audit2.admin_id! }
  });
  typia.assert(list);
  TestValidator.predicate("all admin_id match")(
    list.data.every(x => x.admin_id === audit2.admin_id)
  );

  // 2e. Created_at range filter (simulate: filter audits in last hour)
  // Not natively supported as field, but if supported, should invoke as e.g.:
  // list = await api.functional.ai_ecommerce.complianceAudit.patch(connection, {
  //   body: { created_from: baseTime.toISOString(), created_to: recentTime.toISOString() }
  // });
  // But since IListAiEcommerceComplianceAudit.Request has no fields, we must skip explicitly testing this filter.

  // 3. Pagination: simulate using (if fields present such as current/limit)
  // Not supported in schema, so can't be implemented.

  // 4. Overly strict filter (should return empty result, not error):
  list = await api.functional.ai_ecommerce.complianceAudit.patch(connection, {
    body: { audit_type: "DOES_NOT_EXIST" }
  });
  typia.assert(list);
  TestValidator.equals("data empty for strict filter")(list.data.length)(0);

  // 5. Permission: simulate forbidden by calling with a dummy non-admin connection
  const nonAdminConnection = { ...connection, headers: { ...connection.headers, Authorization: "Bearer NONADMIN" } };
  await TestValidator.error("forbidden for non-admin")(() =>
    api.functional.ai_ecommerce.complianceAudit.patch(nonAdminConnection as any, {
      body: {}
    })
  );

  // 6. Malformed request: supply invalid payload (should raise validation error)
  await TestValidator.error("validation error for bad schema")(() =>
    // Give an impossible payload that doesn't match schema
    api.functional.ai_ecommerce.complianceAudit.patch(connection, {
      body: { bad_field: 123 } as any
    })
  );
}

