 * Steps:
 * 1. Create and verify a valid audit.
 * 2. Try submitting with missing required fields (should error).
 * 3. Try with invalid status and bad subject_id.
 * 4. Try as non-admin (no admin_id).
 * 5. Try duplicate of same audit_type and subject_id.
 */
export async function test_api_ai_ecommerce_test_create_compliance_audit_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Success: create valid audit event as admin
  const admin_id: string = typia.random<string & tags.Format<"uuid">>();
  const audit_type = "GDPR_DELETE";
  const subject_table = "ai_ecommerce_customer";
  const subject_id: string = typia.random<string & tags.Format<"uuid">>();
  const status = "pending";
  const notes = "Initial GDPR delete request for subject.";

  const validBody: IAiEcommerceComplianceAudit.ICreate = {
    admin_id,
    audit_type,
    subject_table,
    subject_id,
    status,
    notes,
  };

  const created = await api.functional.ai_ecommerce.complianceAudit.post(connection, {
    body: validBody,
  });
  typia.assert(created);
  TestValidator.equals("admin_id echoed")(created.admin_id)(admin_id);
  TestValidator.equals("audit_type echoed")(created.audit_type)(audit_type);
  TestValidator.equals("subject_table echoed")(created.subject_table)(subject_table);
  TestValidator.equals("subject_id echoed")(created.subject_id)(subject_id);
  TestValidator.equals("status echoed")(created.status)(status);
  TestValidator.equals("notes echoed")(created.notes)(notes);
  TestValidator.predicate("response has uuid id")(/^[0-9a-fA-F-]{36}$/.test(created.id));
  TestValidator.predicate("created_at iso8601")(/^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.\d{3}Z$/.test(created.created_at));

  // 2. Missing required field 'status' (should fail)
  await TestValidator.error("missing required field status")(
    () => api.functional.ai_ecommerce.complianceAudit.post(connection, {
      body: {
        admin_id,
        audit_type,
        subject_table,
        subject_id,
        // status omitted
        notes,
      } as any,
    }),
  );

  // 3. Invalid status value (should fail)
  await TestValidator.error("invalid status value")(
    () => api.functional.ai_ecommerce.complianceAudit.post(connection, {
      body: {
        admin_id,
        audit_type,
        subject_table,
        subject_id,
        status: "INVALID_STATUS",
        notes,
      },
    }),
  );
  // 3b. Invalid subject_id (not a uuid)
  await TestValidator.error("invalid subject_id format")(
    () => api.functional.ai_ecommerce.complianceAudit.post(connection, {
      body: {
        admin_id,
        audit_type,
        subject_table,
        subject_id: "invalid-uuid",
        status,
        notes,
      },
    }),
  );

  // 4. As non-admin (admin_id omitted/null) (should fail)
  await TestValidator.error("forbidden for non-admin (admin_id omitted)")(
    () => api.functional.ai_ecommerce.complianceAudit.post(connection, {
      body: {
        audit_type,
        subject_table,
        subject_id,
        status,
        notes,
      } as any,
    }),
  );

  // 5. Duplicate (audit_type, subject_id) (should fail 409 conflict)
  await TestValidator.error("duplicate audit_type+subject_id")(
    () => api.functional.ai_ecommerce.complianceAudit.post(connection, {
      body: validBody,
    }),
  );
}

