 * 2. Update mutable fields (status, notes) and verify changes
 * 3. Idempotency: repeat allowed update, ensure values are stable
 * 4. Attempt update on a non-existent record, expect error
 *
 * (Immutable field update and unauthorized user scenarios are skipped as they cannot be implemented with available endpoints/types.)
 */
export async function test_api_ai_ecommerce_complianceAudit_test_update_compliance_audit_with_mutable_fields_and_permission_handling(
  connection: api.IConnection,
) {
  // 1. Create initial compliance audit entry as admin
  const createInput: IAiEcommerceComplianceAudit.ICreate = {
    audit_type: "GDPR_DELETE",
    subject_table: "ai_ecommerce_customer",
