    }
  );

  // Note: Immutable field update and unauthorized user scenarios are skipped (cannot be implemented with available DTOs and APIs).
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
