import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserProfile";
import type { IAiEcommerceLoyaltyPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceLoyaltyPoint";
import type { IPageIAiEcommerceLoyaltyPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiEcommerceLoyaltyPoint";

/**
 * 다양한 적립금(로열티 포인트) 내역 필터/검색/페이징, 접근제어 검증
 *
 * 1. 고객 두 명의 유저 프로필을 생성한다
 * 2. 첫 번째 고객에게는 여러 개의 적립금 내역(적립, 사용, 조정등)을 각각 다른 주문/시간(과거/현재/미래) 시나리오로 생성한다.
 * 3. 두 번째 고객에게 하나의 적립금 내역을 생성해 고객 필터 조건 검증에 활용한다.
 * 4. 다음 각각의 필터 조합별로 조회 API를 호출 후 응답과 meta를 검증한다:
 *    a) customer_id: 해당 고객 건만 반환
 *    b) reason: 특정 사유 건만 반환
 *    c) order_id: 지정 주문 관련 건만 반환
 *    d) 날짜 범위로 조회 (from/to)
 *    e) 페이지네이션(limit/offset)으로 자르고 meta 비교
 * 5. soft-delete 후에도 데이터를 찾을 수 없는지 검증하려 했지만 삭제 엔드포인트가 없어 생략
 * 6. 타 고객이 타 고객건 조회 시도 시, 접근불가(빈 배열 등) 확인
 */
export async function test_api_ai_ecommerce_loyaltyPoints_test_list_loyalty_points_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. 고객 두 명 생성
  const customer1Profile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true,
    },
  });
  typia.assert(customer1Profile);
  const customer2Profile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      communication_consent: true,
    },
  });
  typia.assert(customer2Profile);

  // 2. 첫번 째 고객에 대해 여러 개(적립/사용/조정) 적립금 트랜잭션 생성(주문, 시점 분산)
  const orderId1 = typia.random<string & tags.Format<"uuid">>();
  const orderId2 = typia.random<string & tags.Format<"uuid">>();
  const tierId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();
  const earlier = new Date(now.getTime() - 1000 * 60 * 60 * 24 * 7); // 1주 전
  const later = new Date(now.getTime() + 1000 * 60 * 60 * 24 * 7);    // 1주 후
  // 실제 created_at은 서버에서 자동 할당하므로, 시나리오 설명용이며, 조회시 from/to로 검증
  const loyaltyPoints = [
    await api.functional.ai_ecommerce.loyaltyPoints.post(connection, {
      body: {
        customer_id: customer1Profile.id,
        order_id: orderId1,
        loyalty_tier_id: tierId,
        change_amount: 50,
        reason: "purchase",
      },
    }),
    await api.functional.ai_ecommerce.loyaltyPoints.post(connection, {
      body: {
        customer_id: customer1Profile.id,
        order_id: orderId1,
        loyalty_tier_id: tierId,
        change_amount: -20,
        reason: "redemption",
      },
    }),
    await api.functional.ai_ecommerce.loyaltyPoints.post(connection, {
      body: {
        customer_id: customer1Profile.id,
        order_id: orderId2,
        loyalty_tier_id: tierId,
        change_amount: 15,
        reason: "adjustment",
      },
    }),
  ];
  loyaltyPoints.forEach(item => typia.assert(item)); // fix: 콜백 인자로 명시 전달

  // 3. 두번째 고객에 대해 한 건 등록해 customer_id 분리 검증
  const otherLp = await api.functional.ai_ecommerce.loyaltyPoints.post(connection, {
    body: {
      customer_id: customer2Profile.id,
      order_id: typia.random<string & tags.Format<"uuid">>(),
      loyalty_tier_id: typia.random<string & tags.Format<"uuid">>(),
      change_amount: 40,
      reason: "purchase",
    },
  });
  typia.assert(otherLp);

  // 4.a customer_id=customer1으로만 조회
  const resByCustomerId = await api.functional.ai_ecommerce.loyaltyPoints.patch(connection, {
    body: { customer_id: customer1Profile.id },
  });
  typia.assert(resByCustomerId);
  TestValidator.predicate("all by customer_id only")(resByCustomerId.data.every(lp => lp.customer_id === customer1Profile.id));
  TestValidator.equals("total count matches filtered list")(resByCustomerId.pagination.records)(resByCustomerId.data.length);
  TestValidator.predicate("other customer's lp not present")(!resByCustomerId.data.some(lp => lp.customer_id === customer2Profile.id));

  // 4.b reason 필터: purchase만
  const resByReason = await api.functional.ai_ecommerce.loyaltyPoints.patch(connection, { body: { customer_id: customer1Profile.id, reason: "purchase" } });
  typia.assert(resByReason);
  TestValidator.predicate("only purchase reasons")(resByReason.data.every(lp => lp.reason === "purchase"));

  // 4.c order_id 분리
  const resByOrder = await api.functional.ai_ecommerce.loyaltyPoints.patch(connection, {
    body: { customer_id: customer1Profile.id, order_id: orderId1 },
  });
  typia.assert(resByOrder);
  TestValidator.predicate("filtered by order_id")(resByOrder.data.every(lp => lp.order_id === orderId1));

  // 4.d 날짜범위 조회(from/to는 ISO문자열이므로, 실제 트랜잭션 created_at값으로 테스트)
  {
    // loyaltyPoints[0]이 생성된 직후의 created_at 추출(가장 최근 생성건)
    const ref = loyaltyPoints[0].created_at;
    const onOrAfter = await api.functional.ai_ecommerce.loyaltyPoints.patch(connection, {
      body: { customer_id: customer1Profile.id, from_date: ref, to_date: ref },
    });
    typia.assert(onOrAfter);
    TestValidator.predicate("all created at within now date")(onOrAfter.data.every(lp => lp.created_at >= ref && lp.created_at <= ref));
  }

  // 4.e 페이지네이션 (limit=2, offset=1)
  const paged = await api.functional.ai_ecommerce.loyaltyPoints.patch(connection, {
    body: { customer_id: customer1Profile.id, limit: 2, offset: 1 },
  });
  typia.assert(paged);
  TestValidator.equals("page limit")(paged.pagination.limit)(2);
  TestValidator.equals("page offset counted")(paged.data.length)(Math.min(2, resByCustomerId.data.length - 1));

  // 5. soft-delete 검증 (삭제 API 없음, 생략)

  // 6. 타 고객의 적립금 내역 접근불가 확인(조회 불가 또는 빈 배열)
  const forbidden = await api.functional.ai_ecommerce.loyaltyPoints.patch(connection, {
    body: { customer_id: customer2Profile.id },
  });
  typia.assert(forbidden);
  TestValidator.predicate("customer1 can't view customer2's points")(
    forbidden.data.every(lp => lp.customer_id !== customer2Profile.id) || forbidden.data.length === 0
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
