import type { IAiEcommerceLoyaltyPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceLoyaltyPoint";

/**
 * E2E test for retrieval of a single loyalty point record by UUID (GET /ai_ecommerce/loyaltyPoints/{id}).
 *
 * This test walks through the full workflow:
 * 1. Create a customer profile.
 * 2. Create multiple loyalty point records (both accrual and redemption types) for that customer.
 * 3. Use GET /ai_ecommerce/loyaltyPoints/{id} to retrieve a valid record and verify the returned detail fields match the creation.
 * 4. Attempt to fetch with an invalid UUID format (should throw a validation error).
 * 5. Attempt to fetch using a valid UUID that does not exist (should throw a not found error).
 *
 * Validates proper data correctness and API validation behavior.
 */
export async function test_api_ai_ecommerce_loyaltyPoints_test_get_loyalty_point_by_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. Create a user profile for the main customer.
  const userProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      email: RandomGenerator.alphabets(5) + "@example.com",
      communication_consent: true,
    } satisfies IAiEcommerceUserProfile.ICreate,
  });
  typia.assert(userProfile);

  // 2. Create several loyalty point records for that customer (accrual and redemption events).
  const accrualEvent = await api.functional.ai_ecommerce.loyaltyPoints.post(connection, {
    body: {
      customer_id: userProfile.id,
      change_amount: 100,
      reason: "accumulate test",
    } satisfies IAiEcommerceLoyaltyPoint.ICreate,
  });
  typia.assert(accrualEvent);

  const redemptionEvent = await api.functional.ai_ecommerce.loyaltyPoints.post(connection, {
    body: {
      customer_id: userProfile.id,
      change_amount: -50,
      reason: "redeem test",
    } satisfies IAiEcommerceLoyaltyPoint.ICreate,
  });
  typia.assert(redemptionEvent);

  // 3. Fetch a loyalty point record by its ID for this customer.
  const fetched = await api.functional.ai_ecommerce.loyaltyPoints.getById(connection, {
    id: accrualEvent.id,
  });
  typia.assert(fetched);
  TestValidator.equals("loyalty point id matches")(fetched.id)(accrualEvent.id);
  TestValidator.equals("customer id matches")(fetched.customer_id)(userProfile.id);
  TestValidator.equals("change amount matches")(fetched.change_amount)(accrualEvent.change_amount);
  TestValidator.equals("reason matches")(fetched.reason)(accrualEvent.reason);
  TestValidator.equals("created_at present")(typeof fetched.created_at)("string");

  // 4. Attempt to fetch with an invalid UUID format. Should throw a validation error.
  await TestValidator.error("invalid UUID format should throw")(() =>
    api.functional.ai_ecommerce.loyaltyPoints.getById(connection, {
      id: "INVALID-UUID" as any,
    })
  );

  // 5. Attempt fetching with a valid but non-existent UUID.
  const fakeUuid = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("nonexistent UUID should throw")(() =>
    api.functional.ai_ecommerce.loyaltyPoints.getById(connection, {
      id: fakeUuid,
    })
  );
}

