/**
 * Validate the creation of a loyalty point accrual event after a customer completes an order purchase.
 *
 * This test verifies that:
 * - A loyalty point event can be successfully created referencing a real customer, order, and loyalty tier after a purchase.
 * - The accrual record is attributed to the correct customer, matches the given order and tier, uses the correct point amount, and marks the appropriate reason (e.g., 'purchase').
 * - Attempts to create events with missing or invalid references, or duplicate accruals for the same order, are properly handled by business rules and error responses.
 *
 * Steps:
 * 1. Create a new customer user profile.
 * 2. Create a new loyalty tier record.
 * 3. Create a new order for that customer (with any synthetic valid values, using randoms for unmodeled relationships).
 * 4. Successfully accrue loyalty points with valid references via POST /ai_ecommerce/loyaltyPoints.
 *    - Validate response attributes (customer_id, order_id, loyalty_tier_id, change_amount, reason).
 * 5. Attempt accrual with missing order_id and loyalty_tier_id (where allowed by schema)—should fail or behave per API contract.
 * 6. Attempt accrual with invalid (random, non-existent) customer_id and order_id—should yield an API error.
 * 7. Try to create a duplicate point event for the same order—should reject or error according to business logic.
 */
export async function test_api_ai_ecommerce_loyaltyPoints_test_create_loyalty_point_accrual_for_purchase(
  connection: api.IConnection,
) {
  // 1. Create a new customer user profile
  const customer = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
