  // 4. Successfully accrue loyalty points with valid references
  const changeAmount = 200;
  const reason = "purchase";
  const created = await api.functional.ai_ecommerce.loyaltyPoints.post(connection, {
    body: {
      customer_id: customer.id,
      order_id: order.id,
      loyalty_tier_id: tier.id,
      change_amount: changeAmount,
      reason,
    } satisfies IAiEcommerceLoyaltyPoint.ICreate,
  });
  typia.assert(created);
  TestValidator.equals("accrual event customer")(created.customer_id)(customer.id);
  TestValidator.equals("accrual event order")(created.order_id)(order.id);
  TestValidator.equals("accrual event tier")(created.loyalty_tier_id)(tier.id);
  TestValidator.equals("accrual event amount")(created.change_amount)(changeAmount);
  TestValidator.equals("accrual event reason")(created.reason)(reason);

  // 5. Attempt accrue with missing order_id
  await TestValidator.error("missing order_id should fail")(
    async () =>
      await api.functional.ai_ecommerce.loyaltyPoints.post(connection, {
        body: {
          customer_id: customer.id,
          // order_id omitted
          loyalty_tier_id: tier.id,
          change_amount: 123,
          reason,
        } satisfies IAiEcommerceLoyaltyPoint.ICreate,
      })
  );

  // 6. Attempt with invalid customer_id
  await TestValidator.error("invalid customer_id should fail")(
    async () =>
      await api.functional.ai_ecommerce.loyaltyPoints.post(connection, {
        body: {
          customer_id: typia.random<string & tags.Format<"uuid">>(), // unused random UUID
          order_id: order.id,
          loyalty_tier_id: tier.id,
          change_amount: 222,
          reason,
        } satisfies IAiEcommerceLoyaltyPoint.ICreate,
      })
  );

  // 6b. Attempt with invalid order_id
  await TestValidator.error("invalid order_id should fail")(
    async () =>
      await api.functional.ai_ecommerce.loyaltyPoints.post(connection, {
        body: {
          customer_id: customer.id,
          order_id: typia.random<string & tags.Format<"uuid">>(), // unused random UUID
          loyalty_tier_id: tier.id,
          change_amount: 333,
          reason,
        } satisfies IAiEcommerceLoyaltyPoint.ICreate,
      })
  );

  // 7. Attempt duplicate accrual for the same order
  await TestValidator.error("duplicate loyalty accrual for same order should fail")(
    async () =>
      await api.functional.ai_ecommerce.loyaltyPoints.post(connection, {
        body: {
          customer_id: customer.id,
          order_id: order.id,
          loyalty_tier_id: tier.id,
          change_amount: 444,
          reason,
        } satisfies IAiEcommerceLoyaltyPoint.ICreate,
      })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceUserProfile";
import type { IAiEcommerceOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrder";
import type { IAiEcommerceOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceOrderItem";
import type { IAiEcommerceLoyaltyPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceLoyaltyPoint";

/**
 * Validate redemption flow and negative balance protection for loyalty points.
 *
 * This test covers the full lifecycle of a loyalty points redemption event in an e-commerce system.
 * The steps include account/profile creation, point accrual, redemptive spending,
 * and handling errors with insufficient balance and invalid references.
 *
 * Steps:
 * 1. Create a customer profile with required fields.
 * 2. Create an order for the customer (needed for context/references in loyalty events).
 * 3. Accrue (positive) points for the customer for the given order.
 * 4. Redeem (spend) some, but not all, of the accrued points—verify new event and expected remaining balance by summing transactions.
 * 5. Attempt to redeem more points than available—expect error (business rule: negative balances forbidden).
 * 6. Attempt redemption with an invalid customer_id—expect error.
 * 7. Attempt redemption with invalid order reference (e.g. non-existent order)—expect error.
 */
export async function test_api_ai_ecommerce_loyaltyPoints_test_create_loyalty_point_redemption_and_negative_balance_handling(connection: api.IConnection) {
  // 1. Create a customer profile
  const customerProfile = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: {
      nickname: RandomGenerator.name(),
      avatar_uri: null,
      email: typia.random<string & tags.Format<'email'>>(),
      phone_number: RandomGenerator.mobile(),
      communication_consent: true,
    },
  });
  typia.assert(customerProfile);

  // 2. Create an order for the customer
  const order = await api.functional.ai_ecommerce.orders.post(connection, {
    body: {
      customer_id: customerProfile.id,
      cart_id: typia.random<string & tags.Format<'uuid'>>(),
      shipping_address_id: typia.random<string & tags.Format<'uuid'>>(),
      order_status: 'paid',
      order_channel: 'web',
      items: [
        {
          sku_id: typia.random<string & tags.Format<'uuid'>>(),
          quantity: 2,
        },
      ],
    },
  });
  typia.assert(order);

  // 3. Accrue (add) points for the customer/order
  const accruePoints = await api.functional.ai_ecommerce.loyaltyPoints.post(connection, {
    body: {
      customer_id: customerProfile.id,
      order_id: order.id,
      loyalty_tier_id: null,
      change_amount: 100,
      reason: 'purchase',
    },
  });
  typia.assert(accruePoints);

  // 4. Redeem (spend) part of the accrued points
  const redeemPoints = await api.functional.ai_ecommerce.loyaltyPoints.post(connection, {
    body: {
      customer_id: customerProfile.id,
      order_id: order.id,
      loyalty_tier_id: null,
      change_amount: -40,
      reason: 'redemption',
    },
  });
  typia.assert(redeemPoints);

  // 5. Check that the remaining points balance is as expected (accrual - redemption)
  const expectedBalance = accruePoints.change_amount + redeemPoints.change_amount;
  TestValidator.equals('points balance after redemption')(expectedBalance)(60);

  // 6. Attempt to redeem more points than available and expect business error
  await TestValidator.error('insufficient loyalty point balance')(async () => {
    await api.functional.ai_ecommerce.loyaltyPoints.post(connection, {
      body: {
        customer_id: customerProfile.id,
        order_id: order.id,
        loyalty_tier_id: null,
        change_amount: -100,
        reason: 'redemption',
      },
    });
  });

  // 7. Attempt redemption with invalid customer ID
  await TestValidator.error('invalid customer_id')(async () => {
    await api.functional.ai_ecommerce.loyaltyPoints.post(connection, {
      body: {
        customer_id: typia.random<string & tags.Format<'uuid'>>(), // likely not a real customer
        order_id: order.id,
        loyalty_tier_id: null,
        change_amount: -10,
        reason: 'redemption',
      },
    });
