  TestValidator.equals("award loyalty_tier_id")(award.loyalty_tier_id)(awardInput.loyalty_tier_id);
  TestValidator.equals("award reason")(award.reason)(awardInput.reason);
  TestValidator.equals("award customer_id")(award.customer_id)(awardInput.customer_id);

