/**
 * Validates administrator-level update for a loyalty point record,
 * including mutable/immutable field handling and not-found conditions.
 *
 * Business context: Admins may need to correct points given, reason, or tier due to error or operational need,
 * while core associations like the underlying customer and order are immutable. The test also verifies record existence enforcement.
 *
 * Workflow:
 * 1. Create a new customer (POST /ai_ecommerce/userProfiles)
 * 2. Create a loyalty point event for this customer (POST /ai_ecommerce/loyaltyPoints)
 * 3. Update mutable fields (change_amount and reason) via PUT /ai_ecommerce/loyaltyPoints/{id} and confirm update
 * 4. Attempt to "update" immutable fields (customer_id/order_id) – not possible since not present in IUpdate DTO, so skip.
 * 5. Attempt to update non-existent record (random UUID), expect not-found error.
 */
export async function test_api_ai_ecommerce_loyaltyPoints_test_update_loyalty_point_reason_and_amount_by_admin(
  connection: api.IConnection,
) {
  // 1. Create a new user profile (customer)
  const createProfileInput: IAiEcommerceUserProfile.ICreate = {
    nickname: RandomGenerator.name(),
    avatar_uri: null,
    email: typia.random<string & tags.Format<"email">>(),
    phone_number: null,
    communication_consent: true,
  };
  const customer = await api.functional.ai_ecommerce.userProfiles.post(connection, {
    body: createProfileInput,
  });
  typia.assert(customer);

  // 2. Create a loyalty point event for this customer
  const createLoyaltyPointInput: IAiEcommerceLoyaltyPoint.ICreate = {
    customer_id: customer.id,
    order_id: null,
    loyalty_tier_id: null,
    change_amount: 100,
    reason: "initial_signup_reward",
  };
  const point = await api.functional.ai_ecommerce.loyaltyPoints.post(connection, {
    body: createLoyaltyPointInput,
  });
  typia.assert(point);

  // 3. Update mutable fields (change_amount and reason)
  const newAmount = point.change_amount + 50;
  const newReason = "manual_admin_adjustment";
  const updateInput: IAiEcommerceLoyaltyPoint.IUpdate = {
    change_amount: newAmount,
    reason: newReason,
  };

  const updated = await api.functional.ai_ecommerce.loyaltyPoints.putById(connection, {
    id: point.id,
    body: updateInput,
  });
  typia.assert(updated);
  TestValidator.equals("change_amount updated")(updated.change_amount)(newAmount);
  TestValidator.equals("reason updated")(updated.reason)(newReason);

  // 4. Cannot "update" customer_id or order_id directly -- skip: not present in IUpdate schema
  // But confirm that their values haven't changed
  TestValidator.equals("customer_id immutable")(updated.customer_id)(point.customer_id);
  TestValidator.equals("order_id immutable")(updated.order_id)(point.order_id);

  // 5. Attempt update on non-existent record (should error)
  await TestValidator.error("updating non-existent loyalty point fails")(
    () =>
      api.functional.ai_ecommerce.loyaltyPoints.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: updateInput,
      }),
  );
}

