 * This test ensures that the PATCH endpoint /ai_ecommerce/categories correctly filters categories by their parent-child relationship.
 * It covers both setup and end-to-end validation of hierarchical data filtering and pagination.
 *
 * Steps:
 * 1. Create a parent category (root level).
 * 2. Create several (e.g., 3) child categories, each referencing the created parent_id.
 * 3. Optionally, create one unrelated root category (to ensure filter works).
 * 4. Issue a PATCH to /ai_ecommerce/categories with body: { parent_id: parent.id }
 * 5. Validate:
 *    - Only the correct child categories are returned (all with parent_id = parent.id)
 *    - No unrelated categories are present (e.g., parent, unrelated root)
 *    - Pagination metadata is accurate with respect to number of children
 *    - Each child category has correct fields and references
 */
export async function test_api_ai_ecommerce_categories_test_list_categories_with_filtering_by_parent_id(
  connection: api.IConnection,
) {
  // 1. Create a parent category (root, parent_id is null)
  const parent = await api.functional.ai_ecommerce.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(),
      parent_id: null,
    } satisfies ai_ecommerce_categories.ICreate,
  });
  typia.assert(parent);

  // 2. Create several child categories under parent
  const childCategories = await ArrayUtil.asyncRepeat(3)(async () => {
    const child = await api.functional.ai_ecommerce.categories.post(connection, {
      body: {
        name: RandomGenerator.alphaNumeric(8),
        description: RandomGenerator.paragraph()(),
        parent_id: parent.id,
      } satisfies ai_ecommerce_categories.ICreate,
    });
    typia.assert(child);
    return child;
  });

  // 3. Create one unrelated root category
  const unrelatedRoot = await api.functional.ai_ecommerce.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.paragraph()(),
