import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates pagination when the requested page number exceeds available pages for ai_ecommerce_categories.
 *
 * This test ensures the API returns an empty category list and correct pagination meta when querying beyond the last page boundary. Controlled category creation ensures a predictable total count.
 *
 * Steps:
 * 1. Insert a known number of categories (e.g., 3) via POST requests.
 * 2. Search all categories to determine total count and page size (e.g., limit = 2).
 * 3. Calculate the last page (ceil(count/limit)), then request page+1.
 * 4. Assert the api returns an empty data array.
 * 5. Validate pagination meta (current page = requested, correct total pages, total records).
 */
export async function test_api_ai_ecommerce_categories_test_list_categories_with_pagination_beyond_last_page(
  connection: api.IConnection,
) {
  // 1. Insert a known number of categories (e.g., 3 categories for test boundary)
  const categories: ai_ecommerce_categories[] = [];
  for (let i = 0; i < 3; ++i) {
    const category = await api.functional.ai_ecommerce.categories.post(connection, {
      body: {
        name: `PaginationTest${i}`,
        description: `Pagination test category #${i}`,
      } satisfies ai_ecommerce_categories.ICreate,
    });
    typia.assert(category);
    categories.push(category);
  }

  // 2. Query all categories with a fixed small page size (limit = 2)
  const pageSize = 2;
  const firstPage = await api.functional.ai_ecommerce.categories.patch(connection, {
    body: { limit: pageSize, page: 1 },
  });
  typia.assert(firstPage);
  const totalRecords = firstPage.pagination.records;
  const totalPages = firstPage.pagination.pages;

  // 3. Request one page beyond the last available page
  const beyondLastPage = totalPages + 1;
  const emptyPage = await api.functional.ai_ecommerce.categories.patch(connection, {
    body: { limit: pageSize, page: beyondLastPage },
  });
  typia.assert(emptyPage);

  // 4. Assert that the data array is empty (no categories returned)
  TestValidator.equals("data should be empty beyond last page")(emptyPage.data.length)(0);

  // 5. Validate the pagination metadata (current page, total pages, total records)
  TestValidator.equals("current page matches")(emptyPage.pagination.current)(beyondLastPage);
  TestValidator.equals("total pages matches")(emptyPage.pagination.pages)(totalPages);
  TestValidator.equals("total records matches")(emptyPage.pagination.records)(totalRecords);
}

