import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_categories } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_categories";
import type { IPageai_ecommerce_categories } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageai_ecommerce_categories";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing of categories including soft-deleted entries (if supported).
 *
 * This test verifies the behavior of category listing when some categories
 * have been soft-deleted (removed via DELETE endpoint). It does not assume
 * the presence of a dedicated filter for including deleted categories,
 * but instead checks if the default PATCH listing includes or omits
 * soft-deleted categories. The outcome is validated and documented in either case.
 *
 * Process:
 * 1. Create two categories (A and B).
 * 2. Soft-delete category B using the DELETE endpoint.
 * 3. List all categories using PATCH endpoint with no filters.
 * 4. Verify:
 *     - Category A is present.
 *     - Category B is present (if soft-deleted entries are surfaced),
 *       or explicitly absent (if such entries are filtered out).
 *     - If present, optionally verify its metadata.
 *
 * This ensures the category listing API documents and enforces its contract
 * regarding soft-deleted nodes.
 */
export async function test_api_ai_ecommerce_categories_test_list_categories_with_deleted_included_filter(
  connection: api.IConnection,
) {
  // 1. Create two categories (A, B)
  const categoryA = await api.functional.ai_ecommerce.categories.post(connection, {
    body: {
      name: "RootCategoryA-" + RandomGenerator.alphaNumeric(8),
      description: "Category A - for soft-delete retrieval test",
      parent_id: null,
    } satisfies ai_ecommerce_categories.ICreate,
  });
  typia.assert(categoryA);

  const categoryB = await api.functional.ai_ecommerce.categories.post(connection, {
    body: {
      name: "RootCategoryB-" + RandomGenerator.alphaNumeric(8),
      description: "Category B - to be soft-deleted",
      parent_id: null,
    } satisfies ai_ecommerce_categories.ICreate,
  });
  typia.assert(categoryB);

  // 2. Soft-delete category B
  await api.functional.ai_ecommerce.categories.eraseById(connection, {
    id: categoryB.id,
  });

  // 3. List all categories via the PATCH endpoint (no filters)
  const listResult = await api.functional.ai_ecommerce.categories.patch(connection, {
    body: {},
  });
  typia.assert(listResult);

  // 4. Validate category A is present
  const foundA = listResult.data.find(c => c.id === categoryA.id);
  TestValidator.predicate("category A should be found")(!!foundA);
  TestValidator.equals("category A name")(foundA?.name)(categoryA.name);

  // 5. Validate category B's presence or absence
  const foundB = listResult.data.find(c => c.id === categoryB.id);
  if (foundB) {
    TestValidator.equals("category B name")(foundB.name)(categoryB.name);
    // Optionally check updated_at has progressed if supported
    TestValidator.predicate("category B updated_at >= created_at")(
      new Date(foundB.updated_at).getTime() >= new Date(foundB.created_at).getTime(),
    );
  } else {
    // Category B is filtered out after deletion (expected if contract excludes soft-deleted)
    TestValidator.equals("category B should not be found after deletion")(foundB)(undefined);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_categories } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_categories";

/**
 * Validate successful retrieval of detailed category information by ID.
 *
 * Business context:
 * - Product categories support multi-level taxonomy through parent-child relationships. Each category has a unique name under its parent, description, and optional parent ID (for root/category tree).
 * - Catalog and admin interfaces often retrieve details for navigation, editing, or analytics.
 *
 * Test steps:
 * 1. Create a new category by POSTing valid name/description and optionally a parent_id (null/root by default)
 * 2. Retrieve that category by GET /ai_ecommerce/categories/{id}
 * 3. Assert the returned record contains the exact details from creation: name, description, parent_id
 * 4. Validate type safety and field values match the creation input
 */
export async function test_api_ai_ecommerce_categories_test_get_category_details_success(
  connection: api.IConnection,
) {
  // 1. Create a category (may be root or child)
  const createInput: ai_ecommerce_categories.ICreate = {
    name: RandomGenerator.alphabets(10),
    description: RandomGenerator.paragraph()(),
    parent_id: null,
  };
  const created: ai_ecommerce_categories = await api.functional.ai_ecommerce.categories.post(connection, { body: createInput });
  typia.assert(created);

  // 2. Retrieve the category by its id
  const fetched: ai_ecommerce_categories = await api.functional.ai_ecommerce.categories.getById(connection, { id: created.id });
  typia.assert(fetched);

  // 3. Assert key field values match what was created
  TestValidator.equals("name matches")(fetched.name)(createInput.name);
  TestValidator.equals("description matches")(fetched.description)(createInput.description);
  TestValidator.equals("parent_id matches")(fetched.parent_id ?? null)(createInput.parent_id ?? null);

  // 4. Assert type safety and PK equality
  TestValidator.equals("id matches")(fetched.id)(created.id);
}

