 * - Category names are unique within the same parent (sibling scope uniqueness)
 * - The parent-child relationship is correctly established
 * - Business rules and critical metadata (timestamps, linkage fields) are enforced
 *
 * Test steps:
 * 1. Create a parent/root category (no parent_id)
 * 2. Create a child category, referencing the parent category's id
 * 3. Validate the linkage and payload fields for both parent and child
 */
export async function test_api_ai_ecommerce_categories_test_create_category_with_unique_name_under_parent(
  connection: api.IConnection,
) {
  // 1. Create a root category (parent)
  const parentInput = {
    name: `${RandomGenerator.alphabets(12)}-parent`,
    description: RandomGenerator.paragraph()(),
    parent_id: null,
  } satisfies ai_ecommerce_categories.ICreate;
