import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_categories } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_categories";

/**
 * Validate uniqueness constraint for category name under the same parent category.
 *
 * Business Context:
 * Each product category name must be unique within the context of its parent category—
 * this enforces clear navigation, prevents accidental confusion, and supports admin-driven
 * hierarchical product catalog structures. The API should strictly reject any attempt to create
 * a child category with a duplicate name under a given parent, while allowing the same name under
 * different parents.
 *
 * Test Workflow:
 * 1. Create a parent category (root, i.e., with null parent).
 * 2. Create a child category under that parent with a distinct name.
 * 3. Attempt to create a second child category with the SAME name & parent_id—expecting a uniqueness error.
 * 4. Validate error is returned and new duplicate category is NOT created.
 * 5. (Edge validation): Optionally show that the same name CAN be used under a different (or root) parent.
 */
export async function test_api_ai_ecommerce_categories_test_create_category_with_duplicate_name_under_same_parent(connection: api.IConnection) {
  // 1. Create a parent category (root node)
  const parentName = RandomGenerator.alphaNumeric(12);
  const parentDescription = RandomGenerator.paragraph()();
  const parent = await api.functional.ai_ecommerce.categories.post(connection, {
    body: {
      name: parentName,
      description: parentDescription,
      parent_id: null,
    } satisfies ai_ecommerce_categories.ICreate,
  });
  typia.assert(parent);
  TestValidator.equals("category is root")(parent.parent_id)(null);

  // 2. Create a child category under parent
  const childName = RandomGenerator.alphaNumeric(8);
  const childDescription = RandomGenerator.paragraph()();
  const child = await api.functional.ai_ecommerce.categories.post(connection, {
    body: {
      name: childName,
      description: childDescription,
      parent_id: parent.id,
    } satisfies ai_ecommerce_categories.ICreate,
  });
  typia.assert(child);
  TestValidator.equals("parent reference")(child.parent_id)(parent.id);

  // 3. Attempt to create a duplicate-named category under same parent (should fail)
  await TestValidator.error("duplicate category name under same parent should fail")(async () => {
    await api.functional.ai_ecommerce.categories.post(connection, {
      body: {
        name: childName,
        description: RandomGenerator.paragraph()(),
        parent_id: parent.id,
      } satisfies ai_ecommerce_categories.ICreate,
    });
  });

  // 4. Optionally, show that duplicate name under different parent is allowed
  const secondParent = await api.functional.ai_ecommerce.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(),
      parent_id: null,
    } satisfies ai_ecommerce_categories.ICreate,
  });
  typia.assert(secondParent);
  const sameNameUnderDifferentParent = await api.functional.ai_ecommerce.categories.post(connection, {
    body: {
      name: childName,
      description: RandomGenerator.paragraph()(),
      parent_id: secondParent.id,
    } satisfies ai_ecommerce_categories.ICreate,
  });
  typia.assert(sameNameUnderDifferentParent);
  TestValidator.equals("child with same name under different parent")(sameNameUnderDifferentParent.parent_id)(secondParent.id);
}

