  const name = `TopCat-${RandomGenerator.alphaNumeric(8)}`;
  const description = RandomGenerator.paragraph()();

  // 2. Build request with no parent_id (top-level)
  const input: ai_ecommerce_categories.ICreate = {
    name,
    description,
    // parent_id intentionally omitted for root node
  };

