/**
 * Test updating the name and description fields of an existing category.
 *
 * This test ensures that the category update functionality properly allows modification of the name and description attributes for a product category entity.
 *
 * Step-by-step:
 * 1. Create a new category for update testing purposes using POST /ai_ecommerce/categories.
 * 2. Update the created category (PUT /ai_ecommerce/categories/{id}) by modifying only the name and description fields, leaving parent_id unchanged.
 * 3. Verify that the returned category has the updated name and description and maintains other properties (including id, parent_id, and timestamps).
 */
export async function test_api_ai_ecommerce_categories_test_update_category_name_and_description(
  connection: api.IConnection,
) {
  // 1. Create a category
  const input: ai_ecommerce_categories.ICreate = {
    name: RandomGenerator.paragraph()(3),
    description: RandomGenerator.paragraph()(2),
    parent_id: null,
  };
  const created = await api.functional.ai_ecommerce.categories.post(connection, {
    body: input,
  });
  typia.assert(created);

  // 2. Update category's name and description
  const updatedName = RandomGenerator.paragraph()(4);
  const updatedDescription = RandomGenerator.paragraph()(3);
  const updated = await api.functional.ai_ecommerce.categories.putById(connection, {
