import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_categories } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_categories";

/**
 * Validate that updating a product category's parent_id successfully moves it from one parent to another.
 *
 * Business context:
 * E-commerce category trees require the flexibility to reorganize category hierarchy safely. A category initially created under one parent must be able to change its parent reference. This test ensures that a category can be reassigned from parent category A to parent category B, and the changes properly persist in the API.
 *
 * Steps:
 * 1. Create parent category A (root, parent_id: null)
 * 2. Create parent category B (root, parent_id: null)
 * 3. Create a child category C with parent_id = A.id
 * 4. Update category C's parent_id to B.id via PUT by id.
 * 5. Confirm response: child C's parent_id is now B.id
 * 6. Optionally, ensure that A and B remain root categories (parent_id: null)
 * 7. Optionally, throw if update fails or parent_id is not correctly reassigned.
 */
export async function test_api_ai_ecommerce_categories_test_update_category_parent_id_to_reassign_hierarchy(
  connection: api.IConnection,
) {
  // 1. Create parent category A (no parent)
  const parentA = await api.functional.ai_ecommerce.categories.post(
    connection,
    { body: { name: RandomGenerator.alphabets(10), description: RandomGenerator.paragraph()(), parent_id: null } satisfies ai_ecommerce_categories.ICreate },
  );
  typia.assert(parentA);
  TestValidator.equals("parentA.parent_id is null")(parentA.parent_id)(null);

  // 2. Create parent category B (no parent)
  const parentB = await api.functional.ai_ecommerce.categories.post(
    connection,
    { body: { name: RandomGenerator.alphabets(10), description: RandomGenerator.paragraph()(), parent_id: null } satisfies ai_ecommerce_categories.ICreate },
  );
  typia.assert(parentB);
  TestValidator.equals("parentB.parent_id is null")(parentB.parent_id)(null);

  // 3. Create child category C under parent A
  const childC = await api.functional.ai_ecommerce.categories.post(
    connection,
    { body: { name: RandomGenerator.alphabets(10), description: RandomGenerator.paragraph()(), parent_id: parentA.id } satisfies ai_ecommerce_categories.ICreate },
  );
  typia.assert(childC);
  TestValidator.equals("childC.parent_id = parentA.id")(childC.parent_id)(parentA.id);

  // 4. Update C's parent_id to parent B
  const updatedC = await api.functional.ai_ecommerce.categories.putById(
    connection,
    { id: childC.id, body: { parent_id: parentB.id } satisfies ai_ecommerce_categories.IUpdate },
  );
  typia.assert(updatedC);

  // 5. Confirm childC's parent_id is now parentB.id
  TestValidator.equals("childC's parent_id updated to parentB.id")(updatedC.parent_id)(parentB.id);
  TestValidator.equals("category id unchanged after update")(updatedC.id)(childC.id);

