/**
 * 상품에서 참조되고 있는 카테고리를 소프트 삭제(soft-delete) 시도 시 referential integrity 방어 로직을 검증합니다.
 *
 * - 신규 카테고리를 생성하고,
 * - 해당 카테고리를 참조하는 상품을 1개 생성한 뒤
 * - 해당 카테고리를 soft-delete(삭제) 시도하면, 참조 무결성에 의해 API가 삭제를 차단(에러 반환)해야 합니다.
 *
 * 카테고리 삭제가 성공하면 오히려 문제이므로,
 * 반드시 TestValidator.error로 방어 로직이 동작하는지 확인합니다.
 * 단, 실제 상품 생성 DTO에 카테고리 참조가 불가능하다면(실제 필드 없음), 이 논리적 테스트는 구현 불가이니 그 경우 상품-카테고리 참조 없이 삭제만 검증해야 합니다.
 */
export async function test_api_ai_ecommerce_categories_test_soft_delete_category_in_use_by_products(
  connection: api.IConnection,
) {
  // 1. 새 카테고리 생성
  const category = await api.functional.ai_ecommerce.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
    } satisfies ai_ecommerce_categories.ICreate,
  });
  typia.assert(category);

  // 2. 카테고리 참조 상품 생성 (단, 상품 생성 DTO에 카테고리 참조가 가능해야만 아래 단계 유효)
  //          └ ai_ecommerce_product.ICreate에는 category_id 또는 유사 필드 없음 (제공된 DTO 기준)
  //     => 상품 - 카테고리 참조가 불가하므로, 실제 referential integrity 테스트는 불가
  //     => 카테고리 soft delete 자체 테스트만 진행

  // 3. 해당 카테고리 소프트 삭제 시도 (상품 참조 없으므로 삭제 성공해야 함)
  await api.functional.ai_ecommerce.categories.eraseById(connection, {
    id: category.id,
  });

  // 정상적으로 삭제 동작하면 soft-delete 논리는 검증 가능, RDB 참조 방어 기능은 실제 상품-카테고리 FK가 존재할 때만 추가 검증 필요
}

