/**
 * Test the paginated retrieval of coupons for the current user with various filter conditions and pagination controls.
 *
 * This test validates the main functionality and edge cases for paginated coupon listing:
 * 1. Create a coupon for the current context (via the dependency/create endpoint)
 * 2. Retrieve all coupons and confirm the created coupon exists and pagination metadata is reasonable
 * 3. Filter by is_active=true and confirm the created coupon is returned and all listed are active
 * 4. Filter by code (exact match) and confirm only the expected coupon(s) are returned
 * 5. Filter by owner (customer_id, seller_id if set) and confirm all returned coupons have correct owner
 * 6. Filter by discount_rule_id and confirm proper coupon is returned in result set and all records match query
 * 7. Negative search: filter by non-existing code and check returns empty data set and zero records in pagination
 * 8. Pagination controls: request limit=1 and offset=0, confirm returned count, limit, paging correctness
 *
 * All major contract constraints, including result data correctness, owner and rule linkage, and pagination metadata are asserted.
 */
export async function test_api_ai_ecommerce_coupons_test_list_coupons_with_filters_and_pagination_valid(
  connection: api.IConnection,
) {
  // 1. Create a coupon (dependency setup)
  const couponCreateInput: IAiEcommerceCoupon.ICreate = {
    // You may fill out owner fields (customer or seller) depending on context/use-case
    discount_rule_id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphaNumeric(8),
    issued_at: new Date().toISOString(),
    expires_at: null,
    is_active: true,
    usage_limit: 10,
    usage_per_customer_limit: 1,
  };
  const coupon = await api.functional.ai_ecommerce.coupons.post(connection, { body: couponCreateInput });
  typia.assert(coupon);

  // 2. Unfiltered list, confirm coupon is present and meta is accurate
  const all = await api.functional.ai_ecommerce.coupons.patch(connection, {
    body: {},
  });
  typia.assert(all);
  TestValidator.predicate("Unfiltered list: created coupon exists")(all.data.some((c) => c.id === coupon.id && c.code === coupon.code));
  TestValidator.predicate("Unfiltered list: at least one coupon in result")(all.pagination.records >= 1);
  TestValidator.predicate("Unfiltered list: pagination page >= 1")(all.pagination.current >= 1);
  TestValidator.predicate("Unfiltered list: limit > 0")(all.pagination.limit > 0);

  // 3. Filter by is_active
  const activeOnly = await api.functional.ai_ecommerce.coupons.patch(connection, {
    body: { is_active: true },
  });
  typia.assert(activeOnly);
  TestValidator.predicate("Active filter: created coupon present")(activeOnly.data.some((c) => c.id === coupon.id));
  activeOnly.data.forEach((c) => TestValidator.equals("Active filter: all coupons are active")(c.is_active)(true));

  // 4. Filter by coupon code (exact match)
  const byCode = await api.functional.ai_ecommerce.coupons.patch(connection, {
    body: { code: coupon.code },
  });
  typia.assert(byCode);
  TestValidator.predicate("Code filter: created coupon present")(byCode.data.some((c) => c.id === coupon.id));
  byCode.data.forEach((c) => TestValidator.equals("Code filter: correct code")(c.code)(coupon.code));

  // 5. Filter by owner (customer_id or seller_id, skip if not present)
  if (coupon.customer_id != null) {
    const byCustomer = await api.functional.ai_ecommerce.coupons.patch(connection, {
      body: { customer_id: coupon.customer_id },
    });
    typia.assert(byCustomer);
    byCustomer.data.forEach((c) => TestValidator.equals("Owner filter: correct customer_id")(c.customer_id)(coupon.customer_id));
  }
  if (coupon.seller_id != null) {
    const bySeller = await api.functional.ai_ecommerce.coupons.patch(connection, {
      body: { seller_id: coupon.seller_id },
    });
    typia.assert(bySeller);
    bySeller.data.forEach((c) => TestValidator.equals("Owner filter: correct seller_id")(c.seller_id)(coupon.seller_id));
  }

  // 6. Filter by discount_rule_id
  const byRule = await api.functional.ai_ecommerce.coupons.patch(connection, {
    body: { discount_rule_id: coupon.discount_rule_id },
  });
  typia.assert(byRule);
  TestValidator.predicate("Discount rule filter: created coupon present")(byRule.data.some((c) => c.id === coupon.id));
  byRule.data.forEach((c) => TestValidator.equals("Discount rule filter: correct discount_rule_id")(c.discount_rule_id)(coupon.discount_rule_id));

  // 7. Negative case: non-existent code
  const negative = await api.functional.ai_ecommerce.coupons.patch(connection, {
    body: { code: RandomGenerator.alphaNumeric(16) },
  });
  typia.assert(negative);
  TestValidator.equals("Negative search: data array is empty")(negative.data.length)(0);
  TestValidator.equals("Negative search: zero records in pagination")(negative.pagination.records)(0);

  // 8. Pagination: limit and offset
  const paged = await api.functional.ai_ecommerce.coupons.patch(connection, {
    body: {
      limit: 1,
      offset: 0,
    },
  });
  typia.assert(paged);
  TestValidator.predicate("Pagination: page contains at most 1 card")(paged.data.length <= 1);
  TestValidator.equals("Pagination: limit as requested")(paged.pagination.limit)(1);
  TestValidator.equals("Pagination: current page is 1")(paged.pagination.current)(1);
  TestValidator.predicate("Pagination: records count >= result array length")(paged.pagination.records >= paged.data.length);
}

