import type { IAiEcommerceCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceCoupon";

/**
 * Validate that the API properly denies access to coupon details when the requesting party is not authorized (e.g., fetching another customer's or unrelated coupon).
 *
 * This test checks the platform's compliance with access control for coupons, protecting personal or business information, and preventing unauthorized coupon use or information leaks.
 *
 * Test workflow:
 * 1. Prepare two user contexts: User A and User B (simulate with UUIDs since user authentication APIs are unavailable here).
 * 2. Create a coupon assigned specifically to User A by specifying their customer_id.
 * 3. Attempt to fetch the coupon details as User B using their (different) UUID.
 * 4. Expect the API to reject the unauthorized access attempt with a forbidden or equivalent error.
 * 5. Validate that no coupon details are leaked to unauthorized users.
 */
export async function test_api_ai_ecommerce_coupons_test_get_coupon_details_forbidden_access(
  connection: api.IConnection,
) {
  // 1. Simulate two users (User A and User B) by generating two UUIDs
  const userA_id = typia.random<string & tags.Format<"uuid">>();
  const userB_id = typia.random<string & tags.Format<"uuid">>();

  // 2. Create a coupon specifically assigned to User A
  const coupon = await api.functional.ai_ecommerce.coupons.post(connection, {
    body: {
      customer_id: userA_id,
      discount_rule_id: typia.random<string & tags.Format<"uuid">>(),
      code: RandomGenerator.alphaNumeric(10),
      issued_at: new Date().toISOString(),
      is_active: true,
      usage_limit: 1,
      usage_per_customer_limit: 1,
    } satisfies IAiEcommerceCoupon.ICreate,
  });
  typia.assert(coupon);

  // 3. Simulate request as User B attempting to fetch User A's coupon (business logic assumed by customer_id in test system)
  // In a real API, user context would be handled by authentication but here we simulate separation by distinct UUIDs.
  await TestValidator.error("Access should be denied to unauthorized user")(async () => {
    await api.functional.ai_ecommerce.coupons.getById(connection, { id: coupon.id });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_customers } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_customers";
import type { IAiEcommerceCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceCoupon";
import type { ai_ecommerce_coupon } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_coupon";
import type { IAiEcommerceDiscountRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceDiscountRule";

/**
 * Test the successful creation of a coupon entity for a customer using all required fields.
 *
 * Business context:
 * Coupons are only valid if they are linked to an existing discount rule and optionally assigned to a customer as owner.
 * The system requires explicit setup: the referenced discount rule and customer must exist before coupon creation. This
 * test simulates a platform/admin creating a customer-targeted coupon with full constraints as per business rules.
 *
 * Workflow steps:
 * 1. Create a discount rule (prerequisite for coupon rule reference)
 * 2. Create a customer (prerequisite/coupon owner)
 * 3. Compose a coupon payload referencing the above resources and including all required properties
 * 4. Create coupon using /ai_ecommerce/coupons POST API
 * 5. Validate the response:
 *      - Coupon has a valid UUID as ID
 *      - Coupon status fields and IDs match input
 *      - Unset nullable fields are present as null
 *      - Timestamps and code are correct
 *      - All output matches schema validation
 */
export async function test_api_ai_ecommerce_coupons_test_create_coupon_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a discount rule as dependency
  const discountRule = await api.functional.ai_ecommerce.discountRules.post(connection, {
    body: {
      rule_type: "percentage",
      description: RandomGenerator.paragraph()(),
      predicate_json: JSON.stringify({ min_amount: 5000, category: ["Electronics", "Food"] }),
    } satisfies IAiEcommerceDiscountRule.ICreate,
  });
  typia.assert(discountRule);
  // 2. Create a customer (for customer-targeted coupon)
  const customer = await api.functional.ai_ecommerce.customers.post(connection, {
    body: {
      profile_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies ai_ecommerce_customers.IRegister,
  });
  typia.assert(customer);
  // 3. Prepare coupon payload
  const input: IAiEcommerceCoupon.ICreate = {
    customer_id: customer.id,
    seller_id: null,
    discount_rule_id: discountRule.id,
    code: `PROMO-${RandomGenerator.alphaNumeric(8)}`,
    issued_at: new Date().toISOString(),
    expires_at: new Date(Date.now() + 10 * 24 * 60 * 60 * 1000).toISOString(),
    is_active: true,
    usage_limit: 3,
    usage_per_customer_limit: 1,
  };
  // 4. Attempt to create the coupon
  const coupon = await api.functional.ai_ecommerce.coupons.post(connection, {
    body: input,
  });
  typia.assert(coupon);
  // 5. Validation
  TestValidator.predicate("coupon id is valid uuid")(
    typeof coupon.id === "string" && coupon.id.length >= 30 && coupon.id.indexOf("-") > 0,
  );
  TestValidator.equals("coupon customer_id matches")(coupon.customer_id)(input.customer_id);
  TestValidator.equals("coupon seller_id matches (should be null)")(coupon.seller_id)(null);
  TestValidator.equals("coupon rule id matches")(coupon.discount_rule_id)(input.discount_rule_id);
  TestValidator.equals("coupon code matches")(coupon.code)(input.code);
  TestValidator.equals("coupon issue timestamp matches")(coupon.issued_at)(input.issued_at);
  TestValidator.equals("expiry timestamp matches")(coupon.expires_at)(input.expires_at);
  TestValidator.equals("active status matches")(coupon.is_active)(input.is_active);
  TestValidator.equals("usage_limit matches")(coupon.usage_limit)(input.usage_limit);
  TestValidator.equals("usage_per_customer_limit matches")(coupon.usage_per_customer_limit)(input.usage_per_customer_limit);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceCoupon";
import type { ai_ecommerce_coupon } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_coupon";

/**
 * Test validation of duplicate coupon code business rule.
 *
 * This test verifies that the API enforces code uniqueness constraints for coupons by attempting to create two coupons with the same code and owner scope.
 *
 * Workflow:
 * 1. Create an initial coupon for a specific owner (customer or seller) with a specific discount rule and a given code.
 * 2. Attempt to create a second coupon (same owner/rule, same code).
 * 3. API should reject the second creation and return an error indicating code uniqueness violation.
 *
 * This ensures compliance integrity and prevents duplicate coupon code collisions for the intended owner scope.
 */
export async function test_api_ai_ecommerce_test_create_coupon_with_duplicate_code(
  connection: api.IConnection,
) {
  // 1. Generate owner and rule context for coupon
  const discount_rule_id: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const owner_type: "customer_id" | "seller_id" = Math.random() < 0.5 ? "customer_id" : "seller_id";
  const owner_id: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const code: string = `DUPLICATE-${Math.random().toString(36).substring(2,8).toUpperCase()}`;

  // 2. Create the first coupon for this owner/rule/code
  const createCouponInput: IAiEcommerceCoupon.ICreate = {
    [owner_type]: owner_id,
    discount_rule_id: discount_rule_id,
    code: code,
    issued_at: new Date().toISOString(),
    expires_at: new Date(Date.now() + 1000 * 60 * 60 * 24 * 30).toISOString(), // +30 days
    is_active: true,
    usage_limit: 100,
    usage_per_customer_limit: 1,
  };

  const coupon = await api.functional.ai_ecommerce.coupons.post(connection, {
    body: createCouponInput,
  });
  typia.assert(coupon);
  TestValidator.equals("created coupon matches owner code")(coupon.code)(code);
  TestValidator.equals("owner matches")(coupon[owner_type])(owner_id);
  TestValidator.equals("rule matches")(coupon.discount_rule_id)(discount_rule_id);

  // 3. Try to create another coupon with same code/owner/rule
  await TestValidator.error("should fail on duplicate coupon code")(
    async () => {
      await api.functional.ai_ecommerce.coupons.post(connection, {
        body: { ...createCouponInput },
      });
    },
  );
}

