import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceCoupon";
import type { ai_ecommerce_coupon } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_coupon";

/**
 * Validate updating a coupon's mutable fields (expiration, usage limits, status) by an authorized updater.
 *
 * Business Context:
 * - An authorized actor (admin, issuer seller) should be able to update certain mutable fields of a coupon after it is created.
 * - Immutable fields such as code, ids, and the discount_rule reference must remain unchanged after update attempts.
 *
 * Test Steps:
 * 1. Create a coupon with known values using POST /ai_ecommerce/coupons.
 * 2. Prepare an update payload that changes 'expires_at', 'usage_limit', 'usage_per_customer_limit', and 'is_active'.
 * 3. Update the coupon via PUT /ai_ecommerce/coupons/{id} as the proper actor.
 * 4. Assert that updated coupon fields reflect the changes and that immutable fields remain unchanged.
 */
export async function test_api_ai_ecommerce_coupons_test_update_coupon_valid_fields(
  connection: api.IConnection,
) {
  // 1. Create a coupon (dependency: /ai_ecommerce/coupons POST)
  const couponCreate: IAiEcommerceCoupon.ICreate = {
    discount_rule_id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphaNumeric(12),
    issued_at: new Date().toISOString(),
    expires_at: new Date(Date.now() + 1000 * 60 * 60 * 24 * 7).toISOString(), // 7 days from now
    is_active: true,
    usage_limit: 10,
    usage_per_customer_limit: 1,
  };
  const created = await api.functional.ai_ecommerce.coupons.post(connection, { body: couponCreate });
  typia.assert(created);

  // 2. Build an update payload modifying mutable fields
  const updatePayload: IAiEcommerceCoupon.IUpdate = {
    expires_at: new Date(Date.now() + 1000 * 60 * 60 * 24 * 30).toISOString(), // 30 days from now
    usage_limit: couponCreate.usage_limit + 5,
    usage_per_customer_limit: couponCreate.usage_per_customer_limit + 2,
    is_active: false, // deactivate
  };

  // 3. Perform coupon update
  const updated = await api.functional.ai_ecommerce.coupons.putById(connection, {
    id: created.id,
    body: updatePayload,
  });
  typia.assert(updated);

  // 4. Validate all updated and unchanged fields post-update
  TestValidator.equals("expires_at updated")(updated.expires_at)(updatePayload.expires_at);
  TestValidator.equals("usage_limit updated")(updated.usage_limit)(updatePayload.usage_limit);
  TestValidator.equals("usage_per_customer_limit updated")(updated.usage_per_customer_limit)(updatePayload.usage_per_customer_limit);
  TestValidator.equals("is_active updated")(updated.is_active)(updatePayload.is_active);
  // Immutable fields must not change
  TestValidator.equals("coupon code unchanged")(updated.code)(created.code);
  TestValidator.equals("discount_rule_id unchanged")(updated.discount_rule_id)(created.discount_rule_id);
  TestValidator.equals("issued_at unchanged")(updated.issued_at)(created.issued_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceCoupon";
import type { ai_ecommerce_coupon } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_coupon";

/**
 * Test forbidden updates to immutable coupon fields (code, owner, issued_at).
 *
 * This test validates that once a coupon is created, certain fields (such as
 * code, customer, seller, discount rule, or issuance timestamp) cannot be
 * changed by an update operation, in order to maintain compliance and
 * auditability.
 *
 * Steps:
 * 1. Create a coupon as the baseline (simulate typical creation for system).
 * 2. Attempt to update the coupon, but include fields that should be immutable
 *    (e.g., 'code', 'customer_id', 'seller_id', 'discount_rule_id',
 *    'issued_at') — try using a type assertion or force-casting to provide them.
 * 3. Expect a detailed business logic error in response, indicating which
 *    fields are disallowed for update.
 * 4. Re-read the coupon via update return value and confirm the immutable
 *    fields have not changed (read via the update's result, since GET isn't available).
 */
export async function test_api_ai_ecommerce_coupons_test_update_coupon_immutable_fields_attempt(
  connection: api.IConnection,
) {
  // 1. Create a baseline coupon
  const couponInput: IAiEcommerceCoupon.ICreate = {
    discount_rule_id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphaNumeric(10),
    issued_at: new Date().toISOString(),
    is_active: true,
    usage_limit: typia.random<number & tags.Type<"int32">>(),
    usage_per_customer_limit: typia.random<number & tags.Type<"int32">>(),
  };
  const coupon = await api.functional.ai_ecommerce.coupons.post(connection, {
    body: couponInput,
  });
  typia.assert(coupon);

  // 2. Attempt to update immutable fields (simulate forbidden update)
  // TypeScript would block assigning forbidden fields, so force-cast as any to simulate invalid payload.
  const forbiddenUpdate = {
    code: RandomGenerator.alphaNumeric(12),
    discount_rule_id: typia.random<string & tags.Format<"uuid">>(),
    issued_at: new Date(Date.now() + 86400_000).toISOString(),
    is_active: false,
    usage_limit: typia.random<number & tags.Type<"int32">>(),
    usage_per_customer_limit: typia.random<number & tags.Type<"int32">>(),
  } as any;
  await TestValidator.error("forbidden fields must be rejected")(async () => {
    await api.functional.ai_ecommerce.coupons.putById(connection, {
      id: coupon.id,
      body: forbiddenUpdate,
    });
  });

  // 3. Perform valid update for allowed fields (control test)
  const allowedUpdate = {
    usage_limit: coupon.usage_limit + 1,
  } satisfies IAiEcommerceCoupon.IUpdate;
  const updated = await api.functional.ai_ecommerce.coupons.putById(connection, {
    id: coupon.id,
    body: allowedUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("coupon code unchanged")(updated.code)(coupon.code);
  TestValidator.equals("coupon issued_at unchanged")(updated.issued_at)(coupon.issued_at);
  TestValidator.equals("coupon discount_rule unchanged")(updated.discount_rule_id)(coupon.discount_rule_id);
}

