import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceRecommendation } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceRecommendation";
import type { IPageIAiEcommerceRecommendation } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiEcommerceRecommendation";

/**
 * E2E test: listing recommendations for a specific customer with pagination.
 *
 * This test verifies the ability to retrieve a customer's product recommendations in a paginated manner, ensuring that only recommendations for the correct customer are returned and that the pagination metadata (total, limit, offset) is accurate for various scenarios. It also validates that recommendations for other customers are not included.
 *
 * Steps:
 * 1. Generate a random customer_id for the test scenario.
 * 2. Create three unique recommendations for this customer using POST.
 * 3. List recommendations using PATCH with multiple pagination configurations:
 *    - limit greater than available (total < page size)
 *    - limit equal to total (total = page size)
 *    - limit less than total with offset spanning multiple pages
 * 4. For each listing, check that only records for the specified customer are returned, data length matches page settings, and total is correct.
 * 5. Negative test: Query a different unrelated customer, expect empty result.
 */
export async function test_api_ai_ecommerce_test_list_recommendations_with_valid_customer_and_pagination(
  connection: api.IConnection,
) {
  // 1. Generate a unique test customer UUID
  const customer_id = typia.random<string & tags.Format<'uuid'>>();

  // 2. Create three recommendations for this customer
  const rec_ids: string[] = [];
  for (let i = 0; i < 3; ++i) {
    const product_id = typia.random<string & tags.Format<'uuid'>>();
    const create_input = {
      customer_id,
      product_id,
    } satisfies IAiEcommerceRecommendation.ICreate;
    const rec = await api.functional.ai_ecommerce.recommendations.post(
      connection,
      { body: create_input },
    );
    typia.assert(rec);
    TestValidator.equals('customer_id')(rec.customer_id)(customer_id);
    rec_ids.push(rec.id);
  }

  // 3. List using PATCH in four pagination scenarios

  // (a) limit = 5 (total < page size)
  {
    const page = await api.functional.ai_ecommerce.recommendations.patch(
      connection,
      { body: { customer_id, limit: 5 } },
    );
    typia.assert(page);
    TestValidator.equals('total count')(page.total)(3);
    TestValidator.equals('result count')(page.data.length)(3);
    for (const rec of page.data) {
      TestValidator.equals('right customer')(rec.customer_id)(customer_id);
    }
  }

  // (b) limit = 3 (total == page size)
  {
    const page = await api.functional.ai_ecommerce.recommendations.patch(
      connection,
      { body: { customer_id, limit: 3 } },
    );
    typia.assert(page);
    TestValidator.equals('total count')(page.total)(3);
    TestValidator.equals('result count')(page.data.length)(3);
    for (const rec of page.data) {
      TestValidator.equals('right customer')(rec.customer_id)(customer_id);
    }
  }

  // (c) limit = 2, offset = 0 (first page)
  {
    const page = await api.functional.ai_ecommerce.recommendations.patch(
      connection,
      { body: { customer_id, limit: 2, offset: 0 } },
    );
    typia.assert(page);
    TestValidator.equals('total count')(page.total)(3);
    TestValidator.equals('result count')(page.data.length)(2);
    for (const rec of page.data) {
      TestValidator.equals('right customer')(rec.customer_id)(customer_id);
    }
  }
  // (d) limit = 2, offset = 2 (second page, result < limit)
  {
    const page = await api.functional.ai_ecommerce.recommendations.patch(
      connection,
      { body: { customer_id, limit: 2, offset: 2 } },
    );
    typia.assert(page);
    TestValidator.equals('total count')(page.total)(3);
    TestValidator.equals('result count')(page.data.length)(1);
    for (const rec of page.data) {
      TestValidator.equals('right customer')(rec.customer_id)(customer_id);
    }
  }

  // 4. Negative: Query for different customer should yield no results
  {
    const other_customer_id = typia.random<string & tags.Format<'uuid'>>();
    const page = await api.functional.ai_ecommerce.recommendations.patch(
      connection,
      { body: { customer_id: other_customer_id } },
    );
    typia.assert(page);
    TestValidator.equals('total count')(page.total)(0);
    TestValidator.equals('result count')(page.data.length)(0);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
