import api from "@ORGANIZATION/PROJECT-api";
import type { IAiEcommerceRecommendation } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiEcommerceRecommendation";
import type { IPageIAiEcommerceRecommendation } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiEcommerceRecommendation";

/**
 * Validate the filtering of AI e-commerce recommendation results by reason_code.
 *
 * This test ensures that when the /ai_ecommerce/recommendations PATCH endpoint is called
 * with a specific reason_code in the request body, only recommendations with that reason_code
 * are returned in the result, while others are not included. This validates that server-side
 * filtering by reason_code operates as intended.
 *
 * Step-by-step process:
 * 1. Create a single customer_id and several product_id values.
 * 2. Create multiple recommendations for the same customer_id: at least two with the same reason_code (e.g., 'trending'), and at least one with a different reason_code (e.g., 'similar_items').
 * 3. Query the PATCH endpoint with the test customer_id and filter by the specific test reason_code (e.g., 'trending').
 * 4. Assert that only recommendations with that reason_code are included, and recommendations with other reason_code values are not present in the response data.
 * 5. Validate response structure and business logic filtering.
 */
export async function test_api_ai_ecommerce_test_list_recommendations_with_filtering_by_reason_code(
  connection: api.IConnection,
) {
  // 1. Generate test customer and product IDs
  const customer_id = typia.random<string & tags.Format<"uuid">>();
  const product_id_1 = typia.random<string & tags.Format<"uuid">>();
  const product_id_2 = typia.random<string & tags.Format<"uuid">>();
  const product_id_3 = typia.random<string & tags.Format<"uuid">>();

  // 2. Create 3 recommendations for the customer: two with reason_code 'trending', one 'similar_items'
  const rec1 = await api.functional.ai_ecommerce.recommendations.post(connection, {
    body: {
      customer_id,
      product_id: product_id_1,
      reason_code: "trending",
    } satisfies IAiEcommerceRecommendation.ICreate,
  });
  typia.assert(rec1);
  const rec2 = await api.functional.ai_ecommerce.recommendations.post(connection, {
    body: {
      customer_id,
      product_id: product_id_2,
      reason_code: "trending",
    } satisfies IAiEcommerceRecommendation.ICreate,
  });
  typia.assert(rec2);
  const rec3 = await api.functional.ai_ecommerce.recommendations.post(connection, {
    body: {
      customer_id,
      product_id: product_id_3,
      reason_code: "similar_items",
    } satisfies IAiEcommerceRecommendation.ICreate,
  });
  typia.assert(rec3);

  // 3. Query with reason_code filter 'trending', expecting only rec1 and rec2 returned
  const result = await api.functional.ai_ecommerce.recommendations.patch(connection, {
    body: {
      customer_id,
      reason_code: "trending",
    } satisfies IAiEcommerceRecommendation.IRequest,
  });
  typia.assert(result);
  // 4. Validate all returned recommendations have reason_code 'trending'
  TestValidator.predicate("all results reason_code is 'trending'")(
    result.data.every(x => x.reason_code === "trending")
  );
  // 5. Validate that returned recommendations are for our customer_id
  TestValidator.predicate("all results match customer_id")(
    result.data.every(x => x.customer_id === customer_id)
  );
  // 6. Validate only the created trending product_ids are present
  const returnedIds = result.data.map(x => x.product_id);
  TestValidator.equals("only trending recommendation products")(
    returnedIds.sort()
  )([
    product_id_1,
    product_id_2
  ].sort());
  // 7. Validate recommendations with different reason_codes are not included
  TestValidator.predicate("'similar_items' not present")(
    !result.data.some(x => x.product_id === product_id_3)
  );
}

