/**
 * Validate updating an existing ai_ecommerce_recommendation record’s reason_code and/or snapshot_id fields.
 *
 * This test ensures that as the owner or admin, one can update the mutable fields (reason_code and snapshot_id) of a recommendation entry. Changes should be correctly persisted and returned in the API response.
 *
 * Test Workflow:
 * 1. Create a new recommendation record using the POST endpoint (capture the output).
 * 2. Issue a PUT update, changing either the reason_code, snapshot_id, or both.
 * 3. Assert that the returned response reflects the updated values and immutable fields remain unchanged.
 * 4. Test an edge case where null is provided to clear the reason_code or snapshot_id.
 */
export async function test_api_ai_ecommerce_recommendations_test_update_recommendation_reason_code_and_context(
  connection: api.IConnection,
) {
  // 1. Create a recommendation as setup
  const originalCreate: IAiEcommerceRecommendation = await api.functional.ai_ecommerce.recommendations.post(connection, {
    body: {
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      product_id: typia.random<string & tags.Format<"uuid">>(),
      snapshot_id: typia.random<string & tags.Format<"uuid">>(),
      reason_code: "personalized",
    } satisfies IAiEcommerceRecommendation.ICreate,
  });
  typia.assert(originalCreate);

  // 2. Update reason_code and snapshot_id
  const updatedReason = "trending";
  const updatedSnapshotId = typia.random<string & tags.Format<"uuid">>();
  const updateResp: IAiEcommerceRecommendation = await api.functional.ai_ecommerce.recommendations.putById(connection, {
    id: originalCreate.id,
    body: {
      reason_code: updatedReason,
      snapshot_id: updatedSnapshotId,
    } satisfies IAiEcommerceRecommendation.IUpdate,
  });
  typia.assert(updateResp);
  TestValidator.equals("reason_code updated")(updateResp.reason_code)(updatedReason);
  TestValidator.equals("snapshot_id updated")(updateResp.snapshot_id)(updatedSnapshotId);
  // Immutable fields unchanged
  TestValidator.equals("customer_id retained")(updateResp.customer_id)(originalCreate.customer_id);
  TestValidator.equals("product_id retained")(updateResp.product_id)(originalCreate.product_id);
  TestValidator.equals("id retained")(updateResp.id)(originalCreate.id);

  // 3. Provide nulls to clear fields (edge case)
  const updateNullResp: IAiEcommerceRecommendation = await api.functional.ai_ecommerce.recommendations.putById(connection, {
    id: originalCreate.id,
    body: {
      reason_code: null,
      snapshot_id: null,
    } satisfies IAiEcommerceRecommendation.IUpdate,
  });
  typia.assert(updateNullResp);
  TestValidator.equals("reason_code cleared")(updateNullResp.reason_code)(null);
  TestValidator.equals("snapshot_id cleared")(updateNullResp.snapshot_id)(null);
  // Unchanged base fields
  TestValidator.equals("customer_id retained after null update")(updateNullResp.customer_id)(originalCreate.customer_id);
  TestValidator.equals("product_id retained after null update")(updateNullResp.product_id)(originalCreate.product_id);
  TestValidator.equals("id retained after null update")(updateNullResp.id)(originalCreate.id);
}

