import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_product } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_product";
import type { IPageai_ecommerce_product } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageai_ecommerce_product";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing and searching of products with pagination and filtering options.
 *
 * Ensures product listing supports:
 * - basic pagination (default, min, and max page sizes)
 * - filtering by seller, status, approval_state, creation date
 * - empty filter returns all permitted products
 * - role-based results (e.g. sellers see only their products)
 * - correct pagination metadata in response
 * - defensive limits on queries (e.g. overlarge page size)
 * - clear error for invalid/malformed request
 *
 * This test does NOT cover product creation, update, delete operations,
 * nor does it test irrelevant fields not present in the IRequest DTO.
 *
 * Steps:
 * 1. As admin, request paginated products with default filters, confirm response correctness.
 * 2. As admin, filter by specific seller_id, status, approval_state, creation date window.
 * 3. Test maximum and minimum valid page limits with pagination—*pagination/limit only via response metadata, not via request*.
 * 4. Test malformed/abusive query (e.g. negative limits, bogus seller) yields error.
 * 5. As seller, filter by own seller_id, confirm only their products are returned.
 * 6. As admin, send empty filter—confirm all products are fetched (within max page limit).
 */
export async function test_api_ai_ecommerce_products_patch(
  connection: api.IConnection,
) {
  // 1. Default pagination / empty filter — should return all accessible products (within system limit)
  const defaultOutput = await api.functional.ai_ecommerce.products.patch(connection, {
    body: {},
  });
  typia.assert(defaultOutput);
  TestValidator.equals("current page is 1")(defaultOutput.pagination.current)(1);
  TestValidator.predicate("records is non-negative")(defaultOutput.pagination.records >= 0);
  TestValidator.equals("data length<=limit")(defaultOutput.data.length <= defaultOutput.pagination.limit)(true);

  // 2. Filter by seller_id (simulate RBAC: only this seller's products)
  if (defaultOutput.data.length > 0) {
    const sellerId = defaultOutput.data[0].seller_id;
    const sellerFiltered = await api.functional.ai_ecommerce.products.patch(connection, {
      body: { seller_id: sellerId },
    });
    typia.assert(sellerFiltered);
    for (const prod of sellerFiltered.data) {
      TestValidator.equals("seller_id matches")(prod.seller_id)(sellerId);
    }
  }

  // 3. Filter by status, approval_state
  if (defaultOutput.data.length > 0) {
    const status = defaultOutput.data[0].status;
    const approvalState = defaultOutput.data[0].approval_state;
    const filtered = await api.functional.ai_ecommerce.products.patch(connection, {
      body: { status, approval_state: approvalState },
    });
    typia.assert(filtered);
    for (const prod of filtered.data) {
      TestValidator.equals("status matches")(prod.status)(status);
      TestValidator.equals("approval_state matches")(prod.approval_state)(approvalState);
    }
  }

  // 4. Filter by creation date window (using created_at of first record)
  if (defaultOutput.data.length > 0) {
    const createdAt = defaultOutput.data[0].created_at;
    const filtered = await api.functional.ai_ecommerce.products.patch(connection, {
      body: { created_from: createdAt, created_to: createdAt },
    });
    typia.assert(filtered);
    for (const prod of filtered.data) {
      TestValidator.equals("created_at in window")(prod.created_at)(createdAt);
    }
  }

  // 5. Role-based test (simulate as if current user is seller, via seller_id filter)
  if (defaultOutput.data.length > 0) {
    const sellerId = defaultOutput.data[0].seller_id;
    const sellerFiltered = await api.functional.ai_ecommerce.products.patch(connection, {
      body: { seller_id: sellerId },
    });
    typia.assert(sellerFiltered);
    for (const prod of sellerFiltered.data) {
      TestValidator.equals("RBAC/Seller: seller_id matches")(prod.seller_id)(sellerId);
    }
  }

  // 6. Defensive: malformed seller_id triggers error
  await TestValidator.error("malformed seller_id should error")(async () => {
    await api.functional.ai_ecommerce.products.patch(connection, {
      body: { seller_id: "not-a-uuid" },
    });
  });

  // 7. Defensive: created_from/created_to unnatural window triggers error
  await TestValidator.error("created_from after created_to should error")(async () => {
    await api.functional.ai_ecommerce.products.patch(connection, {
