import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ai_ecommerce_product } from "@ORGANIZATION/PROJECT-api/lib/structures/ai_ecommerce_product";

/**
 * Validate atomic update of allowed fields on an existing product by owner (seller or admin).
 *
 * This test verifies that a product, once created, can have its updatable fields (title, description, approval_state, status)
 * changed by an authorized owner. The test ensures only allowed fields are changed and all other fields remain the same.
 * Audit fields (updated_at) must also reflect the change, but fields like created_at should remain unchanged.
 * The test further checks for atomicity—changes should apply fully to the target product and no other product/entities.
 *
 * Workflow:
 * 1. Create a new product via POST (simulate seller or admin ownership).
 * 2. Update one or more of: title, description, approval_state, status via PUT (by product ID).
 * 3. Assert that all intended fields are updated, other fields (including seller_id, created_at, deleted_at) are unchanged.
 * 4. Confirm updated_at audit field is refreshed and strictly newer than pre-update value.
 * 5. Confirm created_at and deleted_at (if present) are unchanged.
 */
export async function test_api_ai_ecommerce_products_test_update_product_with_allowed_fields_by_owner(
  connection: api.IConnection,
) {
  // 1. Create a new product as baseline (simulates seller/admin ownership)
  const createInput: ai_ecommerce_product.ICreate = {
    seller_id: typia.random<string & tags.Format<"uuid">>(),
    title: "Original Product Title",
    description: "Description before update.",
    status: "draft",
    approval_state: "pending",
  };
  const product = await api.functional.ai_ecommerce.products.post(connection, { body: createInput });
  typia.assert(product);

  // 2. Prepare update (change allowed fields)
  const updateInput: ai_ecommerce_product.IUpdate = {
    title: "Updated Product Title",
    description: "Description after update.",
    approval_state: "approved",
    status: "published",
  };
  // Capture original audit fields
  const originalUpdatedAt = product.updated_at;
  const originalCreatedAt = product.created_at;
  const originalDeletedAt = product.deleted_at ?? null;

  // 3. Execute update via PUT
  const updatedProduct = await api.functional.ai_ecommerce.products.putById(connection, {
    id: product.id,
    body: updateInput,
  });
  typia.assert(updatedProduct);

  // 4. Assert allowed fields were updated
  TestValidator.equals("title updated")(updatedProduct.title)(updateInput.title);
  TestValidator.equals("description updated")(updatedProduct.description)(updateInput.description);
  TestValidator.equals("approval_state updated")(updatedProduct.approval_state)(updateInput.approval_state);
  TestValidator.equals("status updated")(updatedProduct.status)(updateInput.status);

  // 5. Assert other fields not changed
  TestValidator.equals("id unchanged")(updatedProduct.id)(product.id);
  TestValidator.equals("seller_id unchanged")(updatedProduct.seller_id)(product.seller_id);
  TestValidator.equals("created_at unchanged")(updatedProduct.created_at)(originalCreatedAt);
  TestValidator.equals("deleted_at unchanged")(updatedProduct.deleted_at ?? null)(originalDeletedAt);

  // 6. Assert updated_at is refreshed (strictly newer)
  TestValidator.predicate("updated_at newer")(new Date(updatedProduct.updated_at) > new Date(originalUpdatedAt));
}

